    ["01-2"] = {name="듀로타", nameA="듀로타: {a:367} & {a:362}", shortA="듀로타: {a:367} +", tips={{k="取捨", text="보급품 조달를 수행합니다. 다른 타이라가드 요새 목표와 함께 캔버스 천조각를 수집하세요."}, {k="取捨", text="배신자 처단를 돌려 난파선를 잠금 해제하세요. 나약한 정신와 함께 수행하세요."}, {k="取捨", text="어둠의 틈 던전 체인을 저장하세요. 성난불길 협곡를 실행할 계획이라면 스랄에서 내부의 배신자( → →)를 가져옵니다. 북쪽에 있는 불타는 칼날단 캠프에서 배지를 획득하세요."}, {k="提醒", text="레벨 12 이하? 보급로 확보, 해골 바위굴 또는 아래 퀘스트의 처음 몇 위협를 수행하세요.", s={{"레벨 12 이하?"}, {"보급로 확보, 해골 바위굴 또는 아래 퀘스트의 처음 몇 위협를 수행하세요"}}}}, danger={[1]="타이라가드 요새의 계단과 출입구는 선원들을 위층으로 끌어올 수 있습니다. 먼저 외벽과 입구를 정리하세요.", [2]="바다 거인들이 북쪽 해안의 나가 지역을 돌아다닙니다. 근처의 몹을 잡아당기기 전에 제거하세요. 문제가 발생하면 해안을 따라 후퇴하세요."}, grind={[1]={mob="쿨 티라스 해병", note="타이라가드 요새에 밀집된 일반 몹. 홀에 추가되는 것을 피하기 위해 밖으로 당기십시오. 새로운 가방을 위해 캔버스 천조각를 수집하세요."}, [2]={mob="서슬갈기일족 전투호위병", note="칼바위 언덕 서쪽에 일반 몹이 모여있습니다. 캠프 가장자리를 따라 당기고 순찰대를 지켜보세요. 영토 침범와 페어링하세요."}, [3]={mob="먼지바람일족 폭풍마녀", note="듀로타 북부의 일반 몹 클러스터. 덮개를 사용하여 바퀴를 가까이 끌어당기세요. 보급로 확보를 수행하거나 오그리마 전에 12로 그라인딩합니다."}}, supply={[1]={npc="트라예시르"}, [2]={npc="여관주인 그로스크"}, [3]={npc="우아크"}, [4]={npc="여관주인 그로스크"}, [5]={npc="그와트"}, [6]={npc="도라스"}}, steps={[1]={npc="우코르", tgt="우코르", desc="시험의 골짜기에서 센진 마을로 가는 길에서 우코르를 찾으세요."}, [2]={hint="센진 마을에 있는 가드린 장로와 대화하십시오."}, [3]={npc="장로 가드린", tgt="장로 가드린"}, [4]={npc="라르 프라울터스크", tgt="라르 프라울터스크"}, [5]={npc="벨린 팡", tgt="벨린 팡"}, [6]={npc="장로 보르날", tgt="장로 보르날"}, [7]={npc="장로 가드린", tgt="장로 가드린"}, [8]={npc="장로 가드린", tgt="장로 가드린"}, [9]={npc="장로 가드린", tgt="장로 가드린"}, [10]={npc="벨린 팡", tgt="벨린 팡"}, [11]={npc="살티", tgt="살티"}, [12]={npc="장로 보르날", tgt="장로 보르날"}, [13]={npc="파줄라", tgt="파줄라", tag="선택사항", desc="마법을 해제하는 재료를 얻을 수 있는 경우에만 이 작업을 수행하십시오."}, [14]={text="칼바위 언덕에서 먼저 체크인하세요"}, [15]={hint="듀로타 남부에서 능선그늘 거미 6마리와 능선그늘 잠복꾼 6마리를 처치한 후, 칼바위 언덕에 있는 가르톡에게 보고해야 합니다."}, [16]={hint="일지를 칼바위 언덕 근처에 있는 브라크에게 가져가야 합니다.", tag="선택사항"}, [17]={npc="브라크", tgt="브라크", tag="선택사항"}, [18]={npc="브라크", tgt="브라크", tag="선택사항"}, [19]={hint="브라크의 작은 모닥불 주위에 앉은 다음, \"휴식 강화\" 강화 효과를 받을 때까지 기다려야 합니다.", tag="선택사항"}, [20]={npc="브라크", tgt="브라크", tag