    ["01-3"] = {name="나라체 야영지", tips={{k="交通", text="다른 시작 지역에서 오시나요? 블러드후프 마을로 향하고 남쪽으로 붉은구름 고원에서 나라체 야영지까지 도로를 따라 가세요. 위의 여행 기록을 참조하세요."}, {k="取捨", text="하나의 칼날가시 협곡 루프에서 힘의 의식, 족장 뾰족어금니 처치! 및 전투멧돼지 를 수행합니다. 지도를 약탈하면 나라체 야영지에 대한 공격를 수락하세요."}, {k="提醒", text="6레벨이 안 됐다면 칼날가시 협곡 외곽에서 전투멧돼지나 뾰족털 가시멧돼지를 처치한 뒤 블러드후프 마을로 가세요.", s={{"6레벨이 안 됐다면 칼날가시 협곡 외곽에서 전투멧돼지나 뾰족털 가시멧돼지를 처치한 뒤 블러드후프 마을로 가세요"}}}}, danger={[1]="Quilboar는 칼날가시 협곡의 좁은 경사로를 포장합니다. 족장 뾰족어금니를 당기기 전에 지우십시오. 붉은구름 고원 방향으로 후퇴합니다."}, grind={[1]={mob="초원타조", note="나라체 야영지의 남동쪽 우물에는 밀도가 높고 대부분 중립적인 일반 몹이 있습니다. 사냥의 시작 동안 한 번에 한 명의 적을 끌어당깁니다."}, [2]={mob="산지퓨마", note="붉은구름 고원의 남쪽 경사면에는 대부분 중립적인 일반 몹이 밀집되어 있습니다. 계속되는 사냥에 필요한 가죽을 얻기 위해 한 번에 한 명의 적을 끌어당깁니다."}, [3]={mob="뾰족털일족 전투멧돼지", note="칼날가시 협곡의 뾰족털 가시멧돼지 사이에 일반 몹이 모여 있습니다. 먼저 가장자리를 지웁니다. 전투멧돼지 및 힘의 의식와 페어링하세요."}}, supply={[1]={npc="브롱크 스틸레이지"}, [2]={npc="무단 선그레인"}, [3]={npc="카우니 소프트브리즈"}}, steps={[1]={npc="나라체 야영지 선물교환권", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="나라체 야영지 선물교환권가 있는 경우에만 수락하세요. 레이스의 시작 바우처를 마우스 오른쪽 버튼으로 클릭하세요. 지도에는 수락이 없습니다."}, [2]={hint="보른 스카이시어에게 나라체 야영지 선물교환권을 가져가야 합니다.", tag="선택사항", desc="나라체 야영지 선물교환권가 있는 경우에만 수락하세요."}, [3]={npc="보른 스카이시어", tgt="보른 스카이시어", tag="선택사항", desc="나라체 야영지 선물교환권가 있는 경우에만 수락하세요."}, [4]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [5]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [6]={hint="나라체 야영지에 있는 그룰 호크윈드가 초원타조 깃털 7개와 초원타조 고기 7덩이를 가져다 달라고 부탁했습니다."}, [7]={hint="족장 호크윈드가 나라체 야영지 남동쪽에 있는 우물 근처에서 그의 어머니를 찾아봐 달라고 부탁했습니다."}, [8]={npc="대모 호크윈드", tgt="대모 호크윈드"}, [9]={npc="대모 호크윈드", tgt="대모 호크윈드"}, [10]={hint="우물에 있는 물병을 집어서 우물에서 북서쪽에 있는 나라체 야영지의 족장 호크윈드에게 가져가야 합니다.", desc="대모 호크윈드 옆 우물에서 물병를 획득하세요."}, [11]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [12]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [13]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [14]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [15]={npc="용사 윈드페더", tgt="용사 윈드페더"}, [16]={hint="나라체 야영지의 그룰 호크윈드가 산지퓨마 모피 10필을 가져다 달라고 부탁했습니다."}, [17]={hint="나라체 야영지 정남쪽에 있는 언덕에 사는 예언자 그레이텅을 찾아가야 합니다."}, [18]={npc="예언자 그레이텅", tgt="예언자 그레이텅"}, [19]={npc="예언자 그레이텅", tgt="예언자 그레이텅"}, [20]={npc="예언자 그레이텅", tgt="예언자 그레이텅", tag="선택사항", desc="향을 받은 후 10분 이내에 남동쪽 제단으로 가져오십시오.", star={"그슬린 가죽 주머니"}}, [21]={hint="타들어가는 향이 재만 남기 전에 10분 내로 남동쪽 언덕에 있는 안쉬와 무샤의 제단으로 가져가야 합니다.", tag="선택사항", desc="향을 받은 후 10분 이내에 남동쪽 제단으로 가져오십시오."}, [22]={npc="의식의 불꽃", npcObj=true, tag="선택사항", desc="향을 받은 후 10분 이내에 남동쪽 제단으로 가져오십시오.", star={"그슬린 가죽 주머니"}}, [23]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [24]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [25]={hint="칼날가시 협곡에 있는 뾰족털일족들을 처치하고 나라체 야영지에 있는 족장 호크윈드에게 뾰족털일족 허리띠 12개를 가져가야 합니다."}, [26]={hint="족장 뾰족어금니를 처치한 후 그 증거로 그의 머리카락을 붉은구름 고원에 있는 용사 윈드페더에게 가져가야 합니다."}, [27]={hint="나라체 야영지에 있는 그룰 호크윈드가 전투멧돼지를 처치하고 전투멧돼지 주둥이 8개와 전투멧돼지 갈비살 8점을 가져다 달라고 부탁했습니다."}, [28]={npc="지저분한 지도", npcObj=true, tag="선택사항", desc="뾰족털 가시멧돼지에서 흙으로 얼룩진 지도를 획득하고 마우스 오른쪽 버튼을 클릭하세요."}, [29]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [30]={npc="용사 윈드페더", tgt="용사 윈드페더"}, [31]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [32]={hint="나라체 야영지에 있는 족장 호크윈드에게 뾰족털일족의 작전도를 가져가야 합니다.", tag="선택사항"}, [33]={npc="족장 호크윈드", tgt="족장 호크윈드", tag="선택사항"}, [34]={npc="족장 호크윈드", tgt="족장 호크윈드"}, [35]={npc="족장 호크윈드", tgt="족장 호크윈드", tag="선택사항"}, [36]={npc="안투르 팰로우", tgt="안투르 팰로우", tag="선택사항", desc="캠프 서쪽에 있는 안투르 팰로우에서 수락하세요."}, [37]={npc="그룰 호크윈드", tgt="그룰 호크윈드", desc="사냥의 시작번 퀘스트를 완료한 뒤 직업 상급자에게서 시작 퀘스트를 받으세요."}, [38]={hint="간결한 쪽지를 읽고 나라체 야영지에 있는 하루트 썬더혼과 대화해야 합니다.", desc="사냥의 시작번 퀘스트를 완료한 뒤 직업 상급자에게서 시작 퀘스트를 받으세요."}, [39]={npc="하루트 썬더혼", tgt="하루트 썬더혼", desc="사냥의 시작번 퀘스트를 완료한 뒤 직업 상급자에게서 시작 퀘스트를 받으세요."}, [40]={npc="그룰 호크윈드", tgt="그룰 호크윈드", desc="사냥의 시작번 퀘스트를 완료한 뒤 직업 상급자에게서 시작 퀘스트를 받으세요."}, [41]={hint="룬으로 새겨진 쪽지를 읽고 나라체 야영지에 있는 밀라 던스트라이더와 대화해야 합니다.", desc="사냥의 시작번 퀘스트를 완료한 뒤 직업 상급자에게서 시작 퀘스트를 받으세요."}, [42]={npc="밀라 던스트라이더", tgt="밀라 던스트라이더", desc="사냥의 시작번 퀘스트를 완료한 뒤 직업 상급자에게서 시작 퀘스트를 받으세요."}, [43]={npc="예언자 레이븐페더", tgt="예언자 레이븐페더"}, [44]={hint="나라체 야영지에 있는 예언자 레이븐페더에게 의식의 물약 2개를 가져가야 합니다."}, [45]={npc="예언자 레이븐페더", tgt="예언자 레이븐페더"}, [46]={npc="예언자 레이븐페더", tgt="예언자 레이븐페더", desc="하급 대지의 현신를 보려면 Sapta를 마셔보세요."}, [47]={hint="코도 바위를 찾아 대지의 정기를 마셔야 합니다.", desc="하급 대지의 현신를 보려면 Sapta를 마셔보세요."}, [48]={npc="하급 대지의 현신", tgt="하급 대지의 현신", desc="하급 대지의 현신를 보려면 Sapta를 마셔보세요."}, [49]={npc="하급 대지의 현신", tgt="하급 대지의 현신", desc="대지의 토템를 얻으려면 퀘스트를 완료하세요."}, [50]={hint="나라체 야영지에 있는 예언자 레이븐페더에게 천연 석영을 가져가야 합니다.", desc="대지의 토템를 얻으려면 퀘스트를 완료하세요."}, [51]={npc="예언자 레이븐페더", tgt="예언자 레이븐페더", desc="대지의 토템를 얻으려면 퀘스트를 완료하세요."}, [52]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [53]={hint="글이 새겨진 쪽지를 읽고 붉은구름 고원에 있는 랑카 파샷과 대화해야 합니다."}, [54]={npc="랑카 파샷", tgt="랑카 파샷"}, [55]={npc="그룰 호크윈드", tgt="그룰 호크윈드"}, [56]={hint="푸른 쪽지를 읽고 나라체 야영지에 있는 가트 미스트러너와 대화해야 합니다."}, [57]={npc="가트 미스트러너", tgt="가트 미스트러너"}, [58]={text="붉은구름 고원를 떠나 북쪽으로 길을 따라 블러드후프 마을로 가세요."}}},
    ["01-4"] = {name="멀고어", nameA="멀고어: {a:222}", tips={{k="取捨", text="예언의 의식( → →), 지혜의 의식 및 썬더 블러프로의 여정를 수행합니다. 마지막 구간의 잠금 해제 비행 지점."}, {k="取捨", text="다음 퀘스트를 시작하기 전에 각 우물 퀘스트를 완료하세요. 타우렌에만 해당됩니다. 이미 레벨 12라면 와일드메인 우물 체인을 건너뛰세요. 타우렌에만 해당됩니다.", s={{"다음 퀘스트를 시작하기 전에 각 우물 퀘스트를 완료하세요. 타우렌에만 해당됩니다. 이미 레벨 12라면 와일드메인 우물 체인을 건너뛰세요. 타우렌에만 해당됩니다.", {race={"Tauren"}}}}}, {k="取捨", text="성난불길 협곡를 실행 중입니까? 썬더 블러프의 라하우로에서 성난불길 협곡의 트로그 및 잃어버린 가방 찾기를 선택합니다."}, {k="提醒", text="레벨 12에 경험치가 필요합니까? 북부 멀고어에서 하피를 갈거나 붉은 바위 언덕 또는 Venture Co. 광산로 향하세요. 레벨 10 잠금 해제에 대해서는 아래 클래스 퀘스트를 참조하세요.", s={{"레벨 12에 경험치가 필요합니까?"}, {"북부 멀고어에서 하피를 갈거나 붉은 바위 언덕 또는 Venture Co"}, {"광산로 향하세요"}, {"레벨 10 잠금 해제에 대해서는 아래 클래스 퀘스트를 참조하세요"}}}}, danger={[1]="순찰대와 광부들은 Venture Co. 광산 내부에 함께 모일 수 있습니다. 먼저 외부를 정리하고 클립보드를 챙겨 터널을 빠져나갑니다."}, grind={[1]={mob="긴발톱 초원늑대", note="블러드후프 마을 북쪽에 흩어져 있는 일반 몹. 한 번에 한 명의 적을 풀밭에 끌어당기고 배회하는 사람들을 감시하세요. 마즈라나체 재료를 선택하세요."}, [2]={mob="투자개발회사 현장감독", note="Venture Co. 광산 주변에는 일반 몹이 모여있습니다. 외부에서 끌어당겨 작업자와 순찰대원을 감시하세요. 광산 퀘스트와 짝을 이루세요."}, [3]={mob="성난바람일족 우두머리", note="북서쪽 멀고어에 있는 하피 캠프에 밀집된 일반 몹. 바퀴가 생기지 않도록 가장자리를 따라 당기세요. 레벨 12에 가까우면 여기서 갈아주세요."}}, supply={[1]={npc="여관주인 카우스"}, [2]={npc="하란트 아이언브레이스"}, [3]={npc="여관주인 카우스"}, [4]={npc="케나 호크스아이"}, [5]={npc="탈"}}, steps={[1]={hint="보급품 묶음을 블러드후프 마을 주위에 있는 카가 와일드후프에게 전달해야 합니다.", tag="선택사항"}, [2]={npc="카가 와일드후프", tgt="카가 와일드후프", tag="선택사항"}, [3]={npc="카가 와일드후프", tgt="카가 와일드후프", tag="선택사항"}, [4]={hint="카가의 작은 모닥불 주위에 앉은 다음, \"휴식 강화\" 강화 효과를 받을 때까지 기다려야 합니다.", tag="선택사항"}, [5]={npc="카가 와일드후프", tgt="카가 와일드후프", tag="선택사항"}, [6]={npc="카가 와일드후프", tgt="카가 와일드후프", tag="선택사항"}, [7]={npc="카가 와일드후프", tgt="카가 와일드후프", tag="선택사항", desc="수락하기 전에 무두질를 알아보십시오. 기술 요구 사항을 충족하면 제출하세요."}, [8]={hint="블러드후프 마을에 있는 바인 블러드후프에게 호크윈드의 토템을 가져가야 합니다. 나라체 야영지 외곽의 길을 따라가십시오."}, [9]={npc="바인 블러드후프", tgt="바인 블러드후프"}, [10]={hint="블러드후프 마을에 있는 여관주인 카우스에게 모피 묶음을 가져가야 합니다.", tag="선택사항"}, [11]={npc="여관주인 카우스", tgt="여관주인 카우스", tag="선택사항"}, [12]={text="귀환석를 블러드후프 마을(45.93, 64.16)의 여관주인 