    ["01-5"] = {name="죽음의 종소리 마을", tips={{k="交通", text="다른 시작 지역에서 오시나요? 브릴 남쪽의 비행선 타워에서 하차하여 서쪽으로 데스넬 방향으로 길을 따라 가세요. 위의 여행 기록을 참조하세요."}, {k="提醒", text="지하실 내부에서 각성의 시간로 시작하세요(언데드만 해당). 어둠의사제 사비스(30.84, 66.20)에서 넋 나간 좀비를 선택하세요. 퀘스트가 없다면 브릴로 가는 길을 따라가세요.", s={{"지하실 내부에서 각성의 시간로 시작하세요(언데드만 해당)", {race={"Scourge"}}}, {"어둠의사제 사비스(30.84, 66.20)에서 넋 나간 좀비를 선택하세요"}, {"퀘스트가 없다면 브릴로 가는 길을 따라가세요"}}}, {k="提醒", text="덜거덕거리는 해골을 레벨 3까지 처치한 다음 말라의 마지막 소원를 수락합니다. 레벨 6에서 또는 이 섹션을 마친 후에 브릴로 이동하세요.", s={{"덜거덕거리는 해골을 레벨 3까지 처치한 다음 말라의 마지막 소원를 수락합니다"}, {"레벨 6에서 또는 이 섹션을 마친 후에 브릴로 이동하세요"}}}}, danger={[1]="검은그물 거미굴의 좁은 터널은 양쪽에서 스파이더 팩을 끌어당길 수 있습니다. 들어가기 전에 입구를 정리하세요."}, grind={[1]={mob="흉측한 좀비", note="데스넬 북쪽에 조밀하고 대부분 중립적인 일반 몹이 있습니다. 레벨 1~2에서 넋 나간 좀비 동안 한 번에 한 명의 적을 끌어당깁니다."}, [2]={mob="검은그물거미", note="검은그물 거미굴 내부에는 밀도가 높은 일반 몹이 있습니다. 추가 당김을 피하기 위해 입구부터 단계적으로 클리어하세요. 동굴 퀘스트와 짝을 이루세요."}, [3]={mob="붉은십자군 견습마법사", note="스칼렛 캠프 동부에 밀집된 일반 몹. 광신도를 끌어당기지 않으려면 가장자리를 따라 청소하세요. 완장 퀘스트와 짝을 이루세요."}}, supply={[1]={npc="대장장이 란드"}, [2]={npc="조슈아 키엔"}, [3]={npc="조슈아 키엔"}}, steps={[1]={npc="장의사 모르도", tgt="장의사 모르도"}, [2]={hint="어둠의사제 사비스와 대화해야 합니다."}, [3]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스"}, [4]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스"}, [5]={hint="어둠의사제 사비스가 넋 나간 좀비 8명과 흉측한 좀비 8명을 처치해 달라고 부탁했습니다."}, [6]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스"}, [7]={npc="수련사제 엘레스", tgt="수련사제 엘레스"}, [8]={hint="수련사제 엘레스가 승냥이 앞발 6개와 그늘박쥐 날개 6개를 구해다 달라고 부탁했습니다."}, [9]={npc="수련사제 엘레스", tgt="수련사제 엘레스"}, [10]={npc="어둠의사제 사비스", tgt="어둠의사제 사비스"}, [11]={npc="죽음의경비병 살테인", tgt="죽음의경비병 살테인"}, [12]={npc="집행관 아렌", tgt="집행관 아렌"}, [13]={npc="수련사제 엘레스", tgt="수련사제 엘레스"}, [14]={npc="아라미스 해머핸드", tgt="아라미스 해머핸드"}, [15]={hint="덜그럭거리는 해골 12명을 처치한 후, 데스넬에 있는 어둠의사제 사비스에게 돌아가야 합니다."}, [16]={hint="데스넬과 그 주변에서 쓸만한 물건 6개를 찾아 죽음경비병 살테인에게 돌아가야 합니다."}, [17]={hint="집행관 아렌이 새끼 검은그물거미 10마리와 검은그물거미 8마리를 처치해 달라고 부탁했습니다."}, [18]={hint="사무엘 핍스를 처치하고 그의 유골을 말라의 묘로 옮긴 다음 수련사제 엘레스에게 돌아가야 합니다."}, [19]={hint="데스넬의 검은그물 거미굴에서 아라미스 해머핸드를 도와 거미줄에 감긴 희생자 6명을 구출해야 합니다."}, [20]={npc=