    ["01-6"] = {name="티리스팔 숲", nameA="티리스팔 숲: {a:159}", tips={{k="提醒", text="중요한 정보를 수락하지 않은 경우 브릴 여관에서 시작하여 첫 번째 퀘스트 배치를 선택하세요.", s={{"중요한 정보를 수락하지 않은 경우 브릴 여관에서 시작하여 첫 번째 퀘스트 배치를 선택하세요"}}}, {k="取捨", text="남동쪽 루프에서 스칼렛, 거미, 무덤 이끼 목표를 수행하세요. 북쪽 해안 멀록과 아가만드 퀘스트를 연결하세요. 근처 퀘스트를 완료하고 레벨 12의 크로스로드로 출발하세요."}, {k="取捨", text="여관 옆의 죽음의 한기 공급업체에서 굵은 실타래를 구입하세요. 포세이큰을 위한 가죽에 사용할 북쪽 해안 멀록 가죽이 여전히 필요하다면 다음 해안 여행에서 완성하세요."}, {k="取捨", text="로컬 은빛 여명회 퀘스트를 모두 완료하여 반다리온 성채를 잠금 해제하세요(오크, 트롤 및 언데드에만 해당). 일부 후속 조치는 언데드에만 해당됩니다. 크로스로드로 바로 가신다면, 두 개의 로컬 퀘스트를 마치고 떠나세요.", s={{"로컬 은빛 여명회 퀘스트를 모두 완료하여 반다리온 성채를 잠금 해제하세요(오크, 트롤 및 언데드에만 해당)", {race={"Orc", "Troll", "Scourge"}}}, {"일부 후속 조치는 언데드에만 해당됩니다", {race={"Scourge"}}}, {"크로스로드로 바로 가신다면, 두 개의 로컬 퀘스트를 마치고 떠나세요"}}}, {k="提醒", text="레벨 12 이하? 가용성과 현재 위치에 따라 붉은십자군과의 전쟁, 아가만드가 납골당 또는 은빛 여명회 퀘스트 은빛 여명회 사절, 저주받은 자들의 교단 및 전쟁의 잔재 를 수행하세요.", s={{"레벨 12 이하?"}, {"가용성과 현재 위치에 따라 붉은십자군과의 전쟁, 아가만드가 납골당 또는 은빛 여명회 퀘스트 은빛 여명회 사절, 저주받은 자들의 교단 및 전쟁의 잔재 를 수행하세요"}}}}, danger={[1]="남동쪽 묘지에서 좀비와 배회하는 영혼을 조심하세요. 상자에 갇히지 않도록 가장자리를 따라 정리하세요."}, grind={[1]={mob="붉은십자군 선교사", note="브릴 남서쪽에 흩어져 있는 일반 캐스터. 첫 번째 붉은십자군 퀘스트 중에 가장자리에서 한 번에 한 명의 적을 끌어당깁니다."}, [2]={mob="떠도는 영혼", note="남동쪽 묘지에 블러드 좀비가 있는 일반 몹이 모여있습니다. 순찰을 조심하세요. 후방 경비와 묘지 허브 퀘스트를 페어링하세요."}, [3]={mob="암흑 수련사", note="남동쪽에 있는 은빛 여명회 퀘스트 근처에 밀집된 일반 몹이 있습니다. Dark Enforcer를 피하려면 캠프 가장자리에서 한 번에 한 명의 적을 끌어내십시오. 11에서 12까지 갈아주세요."}}, supply={[1]={npc="여관주인 리니"}, [2]={npc="아베 윈터스"}, [3]={npc="여관주인 리니"}, [4]={npc="미시즈 윈터스"}, [5]={npc="도라스"}}, steps={[1]={npc="죽음의경비병 시머", tgt="죽음의경비병 시머"}, [2]={npc="고르도", tgt="고르도"}, [3]={hint="데스넬 북쪽에 있는 농장에서 티리스팔 호박을 10개 훔친 다음 브릴에 있는 연금술사 요한에게 가져가야 합니다."}, [4]={hint="어둠풀 3개를 채집해 브릴 공동묘지에 있는 초보연금술사 홀랜드에게 가져가야 합니다."}, [5]={hint="브릴에 있는 집행관 자이건드에게 붉은십자군 문서를 전달해야 합니다."}, [6]={npc="집행관 자이건드", tgt="집행관 자이건드"}, [7]={npc="연금술사 요한", tgt="연금술사 요한"}, [8]={npc="초보연금술사 홀랜드", tgt="초보연금술사 홀랜드"}, [9]={text="귀환석를 브릴(61.72, 52.05)의 여관주인 리니와 바인딩합니다."}, [10]={npc="연금술사 요한", tgt="연금술사 요한"}, [11]={hint="사로잡힌 