    ["01-7"] = {tips={{k="交通", text="다른 시작 지역에서 오시나요? 멀고어(34.30, 25.80)의 하늘감시자 고원 남쪽 부두에서 스카이커터에 탑승하세요. 발라나르 서쪽 선착장(57.90, 80.90)에서 하차하여 북쪽으로 길을 따라 센달 숲로 가세요."}, {k="提醒", text="발라나르에서 센달 숲까지 북쪽 도로를 따라 가세요. 다른 호드 연합 종족은 공유 사이드 퀘스트를 수행할 수 있습니다. 이 애드온은 경주로 잠긴 단계와 전제 조건이 누락된 단계를 숨깁니다. 레벨 1~3에서는 모임과 마을 퀘스트 전에 어린 벌드렌과 권운을 처치하세요. 아직도 12시 미만인가요? 블러드후프 마을로 마무리하세요.", s={{"발라나르에서 센달 숲까지 북쪽 도로를 따라 가세요"}, {"다른 호드 연합 종족은 공유 사이드 퀘스트를 수행할 수 있습니다"}, {"이 애드온은 경주로 잠긴 단계와 전제 조건이 누락된 단계를 숨깁니다"}, {"레벨 1~3에서는 모임과 마을 퀘스트 전에 어린 벌드렌과 권운을 처치하세요"}, {"아직도 12시 미만인가요?"}, {"블러드후프 마을로 마무리하세요"}}}, {k="取捨", text="센달 숲에서 셴다르 마을, 발라나르를 거쳐 아키르 사당까지 아일랜드 체인을 따라가세요. 레벨 12 이하? 비행선에 탑승하기 전에 과수원이나 그늘돌풍 숲 사이드 퀘스트를 수행하세요."}, {k="取捨", text="견습생과 산적 퀘스트를 함께 선택하세요. 스카이본인 경우 히포그리프 괴롭힘(히포그리프의 괴롭힘)을 추가하세요. Prideclaws 문제는 단순한 가죽 가방를 보상합니다. Meddlesome Mages는 드루이드에게 변덕스러운 조류의 우상를 제안합니다. 주술사는 불의 부름에서 충전된 불길의 토템를 얻습니다.", s={{"견습생과 산적 퀘스트를 함께 선택하세요"}, {"스카이본인 경우 히포그리프 괴롭힘(히포그리프의 괴롭힘)을 추가하세요", {race={"天裔精靈"}}}, {"Prideclaws 문제는 단순한 가죽 가방를 보상합니다"}, {"Meddlesome Mages는 드루이드에게 변덕스러운 조류의 우상를 제안합니다", {class={"DRUID"}}}, {"주술사는 불의 부름에서 충전된 불길의 토템를 얻습니다", {class={"SHAMAN"}}}}}, {k="提醒", text="섬 후속 퀘스트 다가오는 미래, 대지 고리회는 13레벨로 표시되지만 7레벨부터 받을 수 있습니다. 주요 연계를 마친 뒤 받으세요.", s={{"섬 후속 퀘스트 다가오는 미래, 대지 고리회는 13레벨로 표시되지만 7레벨부터 받을 수 있습니다"}, {"주요 연계를 마친 뒤 받으세요"}}}}, danger={[1]="센달 숲 전망대에서 뛰어내리기 전에 액션 바에 종족을 입력하세요. 점프한 후 바로 사용하세요.", [2]="알아케스 스톰체이서는 그늘돌풍 숲 캠프의 보병과 섞여 있습니다. 가장자리에서 한 번에 하나씩 당기고 가운데는 피하십시오."}, grind={[1]={mob="어린 벌드렌", note="센달 숲의 밀도가 높은 일반 몹. 한 번에 한 명의 적을 끌어당기고 근처에 있는 떼를 관찰하세요. 레벨 1~2의 시작 부분에서 그라인딩합니다."}, [2]={mob="고원 좀도둑", note="셴다르 고원에는 밀도가 높은 일반 몹이 있습니다. 그룹을 피하기 위해 캠프 가장자리에서 도적을 끌어내십시오. Criminal Element 및 Pilfered Windstones와 짝을 이루십시오."}, [3]={mob="알아케스 폭풍추격자", note="그늘돌풍 숲의 밀도가 높은 일반 몹. 보병을 피하기 위해 가장자리에서 당기십시오. Unwanted 및 Unworthy와 페어링하거나 12로 그라인딩합니다."}}, supply={[1]={npc="페브라스 스카이해머"}, [2]={npc="우알리아 선크레스트"}, [3]={npc="우알리아 선크레스트"}, [4]={npc="제프라스 시민"}, [5]={npc="에디 스라이스포지드"}, [6]={npc="제프라스 시민"}, [7]={npc="벨란디엘 파플라이트"}, [8]