desc="이미 발라나르에 있나요? 퀠라나 퀵게일가 야수 길들이기을 제공하는지 확인하세요."}, [288]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일", desc="이미 발라나르에 있나요? 퀠라나 퀵게일가 야수 길들이기을 제공하는지 확인하세요."}, [289]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [290]={hint="물가 근처에서 조련용 막대를 사용해 바람노래 집게발을 길들여야 합니다."}, [291]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [292]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [293]={hint="강풍딸기 저지대에서 조련용 막대를 사용해 심술궂은 돌풍타조를 길들여야 합니다."}, [294]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [295]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [296]={hint="강풍딸기 저지대에서 조련용 막대를 사용해 벌드렌 우두머리를 길들여야 합니다. 기술을 연습한 후 발라나르에 있는 퀠라나 퀵게일에게 조련용 막대를 돌려주어야 합니다."}, [297]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [298]={npc="퀠라나 퀵게일", tgt="퀠라나 퀵게일"}, [299]={hint="발라나르에서 퀠도라 퀵게일과 대화해야 합니다."}, [300]={npc="퀠도라 퀵게일", tgt="퀠도라 퀵게일"}, [301]={npc="에일리 파하트", tgt="낮의 탐구자 로리안"}, [302]={hint="접힌 양피지를 읽은 다음, 센달 숲에서 자이톤 실버윈드와 대화해야 합니다."}, [303]={npc="바람구체자 보로", tgt="자이톤 실버윈드"}, [304]={npc="로셀룸 스타브리즈", tgt="로셀룸 스타브리즈"}, [305]={hint="발라나르 북동쪽 폭포 주위에서 우르센드리스와 대화해야 합니다."}, [306]={npc="우르센드리스", tgt="우르센드리스"}, [307]={npc="우르센드리스", tgt="우르센드리스", desc="우렌드라가 셴다르 고원를 순찰합니다."}, [308]={hint="셴다르 고원에서 우렌드라를 찾아 처치해야 합니다.", desc="우렌드라가 셴다르 고원를 순찰합니다."}, [309]={npc="우르센드리스", tgt="우르센드리스", desc="우렌드라가 셴다르 고원를 순찰합니다."}, [310]={npc="알라나 스톰워커", tgt="Muln Earthfury", tag="선택사항", desc="멀고어 도착 시 수락하세요. 대체 수락: 알라나 스톰워커 (33.38, 22.51)."}, [311]={hint="썬더 블러프에서 투락 룬토템과 대화해야 합니다.", tag="선택사항", desc="Skycutter가 멀고어에 도달하면 시작 퀘스트를 수락합니다."}, [312]={npc="투락 룬토템", tgt="투락 룬토템", tag="선택사항", desc="Skycutter가 멀고어에 도달하면 시작 퀘스트를 수락합니다."}, [313]={npc="투락 룬토템", tgt="투락 룬토템", desc="썬더 블러프에서 텔레포트를 배운 다음 이를 사용하여 달의 숲에서 제출하세요."}, [314]={hint="\"순간이동: 달의 숲\" 주문을 이용하여 달의 숲으로 이동해야 합니다. 달의 숲에 도착하면 나이트헤이븐의 덴드리트 스타블레이즈와 대화해야 합니다.", desc="썬더 블러프에서 텔레포트를 배운 다음 이를 사용하여 달의 숲에서 제출하세요."}, [315]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈", desc="썬더 블러프에서 텔레포트를 배운 다음 이를 사용하여 달의 숲에서 제출하세요."}, [316]={text="하늘감시자 고원에서 남쪽으로 달려가 썬더 블러프까지 리프트를 타고 탈의 비행 지점(47.00, 49.83)를 알아보세요. 잠금이 해제되면 크로스로드로 날아갑니다. 그렇지 않으면 동쪽 패스를 통해 멀고어를 떠나 오무사 썬더혼(44.45, 59.15)에서 타우라조 야영지를 배운 다음 북쪽 도로를 따르세요. 크로스로드 에서 데브락 의 비행 지점(51.50, 30.34)를 배우고 귀환석 를 여관주인 부어란드 플레인즈윈드(51.99, 29.89)와 바인딩합니다."}}},
    ["02-8"] = {name="불모의 땅", nameA="불모의 땅: {a:380}", tips={{k="交通", text="4단계에서 크로스로드 비행 지점의 잠금을 해제하고 귀환석를 설정합니다. 톱니항를 처음 방문할 때 브라고크를 참조하세요. 떠날 때는 프레자 옆에서 티리스팔 숲 비행선을 기다리세요."}, {k="取捨", text="Silverpine용 무라 룬토템를 잠금 해제하려면 잊혀진 웅덩이 → 죽은 오아시스 → 변화된 생물를 수행하세요. 이 경로는 변화된 생물를 TUG보다 일찍 이동하므로 다음 정류장에서 무라 룬토템를 반납할 수 있습니다."}, {k="取捨", text="톱니항 및 타우라조 야영지 루프를 위해 북부 습지 호위, 광산 및 도난당한 전리품를 저장합니다. 톱니항를 처음 방문할 때는 해안 근처의 해적들만 처치하세요."}, {k="取捨", text="썬더 블러프 를 통과하는 경우 연금술사 자마, 하뮬 룬토템 및 영원한 이별 를 수행합니다. 레벨 16이고 통곡의 동굴 그룹이 없다면 바로 Silverpine으로 가세요."}, {k="提醒", text="성난불길 협곡는 14~16에서 선택 사항입니다. 16 미만에서는 톱니항 및 타우라조 야영지 다리 도중에 에체야키 및 하피 부대장를 수행하거나 Stagnant Oasis(약 55, 42)에서 Altered Snapjaws를 처치하세요. 떠나기 전에 완료된 퀘스트를 완료하세요.", s={{"성난불길 협곡는 14~16에서 선택 사항입니다"}, {"16 미만에서는 톱니항 및 타우라조 야영지 다리 도중에 에체야키 및 하피 부대장를 수행하거나 Stagnant Oasis(약 55, 42)에서 Altered Snapjaws를 처치하세요"}, {"떠나기 전에 완료된 퀘스트를 완료하세요"}}}}, danger={[1]="남쪽바다 포병과 해적은 톱니항 남쪽의 두 층 모두에서 끌어올 수 있습니다. 부품을 찾으러 올라가기 전에 언덕 기슭을 정리하세요."}, grind={[1]={mob="검은부리초원타조", note="크로스로드 남동쪽 개방형 평야의 밀도는 보통입니다. 레벨 12~13에서 외로운 키가 큰 스트라이더를 선택하세요. 켄타우로스 순찰대를 조심하세요."}, [2]={mob="오아시스 무쇠턱거북", note="Stagnant Oasis를 따라 밀집된 일반 몹. 해안에서 멀어져 콜카르를 지켜보세요. 진행하면서 변경된 무쇠턱거북 포탄을 수집하세요."}}, supply={[1]={npc="데브락"}, [2]={npc="여관주인 부어란드 플레인즈윈드"}, [3]={npc="자안 호크윙"}, [4]={npc="여관주인 부어란드 플레인즈윈드"}, [5]={npc="우스로크"}, [6]={npc="훌라마히"}, [7]={npc="브라고크"}, [8]={npc="그라즐릭스"}}, steps={[1]={hint="오그리마로 이동한 후 지혜의 골짜기에서 스랄과 대화해야 합니다.", tag="선택사항", desc="이미 수락했다면 수락하세요. 여전히 오그리마에 있는 경우 지혜의 골짜기의 스랄를 참조하세요."}, [2]={npc="스랄", tgt="스랄", tag="선택사항"}, [3]={npc="스랄", tgt="스랄", tag="선택사항", desc="먼저 아제로스에 오신 걸 환영합니다를 켜세요."}, [4]={text="크로스로드 에서 데브락 의 비행 지점(51.50, 30.34)를 배우고 귀환석를 여관주인 부어란드 플레인즈윈드(51.99, 29.89)와 바인딩합니다. Silverpine, 톱니항 및 타우라조 야영지에서 돌아올 때까지 보관하세요."}, [5]={hint="불모의 땅 크로스로드에 있는 톨크에게 보고해야 합니다.", tag="선택사항"}, [6]={npc="톨크", tgt="톨크", tag="선택사항"}, [7]={hint="크로스로드에 있는 셀그라 다크쏜과 대화해야 합니다.", tag="선택사항", desc="편지 전제 조건이 있는 경우에만 이 작업을 수행하십시오."}, [8]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜", tag="선택사항"}, [9]={hint="크로스로드에 있는 통가 룬토템과 대화해야 합니다.", tag="선택사항", desc="편지 전제 조건이 있는 경우에만 이 작업을 수행하십시오."}, [10]={npc="통가 룬토템", tgt="통가 룬토템", tag="선택사항"}, [11]={hint="불모의 땅에 있는 연금술사 헬브림에게 늑대 심장 견본을 가져가야 합니다.", tag="선택사항", desc="편지 전제 조건이 있는 경우에만 이 작업을 수행하십시오."}, [12]={npc="연금술사 헬브림", tgt="연금술사 헬브림", tag="선택사항"}, [13]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [14]={npc="가즈록", tgt="가즈록"}, [15]={npc="톨크", tgt="톨크"}, [16]={npc="톨크", tgt="톨크"}, [17]={npc="통가 룬토템", tgt="통가 룬토템"}, [18]={npc="연금술사 헬브림", tgt="연금술사 헬브림"}, [19]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거"}, [20]={npc="연금술사 헬브림", tgt="연금술사 헬브림"}, [21]={hint="초원타조 부리 7개를 모은 후 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오."}, [22]={hint="크로스로드에 있는 가즈록에게 랩터 머리 12개를 가져가야 합니다."}, [23]={hint="서슬갈기일족 풍수사 8마리, 서슬갈기일족 가시마술사 8마리 및 서슬갈기일족 사냥꾼 3마리를 처치한 후에 크로스로드에 있는 톨크에게 돌아가십시오."}, [24]={npc="첸의 빈 술통", npcObj=true, tag="선택사항", desc="먼저 북동쪽 가시멧돼지 캠프 바깥에 있는 통 옆에서 몹을 처치하세요."}, [25]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [26]={npc="톨크", tgt="톨크"}, [27]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [28]={npc="톨크", tgt="톨크"}, [29]={text="동부 가시멧돼지. 돌아오는 길에 보급품을 반납하고 첫 번째 사냥을 하세요."}, [30]={hint="굶주린 얼룩말이나 사나운 얼룩말을 처치하여 얼룩말 발굽 4개를 모아 크로스로드에 있는 셀그라 다크쏜에게 가져다주어야 합니다."}, [31]={hint="서슬갈기일족 흙점쟁이 8명과 서슬갈기일족 파수병 8명, 크리니그 스날스나웃을 처치해야 합니다."}, [32]={hint="크로스로드 보급품 상자를 찾아서 불모의 땅의 톨크에게 가져가 주어야 합니다."}, [33]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [34]={npc="톨크", tgt="톨크"}, [35]={npc="톨크", tgt="톨크"}, [36]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [37]={npc="가즈록", tgt="가즈록"}, [38]={npc="가즈록", tgt="가즈록", desc="두 번째 Barrens 방문 시 랩터 둥지를 위해 이것을 저장하세요."}, [39]={text="잊혀진 웅덩이: 켄타우로스 체인을 시작한 다음 하피 캠프 주위를 순환합니다."}, [40]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [41]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [42]={hint="통가 룬토템에게 발견한 내용을 보고해야 합니다."}, [43]={hint="크로스로드에 있는 연금술사 헬브림에게 버섯 포자 4개를 가져다주어야 합니다."}, [44]={hint="크로스로드 서쪽에 있는 렉타르 데스게이트에게 켄타우로스의 팔보호구 15개를 가져가야 합니다.", desc="오아시스에서 콜카르 랭글러를 처치하세요. 근처의 다른 콜카르도 팔 보호구를 떨어뜨릴 수 있습니다."}, [45]={hint="바라크 코도베인을 처치하고 그 증거로 그의 머리띠를 크로스로드 서쪽에 있는 렉타르 데스게이트에게 가져가야 합니다.", desc="랭글러에서 당겨 빼내세요. 레벨이 낮으면 그룹화하세요."}, [46]={hint="칼날바람하피의 갈퀴발톱을 8개 모아야 합니다."}, [47]={hint="불모의 땅의 굶주린 사바나 사자에게서 굶주린 사자의 발톱 7개를 모아 크로스로드에 있는 셀그라 다크쏜에게 돌아가십시오."}, [48]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [49]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트"}, [50]={npc="렉타르 데스게이트", tgt="렉타르 데스게이트", desc="톱니항 및 타우라조 야영지용으로 저장합니다. Stagnant Oasis 캠프의 소환 Verog."}, [51]={npc="통가 룬토템", tgt="통가 룬토템"}, [52]={npc="연금술사 헬브림", tgt="연금술사 헬브림"}, [53]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거"}, [54]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [55]={npc="통가 룬토템", tgt="통가 룬토템"}, [56]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거"}, [57]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [58]={text="톱니항: 첫 번째 방문에서 부두를 선택하고 해적 퀘스트를 받으세요."}, [59]={text="동쪽 도로를 따라 톱니항로 가세요. 브라고크 의 비행 지점 (63.08, 37.16)를 알아보세요."}, [60]={hint="톱니항에 있는 부두주임 디지위그에게 단단히 잠긴 상자를 가져가야 합니다."}, [61]={npc="부두주임 디지위그", tgt="부두주임 디지위그"}, [62]={npc="가즈로", tgt="가즈로"}, [63]={npc="비운의 레닉스", tgt="비운의 레닉스"}, [64]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [65]={npc="현상수배!", npcObj=true, tag="선택사항", desc="해적 선장은 더 남쪽에 있습니다. 레벨이 낮으면 건너뛰세요."}, [66]={hint="첸의 빈 술통에 대해 아는 이를 찾아야 합니다.", tag="선택사항", desc="배럴을 약탈한 경우에만 이 작업을 수행하십시오."}, [67]={npc="양조업자 드론", tgt="양조업자 드론", tag="선택사항"}, [68]={npc="양조업자 드론", tgt="양조업자 드론", tag="선택사항", desc="톱니항 및 타우라조 야영지용으로 저장합니다. 사자 송곳니, 새 신장, 도마뱀 뿔을 약탈하세요."}, [69]={hint="톱니항에 있는 가즈로를 위해 남쪽바다 해적단 약탈자 12명과 남쪽바다 해적단 포병 6명을 처치해야 합니다."}, [70]={hint="톱니항 남부의 해적 야영지 상부에서 복잡한 부품 한 줌 5개를 모은 후 톱니항에 있는 비운의 레닉스에게 가야 합니다."}, [71]={hint="롱쇼어 남작을 처치하고 그 증거로 그의 머리카락을 톱니항에 있는 가즈로에게 가져다주어야 합니다.", tag="선택사항"}, [72]={npc="가즈로", tgt="가즈로"}, [73]={npc="비운의 레닉스", tgt="비운의 레닉스"}, [74]={npc="가즈로", tgt="가즈로", tag="선택사항"}, [75]={npc="가즈로", tgt="가즈로"}, [76]={hint="부두주임 디지위그에게 가즈로의 장부를 가져가야 합니다."}, [77]={npc="부두주임 디지위그", tgt="부두주임 디지위그"}, [78]={npc="부두주임 디지위그", tgt="부두주임 디지위그"}, [79]={hint="톱니항에 있는 가즈로에게 가즈로의 장부를 돌려주어야 합니다."}, [80]={npc="가즈로", tgt="가즈로"}, [81]={npc="가즈로", tgt="가즈로", desc="두 번째 Barrens 방문 시 북부 전초기지 대포를 사용하여 이 작업을 수행하세요."}, [82]={text="남서쪽 길을 따라 Stagnant Oasis로 가세요. 그것을 지우고 크로스로드로 돌아가서 반납하세요. Silverpine에서 돌아올 때를 위해 난로를 아껴두세요."}, [83]={text="정체된 오아시스와 변형된 Snapjaws. 잠금 해제 실버파인 리드인"}, [84]={hint="죽은 오아시스를 조사한 후 크로스로드에 있는 통가에게 돌아가야 합니다."}, [85]={npc="통가 룬토템", tgt="통가 룬토템"}, [86]={npc="통가 룬토템", tgt="통가 룬토템"}, [87]={hint="크로스로드에 있는 통가 룬토템에게 변형된 무쇠턱거북 등껍질 8개를 가져다주어야 합니다.", tag="대상: 오아시스 무쇠턱거북 / 오아시스 무쇠턱거북 새끼", desc="크로스로드 남서쪽의 푸른 오아시스 또는 Stagnant Oasis에서 거북이를 처치하세요."}, [88]={npc="통가 룬토템", tgt="통가 룬토템"}, [89]={npc="통가 룬토템", tgt="통가 룬토템", desc="은빛소나무 숲의 공동 묘지 반납을 위해 이것을 저장하세요."}, [90]={npc="통가 룬토템", tgt="통가 룬토템", tag="선택사항", desc="통곡의 동굴를 선택하세요. 체인은 썬더 블러프 에서 시작됩니다."}, [91]={text="16세 이하? 건너기 전에 추가 사냥을 완료하세요"}, [92]={npc="연금술사 헬브림", tgt="연금술사 헬브림", tag="선택사항", desc="지금 썬더 블러프로 향하는 경우에만 수락하세요. 45분 남았습니다."}, [93]={text="옵션인 썬더 블러프 우회의 경우 잠금이 해제된 경우 크로스로드에서 비행하세요. 그렇지 않으면 타우라조 야영지를 통해 멀고어를 입력하고 리프트를 타고 탈의 비행 지점(47.00, 49.83)를 알아보세요. Quest 연금술사 자마는 수락 시 타이머를 시작합니다. 가능하신 분만 가져가세요."}, [94]={hint="제한 시간 내에 썬더 블러프에 있는 연금술사 자마에게 정제된 포자를 가져가야 합니다.", tag="선택사항"}, [95]={hint="하뮬 룬토템과 대화하십시오.", tag="선택사항"}, [96]={npc="연금술사 자마", tgt="연금술사 자마", tag="선택사항"}, [97]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템", tag="선택사항"}, [98]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템", tag="선택사항", desc="먼저 하뮬 룬토템를 완료하세요. 10번 정류장에서 칼림도어로 복귀한 후 통곡의 동굴를 실행합니다."}, [99]={hint="나라 와일드메인과 대화하십시오.", tag="선택사항", desc="먼저 하뮬 룬토템를 완료하세요. 10번 정류장에서 칼림도어로 복귀한 후 통곡의 동굴를 실행합니다."}, [100]={npc="나라 와일드메인", tgt="나라 와일드메인", tag="선택사항", desc="먼저 하뮬 룬토템를 완료하세요. 10번 정류장에서 칼림도어로 복귀한 후 통곡의 동굴를 실행합니다."}, [101]={npc="나라 와일드메인", tgt="나라 와일드메인", tag="선택사항", desc="그룹과 함께 통곡의 동굴를 실행하는 경우에만 나라 와일드메인 이후에 수락하세요.", star={"초승달 지팡이", {"MAGE", "PRIEST", "WARLOCK", "DRUID", "SHAMAN"}}}, [102]={npc="연금술사 자마", tgt="연금술사 자마", tag="선택사항", desc="통곡의 동굴 그룹이 있는 경우에만 수락하세요."}, [103]={npc="클라리스 포스터", tgt="클라리스 포스터", tag="선택사항", desc="정기의 봉우리의 Clarice에서 수락하세요. 나중에 공동묘지에 반납하세요."}, [104]={text="잠금이 해제되면 오그리마로 날아갑니다. 처음 방문하는 경우 크로스로드에서 시작하여 성난남녘 강를 건너 북쪽으로 듀로타 도로를 따라 가세요. 썬더 블러프에서 먼저 크로스로드로 날아갑니다. 잠금 해제 오그리마 및 도라스(45.12, 63.89)."}, [105]={npc="조르 론트리", tgt="조르 론트리", tag="선택사항", desc="오그리마의 지혜의 골짜기에서 수락하세요. 해바위 야영지 다리의 Seereth를 참조하세요."}, [106]={npc="타쇼 재기드스카", tgt="타쇼 재기드스카", desc="칼바위 언덕 리드를 천리길 경비초소로 가져가세요. 브릴의 학살자 울라그를 했다면 건너뛰세요."}, [107]={hint="천리길 경비초소에 있는 우제크과 대화하십시오.", desc="나열된 전사 트레이너에서 시작하세요. 브릴의 학살자 울라그를 수행했다면 이 분기를 건너뛰십시오."}, [108]={npc="우제크", tgt="우제크", desc="나열된 전사 트레이너에서 시작하세요. 브릴의 학살자 울라그를 수행했다면 이 분기를 건너뛰십시오."}, [109]={npc="우제크", tgt="우제크", desc="이 방어 태세 퀘스트 또는 브릴에서 학살자 울라그를 선택하세요."}, [110]={hint="불모의 땅의 천리길 경비초소에 있는 우제크에게 그슬린 비늘 5개를 가져가야 합니다.", desc="이 방어 태세 퀘스트 또는 브릴에서 학살자 울라그를 선택하세요."}, [111]={npc="우제크", tgt="우제크", desc="이 방어 태세 퀘스트 또는 브릴에서 학살자 울라그를 선택하세요."}, [112]={npc="우제크", tgt="우제크", tag="선택사항", desc="크로스로드를 처음 통과할 때 무기 퀘스트를 계속하세요."}, [113]={hint="불모의 <name>에 있는 툰그림 파이어게이즈와 대화하십시오.", tag="선택사항", desc="크로스로드를 처음 통과할 때 무기 퀘스트를 계속하세요."}, [114]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="크로스로드를 처음 통과할 때 무기 퀘스트를 계속하세요."}, [115]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="가시멧돼지 캠프의 상자를 열기 전에 경비병을 처치하세요."}, [116]={hint="불모의 땅에 있는 툰그림 파이어게이즈에게 단조된 강철 주괴를 가져가야 합니다.", tag="선택사항", desc="가시멧돼지 캠프의 상자를 열기 전에 경비병을 처치하세요."}, [117]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="가시멧돼지 캠프의 상자를 열기 전에 경비병을 처치하세요."}, [118]={npc="크라날 피스", tgt="크라날 피스", desc="산기슭에서 오르막길을 따라 가세요."}, [119]={hint="듀로타에 있는 텔프 줄람에게 희미한 불씨의 횃불을 가져가야 합니다.", desc="산기슭에서 오르막길을 따라 가세요."}, [120]={npc="텔프 줄람", tgt="텔프 줄람", desc="산기슭에서 오르막길을 따라 가세요."}, [121]={npc="텔프 줄람", tgt="텔프 줄람", desc="불모의 땅 가시멧돼지에게서 타르를 구하고 불타는 칼날단 이교도에게서 시약 주머니를 구하세요."}, [122]={hint="듀로타에 있는 텔프 줄람에게 불붙인 타르 1개와 시약 주머니 1개를 가져가야 합니다.", desc="불모의 땅 가시멧돼지에게서 타르를 구하고 불타는 칼날단 이교도에게서 시약 주머니를 구하세요."}, [123]={npc="텔프 줄람", tgt="텔프 줄람", desc="불모의 땅 가시멧돼지에게서 타르를 구하고 불타는 칼날단 이교도에게서 시약 주머니를 구하세요."}, [124]={npc="텔프 줄람", tgt="텔프 줄람", desc="불의 정령과 싸우기 전에 성소 옆에서 Sapta를 마셔보세요."}, [125]={hint="하급 불의 현신을 물리친 다음 희미한 불꽃의 화로에 타오르는 불꽃을 넣어야 합니다.", tag="대상: 하급 불의 현신 / 화염의 현신", desc="불의 정령과 싸우기 전에 성소 옆에서 Sapta를 마셔보세요."}, [126]={npc="희미한 불꽃의 화로", npcObj=true, desc="불의 정령과 싸우기 전에 성소 옆에서 Sapta를 마셔보세요."}, [127]={npc="희미한 불꽃의 화로", npcObj=true, desc="불의 토템를 얻으려면 퀘스트를 완료하세요.", star={"충전된 불길의 토템", {"SHAMAN"}}}, [128]={hint="불모의 땅에 있는 크라날 피스에게 영원한 불꽃의 횃불을 가져가야 합니다.", desc="불의 토템를 얻으려면 퀘스트를 완료하세요."}, [129]={npc="크라날 피스", tgt="크라날 피스", desc="불의 토템를 얻으려면 퀘스트를 완료하세요.", star={"충전된 불길의 토템", {"SHAMAN"}}}, [130]={npc="투락 룬토템", tgt="투락 룬토템", desc="대체 수락: 북부 멀고어(33.42, 22.13)의 Hanna Lighthoof."}, [131]={hint="달의 숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다.", desc="멀고어 북부에 있는 Hanna Lighthoof도 이 퀘스트를 제공합니다."}, [132]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈", desc="멀고어 북부에 있는 Hanna Lighthoof도 이 퀘스트를 제공합니다."}, [133]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [134]={hint="빈 공포의 안개봉우리 견본병을 봉우리 정상까지 가지고 가서 꼭대기 물웅덩이의 물을 채취해야 합니다."}, [135]={npc="통가 룬토템", tgt="통가 룬토템"}, [136]={npc="통가 룬토템", tgt="통가 룬토템", desc="뱀뿌리를 구매하거나 거래하세요. Barrens kodos에서 코도 뿔 5개를 획득하세요."}, [137]={hint="크로스로드의 통가 룬토템이 치료제를 만들 수 있도록 뱀뿌리 5개와 코도 뿔 5개를 갖다주어야 합니다.", desc="뱀뿌리를 구매하거나 거래하세요. Barrens kodos에서 코도 뿔 5개를 획득하세요."}, [138]={npc="통가 룬토템", tgt="통가 룬토템", desc="뱀뿌리를 구매하거나 거래하세요. Barrens kodos에서 코도 뿔 5개를 획득하세요."}, [139]={npc="통가 룬토템", tgt="통가 룬토템", desc="선물 10 크로스로드 북쪽의 병약한 가젤. 순간이동를 Dendrite로 전환합니다."}, [140]={hint="불모의 땅 북부에 퍼져 있는 병든 가젤 10마리를 찾아 잘 듣는 동물 연고를 발라서 치료해야 합니다. 병든 가젤은 크로스로드를 동서로 가로지르는 길의 북쪽에 있다고 합니다.", desc="선물 10 크로스로드 북쪽의 병약한 가젤. 순간이동를 Dendrite로 전환합니다."}, [141]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈", desc="선물 10 크로스로드 북쪽의 병약한 가젤. 순간이동를 Dendrite로 전환합니다."}, [142]={npc="덴드리트 스타블레이즈", tgt="덴드리트 스타블레이즈"}, [143]={hint="썬더 블러프 장로의 봉우리에 있는 투락 룬토템에게 돌아가야 합니다."}, [144]={npc="투락 룬토템", tgt="투락 룬토템"}, [145]={text="오그리마를 떠나 프레자의 플랫폼(50.82, 13.54)에서 티리스팔 숲 비행선에 탑승하세요. 크로스로드에 난로를 유지하세요."}}},
    ["05-d2"] = {name="Hall of Thanes", entrance="아이언포지 27.63, 47.83", pickup="체계적인 업적 실행을 위해서만 아이언포지 여행을 하십시오. 언더시티에서 Silverpine, 힐스브래드 및 Arathi를 거쳐 저습지 및 던 알가즈를 거쳐 남쪽으로 던 모로로 이동합니다. 호드 연합 전제 조건 수락이 확인되지 않았습니다.", pickupS={{"체계적인 업적 실행을 위해서만 아이언포지 여행을 하십시오"}, {"언더시티에서 Silverpine, 힐스브래드 및 Arathi를 거쳐 저습지 및 던 알가즈를 거쳐 남쪽으로 던 모로로 이동합니다"}, {"호드 연합 전제 조건 수락이 확인되지 않았습니다"}}, tips={{k="動線", text="입구 → 앤빌마의 휴식처의 파들린 → 검은무쇠 소환사의 마그마투스 → 순찰 중인 리버 → 왕실 금고의 Durgan."}, {k="說明", text="지하 지도, 구 아이언포지 침입, 안식 없는 죽음, 해묵은 원한, 중요한 가보, 이해의 조약은 얼라이언스 퀘스트이며, 호드는 수락할 수 없습니다.", s={{"지하 지도, 구 아이언포지 침입, 안식 없는 죽음, 해묵은 원한, 중요한 가보, 이해의 조약은 얼라이언스 퀘스트이며, 호드는 수락할 수 없습니다"}}}, {k="說明", text="전리품이나 업적을 위해 달려보세요. 보스에는 팔드림 앤빌마, 마그마투스, 약탈골렘 및 드루겐 더지해머 가 포함됩니다.", s={{"전리품이나 업적을 위해 달려보세요"}, {"보스에는 팔드림 앤빌마, 마그마투스, 약탈골렘 및 드루겐 더지해머 가 포함됩니다"}}}, {k="說明", text="호드 연합 반납 위치가 확인되지 않았습니다.", s={{"호드 연합 반납 위치가 확인되지 않았습니다"}}}, {k="取捨", text="레벨링하는 동안 건너 뛰세요. 레거시 업적을 달성하려면 들어가기 전에 그룹을 구성하세요. 얼라이언스 연합 캐피탈 가드와 PvP 규칙으로 인해 입장이 더 어려워집니다."}, {k="說明", text="아이언포지의 알현실에 있는 옆문을 통해 Old 아이언포지로 이동한 후 던전 포털로 가는 통로를 따라가세요. 눈보라는 호드 연합가 얼라이언스 연합 영역을 통해 들어갈 수 있음을 확인합니다.", s={{"아이언포지의 알현실에 있는 옆문을 통해 Old 아이언포지로 이동한 후 던전 포털로 가는 통로를 따라가세요"}, {"눈보라는 호드 연합가 얼라이언스 연합 영역을 통해 들어갈 수 있음을 확인합니다"}}}}, steps={[1]={text="Hall of Thanes 입구"}}},
    ["05-d1"] = {name="성난불길 협곡", entrance="오그리마 52.60, 49.00", pickup="잠금 해제, 크로스로드 비행 지점, 라하우로에서 잃어버린 가방 찾기 및 성난불길 협곡의 트로그의 경우 썬더 블러프로 비행한 다음, 오그리마에서 스랄로 내부의 배신자 및 내부의 배신자를 수행합니다. 어둠의 틈에서 야수 처단를 선택하세요. 언더시티를 잠금 해제한 경우 교차하는 동안 바리마트라스에서 파괴해야 할 힘를 받으세요.", pickupS={{"잠금 해제, 크로스로드 비행 지점, 라하우로에서 잃어버린 가방 찾기 및 성난불길 협곡의 트로그의 경우 썬더 블러프로 비행한 다음, 오그리마에서 스랄로 내부의 배신자 및 내부의 배신자를 수행합니다"}, {"어둠의 틈에서 야수 처단를 선택하세요"}, {"언더시티를 잠금 해제한 경우 교차하는 동안 바리마트라스에서 파괴해야 할 힘를 받으세요"}}, tips={{k="動線", text="입구에서 트로그 제거 → 첫 번째 홀의 오른쪽 경사로로 오글플린트 및 마우르 그림토템로 이동 → 용암 다리를 건너 욕망의 타라가만로 이동 → 불타는 칼날단 이교도 제거 → 바잘란로 오른쪽 경사로 위로 올라간 후 끝에 기원사 제로쉬가 있습니다."}, {k="取捨", text="잠금 해제 내부의 배신자 들어가기 전. 성난불길 협곡를 한번 실행하고 어둠의 틈 근처에 있는 야수 처단를 켜세요. 경로의 도시 방문을 위해 썬더 블러프 및 언더시티 퀘스트를 저장하세요."}, {k="說明", text="오그리마에 어둠의 틈에 들어가 통로를 따라 파란색 던전 포탈로 내려가세요.", s={{"오그리마에 어둠의 틈에 들어가 통로를 따라 파란색 던전 포탈로 내려가세요"}}}}, steps={[1]={npc="라하우로", tgt="라하우로"}, [2]={npc="라하우로", tgt="라하우로"}, [3]={npc="바리마트라스", tgt="바리마트라스", tag="선택사항", desc="언더시티를 건너뛴 경우 그룹에 파괴해야 할 힘를 공유하도록 요청하세요. 그렇지 않으면 나머지 4개를 공유하세요."}, [4]={npc="스랄", tgt="스랄"}, [5]={hint="오그리마에 있는 스랄에게 부관의 휘장을 가져가야 합니다."}, [6]={npc="스랄", tgt="스랄"}, [7]={npc="스랄", tgt="스랄", preText="내부의 배신자"}, [8]={hint="부관의 휘장을 네루 파이어블레이드에게 가져간 다음 대화를 해야 합니다. 네루 파이어블레이드가 당신을 불타는칼날단의 일원으로 믿고 있는지 확인한 다음 오그리마에 있는 스랄에게 돌아가야 합니다."}, [9]={npc="스랄", tgt="스랄"}, [10]={npc="스랄", tgt="스랄", preText="내부의 배신자"}, [11]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드"}, [12]={text="성난불길 협곡 입구"}, [13]={hint="오그리마에 있는 성난불길 협곡을 찾아 성난불길 트로그 8마리와 성난불길일족 주술사 8마리를 처치하고 썬더 블러프에 있는 라하우로에게 돌아가야 합니다.", desc="위치: 경사면을 따라 첫 번째 트로그 전당으로 가세요. 주술사와 트로그를 처치하세요.", spot="경사면을 따라 첫 번째 트로그 전당으로 가세요. 주술사와 트로그를 처치하세요."}, [14]={hint="성난불길 협곡에서 마우리 그림토템의 시체를 찾아 도움이 될 만한 것들을 찾아야 합니다.", desc="위치: 첫 번째 트로그 홀에서 오른쪽 경사로로 가세요. 오글플린트 뒤에 있는 시체를 찾으세요.", spot="첫 번째 트로그 홀에서 오른쪽 경사로로 가세요. 오글플린트 뒤에 있는 시체를 찾으세요."}, [15]={npc="마우르 그림토템", tgt="마우르 그림토템", tag="게임 내 확인이 필요합니다", spot="첫 동굴 홀 오른쪽 경사로 위, 오글플린트 뒤 시체"}, [16]={npc="마우르 그림토템", tgt="마우르 그림토템", tag="게임 내 확인이 필요합니다", preText="잃어버린 가방 찾기"}, [17]={hint="성난불길 협곡으로 가서 욕망의 타라가만을 제거한 다음 그의 심장을 오그리마에 있는 네루 파이어블레이드에게 가져가야 합니다.", desc="위치: 기본 경로로 돌아갑니다. 욕망의 타라가만는 용암 교차로의 플랫폼에 있습니다.", spot="기본 경로로 돌아갑니다. 욕망의 타라가만는 용암 교차로의 플랫폼에 있습니다."}, [18]={hint="언더시티에 있는 바리마트라스에게 어둠의 주문서와 황천의 마법서를 가져가야 합니다.", tag="선택사항", desc="위치: 용암 다리를 건너 마지막 보스를 향해 불타는 칼날단 이교도들을 처치하세요.", spot="용암 다리를 건너 마지막 보스를 향해 불타는 칼날단 이교도들을 처치하세요."}, [19]={hint="바잘란과 기원사 제로쉬를 제거한 다음 오그리마에 있는 스랄에게 돌아가야 합니다.", desc="위치: 바잘란 방향으로 오른쪽 진입로를 택한 후 기원사 제로쉬 방향으로 기본 경로로 돌아갑니다.", spot="바잘란 방향으로 오른쪽 진입로를 택한 후 기원사 제로쉬 방향으로 기본 경로로 돌아갑니다."}, [20]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드"}, [21]={npc="스랄", tgt="스랄"}, [22]={npc="스랄", tgt="스랄", preText="내부의 배신자"}, [23]={hint="오그리마에 있는 네루 파이어블레이드와 대화하십시오."}, [24]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드"}, [25]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드", preText="내부의 배신자"}, [26]={hint="오그리마에 있는 스랄에게 알아낸 것을 보고해야 합니다."}, [27]={npc="스랄", tgt="스랄"}, [28]={hint="썬더 블러프에 있는 라하우로에게 그림토템 가방을 가져가야 합니다."}, [29]={npc="라하우로", tgt="라하우로"}, [30]={npc="라하우로", tgt="라하우로"}, [31]={npc="바리마트라스", tgt="바리마트라스", tag="선택사항"}}},
    ["02-9"] = {name="은빛소나무 숲", tips={{k="交通", text="첫 번째 방문에서 공동묘지로 가서 비행 지점를 잠금 해제하세요. 돌아오는 길에 귀환석를 사용하여 크로스로드로 돌아갑니다. 귀환석가 쿨다운 중이라면 오그리마 비행선을 타세요."}, {k="取捨", text="잠금 해제 앰버밀 조사 및 Forever 퀘스트 길목의 파수꾼, 그런 다음 하나의 루프에서 앰버밀에서 두 가지를 모두 수행합니다. 대마법사의 지팡이의 마법사를 죽이기 전에 앰버밀 조사를 켜십시오."}, {k="取捨", text="장작나무 마을에서 99와 죽음의 비법를 함께 수행합니다. 99를 켜고 아루갈의 계략와 확산 저지를 가져와 Greymane Wall에서 둘 다 수행하세요."}, {k="取捨", text="레벨 20의 불모의 땅으로 돌아가십시오. 시작하지 않은 경우 호위 엘런드 경호, 매복 장작나무 마을 매복 및 그림자송곳니 성채 체인을 건너뛰십시오. 공동묘지에서 돌아올 때 죽음의 비법 또는 썩은가죽일족의 기원와 같은 활성 언더시티 퀘스트를 완료하세요."}, {k="取捨", text="레벨 19에서 힐스브래드 구릉지로의 여정를 수락하고 힐스브래드 구릉지에 타렌 밀농장용으로 저장합니다. 별도의 여행을 피하기 위해 먼저 불모의 땅으로 돌아가십시오."}, {k="提醒", text="레벨 20 이하? Greymane Wall(약 43, 81) 또는 앰버밀(약 63, 65)에서 솔로 퀘스트를 완료하고 일반 몹을 처치하세요. 그룹이 있으면 그림자송곳니 성채를 실행하세요. Quest 우르의 책에는 레벨 16이 필요하고, 아루갈의 최후 및 그림자송곳니 성채의 죽음추적자에는 레벨 18이 필요합니다.", s={{"레벨 20 이하?"}, {"Greymane Wall(약 43, 81) 또는 앰버밀(약 63, 65)에서 솔로 퀘스트를 완료하고 일반 몹을 처치하세요"}, {"그룹이 있으면 그림자송곳니 성채를 실행하세요"}, {"Quest 우르의 책에는 레벨 16이 필요하고, 아루갈의 최후 및 그림자송곳니 성채의 죽음추적자에는 레벨 18이 필요합니다"}}}}, danger={[1]="레벨 24~25 엘리트 Sons of 아루갈 순찰 은빛소나무 숲. 그들에게 넓은 공간을 제공하십시오. 누군가 당신을 발견하면 숲에서 벗어나십시오.", [2]="아루갈의 아들들도 장작나무 마을에서 그레이메인 성벽까지의 도로를 순찰합니다. 매복 후 떠나고 벽을 따라 몹을 쫓지 마십시오."}, grind={[1]={mob="달라란 요술사", note="앰버밀 외부의 일반 원거리 몹 밀도는 보통입니다. 길가를 먼저 청소하세요. 지형을 사용하여 몹을 출입구에서 멀리 끌어내십시오."}, [2]={mob="달라란 마술사", note="달라란 퀘스트 지역 근처 앰버밀 외부의 일반 원거리 몹 밀도는 보통입니다. 한 번에 한 명의 적을 끌어당기고 경비병을 감시하세요."}, [3]={mob="병든 피난민", note="그레이메인 성벽 근처의 밀집된 일반 몹. 길가에 있는 적을 한 번에 하나씩 끌어당깁니다. 떠나기 전에 레벨 20에 도달할 때까지 적을 처치하세요."}}, supply={[1]={npc="카로스 라조크"}, [2]={npc="여관주인 베이츠"}, [3]={npc="세바스티안 멜로체"}, [4]={npc="여관주인 베이츠"}, [5]={npc="에드윈 할리"}, [6]={npc="패트라이스 드위어"}, [7]={npc="여관주인 리니"}, [8]={npc="여관주인 리니"}, [9]={npc="마이클 가레트"}, [10]={npc="토마스 모던"}, [11]={npc="에제키엘 그레이브"}}, steps={[1]={text="듀로타 비행선 타워에서 프레자(50.82, 13.54)로 티리스팔 숲 경로를 확인하세요. 브릴 남쪽에서 내려 언더시티 방향으로 길을 따라 가세요. 크로스로드에 난로를 유지하세요."}, [2]={text="마이클 가레트(63.25, 48.56)에게서 언더시티 의 비행 지점를 알아보세요. 잠금이 해제되면 무덤으로 날아가세요. 그렇지 않으면 도시를 떠나 티리스팔의 남서쪽 도로를 타고 은빛소나무 숲로 가세요."}, [3]={text="무덤에서 수락 → 북부 농장"}, [4]={text="카로스 라조크(45.62, 42.60)에게서 무덤 비행 지점를 배우세요. 현재의 난로를 유지하세요."}, [5]={hint="공동묘지에 있는 무라 룬토템과 대화하십시오."}, [6]={npc="무라 룬토템", tgt="무라 룬토템"}, [7]={hint="은빛소나무 숲에 있는 연금술사 렌퍼럴에게 요한의 연구 결과를 전달해야 합니다.", tag="선택사항"}, [8]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", tag="선택사항"}, [9]={hint="은빛소나무 숲에 있는 유리브의 무덤에 클라리스의 펜던트를 가져다 놓아야 합니다.", tag="선택사항"}, [10]={npc="유리브의 묘비", npcObj=true, tag="선택사항"}, [11]={npc="달라 던위버", tgt="달라 던위버"}, [12]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉"}, [13]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉"}, [14]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴"}, [15]={npc="어둠의사제 알리스터", tgt="어둠의사제 알리스터"}, [16]={hint="공동묘지에 있는 달라 던위버가 달의분노일족 백발전사 5마리를 처치해 달라고 부탁했습니다."}, [17]={hint="죽음의 농장에서 썩은가죽 놀들을 처치하십시오. 나이트래쉬가 나타나면 그녀를 처치하십시오."}, [18]={hint="죽음추적자 쿠인 요릭과 레인 요릭을 찾아야 합니다."}, [19]={npc="레인 요릭", tgt="레인 요릭"}, [20]={npc="레인 요릭", tgt="레인 요릭"}, [21]={hint="변색된 검은늑대 심장 3개를 모아 공동묘지에 있는 연금술사 렌퍼럴에게 가져가야 합니다."}, [22]={npc="죽음의추적자 엘런드", tgt="죽음의추적자 엘런드", tag="선택사항"}, [23]={hint="레인 요릭이 있는 곳까지 늑대들을 물리치고 엘런드를 경호해야 합니다.", tag="선택사항"}, [24]={npc="레인 요릭", tgt="레인 요릭", tag="선택사항"}, [25]={npc="레인 요릭", tgt="레인 요릭", tag="퀘스트 엘런드 경호 필요, 선택사항"}, [26]={hint="불곰 심장 6개와 땅거미 점액 6개를 모아 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다."}, [27]={npc="달라 던위버", tgt="달라 던위버"}, [28]={npc="달라 던위버", tgt="달라 던위버"}, [29]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉"}, [30]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉"}, [31]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴"}, [32]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴"}, [33]={hint="공동묘지에 있는 고위집행관 하드렉에게 죽음추적자 보고서를 가져가야 합니다.", tag="퀘스트 엘런드 경호 필요, 선택사항"}, [34]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉", tag="퀘스트 엘런드 경호 필요, 선택사항"}, [35]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉", tag="퀘스트 죽음추적자의 보고 필요, 선택사항"}, [36]={hint="공동묘지에 있는 연금술사 렌퍼럴과 대화해야 합니다.", tag="퀘스트 죽음추적자의 보고 필요, 선택사항"}, [37]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", tag="퀘스트 죽음추적자의 보고 필요, 선택사항"}, [38]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", tag="퀘스트 렌퍼럴과 대화 필요, 선택사항"}, [39]={text="북부 농장 → 호숫가 횡단 → 남쪽 도로의 상자"}, [40]={hint="공동묘지에 있는 달라 던위버에게 아루갈의 치료법을 가져가야 합니다.