    ["05-d3"] = {name="로데론의 폐허", entrance="언더시티 72.41, 11.37", pickup="브릴의 Linnea로 후방 경비를 확인하세요. Linnea는 또한 Orcs 및 언데드에 후방 경비를 제공합니다. 비행선에서 내린 후 리네아와 크리스토프를 방문하세요. 공동묘지에서 Tabitha의 두려움에 찬 부탁를 가져와 죽음의 비법 → 죽음의 비법 → 죽음의 비법을 완료하세요. Grave와 Morbin의 Apothecium을 참조하세요. 던전 다리에 대한 퀘스트 핸드인 세트 6개를 모두 저장하세요.", pickupS={{"브릴의 Linnea로 후방 경비를 확인하세요"}, {"Linnea는 또한 Orcs 및 언데드에 후방 경비를 제공합니다", {race={"Orc", "Scourge"}}}, {"비행선에서 내린 후 리네아와 크리스토프를 방문하세요"}, {"공동묘지에서 Tabitha의 두려움에 찬 부탁를 가져와 죽음의 비법 → 죽음의 비법 → 죽음의 비법을 완료하세요"}, {"Grave와 Morbin의 Apothecium을 참조하세요"}, {"던전 다리에 대한 퀘스트 핸드인 세트 6개를 모두 저장하세요"}}, tips={{k="動線", text="입구 → 왕의 골목에서 쇠퇴송곳니 → 언데드 클리어 → 남작을 죽이고 문장을 약탈 → 묘지에서 라스마엘, 서쪽에서 에드워드. 시장의 포세이큰과 남서쪽 굴뚝의 빅터는 선택 사항입니다."}, {k="取捨", text="호드 연합는 레벨 16~20에서 실행 우선순위를 지정할 수 있습니다. Silverpine 레시피 체인을 완료하지 않은 경우, 공동묘지 퀘스트를 먼저 수행하여 쇠퇴송곳니가 체인에 포함되도록 하세요."}, {k="說明", text="포털은 언더시티 위의 로데론의 폐허에 있습니다. 언더시티 지도 좌표를 사용하세요. 엘리베이터를 타고 내려가는 대신 폐허 안으로 들어가 왼쪽 돌계단을 올라갑니다.", s={{"포털은 언더시티 위의 로데론의 폐허에 있습니다"}, {"언더시티 지도 좌표를 사용하세요"}, {"엘리베이터를 타고 내려가는 대신 폐허 안으로 들어가 왼쪽 돌계단을 올라갑니다"}}}}, steps={[1]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아", desc="브릴에서 이 작업을 완료했다면 건너뛰세요."}, [2]={hint="피투성이 좀비 8명과 떠도는 영혼 8명을 처치한 다음 초소로 돌아가 리니아에게 보고해야 합니다.", desc="브릴에서 이 작업을 완료했다면 건너뛰세요."}, [3]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아", desc="브릴에서 이 작업을 완료했다면 건너뛰세요."}, [4]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아", preText="후방 경비"}, [5]={hint="죽음경비병 리니아에게 너덜토막의 심장을 가져가야 합니다."}, [6]={npc="죽음의경비병 리니아", tgt="죽음의경비병 리니아"}, [7]={npc="죽음경비병 크리스토프", tgt="죽음경비병 크리스토프", desc="선행 퀘스트 후방 경비에는 종족 제한이 있습니다. 다른 종족은 크리스토프가 이 퀘스트를 제공하는지 확인하세요.", preText="후방 경비"}, [8]={npc="타비사 하트위버", tgt="타비사 하트위버"}, [9]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", desc="무덤에서 이 작업을 시작했다면 현재 진행 상황을 계속 진행하세요."}, [10]={hint="불곰 심장 6개와 땅거미 점액 6개를 모아 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다.", desc="무덤에서 이 작업을 시작했다면 현재 진행 상황을 계속 진행하세요."}, [11]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="무덤에서 이 작업을 시작했다면 현재 진행 상황을 계속 진행하세요."}, [12]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="장작나무 마을 여관에서 버나드의 일기를 찾으세요.", preText="죽음의 비법"}, [13]={hint="장작나무 마을에서 베랄드의 일지를 찾아 공동묘지에 있는 연금술사 렌퍼럴에게 가져가야 합니다.", desc="장작나무 마을 여관에서 버나드의 일기를 찾으세요."}, [14]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", desc="장작나무 마을 여관에서 버나드의 일기를 찾으세요."}, [15]={npc="연금술사 렌퍼럴", tgt="연금술사 렌퍼럴", preText="죽음의 비법"}, [16]={hint="호수늪지이끼 6개, 호수덤불이끼 6개, 그리고 굳어진 종양 1개를 언더시티에 있는 수석 연금술사 파라넬에게 가져가야 합니다."}, [17]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [18]={npc="시어도어 그리프스", tgt="시어도어 그리프스", preText="죽음의 비법"}, [19]={npc="모빈 라이트베인", tgt="모빈 라이트베인"}, [20]={text="로데론의 폐허 입구"}, [21]={hint="로데론의 폐허에 있는 쇠퇴송곳니에게서 고독성 변종을 채취해 언더시티에 있는 시어도어 그리프스에게 가져가야 합니다.", desc="위치: 네루비안을 지나서 왕의 골목를 순찰하는 쇠퇴송곳니를 찾으세요.", spot="네루비안을 지나서 왕의 골목를 순찰하는 쇠퇴송곳니를 찾으세요."}, [22]={hint="언더시티에 있는 모빈 라이트베인을 위해 로데론의 폐허에서 온전한 사지 25개를 수집해야 합니다.", desc="위치: 왕의 골목, 전망대 및 묘지를 통과하는 주요 경로를 따라 언데드를 약탈하세요.", spot="왕의 골목, 전망대 및 묘지를 통과하는 주요 경로를 따라 언데드를 약탈하세요."}, [23]={npc="흉측한 머리", npcObj=true, tag="게임 내 확인이 필요합니다", desc="남작의 머리를 약탈하고 사용하세요. 호드 연합는 11월 6일 핫픽스 이후 15시에 이를 선택할 수 있습니다."}, [24]={npc="로데론의 문장", npcObj=true, tag="게임 내 확인이 필요합니다", desc="로데론의 문장의 스파이더 안뜰, 타워 및 잠긴 방을 확인하세요."}, [25]={hint="로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다.", desc="위치: 라스마엘의 묘지 서쪽에 있는 구울 옆에서 에드워드를 찾으세요. 순서: 신체에 접근하기 전에 25단계를 수행하십시오.", spot="라스마엘의 묘지 서쪽에 있는 구울 옆에서 에드워드를 찾으세요."}, [26]={hint="브릴의 죽음경비병 크리스토프를 위해 로데론의 폐허에 있는 라스마엘을 처치해야 합니다.", desc="위치: 당기기 전에 로데론 묘지의 라스마엘 주변 공간을 정리하세요.", spot="당기기 전에 로데론 묘지의 라스마엘 주변 공간을 정리하세요."}, [27]={npc="시어도어 그리프스", tgt="시어도어 그리프스"}, [28]={npc="모빈 라이트베인", tgt="모빈 라이트베인"}, [29]={hint="로데론의 문장을 언더시티에 있는 오란 스네이크레이드에게 가져가야 합니다.", desc="로데론의 문장의 스파이더 안뜰, 타워 및 잠긴 방을 확인하세요."}, [30]={npc="오란 스네이크레이드", tgt="오란 스네이크레이드"}, [31]={hint="흉측한 머리를 언더시티에 있는 수석 연금술사 파라넬에게 전달해야 합니다.", desc="남작의 머리를 약탈하고 사용하세요. 호드 연합는 11월 6일 핫픽스 이후 15시에 이를 선택할 수 있습니다."}, [32]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [33]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", preText="끝없는 고통"}, [34]={hint="남작의 머리카락을 언더시티에 있는 오스마르의 몸으로 가져가야 합니다."}, [35]={npc="미완성 누더기골렘", tgt="미완성 누더기골렘"}, [36]={npc="미완성 누더기골렘", tgt="미완성 누더기골렘", preText="끝없는 고통"}, [37]={hint="알아낸 정보를 언더시티에 있는 수석 연금술사 파라넬에게 보고해야 합니다."}, [38]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [39]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="무역에서 첫 번째 시약, 트레이너가 만든 약초, 도적 지구에서 독을 찾으세요.", preText="끝없는 고통"}, [40]={hint="언더시티의 수석 연금술사 파라넬을 위해 상업 지구에 있는 타우니 그리제트에게서 유독한 해골갓을, 전문 약초채집사 근처에서 물집풀을, 도적 지구 독 상인에게서 괴로움의 정수를 입수해야 합니다.", desc="무역에서 첫 번째 시약, 트레이너가 만든 약초, 도적 지구에서 독을 찾으세요."}, [41]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="무역에서 첫 번째 시약, 트레이너가 만든 약초, 도적 지구에서 독을 찾으세요."}, [42]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="유골 위의 장치에 혈청을 주입합니다.", preText="끝없는 고통"}, [43]={hint="수석 연금술사 파라넬이 말한 대로 오스마르의 몸 위 장치에 쉭쉭거리는 혈청을 주입해야 합니다.", desc="유골 위의 장치에 혈청을 주입합니다."}, [44]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="유골 위의 장치에 혈청을 주입합니다."}, [45]={npc="죽음경비병 크리스토프", tgt="죽음경비병 크리스토프"}, [46]={npc="타비사 하트위버", tgt="타비사 하트위버"}}},
    ["02-10"] = {name="불모의 땅", nameA="불모의 땅: {a:392} & {a:378}", shortA="불모의 땅: {a:392} +", tips={{k="交通", text="북쪽 순환을 마친 다음 크로스로드로 향하고 방향을 틀어 톱니항로 날아갑니다. 잠금 해제 첫 방문시 타우라조 야영지 비행 지점."}, {k="取捨", text="부족 간의 전쟁, 그 이름은 올그라 및 타오르는 증오 를 함께 수행하십시오. 타오르는 증오에 필요한 60개의 엄니를 확보하세요. 목표 레벨에 도달했다면 나머지 농사는 건너뛰세요."}, {k="取捨", text="돌발톱 산맥의 다음 정류장에서 진질에게 보내는 편지 및 지즈 피직스를 반납하세요. 지금 동굴이끼거미알용 계란을 모아서 다음에 톱니항를 통과할 때 돌려주세요. 잿빛 골짜기용 잿빛 골짜기 사냥 대회 및 옵션 전쟁노래부족 보고서를 저장합니다."}, {k="取捨", text="현상 수배: 브루즈의 레벨 20 엘리트, 반격!의 켄타우로스 이벤트 및 국경 퀘스트 억울한 누명, 정당한 응징을 위한 그룹입니다. 추가 풀을 피하려면 북부 전초기지 호위를 건너뛰세요."}, {k="取捨", text="광부의 전리품은 드롭률이 낮습니다. 떨어지지 않으면 계속 진행하세요. 네 가지 희귀 퀘스트는 희귀를 찾아 해당 아이템을 약탈한 경우에만 시작됩니다."}, {k="提醒", text="레벨 23 이하인가요? 들판을 비워라 지점(47.11, 77.38)에서 도마뱀과 스토커를 처치하거나 남쪽으로 갠의 땅 회복으로 가세요. 레벨 18~23(입구 47.70, 35.00)에서 통곡의 동굴를 실행하세요. 크로스로드 에서 송곳니의 드루이드 우두머리 및 불뱀꽃, 톱니항 에서 99년 묵은 와인 및 영리해지는 음료, 동굴 외부 선반에서 돌연변이 통가죽 및 돌연변이 짐승 섬멸 를 가져옵니다.", s={{"레벨 23 이하인가요?"}, {"들판을 비워라 지점(47.11, 77.38)에서 도마뱀과 스토커를 처치하거나 남쪽으로 갠의 땅 회복으로 가세요"}, {"레벨 18~23(입구 47.70, 35.00)에서 통곡의 동굴를 실행하세요"}, {"크로스로드 에서 송곳니의 드루이드 우두머리 및 불뱀꽃, 톱니항 에서 99년 묵은 와인 및 영리해지는 음료, 동굴 외부 선반에서 돌연변이 통가죽 및 돌연변이 짐승 섬멸 를 가져옵니다"}}}}, danger={[1]="Field to Clear의 엘리트 약탈자가 일반 몹들 사이를 순찰합니다. 외부에서 도마뱀을 갈아서 전장을 건너지 마십시오.", [2]="얼라이언스 연합 병사들이 먼지진흙 습지대 국경에 모여있습니다. 그룹이 없으면 억울한 누명, 정당한 응징를 건너뛰세요."}, grind={[1]={mob="폭풍도마뱀", note="클리어할 필드에는 밀집된 일반 몹이 있습니다. 잔디밭을 돌아다니며 전투에서 벗어나세요. 엘리트 격분한 약탈자를 살펴보세요."}, [2]={mob="긴발톱 빗송곳니하이에나", note="Stormhides와 같은 필드에 밀집된 일반 몹. 다른 플레이어가 농사를 짓고 있다면 캠프를 이동하지 않고 가장자리를 따라 목표를 전환하세요."}}, supply={[1]={npc="데브락"}, [2]={npc="브라고크"}, [3]={npc="여관주인 윌리"}, [4]={npc="그라즐릭스"}, [5]={npc="여관주인 윌리"}, [6]={npc="재지크"}, [7]={npc="오무사 썬더혼"}, [8]={npc="여관주인 비울라"}, [9]={npc="사누예 룬토템"}}, steps={[1]={text="이미 크로스로드로 돌아왔다면 퀘스트를 선택하세요. 동부 왕국에서 합류하시나요? 난로에 들어가거나, 브릴 남쪽에서 오그리마 비행선을 타고 크로스로드로 날아가세요. 북부 루프의 끝을 위해 난로를 저장하십시오."}, [2]={npc="만크릭", tgt="만크릭"}, [3]={npc="만크릭", tgt="만크릭"}, [4]={npc="코란", tgt="코란"}, [5]={npc="톨크", tgt="톨크"}, [6]={hint="크로스로드에 있는 셀그라 다크쏜에게 에체야키의 통가죽을 가져가야 합니다."}, [7]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜", desc="크로스로드에서 이미 설정한 경우 건너뛰세요."}, [8]={npc="셀그라 다크쏜", tgt="셀그라 다크쏜"}, [9]={hint="칼날바람일족 암살자들에게서 하피 부대장의 반지 6개를 모아 크로스로드에 있는 달소크 스위프트대거에게 가져가야 합니다.", desc="크로스로드에서 완료하지 않은 경우에만 이 작업을 수행하세요."}, [10]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거", desc="크로스로드에서 이미 설정한 경우 건너뛰세요."}, [11]={npc="달소크 스위프트대거", tgt="달소크 스위프트대거"}, [12]={text="비행 지점가 모두 열려 있으면 크로스로드에서 톱니항로 비행하세요. 그렇지 않으면 동쪽 도로를 타고 브라고크(63.08, 37.16)에서 톱니항를 배우세요. 크로스로드에서 퀘스트를 획득한 경우 사모플랜지 퀘스트를 유지하세요."}, [13]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [14]={npc="선장 탈로타스 브라이트썬", tgt="선장 탈로타스 브라이트썬"}, [15]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [16]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [17]={npc="부두주임 디지위그", tgt="부두주임 디지위그", tag="선택사항", desc="북쪽에 있는 광산으로 향하는 경우에만 수락하세요."}, [18]={npc="현상수배!", npcObj=true, tag="선택사항", desc="레벨 20 엘리트. 그룹화할 계획인 경우에만 수락하세요."}, [19]={npc="기중기 기사 비글퍼즈", tgt="기중기 기사 비글퍼즈", tag="선택사항", desc="통곡의 동굴 실행을 계획 중인 경우에만 수락하세요."}, [20]={text="톱니항의 북쪽 출구로 나와 슬러지 Fen으로 가서 북쪽 아파트를 정리하세요. 사모플랜지를 놓치셨다면 먼저 스퍼터밸브에서 수락하세요."}, [21]={hint="투자개발회사 연구 시설의 제어장치로 접근해야 합니다."}, [22]={npc="제어 장치", npcObj=true}, [23]={npc="제어 장치", npcObj=true}, [24]={hint="연료 제어 밸브, 압력 조절 밸브, 주제어 밸브를 잠근 다음 제어장치로 돌아가십시오."}, [25]={npc="제어 장치", npcObj=true}, [26]={npc="제어 장치", npcObj=true}, [27]={hint="땜장이 스니글즈에게서 제어장치 열쇠를 구해야 합니다."}, [28]={npc="제어 장치", npcObj=true}, [29]={npc="제어 장치", npcObj=true}, [30]={hint="톱니항에 있는 부두주임 디지위그가 투자개발회사 감독이나 투자개발회사 집행자로부터 고양이눈 에메랄드를 가져다 달라고 부탁했습니다.", tag="선택사항", desc="고양이눈 에메랄드는 드롭률이 낮습니다. 도중에 시도하되 캠핑을 하지 마십시오."}, [31]={npc="위즐크랭크의 벌목기", tgt="위즐크랭크의 벌목기", desc="시동 열쇠의 감독을 처치하고 Wizzlecrank에게 가져가세요."}, [32]={hint="위즐크랭크에게 시동 열쇠를 가져다주어야 합니다.", desc="시동 열쇠의 감독을 처치하고 Wizzlecrank에게 가져가세요."}, [33]={npc="위즐크랭크의 벌목기", tgt="위즐크랭크의 벌목기", desc="시동 열쇠의 감독을 처치하고 Wizzlecrank에게 가져가세요."}, [34]={npc="위즐크랭크의 벌목기", tgt="위즐크랭크의 벌목기", desc="수락하기 전에 근처의 몹을 치료하고 제거하세요. 에스코트가 즉시 시작됩니다."}, [35]={hint="위즐크랭크와 그가 훔쳐 낸 고블린 벌목기를 톱니항에 있는 스퍼터밸브에게로 호위해 가야 합니다.", desc="슬러지 Fen에서 호위하세요. 대화와 퀘스트 크레딧을 기다립니다."}, [3