    ["05-d5"] = {name="죽음의 폐광", entrance="서부 몰락지대 38.20, 77.50", pickup="실버파인으로 가는 길에 티리스팔의 반다리온 성채에 있는 다니타 모르에서 외교 사건를 가져와 실버파인과 펜리스 섬 전제 조건을 완료하세요. 레벨 20이 되면 무덤에 있는 루미나에게서 달빛이 입 맞춘 칼날를 가져가고 트레반에게서 메모를 받으세요. 언데드 성기사를 위한 퀘스트입니다. 톱니항 보트를 타고 무법항까지 이동한 후 북쪽으로 Stranglethorn을 거쳐 그늘숲까지 이동하고 서쪽으로 문브룩까지 이동합니다.", pickupS={{"실버파인으로 가는 길에 티리스팔의 반다리온 성채에 있는 다니타 모르에서 외교 사건를 가져와 실버파인과 펜리스 섬 전제 조건을 완료하세요"}, {"레벨 20이 되면 무덤에 있는 루미나에게서 달빛이 입 맞춘 칼날를 가져가고 트레반에게서 메모를 받으세요"}, {"언데드 성기사를 위한 퀘스트입니다"}, {"톱니항 보트를 타고 무법항까지 이동한 후 북쪽으로 Stranglethorn을 거쳐 그늘숲까지 이동하고 서쪽으로 문브룩까지 이동합니다"}}, tips={{k="動線", text="광산 터널 → 라크조르 → 스니드 및 목재 → 길니드의 대장간 → 부두 문 폭파 → 미스터 스마이트 → 선장 그린스킨 → 에드윈 밴클리프. 쿠키는 하단 데크에 있습니다. 목재만 필요한 경우 스니드 이후에 떠나세요."}, {k="取捨", text="단지 레벨링 중이라면 이 여행을 건너뛰세요. 달빛이 입 맞춘 칼날의 경우 스니드의 방에 도달하여 목재를 수집하세요(언데드 성기사 전용). 그룹이 최종 보스로부터 전리품을 원한다면 계속 진행하세요.", s={{"단지 레벨링 중이라면 이 여행을 건너뛰세요"}, {"달빛이 입 맞춘 칼날의 경우 스니드의 방에 도달하여 목재를 수집하세요(언데드 성기사 전용)", {race={"Scourge"}, class={"PALADIN"}}}, {"그룹이 최종 보스로부터 전리품을 원한다면 계속 진행하세요"}}}, {k="說明", text="문브룩(42.40, 70.40)에 있는 광산 건물에 들어가서 아래층으로 내려가 터널을 따라 38.20, 77.50에 있는 포털로 이동하세요. 얼라이언스 연합 데피아즈 퀘스트는 호드 연합에서는 사용할 수 없습니다.", s={{"문브룩(42.40, 70.40)에 있는 광산 건물에 들어가서 아래층으로 내려가 터널을 따라 38.20, 77.50에 있는 포털로 이동하세요"}, {"얼라이언스 연합 데피아즈 퀘스트는 호드 연합에서는 사용할 수 없습니다"}}}}, steps={[1]={npc="다니타 모르", tgt="다니타 모르"}, [2]={hint="은빛소나무 숲의 공동묘지로 이동한 후 트레반 롤을 찾아가 실종된 대지 고리회 여행자에 관해 얘기해야 합니다."}, [3]={npc="트레반 롤", tgt="트레반 롤"}, [4]={npc="트레반 롤", tgt="트레반 롤", preText="외교 사건"}, [5]={hint="죽음경비병 발드렌을 찾아가 최근 공동묘지를 지나간 정체불명의 대지 고리회 여행자들에 관해 얘기해야 합니다."}, [6]={npc="죽음경비병 발드렌", tgt="죽음경비병 발드렌"}, [7]={npc="죽음경비병 발드렌", tgt="죽음경비병 발드렌", preText="수상한 한 쌍"}, [8]={hint="동쪽의 펜리스 섬을 조사한 후, 대지 고리회 일행의 운명을 알아내야 합니다."}, [9]={npc="까맣게 탄 시체", npcObj=true}, [10]={npc="까맣게 탄 시체", npcObj=true, preText="암담한 운명"}, [11]={hint="북쪽의 펜리스 요새를 조사하고 실종된 대지 고리회 일행을 찾아야 합니다."}, [12]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어"}, [13]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", preText="펜리스 성채로"}, [14]={hint="썩은가죽 놀에게서 펜리스 섬 열쇠를 회수한 후, 열쇠를 사용해 루미나 윈드싱어를 구출해야 합니다."}, [15]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어"}, [16]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", desc="Skyborne: 은빛소나무 숲에서 Sepulcher의 클래스 단계를 따르세요.", preText="루미나 윈드싱어"}, [17]={hint="루미나 윈드싱어와 동행해 펜리스 요새에서 탈출하도록 도와야 합니다.", desc="Skyborne: 은빛소나무 숲에서 Sepulcher의 클래스 단계를 따르세요."}, [18]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", desc="Skyborne: 은빛소나무 숲에서 Sepulcher의 클래스 단계를 따르세요."}, [19]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", preText="바람구체자의 분노"}, [20]={hint="공동묘지에서 루미나 윈드싱어와 대화해야 합니다."}, [21]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어"}, [22]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", desc="수락 후 트레반 롤와 대화하세요. 무기 노트 하나를 받고 퀘스트를 로그에 기록하세요.", preText="빚"}, [23]={text="죽음의 폐광 입구"}, [24]={hint="공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다.", desc="획득률: 흰돌참나무 재목 from 고블린 Woodcarvers only. 위치: 라크조르를 통과하십시오. 목재실에서 스니드로 목수를 처치하세요.", spot="라크조르를 통과하십시오. 목재실에서 스니드로 목수를 처치하세요."}, [25]={npc="트레반 롤", tgt="트레반 롤", desc="메모, Whitestone Oak, 마력에 걸림 은괴 및 정화된 코르석를 가져오세요."}}},
    ["05-d4"] = {name="통곡의 동굴", entrance="불모의 땅 46.00, 36.30", pickup="크로스로드에서 통가와 함께 잊혀진 웅덩이 → 죽은 오아시스 → 변화된 생물를 마친 후 썬더 블러프에서 하뮬, 나라, 자마를 방문하세요. 톱니항에서 영리해지는 음료 및 99년 묵은 와인를 가져오기 전에 랩터 뿔를 제출하세요. 동굴 입구 위 선반에서 날팍와 에브루를 찾으세요.", pickupS={{"크로스로드에서 통가와 함께 잊혀진 웅덩이 → 죽은 오아시스 → 변화된 생물를 마친 후 썬더 블러프에서 하뮬, 나라, 자마를 방문하세요"}, {"톱니항에서 영리해지는 음료 및 99년 묵은 와인를 가져오기 전에 랩터 뿔를 제출하세요"}, {"동굴 입구 위 선반에서 날팍와 에브루를 찾으세요"}}, tips={{k="動線", text="얕은 입구의 아나콘드라 → 강 서쪽의 코브란 → 동쪽의 피타스, 스컴, 서펜티스, 베르단 → 송곳니 4마리를 모두 모은 뒤 입구로 돌아와 제자를 호위하고 무타누스를 처치합니다. 양쪽 날개의 이탈을 제거하면서 불뱀꽃, 돌연변이 통가죽 및 통곡의 정수를 모으십시오."}, {k="取捨", text="영리해지는 음료을 잠금 해제하려면 랩터 뿔를 반납하세요. 퀘스트 하나를 놓친 경우 그룹이 문 앞에서 기다리게 하지 마세요. 크로스로드 오아시스 체인이 완성되었다면 하뮬 룬토템부터 계속 진행하세요."}, {k="說明", text="푸른 오아시스(47.70, 35.00)의 외부 동굴로 들어가서 터널을 따라 포털로 가세요. 먼저 외부 입구 위 벽감에 있는 날팍 및 에브루에서 퀘스트를 받으세요.", s={{"푸른 오아시스(47.70, 35.00)의 외부 동굴로 들어가서 터널을 따라 포털로 가세요"}, {"먼저 외부 입구 위 벽감에 있는 날팍 및 에브루에서 퀘스트를 받으세요"}}}}, steps={[1]={npc="통가 룬토템", tgt="통가 룬토템"}, [2]={hint="통가 룬토템에게 발견한 내용을 보고해야 합니다."}, [3]={npc="통가 룬토템", tgt="통가 룬토템"}, [4]={npc="통가 룬토템", tgt="통가 룬토템", preText="잊혀진 웅덩이"}, [5]={hint="죽은 오아시스를 조사한 후 크로스로드에 있는 통가에게 돌아가야 합니다."}, [6]={npc="통가 룬토템", tgt="통가 룬토템"}, [7]={npc="통가 룬토템", tgt="통가 룬토템", preText="죽은 오아시스"}, [8]={hint="크로스로드에 있는 통가 룬토템에게 변형된 무쇠턱거북 등껍질 8개를 가져다주어야 합니다.", tag="대상: 오아시스 무쇠턱거북 / 오아시스 무쇠턱거북 새끼"}, [9]={npc="통가 룬토템", tgt="통가 룬토템"}, [10]={npc="통가 룬토템", tgt="통가 룬토템", preText="변화된 생물"}, [11]={hint="하뮬 룬토템과 대화하십시오."}, [12]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템"}, [13]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템", preText="하뮬 룬토템"}, [14]={hint="나라 와일드메인과 대화하십시오."}, [15]={npc="나라 와일드메인", tgt="나라 와일드메인"}, [16]={npc="나라 와일드메인", tgt="나라 와일드메인", preText="나라 와일드메인"}, [17]={npc="연금술사 자마", tgt="연금술사 자마"}, [18]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [19]={hint="온전한 랩터 뿔 5개를 모아 톱니항에 있는 메보크 미지릭스에게 가져가야 합니다."}, [20]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [21]={npc="메보크 미지릭스", tgt="메보크 미지릭스", preText="랩터 뿔"}, [22]={npc="기중기 기사 비글퍼즈", tgt="기중기 기사 비글퍼즈"}, [23]={npc="날팍", tgt="날팍"}, [24]={npc="에브루", tgt="에브루"}, [25]={hint="톱니항에 있는 기중기 기사 비글퍼즈가 통곡의 동굴에 숨어 있는 광기의 매글리시에게서 99년 숙성된 포트 와인을 되찾아 달라고 부탁했습니다."}, [26]={text="통곡의 동굴 입구"}, [27]={hint="썬더 블러프에 있는 연금술사 자마가 불뱀꽃 10개를 모아 달라고 부탁했습니다.", desc="불뱀꽃은 던전 입구 앞 바깥 동굴에 자랍니다. 위치: 얕은 개울을 따라가며 양쪽 제방을 따라 불뱀꽃를 모으세요.", spot="얕은 개울을 따라가며 양쪽 제방을 따라 불뱀꽃를 모으세요."}, [28]={hint="통곡의 동굴에 있는 날팍이 돌연변이 통가죽 20개를 가져다 달라고 부탁했습니다.", desc="Deviate Slayer는 던전 입구 앞 바깥 동굴에 있습니다. 위치: 킬은 얕은 포크와 양쪽 날개에서 벗어납니다. 이동하는 동안 전리품이 숨겨집니다.", spot="킬은 얕은 포크와 양쪽 날개에서 벗어납니다. 이동하는 동안 전리품이 숨겨집니다."}, [29]={hint="통곡의 동굴에 있는 에브루가 돌연변이 약탈자랩터 7마리, 돌연변이 독사 7마리, 돌연변이 늪괴물 7마리, 돌연변이 송곳니천둥매 7마리를 처치해 달라고 부탁했습니다.", desc="위치: 얕은 포크를 치운 다음 서쪽과 동쪽 날개에 있는 몹 4개를 모두 마무리하세요.", spot="얕은 포크를 치운 다음 서쪽과 동쪽 날개에 있는 몹 4개를 모두 마무리하세요."}, [30]={hint="톱니항에 있는 메보크 미지릭스에게 통곡의 정수 6병을 가져가야 합니다.", desc="핀은 외부에 Devouring Ectoplasms를 표시합니다. 내부 카운트에도 스며 나옵니다. 던전 입구 밖에서 탐식하는 심령체를 처치할 수 있습니다. 위치: 통곡의 정수가 부족한 경우 하천을 따라 수액을 찾으세요.", spot="통곡의 정수가 부족한 경우 하천을 따라 수액을 찾으세요."}, [31]={hint="코브란, 아나콘드라, 피타스, 서펜티스의 보석을 모아 썬더 블러프에 있는 나라 와일드메인에게 돌아가야 합니다.", desc="위치: 얕은 곳에서 아나콘드라를 찾고, 서쪽에서 코브란을 찾고, 동쪽에서 다른 두 보스를 찾으세요.", spot="얕은 곳에서 아나콘드라를 찾고, 서쪽에서 코브란을 찾고, 동쪽에서 다른 두 보스를 찾으세요."}, [32]={npc="빛나는 조각", npcObj=true, tag="게임 내 확인이 필요합니다", desc="네 명의 드루이드를 처치한 후 제자에게 돌아가십시오. 그를 호위하고 조각을 위해 무타누스를 처치하세요."}, [33]={npc="날팍", tgt="날팍"}, [34]={npc="에브루", tgt="에브루"}, [35]={npc="기중기 기사 비글퍼즈", tgt="기중기 기사 비글퍼즈"}, [36]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [37]={hint="톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오."}, [38]={npc="팔라 세이지윈드", tgt="팔라 세이지윈드"}, [39]={npc="팔라 세이지윈드", tgt="팔라 세이지윈드", preText="빛나는 조각"}, [40]={hint="장로의 봉우리에 있는 하뮬 룬토템에게 악몽의 조각을 가져가야 합니다."}, [41]={npc="대드루이드 하뮬 룬토템", tgt="대드루이드 하뮬 룬토템"}, [42]={npc="나라 와일드메인", tgt="나라 와일드메인"}, [43]={npc="연금술사 자마", tgt="연금술사 자마"}}},
    ["02-11"] = {name="돌발톱 산맥", tips={{k="交通", text="잠금 해제를 비행 지점로 설정하고 해바위 야영지를 처음 방문할 때 귀환석를 설정하세요. 남쪽 고개로 진입한 후 난로를 다시 해바위 야영지로 이동하고 톱니항로 비행합니다."}, {k="取捨", text="땅거미 호수에서 Gaea 씨앗을 획득하고 돌발톱 봉우리에서 세나리우스의 유산를 수행하세요. 씨앗을 넣은 다음 한 루프에서 네 가지 Charred Vale 목표를 모두 수행하십시오. 높새바람 봉우리로 가는 길에 Great 승강기에서 휴가 통지서를 반납하세요."}, {k="取捨", text="토막나무 주둔지 레그에서 에 대해 오르다누스를 죽입니다. 칼바람 바위산를 다시 방문할 계획인 경우에만 추가 지령 - 게렌조 렌치휘슬를 계속하세요. 그러면 톱니항 로의 왕복 여행이 절약됩니다."}, {k="取捨", text="베스셀레스 및 토석인이여 깨어나라에는 엘리트가 포함됩니다. 퀘스트 진질의 숲의 마법는 여러 종류의 짐승을 쫓아 당신을 보내고 남쪽 끝으로 향합니다. 이미 자료가 있는 경우에만 제출하세요."}, {k="提醒", text="레벨 25 이하? Charred Vale 가장자리에서 혈폭풍 하피 또는 불 정령을 처치하십시오(약 32, 64). 먼저 적을 한 명씩 끌어당깁니다.", s={{"레벨 25 이하?"}, {"Charred Vale 가장자리에서 혈폭풍 하피 또는 불 정령을 처치하십시오(약 32, 64)"}, {"먼저 적을 한 명씩 끌어당깁니다"}}}}, danger={[1]="베스셀레스는 그물누비 고개 근처의 엘리트 거미입니다. 먼저 작은 거미를 제거하세요. 그룹이 없으면 건너뛰세요.", [2]="구릉바위 협곡의 동굴은 좁습니다. 고게로크를 소환하려면 배럴을 열기 전에 입구부터 배럴까지의 경로를 정리하세요."}, grind={[1]={mob="혈폭풍하피", note="까맣게 탄 베일의 동쪽 입구에 있는 일반 몹의 밀도는 보통입니다. 밖에서 싱글을 고르고, 순찰을 지켜보고, 23시부터 열심히 일하세요."}, [2]={mob="혈폭풍일족 바람마녀", note="까맣게 그을린 베일 동부의 조밀한 일반 캐스터. 전체 둥지를 피하기 위해 시선 당김에 절벽을 사용하십시오. Charred Vale 퀘스트와 짝을 이루세요."}}, supply={[1]={npc="타름"}, [2]={npc="여관주인 자이카"}, [3]={npc="보른다"}, [4]={npc="여관주인 자이카"}, [5]={npc="그라우날"}, [6]={npc="지다"}}, steps={[1]={text="크로스로드에서 Stonetalon 방향으로 북서쪽 도로를 이용하세요. 불모의 땅(35.26, 27.88)에 있는 시리스 스톤브레이크를 위해 중지하세요."}, [2]={hint="돌발톱 산맥에 있는 시리스 스톤브레이크와 대화하십시오.", tag="크로스로드에서 승인된 경우, 선택사항"}, [3]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="크로스로드에서 승인된 경우, 선택사항"}, [4]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크"}, [5]={text="남쪽 Stonetalon을 통과하여 말라카진로 이동한 다음, 거미를 지나 오르막길을 따라 칼바람 바위산로 이동합니다."}, [6]={hint="돌발톱 산맥의 동굴에서 야영을 하는 진질에게 달소크의 편지를 전달하십시오.", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [7]={npc="의술사 진질", tgt="의술사 진질", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [8]={npc="젠질라", tgt="젠질라"}, [9]={npc="의술사 진질", tgt="의술사 진질", tag="선택사항"}, [10]={npc="현상수배: 베스셀레스", npcObj=true, tag="선택사항"}, [11]={hint="칼바람 바위산에 있는 지즈 피직스와 대화하십시오.", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [12]={npc="지즈 피직스", tgt="지즈 피직스", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [13]={npc="지즈 피직스", tgt="지즈 피직스"}, [14]={hint="말라카진에 있는 젠질라가 동굴이끼 땅거미 10마리와 동굴이끼 독거미 7마리를 처치해달라고 부탁했습니다."}, [15]={hint="톱니항에 있는 메보크 미지릭스에게 동굴이끼거미알 15개를 가져가야 합니다.", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [16]={hint="투자개발회사 나무꾼 15명을 처치한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오."}, [17]={hint="돌발톱 산맥에 있는 지즈 피직스를 위해 슈퍼 절단기 6000 설계도를 입수해야 합니다.", desc="설계도는 벤처 회사 작업자가 떨어뜨립니다."}, [18]={npc="지즈 피직스", tgt="지즈 피직스"}, [19]={npc="지즈 피직스", tgt="지즈 피직스"}, [20]={hint="베스셀레스를 처치하고 그 증거로 베스셀레스의 송곳니를 들고 해바위 야영지의 마그그랜에게 가져가야 합니다.", tag="선택사항", desc="베스셀레스는 엘리트입니다. 그녀를 이길 수 없다면 건너 뛰세요."}, [21]={text="해바위 야영지까지 길을 따라 가세요. 타름(45.12, 59.84)에서 비행 지점를 배우고 귀환석를 여관주인 자이카(47.47, 62.13)와 바인딩하세요. 남부통로 퀘스트 접수가 완료될 때까지 보관해 두세요."}, [22]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더", tag="선택사항"}, [23]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [24]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드"}, [25]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [26]={npc="츄나만", tgt="츄나만"}, [27]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [28]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [29]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [30]={text="땅거미 호수 및 돌발톱 봉우리를 중심으로 북쪽으로 순환합니다. 같은 방법으로 다시 내려와 서쪽으로 향하기 전에 해바위 야영지에 씨앗을 넣으세요."}, [31]={hint="해바위 야영지에 있는 탐라 윈드필드가 가이아 씨앗 10개를 모아다 달라고 부탁했습니다."}, [32]={hint="해바위 야영지 근처에 있는 브랠린 파이어핸드를 위해 세나리우스의 후예, 세나리우스의 딸, 그리고 세나리온 식물학자들을 각각 4명씩 처치해야 합니다."}, [33]={hint="말라카진에 있는 의술사 진질이 돌발톱 수액 5개, 황혼의 수염 5개, 순록의 눈 30개와 마룡 비늘 1개를 가져다 달라고 부탁했습니다.", tag="선택사항", desc="세나리우스의 유산 실행으로 시선을 사로잡으세요. 나머지는 따로 파밍하지 마세요."}, [34]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [35]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [36]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드"}, [37]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드", tag="선택사항"}, [38]={text="해바위 야영지에서 서쪽으로 Charred Vale로 가세요. 하피와 불의 정령을 처치하고, 반짝이는 태양석을 수집하고, 한 루프에서 둔덕을 확인하세요."}, [39]={hint="해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 하피, 복병, 암살자, 약탈자를 각각 7마리씩 처치해달라고 부탁했습니다."}, [40]={hint="반짝이는 태양석 15개를 모로갈에게 가져가야 합니다."}, [41]={hint="해바위 야영지에 있는 츄나만에게 발화석 10개를 가져가야 합니다."}, [42]={hint="가이아 흙더미에 가이아 씨앗 10개를 심은 후, 마력 깃든 가이아 씨앗을 가지고 해바위 야영지에 있는 탐라에게 돌아가야 합니다.", desc="올려진 가이아 흙더미에 퀘스트 시드를 사용하세요."}, [43]={text="퀘스트를 완료하려면 동쪽의 해바위 야영지로 돌아가세요. 말라카진와 산길 복귀를 위해 난로를 아껴두세요."}, [44]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더"}, [45]={npc="모르로갈", tgt="모르로갈"}, [46]={npc="츄나만", tgt="츄나만"}, [47]={npc="탐라 윈드필드", tgt="탐라 윈드필드"}, [48]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더", tag="엘리트, 선택사항"}, [49]={hint="해바위 야영지에 있는 마그그랜 어스바인더가 혈폭풍일족 갈퀴발톱을 처치하고 그 증거로 그녀의 유해를 가져오라고 부탁했습니다.", tag="엘리트, 선택사항", desc="혈폭풍일족 갈퀴발톱는 레벨 26 엘리트입니다. 그룹을 데려오세요."}, [50]={npc="마그그랜 어스바인더", tgt="마그그랜 어스바인더", tag="엘리트, 선택사항"}, [51]={text="Charred Vale 퀘스트를 완료한 후 남동쪽 도로를 이용하세요. 선택적 구릉바위 협곡 퀘스트를 수행하거나 말라카진 및 Barrens 패스로 바로 이동하세요. 패스 퀘스트를 완료한 후 난로를 보관하세요."}, [52]={hint="구릉바위 협곡에 있는 동굴을 탐사한 다음 해바위 야영지에 있는 모르로갈에게 리조나이트 수정 10개를 가져가야 합니다.", tag="선택사항"}, [53]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [54]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [55]={hint="마력 깃든 리조나이트 수정으로 리조나이트 광석을 연 다음 고게로크를 처치해야 합니다. 그를 처치했다는 소식과 마력 깃든 리조나이트 수정을 들고 모르로갈에게 돌아가십시오.", tag="선택사항", desc="레벨 20의 엘리트를 소환합니다. 솔로라면 건너뛰세요."}, [56]={npc="모르로갈", tgt="모르로갈", tag="선택사항"}, [57]={npc="젠질라", tgt="젠질라"}, [58]={npc="의술사 진질", tgt="의술사 진질", tag="선택사항"}, [59]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크"}, [60]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="경험치가 충분하면 왕복 여행을 건너뜁니다., 선택사항"}, [61]={hint="벌목기 XT:4와 XT:9를 파괴한 다음 돌발톱 산맥과 불모의 땅의 경계에 있는 시리스 스톤브레이크에게 돌아가십시오.", tag="경험치가 충분하면 왕복 여행을 건너뜁니다., 선택사항, 대상: XT:4/XT:9"}, [62]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="경험치가 충분하면 왕복 여행을 건너뜁니다., 선택사항"}, [63]={npc="시리스 스톤브레이크", tgt="시리스 스톤브레이크", tag="썬더 블러프 전제조건, 선택사항"}, [64]={text="패스에서 Seereth로 전환한 후 해바위 야영지로 이동합니다. 계란과 편지를 얻기 위해 타름에서 톱니항로 비행하세요. 난로가 무너지면 크로스로드로 달려가 거기서 날아가세요."}, [65]={npc="메보크 미지릭스", tgt="메보크 미지릭스", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [66]={hint="불모의 땅에 있는 스퍼터밸브에게 봉인된 편지를 전달해야 합니다."}, [67]={npc="스퍼터밸브", tgt="스퍼터밸브"}, [68]={npc="스퍼터밸브", tgt="스퍼터밸브", tag="나중에 지나갈 때 진행, 선택사항"}, [69]={text="옵션인 Innocent Blood 리드인을 수행하고 원로 마가타를 들고 있는 경우 톱니항에서 썬더 블러프로 날아갑니다. 도중에 썬더 블러프를 잠금 해제하지 못할 경우 우회로를 건너뛰고 오그리마로 날아가세요."}, [70]={hint="썬더 블러프에 있는 마가타와 대화하십시오.", tag="썬더 블러프 전제조건, 선택사항"}, [71]={npc="마가타 그림토템", tgt="마가타 그림토템", tag="썬더 블러프 전제조건, 선택사항"}, [72]={npc="마가타 그림토템", tgt="마가타 그림토템", tag="썬더 블러프 전제조건, 선택사항"}, [73]={hint="썬더 블러프의 예언의 웅덩이에 있는 연금술사 자마와 대화해야 합니다.", tag="썬더 블러프 전제조건, 선택사항"}, [74]={npc="연금술사 자마", tgt="연금술사 자마", tag="썬더 블러프 전제조건, 선택사항"}, [75]={npc="연금술사 자마", tgt="연금술사 자마", tag="썬더 블러프 전제조건, 선택사항"}, [76]={npc="비닉스", tgt="비닉스", tag="선택사항", desc="먼저 이 작업을 완료한 다음 Silverpine에서 젤토스의 뿔를 수행하여 던전으로 들어가는 또 다른 방법을 찾으세요."}, [77]={hint="획득처: 투자개발회사 벌채꾼, 투자개발회사 운전수, 투자개발회사 나무꾼", tag="선택사항", desc="먼저 이 작업을 완료한 다음 Silverpine에서 젤토스의 뿔를 수행하여 던전으로 들어가는 또 다른 방법을 찾으세요."}, [78]={npc="비닉스", tgt="비닉스", tag="선택사항", desc="먼저 이 작업을 완료한 다음 Silverpine에서 젤토스의 뿔를 수행하여 던전으로 들어가는 또 다른 방법을 찾으세요."}, [79]={npc="우르쿄", tgt="우르쿄"}, [80]={hint="퀘스트 목표를 완료하세요."}, [81]={npc="우르쿄", tgt="우르쿄"}, [82]={text="선택적 썬더 블러프 퀘스트를 마친 후 오그리마로 날아갑니다. 프레자 플랫폼(50.82, 13.54)에서 티리스팔 비행선에 탑승하세요. 브릴 남쪽에서 내려 언더시티 방향으로 간 후 계속 타렌 밀농장 방향으로 가세요."}}},
    ["02-12"] = {name="힐스브래드 구릉지", tips={{k="交通", text="첫 방문 시 공동묘지에서 타렌 밀농장까지 걸어가세요. 잠금 해제 비행 지점를 자라이즈로 설정하고 귀환석를 Shay로 설정하세요. 떠나려면 언더시티에서 브릴 외부 남쪽 타워까지 걸어간 다음 오그리마 비행선을 타세요."}, {k="取捨", text="힐스브래드 전투와 함께 서쪽 루프에서 괴로움의 비약 및 고통의 비약를 수집합니다. 를 반납하여 죽음의 전리품를 잠금 해제한 다음 인간을 죽이면서 두개골을 약탈하세요."}, {k="取捨", text="죽음추적자 마소즈 주변에서 정찰병 지원와 죽음의 비약를 함께 수행합니다. 순결한 피가 있다면 계속해서 던홀드 요새 외곽으로 가세요. Forever 경험치처럼 루프가 끝날 때까지 기다리는 대신 힐스브래드 전투로 두개골 수집을 시작하세요."}, {k="取捨", text="대상이 누락되어 역추적해야 하는 경우 위험 인물 수배!를 건너뛰세요. 던 가록는 힐스브래드 전투로 붐비므로 나중에 솔로로 진행하세요. 급한 경우 승패의 고지 체인을 건너뛰세요. 더 높은 등급의 퓨마가 서쪽 능선을 순찰합니다."}, {k="取捨", text="해바위 야영지 에서 타렌 밀농장으로의 모험 를 수락한 경우 던홀드 요새 에서 순결한 피 를 완료하세요. 높새바람 봉우리로 가는 길에 썬더 블러프를 지나갈 때 썬더 블러프로의 귀환를 반납하세요."}, {k="取捨", text="죽음의 비약 → 죽음의 비약 를 완료한 다음 타렌 밀농장 다리의 언더시티에서 죽음의 비약를 집어 힐스브래드 해안에서 수행합니다."}, {k="取捨", text="비밀결사대원 현상수배와 함께 던홀드 요새에서 포로 구출를 수행합니다. 두 퀘스트 모두 알터랙 산맥 섹션을 참조하세요. 포로 구출는 레벨 29에서 침투를 잠금 해제합니다."}, {k="提醒", text="레벨 27에서 잿빛 골짜기 이전에 높새바람 봉우리에서 잠시 멈춥니다. 27 미만에서는 힐스브래드 농장(약 33, 42) 또는 던홀드 요새 외부의 일반 비밀결사대 몹(약 77, 43)에서 농부를 그라인드합니다. 그룹으로 던 가록를 할 수 있습니다.", s={{"레벨 27에서 잿빛 골짜기 이전에 높새바람 봉우리에서 잠시 멈춥니다"}, {"27 미만에서는 힐스브래드 농장(약 33, 42) 또는 던홀드 요새 외부의 일반 비밀결사대 몹(약 77, 43)에서 농부를 그라인드합니다"}, {"그룹으로 던 가록를 할 수 있습니다"}}}}, danger={[1]="던 가록 소총병, 사제, 등산가가 계단에서 서로를 돕습니다. 선장에게 들어가기 전에 그룹과 함께 외부를 정리하세요.", [2]="서쪽 봉우리에 약병을 놓으려면 예티 동굴 위의 길을 따라가세요. 더 높은 산의 퓨마가 보이면 똑바로 올라가지 말고 경사면을 따라 돌아보세요."}, grind={[1]={mob="힐스브래드 농부", note="힐스브래드 농장 동쪽에 있는 일반 몹의 밀도는 보통입니다. 농가 옆의 짐을 피하십시오. 이동하면서 힐스브래드 인간 해골을 수집하세요."}, [2]={note="농장 중앙에 있는 일반 몹의 밀도는 적당합니다. 들판을 따라 순찰하는 보병을 찾아보세요. 의원과 농부가 모두 있는 집은 피하세요."}, [3]={mob="덩치큰 회색곰", note="던홀드 요새 북쪽 숲에 있는 드문 일반 몹. 성채의 팩을 피하세요. 동부 경로를 따라 돌아오는 길에 몇 마리를 처치하세요."}}, supply={[1]={npc="자라이즈"}, [2]={npc="여관주인 셰이"}, [3]={npc="여관주인 셰이"}, [4]={npc="케이렌 수트할로우"}, [5]={npc="고든 웬드헴"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="해바위 야영지에서 도착했다면 언더시티부터 시작하세요. 잠금이 해제되면 타렌 밀농장로 날아갑니다. 그렇지 않으면 Sepulcher로 날아가서 남쪽 도로를 따라 동쪽으로 힐스브래드로 들어간 다음 북쪽 분기점을 이용하세요. 필요한 경우 언더시티에서 걸어가세요. 여전히 칼림도어에 있는 경우 먼저 오그리마 외부의 비행선에 탑승하세요."}, [2]={text="도착하면 자라이즈의 비행 지점(60.14, 18.62)를 배우고 귀환석를 여관주인 셰이(62.78, 19.03)와 바인딩합니다."}, [3]={hint="힐스브래드 구릉지의 타렌 밀농장에 있는 연금술사 라이던에게 렐퍼럴의 연구 결과를 가져가야 합니다."}, [4]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [5]={hint="타렌 밀농장에 있는 연금술사 라이던에게 자마의 쪽지를 가져가야 합니다.", tag="선택사항"}, [6]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [7]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="퀘스트 타렌 밀농장으로의 모험 필요, 선택사항"}, [8]={text="타렌 밀농장에서 수락 → 서쪽으로 곰, 거미, 사자 및 농장"}, [9]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [10]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [11]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [12]={npc="위험!", npcObj=true, tag="선택사항"}, [13]={hint="타렌 밀농장에 있는 연금술사 라이던이 회색곰 혀 10개와 이끼거미 수액을 구해다 달라고 부탁했습니다."}, [14]={hint="타렌 밀농장에 있는 연금술사 라이던에게 산사자 피 10병을 가져가야 합니다."}, [15]={hint="힐스브래드 농노 6명, 힐스브래드 농부 6명, 그리고 농부 레이와 농부 게츠를 처치한 다음 타렌 밀농장에 있는 다살리아에게 보고해야 합니다."}, [16]={text="첫 번째 서쪽 순환선을 지나 난로를 타고 타렌 밀농장로 가거나 주요 도로를 타고 돌아옵니다."}, [17]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [18]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [19]={npc="죽음의경비병 삼사", tgt="죽음의경비병 삼사"}, [20]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [21]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [22]={hint="개구리 움피에게 괴로움의 비약을 먹여야 합니다."}, [23]={npc="움피", tgt="움피"}, [24]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [25]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [26]={text="두 번째 농장 루프 → Durnholde 및 진흙주둥이꽃 → 서부 대장간"}, [27]={hint="스탠리에게 고통의 비약을 먹여야 합니다."}, [28]={npc="스탠리", tgt="스탠리"}, [29]={hint="힐스브래드 소작농 15명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}, [30]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [31]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [32]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [33]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [34]={hint="타렌 밀농장에 있는 연금술사 라이던에게 순결한 피가 든 유리병 5병을 가져가야 합니다.", tag="선택사항"}, [35]={hint="고위집행관 다살리아의 최신 명령서를 타렌 밀농장 남쪽, 던 가록 바깥에 있는 죽음추적자 마소즈에게 전달해야 합니다."}, [36]={npc="죽음추적자 마소즈", tgt="죽음추적자 마소즈"}, [37]={npc="죽음추적자 마소즈", tgt="죽음추적자 마소즈", tag="퀘스트 완료 정찰병 지원, 선택사항"}, [38]={hint="타렌 밀농장에 있는 연금술사 라이던에게 진흙주둥이꽃 6개를 가져가야 합니다."}, [39]={hint="대장장이 베링턴과 힐스브래드 견습대장장이 4명을 처치해야 합니다."}, [40]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [41]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [42]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [43]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="먼저 순결한 피를 완료하세요. 높새바람 봉우리에서 반납하세요., 선택사항"}, [44]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [45]={npc="연금술사 라이던", tgt="연금술사 라이던"}, [46]={text="시청 → 광산 → 타렌 밀농장에서 반납"}, [47]={hint="집정관 번사이드와 힐스브래드 원로 5명을 처치해야 합니다. 힐스브래드 선언문을 파괴하고 힐스브래드 마을의 기록부를 빼내 와야 합니다. 그런 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고하십시오."}, [48]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [49]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [50]={hint="현장감독 본즈와 힐스브래드 광부 10명을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다."}, [51]={hint="타렌 밀농장의 고위집행관 다살리아가 서기관 호레이스 화이트스티드, 민간인 윌키스, 광부 하켓, 농부 칼라바에 현상금을 걸었습니다.", tag="선택사항"}, [52]={hint="타렌 밀농장에 있는 죽음경비병 삼사가 힐스브래드 주민의 해골 30개를 가져다 달라고 부탁했습니다."}, [53]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [54]={npc="죽음의경비병 삼사", tgt="죽음의경비병 삼사"}, [55]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="선택사항"}, [56]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="그룹, 선택사항"}, [57]={hint="던 가록으로 가서 던 가록 산악경비대 10명, 던 가록 소총병 8명, 던 가록 사제 4명과 부대장 아이언힐을 처치한 다음 타렌 밀농장에 있는 다살리아에게 돌아와 보고해야 합니다.", tag="그룹, 선택사항"}, [58]={hint="죽음추적자 마소즈를 위해 힐스브래드 구릉지 곳곳의 산봉우리에 연금술사 약병 3개를 놓은 후, 죽음추적자 마소즈에게 가야 합니다.", tag="고레벨 몹., 선택사항"}, [59]={npc="죽음추적자 마소즈", tgt="죽음추적자 마소즈", tag="선택사항"}, [60]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="그룹, 선택사항"}, [61]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아", tag="퀘스트 힐스브래드 전투 필요, 선택사항"}, [62]={text="타렌 밀농장에서 언더시티로 비행하여 죽음의 비약 및 다살리아의 봉인된 추천서를 가지고 있는 경우 이를 반납하세요. 귀환석를 타렌 밀농장에 바인딩된 상태로 유지하세요."}, [63]={hint="언더시티에 있는 수석 연금술사 파라넬에게 진흙주둥이 합성물을 가져가야 합니다."}, [64]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬"}, [65]={hint="언더시티에 있는 바리마트라스에게 다살리아의 봉인된 추천서를 가져가야 합니다.", tag="선택사항"}, [66]={npc="바리마트라스", tgt="바리마트라스", tag="선택사항"}, [67]={hint="힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다."}, [68]={npc="서지 히노트", tgt="서지 히노트"}, [69]={npc="서지 히노트", tgt="서지 히노트", desc="잔질의 손길를 치료하려면 체인을 계속하십시오."}, [70]={hint="서지 히노트가 해독제를 만드는 동안 기다려야 합니다.", desc="잔질의 손길를 치료하려면 체인을 계속하십시오."}, [71]={npc="서지 히노트", tgt="서지 히노트", desc="잔질의 손길를 치료하려면 체인을 계속하십시오."}, [72]={npc="고급스러워 보이는 편지", npcObj=true, tag="선택사항", desc="트레이너가 고급스러워 보이는 편지를 시작합니다. 통로에 있는 상자에 함정 감지를 사용하세요."}, [73]={hint="힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다.", tag="선택사항", desc="트레이너가 고급스러워 보이는 편지를 시작합니다. 통로에 있는 상자에 함정 감지를 사용하세요."}, [74]={npc="파라드", tgt="파라드", tag="선택사항", desc="트레이너가 고급스러워 보이는 편지를 시작합니다. 통로에 있는 상자에 함정 감지를 사용하세요."}, [75]={npc="라벤홀트의 경비병", tgt="라벤홀트의 경비병", tag="선택사항", desc="반복 가능한 평판 퀘스트. 레벨링 중이라면 건너뛰세요."}, [76]={hint="획득처: 비밀결사대 암살자, 비밀결사대 요술사, 비밀결사대 노상강도", tag="선택사항", desc="반복 가능한 평판 퀘스트. 레벨링 중이라면 건너뛰세요."}, [77]={npc="라벤홀트의 경비병", tgt="라벤홀트의 경비병", tag="선택사항", desc="반복 가능한 평판 퀘스트. 레벨링 중이라면 건너뛰세요."}, [78]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="Dunholde 퀘스트와 함께 이 작업을 수행하세요."}, [79]={hint="힐스브래드 구릉지 던홀드 요새에서 군주 토마스를 찾아 처치한 후, 미로코스 사일런트폼에게 가야 합니다.", tag="선택사항", desc="Dunholde 퀘스트와 함께 이 작업을 수행하세요."}, [80]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="Dunholde 퀘스트와 함께 이 작업을 수행하세요."}, [81]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="마을 밖의 비밀 접선 지점. 최소 레벨 1; 23+이 조언했습니다. 비닉스의 폭발물을 단독으로 사용하세요."}, [82]={hint="그림자송곳니 성채에서 젤토스의 뿔을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다. 이 일은 혼자서 완료해야 합니다.", tag="선택사항", desc="마을 밖의 비밀 접선 지점. 최소 레벨 1; 23+이 조언했습니다. 비닉스의 폭발물을 단독으로 사용하세요."}, [83]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="마을 밖의 비밀 접선 지점. 최소 레벨 1; 23+이 조언했습니다. 비닉스의 폭발물을 단독으로 사용하세요."}, [84]={hint="Log", tag="선택사항", desc="사서함에서 후속 조치를 기다린 후 비밀 접선 지점로 돌아갑니다."}, [85]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="사서함에서 후속 조치를 기다린 후 비밀 접선 지점로 돌아갑니다."}, [86]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="레벨 25+. 소멸와 혼란를 먼저 배워보세요. 초대장을 가지고 실버파인으로 돌아가세요."}, [87]={hint="붉은십자군 수도원에서 보스카의 눈을 찾아야 합니다. 그런 다음 장작나무 마을 주변에 있는 C의 비밀 점선 지점에 반환해야 합니다. 이 일은 혼자서 완료해야 합니다.", tag="선택사항", desc="레벨 25+. 소멸와 혼란를 먼저 배워보세요. 초대장을 가지고 실버파인으로 돌아가세요."}, [88]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="레벨 25+. 소멸와 혼란를 먼저 배워보세요. 초대장을 가지고 실버파인으로 돌아가세요."}, [89]={hint="Log", tag="선택사항", desc="후속 편지를 받은 후에만 반환하십시오."}, [90]={npc="비밀 접선 지점", npcObj=true, tag="선택사항", desc="후속 편지를 받은 후에만 반환하십시오."}, [91]={hint="타렌 밀농장에 있는 우물에서 빈 빨간색 물주머니를 채워 불모의 땅에 있는 브린에게 가져가야 합니다.", desc="버섯구름 봉우리에 높새바람 봉우리용 전체 워터스킨을 보관하세요."}, [92]={npc="애살리스테", tgt="애살리스테"}, [93]={hint="퀘스트 목표를 완료하세요."}, [94]={npc="애살리스테", tgt="애살리스테"}, [95]={npc="아나스타샤 하트웰", tgt="아나스타샤 하트웰", tag="선택사항"}, [96]={hint="다이노와 대화하십시오.", tag="선택사항"}, [97]={npc="다이노", tgt="다이노", tag="선택사항"}, [98]={text="높새바람 봉우리의 제페타 서쪽 플랫폼(60.74, 58.87)에서 브릴 남쪽의 오그리마 비행선에 탑승하세요. 높새바람 봉우리가 완료된 레벨 29에서 오그리마에서 토막나무 주둔지까지 직진하세요."}}},
    ["05-d7"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="저습지 (발라리엘의 수색), 47.79, 56.16.", pickup="레벨 24에서 Stonetalon에서 오그리마로 날아간 다음 어둠의 틈를 타고 보르스탄에서 달라지는 입맛를 가져옵니다. 타렌 밀농장 이후 해머폴의 자루크에서 용아귀 소문를 선택하세요. 탄돌 교각를 건너 던 모드르를 지나 텔겐 바위굴 근처의 산악 도로를 따라 죽음의 추적자까지 가세요. 입장하기 전에 용아귀 열기를 수락하세요.", pickupS={{"레벨 24에서 Stonetalon에서 오그리마로 날아간 다음 어둠의 틈를 타고 보르스탄에서 달라지는 입맛를 가져옵니다"}, {"타렌 밀농장 이후 해머폴의 자루크에서 용아귀 소문를 선택하세요"}, {"탄돌 교각를 건너 던 모드르를 지나 텔겐 바위굴 근처의 산악 도로를 따라 죽음의 추적자까지 가세요"}, {"입장하기 전에 용아귀 열기를 수락하세요"}}, tips={{k="動線", text="동쪽 입구에서 습지를 통과하여 서쪽으로 소금가시로 이동 → 덤불 랩터 및 그늘이빨가 있는 덤불 길을 택 → 남서쪽 캠프에서 용아귀 제거 → 발굴 현장에서 패널을 활성화하고 유물 수호자에서 유물을 약탈합니다."}, {k="取捨", text="전체 실행에는 고기, Dragonmaw 파견 및 최종 보스의 유물이 포함됩니다. 다음 오그리마 또는 썬더 블러프 방문을 위해 마지막 칼림도어 제출을 저장합니다."}, {k="說明", text="푸른색 던전 입구는 웰가르의 발굴현장 남동쪽 높은 비탈에 있습니다. 만남의 돌, 죽음의 추적자, 던전 입구의 위치는 각각 다릅니다.", s={{"푸른색 던전 입구는 웰가르의 발굴현장 남동쪽 높은 비탈에 있습니다"}, {"만남의 돌, 죽음의 추적자, 던전 입구의 위치는 각각 다릅니다"}}}}, steps={[1]={npc="보르스탄", tgt="보르스탄"}, [2]={npc="자루크", tgt="자루크"}, [3]={hint="저습지로 이동한 후 용아귀 야영지 위쪽 언덕에서 죽음추적자를 만나야 합니다."}, [4]={npc="죽음의 추적자", tgt="죽음의 추적자"}, [5]={npc="죽음의 추적자", tgt="죽음의 추적자", preText="용아귀 소문"}, [6]={text="Excavation Site: Wetlands 입구"}, [7]={hint="저습지의 발굴 현장에 진입해 덤불 랩터 고기를 가져와야 합니다.", desc="위치: 소금가시의 호수를 지나 그늘이빨 앞에 덤불 같은 길을 따라가며 랩터를 처치하세요.", spot="소금가시의 호수를 지나 그늘이빨 앞에 덤불 같은 길을 따라가며 랩터를 처치하세요."}, [8]={hint="발굴 현장 안에 있는 용아귀 군대를 물리친 후, 발견한 것을 가지고 밖에 있는 죽음추적자에게 가야 합니다.", desc="위치: 그늘이빨를 통과하고 발굴 캠프에서 용아귀 부대를 처치하세요.", spot="그늘이빨를 통과하고 발굴 캠프에서 용아귀 부대를 처치하세요."}, [9]={npc="티탄의 유물", npcObj=true, tag="게임 내 확인이 필요합니다", desc="유물 수호자에서 티탄의 유물를 루팅하고 마우스 오른쪽 버튼을 클릭하면 퀘스트가 시작됩니다."}, [10]={npc="죽음의 추적자", tgt="죽음의 추적자"}, [11]={npc="보르스탄", tgt="보르스탄"}, [12]={hint="티탄의 유물을 썬더 블러프의 장로의 봉우리로 가져가서 자세한 이야기를 해 줄 만한 사람을 찾아야 합니다.", desc="유물 수호자에서 티탄의 유물를 루팅하고 마우스 오른쪽 버튼을 클릭하면 퀘스트가 시작됩니다."}, [13]={npc="바샤나 룬토템", tgt="바샤나 룬토템"}, [14]={npc="바샤나 룬토템", tgt="바샤나 룬토템", desc="Elder Knowledge 이후 Bashana가 유물을 다시 주는지 확인하십시오.", preText="장로의 지식"}, [15]={hint="티탄의 유물을 멀고어 북서쪽의 하늘감시자 고원에 있는 멀른 어스퓨리에게 가져가야 합니다.", desc="Elder Knowledge 이후 Bashana가 유물을 다시 주는지 확인하십시오."}, [16]={npc="알라나 스톰워커", tgt="Muln Earthfury", desc="Elder Knowledge 이후 Bashana가 유물을 다시 주는지 확인하십시오."}}},
    ["05-d6"] = {name="그림자송곳니 성채", entrance="은빛소나무 숲 44.70, 67.80", pickup="Silverpine 전에 Apthecarium에서 우르의 책를 가져온 다음 Sepulcher의 Hadrec과 Dalar에게서 그림자송곳니 성채의 죽음추적자 및 아루갈의 최후를 가져옵니다. 흑마법사는 타우라조 야영지 동쪽에서 소랜루크 수정구를 집을 수 있습니다. 언데드 성기사는 외교 사건에서 달빛이 입 맞춘 칼날까지 Deadmines 체인을 따라가야 하며 달빛이 입 맞춘 칼날를 활성 상태로 유지해야 합니다. 힐스브래드로 가는 도중에 동부 왕국로 돌아온 후 공동묘지로 날아간 후 남쪽으로 이동합니다.", pickupS={{"Silverpine 전에 Apthecarium에서 우르의 책를 가져온 다음 Sepulcher의 Hadrec과 Dalar에게서 그림자송곳니 성채의 죽음추적자 및 아루갈의 최후를 가져옵니다"}, {"흑마법사는 타우라조 야영지 동쪽에서 소랜루크 수정구를 집을 수 있습니다", {class={"WARLOCK"}}}, {"언데드 성기사는 외교 사건에서 달빛이 입 맞춘 칼날까지 Deadmines 체인을 따라가야 하며 달빛이 입 맞춘 칼날를 활성 상태로 유지해야 합니다", {race={"Scourge"}, class={"PALADIN"}}}, {"힐스브래드로 가는 도중에 동부 왕국로 돌아온 후 공동묘지로 날아간 후 남쪽으로 이동합니다"}}, tips={{k="動線", text="레실고어를 죽이고 Adamant를 구출하고 → 안뜰 오른쪽에서 Vincent를 찾고 → 연회장 및 성벽 → Fenrus의 책 방 → 늑대왕 난도스로 타워 정리 → 위층에서 아루갈를 죽이고 그의 테이블을 확인합니다."}, {k="取捨", text="우르의 책, 아루갈의 최후를 던전 밖에서 반납하세요. 그림자송곳니 성채의 죽음추적자를 Vincent 내부에 반납하세요. 레벨 22 이전에 그룹이 어려움을 겪고 있다면 먼저 로데론의 폐허 또는 통곡의 동굴를 사용해 보세요."}, {k="說明", text="공동묘지에서 남쪽으로 가세요. 장작나무 마을 북쪽 경사로로 성에 들어가 바깥문을 통과하면 안뜰 옆에 던전 입구가 있습니다. 달라란의 숨겨진 우두머리를 잡으려면 아루갈의 탁자에서 검은 고서를 가져오세요. 앰버밀 대홀의 지맥 장치로 달라란의 고서를 만드세요.", s={{"공동묘지에서 남쪽으로 가세요"}, {"장작나무 마을 북쪽 경사로로 성에 들어가 바깥문을 통과하면 안뜰 옆에 던전 입구가 있습니다"}, {"달라란의 숨겨진 우두머리를 잡으려면 아루갈의 탁자에서 검은 고서를 가져오세요"}, {"앰버밀 대홀의 지맥 장치로 달라란의 고서를 만드세요"}}}}, steps={[1]={npc="관리인 벨두거", tgt="관리인 벨두거"}, [2]={npc="고위집행관 하드렉", tgt="고위집행관 하드렉"}, [3]={npc="달라 던위버", tgt="달라 던위버"}, [4]={npc="도안 카르한", tgt="도안 카르한", tag="선택사항", desc="반납하기 전에 검은심연 나락에 있는 나머지 조각 3개를 약탈하세요."}, [5]={text="그림자송곳니 성채 입구"}, [6]={hint="죽음추적자 아다만트와 죽음추적자 빈센트를 찾아야 합니다.", desc="위치: 레실고어 이후 감방을 열고 Deathstalker를 따라 오른쪽 계단으로 올라갑니다.", spot="레실고어 이후 감방을 열고 Deathstalker를 따라 오른쪽 계단으로 올라갑니다."}, [7]={npc="죽음의추적자 빈센트", tgt="죽음의추적자 빈센트", tag="게임 내 확인이 필요합니다", spot="안뜰 오른쪽, 죽음추적자 빈센트"}, [8]={hint="언더시티의 연금술 실험실에 있는 관리인 벨두거에게 우르의 책을 가져가야 합니다.", desc="위치: 탑을 오르십시오. 펜러스의 방 왼쪽 책장의 바닥을 확인하세요.", spot="탑을 오르십시오. 펜러스의 방 왼쪽 책장의 바닥을 확인하세요."}, [9]={hint="소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 불모의 땅에 있는 도안 카르한에게 가져가야 합니다.", tag="선택사항", desc="위치: 타워 경로에서 그림자송곳니 검 Darksouls를 처치하세요. 흑마법사 퀘스트를 수행하는 경우에만 전리품을 얻을 수 있습니다.", spot="타워 경로에서 그림자송곳니 검 Darksouls를 처치하세요. 흑마법사 퀘스트를 수행하는 경우에만 전리품을 얻을 수 있습니다."}, [10]={hint="아루갈을 처치하고 그 증거로 그의 머리카락을 공동묘지에 있는 달라 던위버에게 가져가야 합니다.", desc="위치: 늑대왕 난도스를 따라 위층으로 올라가 그의 방에서 아루갈를 처치하세요.", spot="늑대왕 난도스를 따라 위층으로 올라가 그의 방에서 아루갈를 처치하세요."}, [11]={hint="공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다.", tag="선택사항", desc="위치: 아루갈의 방에 있는 테이블을 보세요. Moon-Kissed Blade에 있는 경우에만 전리품을 얻을 수 있습니다.", spot="아루갈의 방에 있는 테이블을 보세요. Moon-Kissed Blade에 있는 경우에만 전리품을 얻을 수 있습니다."}, [12]={npc="달라 던위버", tgt="달라 던위버"}, [13]={npc="관리인 벨두거", tgt="관리인 벨두거"}, [14]={npc="도안 카르한", tgt="도안 카르한", tag="선택사항", desc="검은심연 나락에서 작은 조각 3개를 모두 루팅한 다음 불모의 땅에 반납하세요."}}},
    ["02-13"] = {name="버섯구름 봉우리", tips={{k="交通", text="오그리마에서 타우라조 야영지까지 비행한 다음 불모의 땅 남쪽 끝에 있는 Great 승강기를 타세요. 잠금 해제 높새바람 봉우리 첫 방문시. 신성한 불가 있는 경우에만 썬더 블러프로 우회하세요."}, {k="取捨", text="해바위 야영지가 보낸 편지를 그레이트 승강기의 경비병에게 제출하세요. 높새바람 봉우리 서쪽에서 상자, 세 가지 하피 유형, 인내의 시험를 함께 수행하세요."}, {k="取捨", text="영상에서는 버섯구름 봉우리 우회를 언급하기 전에 잿빛 골짜기를 소개합니다. 잿빛 골짜기 체인 앞의 높새바람 봉우리에서 중지합니다. 나중에 버섯구름 봉우리 방문을 위해 전체 Shimmering Flats 루프를 저장하세요."}, {k="取捨", text="도움이 없거나 이미 목표물을 통과하고 있지 않는 한 라코타 윈드송 호위, 팬더 우리 및 서부 순찰 후속 조치를 건너 뛰십시오."}, {k="提醒", text="가시덩굴 우리 입구는 Great 승강기 앞 불모의 땅 남쪽 끝에 있습니다. 경험치에 뒤처져 있다면 높새바람 봉우리(약 27, 51) 서쪽에서 비명을 지르는 하피를 갈아주세요.", s={{"가시덩굴 우리 입구는 Great 승강기 앞 불모의 땅 남쪽 끝에 있습니다"}, {"경험치에 뒤처져 있다면 높새바람 봉우리(약 27, 51) 서쪽에서 비명을 지르는 하피를 갈아주세요"}}}}, danger={[1]="엘리베이터 낙하가 치명적입니다. 높새바람 봉우리 다리를 건너거나 북쪽 리프트를 이용하기 전에 플랫폼을 기다리세요.", [2]="하피 동굴의 상자를 열기 전에 주변 적을 정리하고 퇴로를 확보하세요. 상자를 열면 적이 나타납니다."}, grind={[1]={mob="점박이하이에나", note="높새바람 봉우리 서쪽 계곡의 일반 몹 밀도는 보통입니다. 계곡 바닥에 적을 한 명씩 끌어당기고 하피 캠프 우회를 건너뜁니다."}, [2]={mob="회오리 하피", note="서쪽 하피 경사면에는 보통 몹의 밀도가 적당합니다. 하피 퀘스트를 수행하는 동안 가장자리를 따라 외로운 하피를 선택하세요."}}, supply={[1]={npc="니세"}, [2]={npc="여관주인 아베크와"}, [3]={npc="스타른"}, [4]={npc="여관주인 아베크와"}, [5]={npc="스타른"}, [6]={npc="몬타르"}, [7]={npc="오무사 썬더혼"}}, steps={[1]={text="브릴(60.74, 58.87) 남쪽 제페타 서쪽 승강장에서 오그리마 비행선을 확인하세요. 착륙 후 오그리마에 진입하세요. 썬더 블러프로의 귀환 방향으로 회전하는 경우 썬더 블러프를 통해 비행하세요. 그렇지 않으면 타우라조 야영지로 직접 비행하세요. 여전히 타렌 밀농장에 있는 경우 먼저 언더시티로 날아갑니다."}, [2]={hint="썬더 블러프에 있는 연금술사 자마에게 라이던의 독약을 가져가야 합니다.", tag="타렌 밀농장에서 승인된 경우, 선택사항"}, [3]={npc="연금술사 자마", tgt="연금술사 자마", tag="타렌 밀농장에서 승인된 경우, 선택사항"}, [4]={text="남부 불모의 땅 길을 따라 Great 승강기로 가서 북쪽에 있는 경비병과 대화하세요."}, [5]={hint="마그그랜이 불모의 땅 구름 승강장에 있는 그리쉬 롱러너에게 통지서를 전해달라고 부탁했습니다.", tag="해바위 야영지에서 승인된 경우"}, [6]={npc="그리쉬 롱러너", tgt="그리쉬 롱러너", tag="해바위 야영지에서 승인된 경우"}, [7]={npc="용사 문혼", tgt="용사 문혼"}, [8]={hint="긴급 전갈을 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 가져가야 합니다."}, [9]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [10]={text="Great 승강기를 쓰러뜨리세요. 동쪽으로 계곡을 따라 높새바람 봉우리 리프트를 타고 올라갑니다. 니세의 비행 지점(45.14, 49.11)를 알아보세요. 난로를 유지하십시오."}, [11]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [12]={npc="하가르 라이트닝후프", tgt="하가르 라이트닝후프"}, [13]={npc="잔디아", tgt="잔디아"}, [14]={npc="잔디아", tgt="잔디아", desc="라우 클리프러너는 이 퀘스트(46.14, 51.71)도 제공합니다."}, [15]={npc="엘루", tgt="엘루"}, [16]={npc="현상수배: 아르낙 그림토템", npcObj=true}, [17]={text="높새바람 봉우리 북쪽의 켄타우로스 캠프를 정리한 다음 Dorn과 바람뱀 둥지로 향하세요."}, [18]={hint="갈라크일족 척후병 12명, 갈라크일족 사냥꾼 10명, 갈라크일족 바람전사 6명을 처치한 후, 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 돌아가야 합니다."}, [19]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [20]={hint="믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오.", desc="돈 바로 앞의 판자에서 뛰어내립니다. 성공적인 점프는 당신을 다시 순간이동시킵니다."}, [21]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [22]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [23]={hint="높새바람 봉우리에 있는 하가르 라이트닝후프에게 괴상한 알을 가져가야 합니다."}, [24]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [25]={npc="하가르 라이트닝후프", tgt="하가르 라이트닝후프"}, [26]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [27]={npc="하가르 라이트닝후프", tgt="하가르 라이트닝후프"}, [28]={text="비명을 지르는 하피를 치우고 서쪽으로 보급품 상자를 가져가세요. 마루둥지를 거쳐 백사장 야영지까지 계곡을 따라 가세요."}, [29]={hint="도난당한 높새바람 보급품 8개를 높새바람 봉우리에 있는 잔디아에게 가져가야 합니다.", desc="높새바람 봉우리에서 서쪽으로 향하고 하피 경사면을 따라 비명을 잠재워라의 동굴에 있는 상자로 가세요. 개체 670338의 게임 내 생성 지점 3개."}, [30]={hint="회오리 하피 5명과 회오리일족 약탈자 하피 5명, 회오리일족 바람마녀 하피 5명을 처치해야 합니다."}, [31]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 그렌카의 발톱을 가져가야 합니다.", desc="먼저 동굴을 클리어하세요. 그렌카 블러드스크리치를 생성하려면 뒤쪽에 있는 상자를 부수세요."}, [32]={hint="높새바람 봉우리에 있는 엘루에게 마루둥지 와이번 알 10개를 가져가야 합니다."}, [33]={npc="파오카 스위프트마운틴", tgt="파오카 스위프트마운틴", tag="에스코트, 선택사항"}, [34]={hint="마루둥지에 있는 파오카 스위프트마운틴을 호위해 간 다음 백사장 야영지에 있는 모테가 파이어메인과 대화하십시오.", tag="에스코트, 선택사항", desc="마루둥지에서 Pao'ka를 호위하기 전에 출구 근처에서 전리품 알과 맨티코어를 제거하세요."}, [35]={npc="모테가 파이어메인", tgt="모테가 파이어메인", tag="에스코트, 선택사항"}, [36]={hint="발견한 사실을 모테가 파이어메인에게 보고해야 합니다."}, [37]={npc="모테가 파이어메인", tgt="모테가 파이어메인"}, [38]={npc="모테가 파이어메인", tgt="모테가 파이어메인", tag="썬더 블러프로 비행하는 경우 수락, 선택사항"}, [39]={npc="위즐로 베어링샤이너", tgt="위즐로 베어링샤이너", tag="엘리트, 선택사항"}, [40]={hint="퓨마를 처치하고 초전도 장치와 퓨마 우리 열쇠를 위즐로 베어링샤이너에게 돌려주어야 합니다.", tag="엘리트, 선택사항", desc="그룹화. 케이지를 열자마자 엘리트들이 공격합니다."}, [41]={npc="위즐로 베어링샤이너", tgt="위즐로 베어링샤이너", tag="엘리트, 선택사항"}, [42]={npc="암살 지령", npcObj=true, tag="순찰 낙하부터 시작, 선택사항", desc="갈라크일족 전령는 캠프 사이를 순찰합니다. 암살 지령를 약탈하고 사용하세요."}, [43]={hint="백사장 야영지에 있는 카나티 그레이클라우드에게 가서 암살 음모에 대해 경고해 주어야 합니다.", tag="순찰 낙하부터 시작, 선택사항", desc="갈라크일족 전령는 캠프 사이를 순찰합니다. 암살 지령를 약탈하고 사용하세요."}, [44]={npc="카나티 그레이클라우드", tgt="카나티 그레이클라우드", tag="순찰 낙하부터 시작, 선택사항"}, [45]={npc="카나티 그레이클라우드", tgt="카나티 그레이클라우드", tag="순찰 낙하부터 시작, 선택사항"}, [46]={hint="켄타우로스의 공격으로부터 카나티 그레이클라우드를 보호해야 합니다.", tag="순찰 낙하부터 시작, 선택사항", desc="수락하기 전에 치유하고 마시십시오. 공격은 즉시 시작됩니다."}, [47]={npc="카나티 그레이클라우드", tgt="카나티 그레이클라우드", tag="순찰 낙하부터 시작, 선택사항"}, [48]={text="서쪽 경사로로 먹구름 봉우리를 타고 올라가서 북쪽으로 다리를 건너세요."}, [49]={hint="먹구름 봉우리에 있는 비밀 쪽지 3개를 찾아 와야 합니다.", desc="31.5, 36.7의 경사로를 타고 다리로 가세요. 세 캠프를 모두 검색하여 메모를 찾으세요."}, [50]={hint="아르낙 그림토템을 처치하고 높새바람 봉우리에 있는 절벽파수꾼 롱혼에게 그 증거물을 갖다주어야 합니다."}, [51]={npc="라코타 윈드송", tgt="라코타 윈드송", tag="시간이 허락한다면, 선택사항"}, [52]={hint="라코타 윈드송을 먹구름 봉우리에서 구출한 후, 높새바람 봉우리에 있는 탈리아 앰버하이드와 대화하십시오.", tag="시간이 허락한다면, 선택사항", desc="먼저 우리 구역과 다리를 정리한 다음 라코타를 산 아래로 호위하세요."}, [53]={hint="불꽃 용설란 10포기를 모아 썬더 블러프 장로의 봉우리에 있는 마가타 그림토템을 찾아가야 합니다.", tag="시간이 허락한다면, 선택사항"}, [54]={text="퀘스트를 완료하려면 높새바람 봉우리로 돌아가세요. 인내의 시험를 포스트 북동쪽에 있는 Dorn으로 가져가세요."}, [55]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [56]={npc="잔디아", tgt="잔디아"}, [57]={npc="잔디아", tgt="잔디아"}, [58]={npc="엘루", tgt="엘루"}, [59]={npc="도른 플레인스토커", tgt="도른 플레인스토커"}, [60]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [61]={npc="탈리아 앰버하이드", tgt="탈리아 앰버하이드", tag="선택사항"}, [62]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="당신이 그것을 본다면, 선택사항"}, [63]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 로크알림의 파편을 가져가야 합니다.", tag="당신이 그것을 본다면, 선택사항", desc="서쪽 계곡과 마루둥지 근처에서 돌주먹 로크알림를 찾으세요."}, [64]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="당신이 그것을 본다면, 선택사항"}, [65]={text="신성한 불가 준비되어 있고 썬더 블러프가 잠금 해제되어 있으면 높새바람 봉우리에서 그곳으로 비행하세요. 그렇지 않으면 다음 제출을 건너뛰고 계속하세요."}, [66]={npc="마가타 그림토템", tgt="마가타 그림토템", tag="썬더 블러프에서 반납하세요, 선택사항"}, [67]={npc="브린", tgt="브린"}, [68]={npc="브린", tgt="브린", desc="토막나무 주둔지에서 물을 얻으세요. 불모의 땅에서 다시 돌아오세요."}, [69]={text="높새바람 봉우리 또는 썬더 블러프에서 비행하세요. 토막나무 주둔지가 잠겨 있으면 크로스로드로 날아가 Mor'shan Rampart를 지나 북쪽으로 잿빛 골짜기로 이동한 다음 동쪽 도로를 따라 Splintertree로 이동하세요."}}},
    ["02-14"] = {name="잿빛 골짜기", tips={{k="交通", text="잠금 해제 토막나무 주둔지 다음 조람가르 전초기지. 뛰어난 퀘스트를 수행하려면 Splintertree, 해바위 야영지 또는 크로스로드로 날아가거나 Zoram'gar에서 오그리마로 바로 이동하세요. 귀환석 설정을 타렌 밀농장 로 유지하세요."}, {k="取捨", text="토막나무 주둔지에서 세 개의 루프를 수행합니다. 남쪽으로 아웃러너, 남서쪽으로 호수 정령, 북쪽으로 사티로스입니다. 조람가르에서 펄볼그와 동굴 부적을 함께 만드세요."}, {k="取捨", text="세 마리의 짐승이 순찰을 돌고 있다. 마주쳤을 때만 죽이세요. 누락된 페이지를 파밍하는 대신 나중에 교환하세요."}, {k="取捨", text="이미 크로스로드 및 오그리마로 향하고 있다면 레벨 29에서 곤충 떼의 위협를 선택하세요. 곤충 떼의 위협를 위해 오그리마에 반납한 다음 Shimmering Flats에서 곤충 떼의 위협를 반납하여 곤충 떼의 위협을 잠금 해제하세요. 방해가 되지 않으면 체인을 건너뛰세요."}, {k="提醒", text="레벨 30 이하? 사티로스(약 67, 57) 또는 엉겅퀴가죽 펄볼그(약 32, 38)를 갈아주세요. 그룹이 준비되면 Zoram Strand에서 검은심연 나락를 실행하세요. 그렇지 않으면 계속해서 질문하세요.", s={{"레벨 30 이하?"}, {"사티로스(약 67, 57) 또는 엉겅퀴가죽 펄볼그(약 32, 38)를 갈아주세요"}, {"그룹이 준비되면 Zoram Strand에서 검은심연 나락를 실행하세요"}, {"그렇지 않으면 계속해서 질문하세요"}}}}, danger={[1]="아스트라나르는 길가에 레벨 40 파수꾼이 있는 얼라이언스 연합 마을입니다. 조람가르로 가는 길에 주변을 돌아보세요.", [2]="펄볼그는 엉겅퀴가죽 요새의 좁은 통로를 막을 수 있습니다. 상자를 열거나 Ruul의 호위를 시작하기 전에 탈출 경로를 확보하세요."}, grind={[1]={mob="검은유혹의 그림자추적자", note="사티로스 캠프 외부의 일반 몹 밀도는 보통입니다. 가장자리를 따라 순찰대와 근처 사티로스를 관찰하고 사티로스의 뿔를 수집하세요."}, [2]={mob="우두머리 유령발늑대", note="토막나무 주둔지 북쪽 숲에 있는 일반 몹의 밀도는 보통입니다. 사티로스 캠프를 건너뛰는 경우 비행 지점 근처의 열린 공간에서 한 번에 한 명의 적을 끌어당깁니다."}, [3]={mob="사비안 도적", note="사비안의 일반 몹 밀도는 보통입니다. 숨어 있는 몹과 순찰대를 조심하세요. 사티로스의 뿔를 수집하면서 외부를 먼저 클리어하고 레벨 29를 완료하세요."}}, supply={[1]={npc="불그라"}, [2]={npc="여관주인 카일리스크"}, [3]={npc="벌크럼"}, [4]={npc="여관주인 카일리스크"}, [5]={npc="벌크럼"}, [6]={npc="안드루크"}, [7]={npc="위크타르"}}, steps={[1]={text="토막나무 주둔지(73.18, 61.59)에서 불그라로부터 비행 지점를 알아보세요. 반환을 위해 타렌 밀농장 난로를 보관하세요. 잿빛 골짜기 에서 바인딩하려면 여관주인 카일리스크(73.99, 60.65)를 참조하세요."}, [2]={hint="잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트를 만나야 합니다.", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [3]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="톱니항 / 타우라조 야영지 구간에서 승인된 경우"}, [4]={npc="세나니 썬더하트", tgt="세나니 썬더하트"}, [5]={hint="퀘스트 목표를 완료하세요.", desc="잿빛 골짜기 사냥 대회를 제출한 다음 잿빛 골짜기 사냥 대회를 수행한 후 드롭에서 세 가지 사냥 퀘스트를 시작하세요."}, [6]={npc="세나니 썬더하트", tgt="세나니 썬더하트"}, [7]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스"}, [8]={npc="픽셀", tgt="픽셀"}, [9]={npc="쿠레이빈", tgt="쿠레이빈"}, [10]={npc="구르다 레이지스카", tgt="구르다 레이지스카", tag="이미 누락된 페이지가 있는지 확인하세요., 선택사항"}, [11]={text="토막나무 주둔지 남쪽에서 잿빛골짜기 정찰꾼를 죽인 다음 남서쪽 호수로 향하세요."}, [12]={npc="뾰족발톱의 발톱", npcObj=true, tag="목표가 보이면 수락, 선택사항", desc="뾰족발톱를 처치하고 가방에 있는 발톱을 마우스 오른쪽 버튼으로 클릭하여 퀘스트를 시작하세요."}, [13]={hint="뾰족발톱의 발톱을 잿빛 골짜기의 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", tag="목표가 보이면 수락, 선택사항", desc="뾰족발톱를 처치하고 가방에 있는 발톱을 마우스 오른쪽 버튼으로 클릭하여 퀘스트를 시작하세요."}, [14]={hint="잿빛 골짜기 정찰꾼 9명을 처치한 후 토막나무 주둔지에 있는 쿠레이빈에게 돌아가십시오."}, [15]={npc="전쟁노래부족 정찰병", tgt="전쟁노래부족 정찰병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항", desc="보고서 뭉치를 연 다음 전쟁노래부족 보고서를 스카우트와 교환하세요."}, [16]={hint="퀘스트 목표를 완료하세요.", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [17]={npc="전쟁노래부족 정찰병", tgt="전쟁노래부족 정찰병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [18]={npc="토렉", tgt="토렉", tag="에스코트, 선택사항"}, [19]={hint="은빛날개 전초기지와 두리엘 문파이어를 공격하는 토렉을 호위한 후, 토막나무 주둔지에 있는 에르톡 레이지터스크에게 보고하십시오.", tag="에스코트, 선택사항", desc="토렉까지 그룹을 기다리세요. 호위를 수락하면 전투가 시작됩니다."}, [20]={hint="돌발톱 토굴길에서 동쪽으로, 그리고 토막나무 주둔지에서 남서쪽으로 있는 미스트랄 호수에서 타락한 물의 정령 12마리를 처치해야 합니다."}, [21]={npc="더럽혀진 물구슬", npcObj=true, tag="떨어지면 해라, 선택사항", desc="호수 옆에서 타이더레스를 찾으세요. 더럽혀진 물구슬를 마우스 오른쪽 버튼으로 클릭하여 시작합니다."}, [22]={hint="잿빛 골짜기 토막나무 주둔지에 있는 마스토크 윌리히스에게 더럽혀진 물구슬을 가져가야 합니다.", tag="떨어지면 해라, 선택사항", desc="호수 옆에서 타이더레스를 찾으세요. 더럽혀진 물구슬를 마우스 오른쪽 버튼으로 클릭하여 시작합니다."}, [23]={npc="우르산고우스의 앞발", npcObj=true, tag="떨어지면 해라, 선택사항", desc="우르산고우스를 죽이고 가방에 있는 그의 발을 마우스 오른쪽 버튼으로 클릭하여 퀘스트를 시작하세요."}, [24]={hint="우르산고우스의 앞발을 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", tag="떨어지면 해라, 선택사항", desc="우르산고우스를 죽이고 가방에 있는 그의 발을 마우스 오른쪽 버튼으로 클릭하여 퀘스트를 시작하세요."}, [25]={npc="샤둠브라의 머리", npcObj=true, tag="떨어지면 해라, 선택사항", desc="샤둠브라를 처치하고 가방에 있는 그녀의 머리를 마우스 오른쪽 버튼으로 클릭하면 퀘스트가 시작됩니다."}, [26]={hint="샤둠브라의 머리를 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다.", tag="떨어지면 해라, 선택사항", desc="샤둠브라를 처치하고 가방에 있는 그녀의 머리를 마우스 오른쪽 버튼으로 클릭하면 퀘스트가 시작됩니다."}, [27]={text="토막나무 주둔지 방향으로 호수 북동쪽을 따라 가세요. 오르다누스를 처치하고 돌아오는 길에 사티로스 캠프를 클리어하세요."}, [28]={hint="오르다누스를 처치하고 그 증거로 그의 머리 장식을 해바위 야영지 근처에 있는 브랠린 파이어핸드에게 가져가야 합니다.", tag="해바위 야영지에서 승인된 경우, 선택사항"}, [29]={hint="사티로스의 뿔 16개를 모아 토막나무 주둔지에 있는 픽셀에게 가져가야 합니다."}, [30]={npc="전쟁노래부족 척후병", tgt="전쟁노래부족 척후병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [31]={hint="퀘스트 목표를 완료하세요.", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [32]={npc="전쟁노래부족 척후병", tgt="전쟁노래부족 척후병", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [33]={npc="쿠레이빈", tgt="쿠레이빈"}, [34]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스"}, [35]={npc="픽셀", tgt="픽셀"}, [36]={npc="에르톡 레이지터스크", tgt="에르톡 레이지터스크", tag="에스코트 후 반납, 선택사항"}, [37]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="캐치가 있으면 제출하세요., 선택사항"}, [38]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="캐치가 있으면 제출하세요., 선택사항"}, [39]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="캐치가 있으면 제출하세요., 선택사항"}, [40]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="캐치가 있으면 제출하세요., 선택사항"}, [41]={hint="퀘스트 목표를 완료하세요.", tag="캐치가 있으면 제출하세요., 선택사항"}, [42]={npc="세나니 썬더하트", tgt="세나니 썬더하트", tag="캐치가 있으면 제출하세요., 선택사항"}, [43]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스", tag="물 글로브를 루팅하면 수락하세요., 선택사항"}, [44]={npc="마스토크 윌리히스", tgt="마스토크 윌리히스", tag="물 글로브를 루팅하면 수락하세요., 선택사항"}, [45]={hint="잃어버린 벌목기 조작설명서 열 두쪽을 찾아서 1장, 2장, 그리고 3장으로 합쳐야 합니다. 그런 다음 토막나무 주둔지 근처에 있는 구르다 레이지스카에게 돌려 주어야 합니다.", tag="모든 페이지가 필요합니다., 선택사항", desc="누락된 페이지를 파밍하지 마세요. 가방에 있는 페이지를 사용하여 챕터를 조립하세요."}, [46]={npc="구르다 레이지스카", tgt="구르다 레이지스카", tag="모든 페이지가 필요합니다., 선택사항"}, [47]={text="잠금이 해제되면 조람가르 전초기지로 날아갑니다. 첫 번째 방문에서는 잿빛 골짜기의 서쪽 도로를 타고 아스트라나르의 얼라이언스 연합 경비병을 피하고 해안으로 계속 이동하세요. 안드루크(12.24, 33.80)에서 비행 지점를 알아보세요."}, [48]={hint="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 더럽혀진 물구슬을 가져가야 합니다.", tag="물 Globe 시작 퀘스트가 있는 경우, 선택사항"}, [49]={npc="제네우 생크리", tgt="제네우 생크리", tag="물 Globe 시작 퀘스트가 있는 경우, 선택사항"}, [50]={npc="전쟁노래부족 길잡이", tgt="전쟁노래부족 길잡이", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [51]={hint="퀘스트 목표를 완료하세요.", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [52]={npc="전쟁노래부족 길잡이", tgt="전쟁노래부족 길잡이", tag="전쟁노래부족 보고서가 필요합니다, 선택사항"}, [53]={npc="카랑 아마카르", tgt="카랑 아마카르"}, [54]={npc="미쑤와", tgt="미쑤와"}, [55]={npc="마루카이", tgt="마루카이", tag="추가 경험치를 위한 저레벨 몹, 선택사항"}, [56]={hint="조람 해안에 있는 마루카이에게 성난지느러미일족의 머리 20개를 가져가야 합니다.", tag="추가 경험치를 위한 저레벨 몹, 선택사항"}, [57]={npc="마루카이", tgt="마루카이", tag="추가 경험치를 위한 저레벨 몹, 선택사항"}, [58]={text="동쪽 도로를 따라 엉겅퀴 마을로 가세요. 마을 북쪽 동굴에 있는 펄볼그를 처치하고 부적을 약탈하세요."}, [59]={hint="엉겅퀴일족 복수자와 주술사를 각각 12마리씩 처치해야 합니다. 조람 해안 동쪽에 있는 엉겅퀴 마을에 몰려 있을 것입니다. 임무를 마치면 잿빛 골짜기 조람가르 호드 전초기지로 가서 카랑 아마카르를 만나야 합니다."}, [60]={hint="조람가르 전초기지에 있는 미쑤와에게 트롤 부적 8개를 가져가야 합니다."}, [61]={npc="루울 스노우후프", tgt="루울 스노우후프", tag="에스코트, 선택사항"}, [62]={hint="루울을 호위해 탈출한 후, 토막나무 주둔지에 있는 야마 스노우후프와 대화하십시오.", tag="에스코트, 선택사항", desc="몹은 입구와 내부에서 스폰될 수 있다. 수락하기 전에 구절을 클리어하세요."}, [63]={npc="카랑 아마카르", tgt="카랑 아마카르"}, [64]={npc="미쑤와", tgt="미쑤와"}, [65]={npc="카랑 아마카르", tgt="카랑 아마카르", tag="동부 캠프로 돌아가기, 선택사항"}, [66]={hint="썩은나무일족 토템고분에 카랑의 깃발을 꽂은 다음 펄볼그들이 깃발을 부수지 못하도록 막아야 합니다. 족장 머구트가 나타나면 그를 물리치고 머구트의 토템을 조람가르 전초기지의 카랑 아마카르에게 가져가야 합니다.", tag="동부 캠프로 돌아가기, 선택사항", desc="깃발을 꽂기 전에 해당 지역을 정리하세요. 파도를 통제할 준비를 하세요."}, [67]={npc="카랑 아마카르", tgt="카랑 아마카르", tag="동부 캠프로 돌아가기, 선택사항"}, [68]={npc="머그래쉬", tgt="머그래쉬", tag="그룹 에스코트, 선택사항"}, [69]={hint="머그래쉬가 화로로 접근하는 동안 안전하게 보호하고, 그를 도와 화로를 꺼야 합니다. 그런 다음 나가와 맞서 싸우는 동안 그를 보호하십시오.", tag="그룹 에스코트, 선택사항"}, [70]={npc="전쟁노래부족 길잡이", tgt="전쟁노래부족 길잡이", tag="그룹 에스코트, 선택사항"}, [71]={text="루울에게 자유를를 제출해야 하거나 거기에서 다른 퀘스트가 필요한 경우 조람가르 전초기지에서 토막나무 주둔지로 비행하세요. 거기에 묶여 있고 준비되어 있으면 난로 대신. 호위를 건너뛰고 퀘스트를 완료하지 못한 경우 조람가르에서 다음 정거장으로 곧장 비행하십시오."}, [72]={npc="야마 스노우후프", tgt="야마 스노우후프", tag="에스코트가 완료되면, 선택사항"}, [73]={text="오르다누스가 완료되었거나 추가 지령를 계속할 계획이라면 Zoram'gar 또는 Splintertree에서 해바위 야영지(45.12, 59.84)로 날아가세요. 돌발톱이 깨끗해지면 여행을 건너뛰세요."}, [74]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드", tag="해바위 야영지에서 승인된 경우, 선택사항"}, [75]={hint="돌발톱 산맥에 있는 지즈 피직스에게 새로운 명령을 전해야 합니다.", tag="수락하고 칼바람 바위산로 돌아가는 경우, 선택사항"}, [76]={npc="지즈 피직스", tgt="지즈 피직스", tag="수락하고 칼바람 바위산로 돌아가는 경우, 선택사항"}, [77]={npc="지즈 피직스", tgt="지즈 피직스", tag="수락하고 칼바람 바위산로 돌아가는 경우, 선택사항"}, [78]={hint="돌발톱 산맥에 있는 지즈 피직스에게 게렌조의 기계팔을 가져가야 합니다.", tag="수락하고 칼바람 바위산로 돌아가는 경우, 선택사항", desc="칼바람 바위산 북쪽 경사로를 타고 플랫폼으로 이동하세요. 호수를 들여다보지 마세요. 게렌조 렌치휘슬은 높은 플랫폼 위에 있습니다."}, [79]={npc="지즈 피직스", tgt="지즈 피직스", tag="수락하고 칼바람 바위산로 돌아가는 경우, 선택사항"}, [80]={npc="브랠린 파이어핸드", tgt="브랠린 파이어핸드", tag="나중에 또는 그룹으로, 선택사항"}, [81]={hint="돌발톱 봉우리에 있는 갈퀴발톱굴로 가야 합니다. 문지기의 열쇠를 이용해 드루이드의 숨겨진 물건을 얻어야 합니다. 그 물건을 이용해 갈퀴발톱굴 저장고를 여십시오.", tag="나중에 또는 그룹으로, 선택사항", desc="경비병과 동굴 몹이 함께 모여있습니다. 근처에 있으면 단체로 가보세요. 처음 세 개의 핀은 캐시를 표시합니다. 마지막은 갈퀴발톱굴 저장고를 표시합니다."}, [82]={npc="갈퀴발톱굴 저장고", npcObj=true, tag="나중에 또는 그룹으로, 선택사항"}, [83]={text="세 개의 전쟁노래 보고서를 모두 가지고 크로스로드로 이동한 후 Mor'shan Rampart(48.12, 5.42) 옆에 있는 카드라크로 가는 북쪽 도로를 이용하세요. 잿빛 골짜기 비행 지점를 잠금 해제한 경우 남쪽으로 동쪽 도로를 이용할 수도 있습니다."}, [84]={hint="먼저 보고서 뭉치를 여십시오. 전쟁노래부족 길잡이, 전쟁노래부족 정찰병, 그리고 전쟁노래부족 척후병에게 전쟁노래부족 보고서를 가져가야 합니다. 그들의 보고 내용을 담고 있는 최신정보 3개를 받아서 불모의 땅 북부 감시탑에 있는 카드라크에게 돌아가십시오.", tag="세 가지 업데이트된 보고서를 모두 제출하세요., 선택사항", desc="여기에 업데이트된 보고서 3개를 제출하세요. 보고서를 더 일찍 열고 거래하세요."}, [85]={npc="카드라크", tgt="카드라크", tag="세 가지 업데이트된 보고서를 모두 제출하세요., 선택사항"}, [86]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날를 수락한 다음 잿빛 골짜기의 Zoram Strand에서 이것을 획득하세요."}, [87]={hint="코르석을 잿빛 골짜기에 있는 울릭 프로스트베일에게 가져가야 합니다.", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날를 수락한 다음 잿빛 골짜기의 Zoram Strand에서 이것을 획득하세요."}, [88]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항", desc="먼저 달빛이 입 맞춘 칼날를 수락한 다음 잿빛 골짜기의 Zoram Strand에서 이것을 획득하세요."}, [89]={hint="공동묘지에서 트레반 롤과 대화한 후, 그가 필요로 하는 재료를 가져가야 합니다.", tag="선택사항", desc="세 가지 재료를 모두 얻으세요. 호드 연합는 Stranglethorn 및 그늘숲를 통해 Deadmines에 도달할 수 있습니다. 획득률: 흰돌참나무 재목 from 고블린 Woodcarvers only."}, [90]={npc="트레반 롤", tgt="트레반 롤", tag="선택사항", desc="3가지 아이템을 모두 가지고 오그리마로 비행하고, 비행선을 타고 티리스팔로 간 다음, 공동묘지로 비행하세요."}, [91]={npc="트레반 롤", tgt="트레반 롤", tag="선택사항", desc="타렌 밀농장 다리에서 수행하거나, 지나간 경우 Sepulcher에서 그곳으로 날아가세요."}, [92]={hint="Speak with Ott and ask him to forge your blade.", tag="선택사항", desc="타렌 밀농장 다리에서 수행하거나, 지나간 경우 Sepulcher에서 그곳으로 날아가세요."}, [93]={npc="오트", tgt="오트", tag="선택사항", desc="타렌 밀농장 다리에서 수행하거나, 지나간 경우 Sepulcher에서 그곳으로 날아가세요."}, [94]={npc="오트", tgt="오트", tag="선택사항"}, [95]={hint="처치: 오트", tag="선택사항"}, [96]={npc="오트", tgt="오트", tag="선택사항"}, [97]={npc="오트", tgt="오트", tag="선택사항", desc="달빛은 칼날를 얻으려면 제출하세요.", star={"달빛은 칼날", {"PALADIN"}}}, [98]={hint="오트의 걸작을 은빛소나무 숲에 있는 트레반 롤에게 가져가야 합니다.", tag="선택사항", desc="달빛은 칼날를 얻으려면 제출하세요."}, [99]={npc="트레반 롤", tgt="트레반 롤", tag="선택사항", desc="달빛은 칼날를 얻으려면 제출하세요.", star={"달빛은 칼날", {"PALADIN"}}}, [100]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", tag="선택사항", desc="레벨 25 엘리트를 위한 그룹입니다. Wolfsbane을 사용하기 전에 아키발드로 2H 도검류를 훈련하세요.", star={"울프스베인", {"PALADIN"}}}, [101]={hint="은빛소나무 숲에서 달빛은 칼날을 사용해 늙은 불꽃눈을 처단해야 합니다.", tag="선택사항", desc="레벨 25 엘리트를 위한 그룹입니다. Wolfsbane을 사용하기 전에 아키발드로 2H 도검류를 훈련하세요."}, [102]={npc="루미나 윈드싱어", tgt="루미나 윈드싱어", tag="선택사항", desc="레벨 25 엘리트를 위한 그룹입니다. Wolfsbane을 사용하기 전에 아키발드로 2H 도검류를 훈련하세요.", star={"울프스베인", {"PALADIN"}}}, [103]={hint="툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.", tag="선택사항", desc="플로지스톤이나 채광 재료가 누락된 경우 지금은 장비 퀘스트를 건너뛰세요."}, [104]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="플로지스톤이나 채광 재료가 누락된 경우 지금은 장비 퀘스트를 건너뛰세요."}, [105]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", star={"투사 갑옷", {"WARRIOR"}}}, [106]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [107]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", star={"투사 갑옷", {"WARRIOR"}}}, [108]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [109]={hint="듀로타에 있는 울라엘레크와 대화하십시오.", tag="선택사항"}, [110]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항"}, [111]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항", desc="투사 갑옷를 마친 후 사티로스의 뿔로 이 작업을 수행하세요."}, [112]={hint="듀로타의 센진 마을에 있는 울라엘레크에게 사티로스 통발굽 7개를 가져가야 합니다.", tag="선택사항", desc="투사 갑옷를 마친 후 사티로스의 뿔로 이 작업을 수행하세요."}, [113]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항", desc="투사 갑옷를 마친 후 사티로스의 뿔로 이 작업을 수행하세요."}, [114]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항"}, [115]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [116]={npc="울라엘레크", tgt="울라엘레크", tag="선택사항"}, [117]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [118]={hint="썬더 블러프에서 오름 스톤후프와 대화하십시오.", tag="선택사항"}, [119]={npc="오름 스톤후프", tgt="오름 스톤후프", tag="선택사항"}, [120]={npc="오름 스톤후프", tgt="오름 스톤후프", t