 오그리마로 날아갑니다. 그렇지 않으면 토막나무 주둔지, 조람가르 전초기지 또는 해바위 야영지에서 비행하세요. 레벨 30 기술을 훈련한 다음 프레자 플랫폼(50.82, 13.54)에서 티리스팔 비행선을 가져가세요. 브릴에서 하차하여 언더시티로 향합니다. 언더시티 퀘스트나 훈련이 없는 경우에만 귀환석를 사용하여 타렌 밀농장로 돌아가세요."}}},
    ["05-d8"] = {name="검은심연의 나락", entrance="잿빛 골짜기 16.50, 11.00", pickup="해바위 야영지의 츄나만로부터 검은심연의 나락으로...를 수락하고 Zoram'gar의 제네우 생크리를 위해 저장하세요. 흑마법사는 Barrens 다리에서 소랜루크 수정구를 사용할 수 있습니다. 언데드 성기사는 Sepulcher의 달빛이 입 맞춘 칼날를 로그에 보관해야 합니다. Zoram Strand에서 아쿠마이의 정수 및 폐허 사이로를 선택하세요. 외부 동굴에서 메모를 약탈했다면 들어가기 전에 전초기지에 반납하세요. 언데드 Paladins는 코르석을 찾아서를 취할 수 있습니다.", pickupS={{"해바위 야영지의 츄나만로부터 검은심연의 나락으로...를 수락하고 Zoram'gar의 제네우 생크리를 위해 저장하세요"}, {"흑마법사는 Barrens 다리에서 소랜루크 수정구를 사용할 수 있습니다"}, {"언데드 성기사는 Sepulcher의 달빛이 입 맞춘 칼날를 로그에 보관해야 합니다"}, {"Zoram Strand에서 아쿠마이의 정수 및 폐허 사이로를 선택하세요"}, {"외부 동굴에서 메모를 약탈했다면 들어가기 전에 전초기지에 반납하세요"}, {"언데드 Paladins는 코르석을 찾아서를 취할 수 있습니다"}}, tips={{k="動線", text="침수된 동굴을 따라 가무라의 수영장으로 이동하고 수중 측면 동굴에서 타엘리드를 찾습니다. → 여왕 사레베스 및 겔리하스트를 지나 황혼 캠프의 로구스 제트까지 이동합니다. 흑마법사는 거기에서 파편을 전리품으로 얻습니다. Aquanis와 그의 지구를 위해 다리 아래의 돌을 사용하십시오 → Kelris → 아쿠마이를 위해 네 개의 화로를 모두 켜기 전에 그룹을 준비하십시오."}, {k="取捨", text="아쿠마이의 정수를 수행하고 한 번의 여행으로 외부 동굴에 있는 메모를 찾으세요. 메모가 떨어지지 않으면 다른 퀘스트를 수행하세요. 언데드 코르석을 찾아서를 장착한 성기사는 동일한 실행으로 완료할 수 있습니다.", s={{"아쿠마이의 정수를 수행하고 한 번의 여행으로 외부 동굴에 있는 메모를 찾으세요"}, {"메모가 떨어지지 않으면 다른 퀘스트를 수행하세요"}, {"언데드 코르석을 찾아서를 장착한 성기사는 동일한 실행으로 완료할 수 있습니다", {race={"Scourge"}, class={"PALADIN"}}}}}, {k="說明", text="수영는 조람 해안의 북서쪽 끝에 있는 폐허에서 나옵니다. 동굴을 통과하여 지하 통로로 향하는 물속에 잠긴 통로를 따라가세요. Kelris 주변의 화로는 각각 파도를 유발합니다. 빛 한 번에 하나씩.", s={{"수영는 조람 해안의 북서쪽 끝에 있는 폐허에서 나옵니다"}, {"동굴을 통과하여 지하 통로로 향하는 물속에 잠긴 통로를 따라가세요"}, {"Kelris 주변의 화로는 각각 파도를 유발합니다"}, {"빛 한 번에 하나씩"}}}}, steps={[1]={npc="츄나만", tgt="츄나만"}, [2]={hint="잿빛 골짜기에 있는 제네우 생크리와 대화하십시오."}, [3]={npc="제네우 생크리", tgt="제네우 생크리"}, [4]={npc="제네우 생크리", tgt="제네우 생크리", desc="먼저 조람가르 전초기지에서 수락하세요."}, [5]={hint="잿빛 골짜기에 있는 제네우 생크리에게 아쿠마이의 사파이어 20개를 가져가야 합니다.", desc="먼저 조람가르 전초기지에서 수락하세요."}, [6]={npc="축축한 쪽지", npcObj=true, tag="선택사항", desc="선행 퀘스트: 검은심연의 나락으로.... 아쿠마이의 정수도 동시에 수락한 상태로 두세요. 쪽지가 나오지 않으면 파티가 기다릴 필요 없습니다.", preText="검은심연의 나락으로..."}, [7]={hint="축축한 메모를 잿빛 골짜기의 제네우 생크리에게 가져가십시오.", tag="선택사항", desc="선행 퀘스트: 검은심연의 나락으로.... 아쿠마이의 정수도 동시에 수락한 상태로 두세요. 쪽지가 나오지 않으면 파티가 기다릴 필요 없습니다."}, [8]={npc="제네우 생크리", tgt="제네우 생크리", tag="선택사항", desc="선행 퀘스트: 검은심연의 나락으로.... 아쿠마이의 정수도 동시에 수락한 상태로 두세요. 쪽지가 나오지 않으면 파티가 기다릴 필요 없습니다."}, [9]={npc="제네우 생크리", tgt="제네우 생크리", tag="선택사항", desc="축축한 쪽지(고대 신들에 대한 충성)를 반납한 후 동일한 NPC로부터 수락하세요.", preText="고대 신들에 대한 충성"}, [10]={npc="제네우 생크리", tgt="제네우 생크리"}, [11]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항", desc="달빛의 칼날(달빛이 입 맞춘 칼날)을 가져가세요. 제출하기 전에 여기에서 정화된 코르석를 구하세요."}, [12]={hint="코르석을 잿빛 골짜기에 있는 울릭 프로스트베일에게 가져가야 합니다.", tag="선택사항"}, [13]={npc="울릭 프로스트베일", tgt="울릭 프로스트베일", tag="선택사항"}, [14]={text="검은심연의 나락 입구"}, [15]={npc="은빛경비병 타엘리드", tgt="은빛경비병 타엘리드", tag="게임 내 확인이 필요합니다", desc="황혼 제단 앞 거북이 웅덩이 옆 침수 통로에서 타엘리드를 찾으세요."}, [16]={hint="검은심연 나락에 있는 로구스 제트를 처치한 후 잿빛 골짜기의 제네우 생크리에게 돌아가십시오.", tag="선택사항", desc="위치: 겔리하스트의 침수된 동굴을 지나 황혼 캠프에서 로구스 제트를 찾으세요.", spot="겔리하스트의 침수된 동굴을 지나 황혼 캠프에서 로구스 제트를 찾으세요."}, [17]={hint="소랜루크 조각 3개와 큰 소랜루크 조각 1개를 찾아 불모의 땅에 있는 도안 카르한에게 가져가야 합니다.", tag="선택사항", desc="위치: 황혼 캠프에서 성소까지 수행자를 처치하고 파편 3개를 획득하세요.", spot="황혼 캠프에서 성소까지 수행자를 처치하고 파편 3개를 획득하세요."}, [18]={hint="황혼의 군주 켈리스를 처치하고 그 증거로 그의 머리카락을 썬더 블러프에 있는 바샤나 룬토템에게 가져가야 합니다.", desc="위치: 달 성소로 해변으로 가십시오. 황혼 제단에서 Kelris를 처치하십시오. 순서: 18~19단계에서는 먼저 물속으로 들어간 다음 성역으로 들어갑니다.", spot="달 성소로 해변으로 가십시오. 황혼 제단에서 Kelris를 처치하십시오."}, [19]={hint="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 심연의 핵을 가져가야 합니다.", desc="위치: 폐허가 된 제단의 다리 아래에 있는 급강하입니다. 코어에는 심연의 돌를 사용합니다. 순서: 19단계에서 돌을 클릭하기 전에 그룹화하여 군주 아쿠아니스를 소환하세요.", spot="폐허가 된 제단의 다리 아래에 있는 급강하입니다. 코어에는 심연의 돌를 사용합니다."}, [20]={npc="이상한 물구슬", npcObj=true, tag="게임 내 확인이 필요합니다", desc="군주 아쿠아니스를 죽이고, 지구본을 약탈하고, 마우스 오른쪽 버튼을 클릭하여 퀘스트를 시작하세요."}, [21]={npc="제네우 생크리", tgt="제네우 생크리"}, [22]={npc="제네우 생크리", tgt="제네우 생크리"}, [23]={npc="제네우 생크리", tgt="제네우 생크리", tag="선택사항"}, [24]={hint="잿빛 골짜기의 조람가르 전초기지에 있는 제네우 생크리에게 이상한 물구슬을 가져가야 합니다."}, [25]={npc="제네우 생크리", tgt="제네우 생크리"}, [26]={npc="바샤나 룬토템", tgt="바샤나 룬토템"}}},
    ["03-15"] = {name="힐스브래드 구릉지", tips={{k="取捨", text="레벨 31 이하? 힐스브래드 동굴에서 예티를 처치하세요."}, {k="取捨", text="달라란 순찰 및 결속의 팔보호구 퀘스트를 잠금 해제하려면 이전 라운드를 제출하세요. 서쪽 루프에서 하세요. 통과하면 도시 열쇠 퀘스트를 선택하고 원하는 경우 달라란를 건너뜁니다."}, {k="取捨", text="포로 구출를 완료하여 침투를 잠금 해제하세요. 알터랙 산맥용으로 저장하세요. 이전 퀘스트를 완료하지 않은 경우 해안 죽음의 비약 분기를 건너뛰세요."}, {k="提醒", text="Helcular의 무덤은 얼라이언스 연합 마을 사우스쇼어 근처에 있습니다. 마을 외부에서 접근합니다.", s={{"Helcular의 무덤은 얼라이언스 연합 마을 사우스쇼어 근처에 있습니다"}, {"마을 외부에서 접근합니다"}}}, {k="提醒", text="레벨 30~32 레그를 아라시 고원에서 해머폴와 결합합니다. 경험치가 필요하십니까? 서쪽 힐스브래드 산기슭(약 45, 29)에서 일반 예티를 처치하거나 해머폴를 따라잡으세요.", s={{"레벨 30~32 레그를 아라시 고원에서 해머폴와 결합합니다"}, {"경험치가 필요하십니까?"}, {"서쪽 힐스브래드 산기슭(약 45, 29)에서 일반 예티를 처치하거나 해머폴를 따라잡으세요"}}}}, danger={[1]="레벨 55 얼라이언스 연합 경비병이 사우스쇼어를 순찰합니다. 헬쿨라의 복수의 무덤에 도달하려면 마을을 돌아보세요.", [2]="설인 동굴 입구에는 리스폰이 밀집되어 있습니다. 헬쿨라의 마법봉를 찾으면서 외부를 정리하세요. 들어가기 전에 탈출 경로를 유지하십시오."}, grind={[1]={mob="동굴 설인", note="서쪽 설인 동굴 바깥 경사면에 밀집된 일반 몹. 한 번에 한 명의 적을 입구에서 멀리 끌어내십시오. 레벨 30부터 시작하세요."}, [2]={mob="사나운 설인", note="동굴 입구에는 동굴 예티와 뒤섞인 일반 몹이 밀집해 있습니다. 레벨 31-32 경험치 의 외부 가장자리를 먼저 지웁니다."}}, supply={[1]={npc="자라이즈"}, [2]={npc="여관주인 셰이"}, [3]={npc="여관주인 셰이"}, [4]={npc="케이렌 수트할로우"}, [5]={npc="고든 웬드헴"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="토막나무 주둔지 이후에 비행선을 탔다면 브릴의 남쪽 타워에서 언더시티로 향하세요. 칼림도어에서 경로에 합류하는 경우 오그리마로 비행하여 기차를 타고 비행선을 타세요. 필요한 경우 잠금 해제 언더시티 의 비행 지점 와 마이클 가레트 (63.25, 48.56)."}, [2]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="언더시티 전제 조건이 필요합니다, 선택사항"}, [3]={text="언더시티에서 타렌 밀농장로 비행합니다."}, [4]={text="타렌 밀농장 비행 지점(60.14, 18.62)를 배우고 귀환석를 바인딩하세요."}, [5]={npc="수련사 사이반드", tgt="수련사 사이반드"}, [6]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [7]={npc="관리인 벨바릴", tgt="관리인 벨바릴"}, [8]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [9]={npc="탈로우", tgt="탈로우"}, [10]={text="산기슭 동굴 → 달라란 캠프"}, [11]={hint="설인에게서 헬쿨라의 마법봉을 되찾아 타렌 밀농장에 있는 수련사 사이반드에게 가져가야 합니다.", desc="사우스쇼어 밖에서 묘비를 찾으세요. 얼라이언스 연합 가드를 피하세요."}, [12]={npc="수련사 사이반드", tgt="수련사 사이반드"}, [13]={npc="수련사 사이반드", tgt="수련사 사이반드"}, [14]={hint="배반자들을 찾아내 유물을 되찾은 다음에 돌아가야 합니다."}, [15]={hint="타렌 밀농장에 있는 관리인 벨바릴에게 닳아해진 징표의 돌 10개를 가져가야 합니다."}, [16]={hint="타렌 밀농장에 있는 학자 워딘 보이드글레어를 위해 달라란 하수도 열쇠를 입수해야 합니다."}, [17]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [18]={npc="관리인 벨바릴", tgt="관리인 벨바릴"}, [19]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [20]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [21]={npc="관리인 벨바릴", tgt="관리인 벨바릴"}, [22]={hint="달라란 소환사 6명과 노예 바위 정령 8마리를 처치한 다음 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 돌아가야 합니다."}, [23]={hint="타렌 밀농장에 있는 관리인 벨바릴에게 대지 결속의 팔보호구 4개를 가져가야 합니다.", desc="팔보호구를 위해 달라란 근처에서 노예화된 정령을 처치하세요."}, [24]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [25]={npc="관리인 벨바릴", tgt="관리인 벨바릴"}, [26]={text="청금석 광산 및 사우스쇼어 근처 해안"}, [27]={hint="타렌 밀농장에 있는 연금술사 라이던에게 진흙주둥이 혼합물, 강렬한 트롤의 피 비약, 비수가시일족의 비늘 5개, 그리고 너덜지느러미일족의 눈 5개를 가져가야 합니다.", tag="선택사항"}, [28]={hint="헬쿨라의 마법봉에 아젤의 불꽃, 베라즈의 불꽃, 우젤의 불꽃의 마력을 불어넣어야 합니다."}, [29]={npc="헬쿨라의 무덤", npcObj=true}, [30]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [31]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [32]={hint="타렌 밀농장에 있는 연금술사 라이던에게 신디거 스타우트 맥주통을 가져가야 합니다.", tag="선택사항"}, [33]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [34]={npc="연금술사 라이던", tgt="연금술사 라이던", tag="선택사항"}, [35]={hint="오염된 맥주통을 사로잡힌 농부들이 있는 방의 양탄자 위에 가져다 놓아야 합니다.", tag="선택사항"}, [36]={npc="더러운 양탄자", npcObj=true, tag="선택사항"}, [37]={npc="소렉", tgt="소렉", desc="동부 왕국로 전환하기 전에 광폭 태세를 시작하십시오. 도시 전사 트레이너에게 문의하세요."}, [38]={hint="클라녹 맥클라우드와 대화하십시오.", desc="동부 왕국로 전환하기 전에 광폭 태세를 시작하십시오. 도시 전사 트레이너에게 문의하세요."}, [39]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드", desc="동부 왕국로 전환하기 전에 광폭 태세를 시작하십시오. 도시 전사 트레이너에게 문의하세요."}, [40]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드", desc="화격자에 오르기 전에 비축하십시오. 광폭 태세 학습을 마치세요."}, [41]={hint="싸움꾼 윌을 꺾고 격투의 섬에 있는 클라녹 맥클라우드과 대화하십시오.", desc="화격자에 오르기 전에 비축하십시오. 광폭 태세 학습을 마치세요."}, [42]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드", desc="화격자에 오르기 전에 비축하십시오. 광폭 태세 학습을 마치세요."}, [43]={npc="클라녹 맥클라우드", tgt="클라녹 맥클라우드", tag="선택사항", desc="광폭 태세와 별도로 소용돌이 무기 체인을 시작하십시오."}, [44]={hint="바람의감시자 바스라와 대화하십시오.", tag="선택사항", desc="광폭 태세와 별도로 소용돌이 무기 체인을 시작하십시오."}, [45]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="광폭 태세와 별도로 소용돌이 무기 체인을 시작하십시오."}, [46]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="가시덤불에서 붉은머리 엄니를 얻고 해머폴 근처에서 부적을 얻으세요. 바스라로 돌아가세요."}, [47]={hint="은빛소나무 숲에서 타락한 하급 물의 현신을 물리치고 영원의 샘 제단 위에 타락한 현신의 팔보호구와 얼마 남지 않은 순수한 물을 함께 올려놓아야 합니다.", desc="먼저 토막나무 주둔지에서 물배달을 하세요. Sapta가 만료되면 Tiev를 확인하세요."}, [48]={npc="영원의 샘 제단", npcObj=true, tag="게임 내 확인이 필요합니다", desc="먼저 토막나무 주둔지에서 물배달을 하세요. Sapta가 만료되면 Tiev를 확인하세요."}, [49]={npc="영원의 샘 제단", npcObj=true, tag="게임 내 확인이 필요합니다"}, [50]={hint="은빛소나무 숲에 있는 하급 물의 현신과 대화하십시오."}, [51]={npc="하급 물의 현신", tgt="하급 물의 현신"}, [52]={npc="하급 물의 현신", tgt="하급 물의 현신", desc="칼림도어로 돌아오면 Shimmering Flats에 반납하세요."}, [53]={npc="간룰 블러드아이", tgt="간룰 블러드아이", tag="선택사항", desc="오그리마 시작 퀘스트. 이것을 받거나 스트라드를 찾아를 사용하거나 톱니항로 바로 이동하세요."}, [54]={hint="톱니항에 있는 스트라드 파선과 대화하십시오.", tag="선택사항", desc="오그리마 시작 퀘스트. 이것을 받거나 스트라드를 찾아를 사용하거나 톱니항로 바로 이동하세요."}, [55]={npc="스트라드 파선", tgt="스트라드 파선", tag="선택사항", desc="오그리마 시작 퀘스트. 이것을 받거나 스트라드를 찾아를 사용하거나 톱니항로 바로 이동하세요."}, [56]={npc="카렌딘 할가르", tgt="카렌딘 할가르", tag="선택사항", desc="언더시티 시작 퀘스트. 이것을 받거나 스트라드를 찾아서를 사용하거나 톱니항로 바로 이동하세요."}, [57]={hint="톱니항에 있는 스트라드 파선을 찾아가야 합니다.", tag="선택사항", desc="언더시티 시작 퀘스트. 이것을 받거나 스트라드를 찾아서를 사용하거나 톱니항로 바로 이동하세요."}, [58]={npc="스트라드 파선", tgt="스트라드 파선", tag="선택사항", desc="언더시티 시작 퀘스트. 이것을 받거나 스트라드를 찾아서를 사용하거나 톱니항로 바로 이동하세요."}, [59]={npc="스트라드 파선", tgt="스트라드 파선"}, [60]={hint="언더시티에 있는 조라 애니슨과 대화해야 합니다."}, [61]={npc="조라 애니슨", tgt="조라 애니슨"}, [62]={npc="조라 애니슨", tgt="조라 애니슨", desc="SW 힐스브래드 해안에서 책을, 남쪽 버섯구름 봉우리에서 원고를 약탈하세요."}, [63]={hint="곰팡이 슨 고서와 너덜너덜한 필사본을 찾아 언더시티에 있는 조라 애니슨에게 가져가야 합니다.", desc="SW 힐스브래드 해안에서 책을, 남쪽 버섯구름 봉우리에서 원고를 약탈하세요."}, [64]={npc="조라 애니슨", tgt="조라 애니슨", desc="SW 힐스브래드 해안에서 책을, 남쪽 버섯구름 봉우리에서 원고를 약탈하세요."}, [65]={npc="조라 애니슨", tgt="조라 애니슨", desc="Dragonmaw Bonewarders 또는 Shadowwarders에게서 막대 3개를 전리품으로 획득하세요. 책/막대를 톱니항로 가져오세요."}, [66]={hint="톱니항에 있는 스트라드 파선에게 복원된 고서와 정신 집중의 마법봉 3개를 가져가야 합니다.", desc="Dragonmaw Bonewarders 또는 Shadowwarders에게서 막대 3개를 전리품으로 획득하세요. 책/막대를 톱니항로 가져오세요."}, [67]={npc="스트라드 파선", tgt="스트라드 파선", desc="Dragonmaw Bonewarders 또는 Shadowwarders에게서 막대 3개를 전리품으로 획득하세요. 책/막대를 톱니항로 가져오세요."}, [68]={npc="스트라드 파선", tgt="스트라드 파선", desc="톱니항 타워 옆 서클에서 비밀의 고서를 사용하세요. 지옥사냥개를 처치하세요."}, [69]={hint="비밀의 고서를 사용해 지옥사냥개를 소환해 제압한 다음 톱니항에 있는 스트라드 파선에게 사용한 고서를 돌려주어야 합니다.", desc="톱니항 타워 옆 서클에서 비밀의 고서를 사용하세요. 지옥사냥개를 처치하세요."}, [70]={npc="스트라드 파선", tgt="스트라드 파선", desc="톱니항 타워 옆 서클에서 비밀의 고서를 사용하세요. 지옥사냥개를 처치하세요."}, [71]={text="타렌 밀농장에서 소라딘의 성벽를 거쳐 아라시 고원로 동쪽으로 가세요."}}},
    ["05-d10"] = {name="달라란", entrance="알터랙 산맥 8.46, 59.21", pickup="타렌 밀농장의 멜리사라에서 무덤 기사를 가져오고 언더시티의 박사 마틴 펠벤에서 힘의 원천를 가져옵니다. 레벨 30에서는 Wordeen에서 감옥 습격 및 도시로 통하는 열쇠를 가져옵니다. 로다미어 호수를 따라 남동쪽으로 가서 혈석과 열쇠를 모두 찾으려면 수용소로 가세요. 타렌 밀농장에서 반납한 다음 달라란 순찰를 수행하고 피로 물든 거리를 가져옵니다. 호숫가를 따라 Modera의 이미지를 따라 분열의 심장를 가져간 다음 하수구 열쇠를 유지하세요.", pickupS={{"타렌 밀농장의 멜리사라에서 무덤 기사를 가져오고 언더시티의 박사 마틴 펠벤에서 힘의 원천를 가져옵니다"}, {"레벨 30에서는 Wordeen에서 감옥 습격 및 도시로 통하는 열쇠를 가져옵니다"}, {"로다미어 호수를 따라 남동쪽으로 가서 혈석과 열쇠를 모두 찾으려면 수용소로 가세요"}, {"타렌 밀농장에서 반납한 다음 달라란 순찰를 수행하고 피로 물든 거리를 가져옵니다"}, {"호숫가를 따라 Modera의 이미지를 따라 분열의 심장를 가져간 다음 하수구 열쇠를 유지하세요"}}, tips={{k="動線", text="하수구 입구에서 고블린 퀘스트를 선택하고 → 아트렉시스를 죽인 다음 선택적으로 린의 룬 챔버에 들어가고 → 거리로 가는 올바른 경로를 택하고 코어를 약탈하고 → 성채 왼쪽 위층에서 책을 가져오고 → 대마법사의 망령를 위한 Violet Parlor로 가는 포털로 이동합니다. 입구에 있는 Rexxie에게 책을 반납하세요."}, {k="取捨", text="호드 연합 전제 조건은 레벨 30부터 시작됩니다. 그룹을 구성하기 전에 액세스 퀘스트를 완료하세요. 누가 열쇠를 가지고 있는지 확인하고 나중에 실행하기 위해 열쇠를 얻으세요. 그룹이 외면받는 린를 원하는 경우 그림자송곳니 성채에서 달라란의 고서를 가져옵니다."}, {k="說明", text="모데라의 이미지와 던전 포탈이 서로 다른 위치에 있습니다. 로다미어 호수 하수구 측에서 접근합니다. 야외 성문 및 NPC 접근에는 세력 제한이 적용됩니다.", s={{"모데라의 이미지와 던전 포탈이 서로 다른 위치에 있습니다"}, {"로다미어 호수 하수구 측에서 접근합니다"}, {"야외 성문 및 NPC 접근에는 세력 제한이 적용됩니다"}}}}, steps={[1]={npc="박사 마틴 펠벤", tgt="박사 마틴 펠벤"}, [2]={npc="멜리사라", tgt="멜리사라"}, [3]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [4]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [5]={hint="배반자들을 찾아내 유물을 되찾은 다음에 돌아가야 합니다."}, [6]={hint="타렌 밀농장에 있는 학자 워딘 보이드글레어를 위해 달라란 하수도 열쇠를 입수해야 합니다."}, [7]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [8]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [9]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어", preText="감옥 습격, 도시로 통하는 열쇠"}, [10]={hint="달라란 소환사 6명과 노예 바위 정령 8마리를 처치한 다음 타렌 밀농장에 있는 학자 워딘 보이드글레어에게 돌아가야 합니다."}, [11]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [12]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어", preText="달라란 순찰, 도시로 통하는 열쇠"}, [13]={hint="로다미어 호수에서 달라란에 들어갈 길을 찾아야 합니다."}, [14]={npc="대마법사 모데라의 환영", tgt="대마법사 모데라의 환영"}, [15]={npc="대마법사 모데라의 환영", tgt="대마법사 모데라의 환영", desc="달라란 하수도 열쇠(277507)를 얻으려면 수락하세요. 더러운 열쇠가 전제 조건입니다.", preText="피로 물든 거리"}, [16]={text="달라란 입구"}, [17]={npc="Rexxie Copperclutch", tag="게임 내 확인이 필요합니다", desc="하수구 오른쪽 창살 뒤에 있는 고블린을 찾으세요."}, [18]={hint="타렌 밀농장에 있는 멜리사라를 위해 달라란에서 무덤 기사 아트렉시스를 처치해야 합니다.", desc="위치: 주 하수구 터널을 따라 열린 공간으로 가서 아트렉시스를 처치하세요.", spot="주 하수구 터널을 따라 열린 공간으로 가서 아트렉시스를 처치하세요."}, [19]={hint="언더시티에 있는 박사 마틴 펠벤을 위해 달라란에서 금이 간 파수꾼 핵 6개를 모아야 합니다.", desc="위치: Grave 기사를 지나 오른쪽 길로 올라갑니다. 부서진 파수꾼을 처치하세요.", spot="Grave 기사를 지나 오른쪽 길로 올라갑니다. 부서진 파수꾼을 처치하세요."}, [20]={hint="하수도 입구 주위에 있는 렉시 코퍼클러치를 위해 달라란에서 달라란 건국사를 입수해야 합니다.", desc="위치: 시타델 계단 왼쪽 건물의 위층으로 가세요. 동상 뒤를 확인해 보세요.", spot="시타델 계단 왼쪽 건물의 위층으로 가세요. 동상 뒤를 확인해 보세요."}, [21]={npc="Rexxie Copperclutch", tag="게임 내 확인이 필요합니다"}, [22]={hint="타렌 밀농장에 있는 학자 워딘 보이드글레어를 위해 달라란에서 비전 티끌을 모아야 합니다.", desc="위치: Violet Citadel 포털을 사용하여 Violet Parlor로 이동하세요. 대마법사의 망령를 처치하세요.", spot="Violet Citadel 포털을 사용하여 Violet Parlor로 이동하세요. 대마법사의 망령를 처치하세요."}, [23]={npc="멜리사라", tgt="멜리사라"}, [24]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어"}, [25]={npc="박사 마틴 펠벤", tgt="박사 마틴 펠벤"}, [26]={npc="학자 워딘 보이드글레어", tgt="학자 워딘 보이드글레어", desc="호드 연합: 외부 호수 옆 이미지로 전환합니다. 퀘스트 마커를 따르세요.", preText="분열의 심장"}, [27]={hint="달라란 근처에 있는 대마법사 모데라의 환영과 대화해야 합니다.", desc="호드 연합: 외부 호수 옆 이미지로 전환합니다. 퀘스트 마커를 따르세요."}, [28]={npc="대마법사 모데라의 환영", tgt="대마법사 모데라의 환영", desc="호드 연합: 외부 호수 옆 이미지로 전환합니다. 퀘스트 마커를 따르세요."}}},
    ["05-d9"] = {name="붉은십자군 수도원: 묘지", entrance="티리스팔 숲 85.20, 32.10", pickup="잠금 해제 타렌 밀농장 도중에 언더시티에서 티리스팔을 거쳐 수도원까지 북쪽 도로를 따라 가세요. 먼저 가시덩굴 우리 퀘스트 조분석을 나에게!를 완료하세요. 버섯구름 봉우리 이후에 RFK를 실행하는 경우 알터랙 산맥 다리에 대해 열정의 증거를 저장하고 지금 묘지에서 Vorrel을 수행하세요. Apthecarium에서 Faranell을 만나보세요. 묘지를 지나 알터랙 호숫가와 타렌 밀농장로 향하세요.", pickupS={{"잠금 해제 타렌 밀농장 도중에 언더시티에서 티리스팔을 거쳐 수도원까지 북쪽 도로를 따라 가세요"}, {"먼저 가시덩굴 우리 퀘스트 조분석을 나에게!를 완료하세요"}, {"버섯구름 봉우리 이후에 RFK를 실행하는 경우 알터랙 산맥 다리에 대해 열정의 증거를 저장하고 지금 묘지에서 Vorrel을 수행하세요"}, {"Apthecarium에서 Faranell을 만나보세요"}, {"묘지를 지나 알터랙 호숫가와 타렌 밀농장로 향하세요"}}, tips={{k="動線", text="입구 홀에서 Crusaders 및 전리품 하트 → Vishas를 죽이고 선반에서 Vorrel 찾기 → 열린 묘지를 건너 혈법사 탈노스로 내려갑니다."}, {k="取捨", text="묘지는 초반에 그룹화하기 쉽습니다. 조분석을 나에게!를 완료하지 않았더라도 Vorrel을 수행하세요."}, {k="說明", text="가장 왼쪽 입구로 들어가세요. 묘지에는 스칼렛 키가 필요하지 않습니다.", s={{"가장 왼쪽 입구로 들어가세요"}, {"묘지에는 스칼렛 키가 필요하지 않습니다"}}}}, steps={[1]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항", desc="가시덩굴 우리를 먼저 수행하는 경우에만 수락하십시오. Shimmering Flats 다리에 맞습니다."}, [2]={hint="언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다.", tag="선택사항", desc="이 단계는 가시덩굴 우리 에 있습니다."}, [3]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항"}, [4]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항", desc="조분석을 나에게!에 대해서는 가시덩굴 우리를 참조하세요. 네 날개 모두에 하트가 떨어지므로 달리기 전에 하트를 획득하세요.", preText="조분석을 나에게!"}, [5]={text="붉은십자군 수도원: 묘지 입구"}, [6]={npc="보렐 센구츠", tgt="보렐 센구츠", tag="게임 내 확인이 필요합니다", desc="첫 번째 심문실 선반에서 보렐을 찾으세요."}, [7]={hint="언더시티에 있는 수석 연금술사 파라넬에게 열정의 증거 20개를 가져가야 합니다.", tag="선택사항", desc="위치: 현관부터 심문실까지 살아있는 붉은십자군을 처치하세요.", spot="현관부터 심문실까지 살아있는 붉은십자군을 처치하세요."}, [8]={hint="타렌 밀농장에 있는 모니카 센구츠에게 보렐의 결혼반지를 가져가야 합니다.", desc="다른 엘리트가 방에 있을 수도 있습니다. 그녀가 부두로 순찰할 때까지 기다리세요."}, [9]={npc="모니카 센구츠", tgt="모니카 센구츠"}, [10]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="선택사항", desc="언더시티에 제출하기 전에 20개를 모두 수집하세요."}}},
    ["03-16"] = {name="아라시 고원", nameA="아라시 고원: {a:321}", tips={{k="取捨", text="해머폴 근처의 랩터와 비밀결사대 몹을 제거하고 남동쪽에 있는 마른나무껍질 몹을 제거하세요. 이미 레벨 32라면 재방문을 위해 이후의 전장으로 및 랩터의 기민함 퀘스트를 저장하세요."}, {k="取捨", text="병동 재입고 및 실키 봉합은 WoW Forever에서 추가입니다. 비단결 봉합사를 반납하면 병동 보급 작전를 잠금 해제할 수 있습니다. 이미 레벨 32라면 다음 방문을 위해 저장해 두세요."}, {k="提醒", text="레벨 32 이하? 버섯구름 봉우리로 떠나기 전에 마을 밖에서(약 68, 69) 일반 마른나무껍질 트롤을 처치하세요. 붐비는 캠프에서 벗어나세요.", s={{"레벨 32 이하?"}, {"버섯구름 봉우리로 떠나기 전에 마을 밖에서(약 68, 69) 일반 마른나무껍질 트롤을 처치하세요"}, {"붐비는 캠프에서 벗어나세요"}}}}, danger={[1]="마른나무껍질 의술사는 오두막 안에서 치료를 하고, 더 높은 레벨의 헤드헌터는 밖에 서 있습니다. 필드 가장자리를 지우고 인터럽트를 저장합니다."}, grind={[1]={mob="마른나무껍질부족 도끼투척병", note="마른나무껍질 마을 외부의 밀집된 일반 원거리 몹. 퀘스트 지역 근처의 경사면에서 적을 한 명씩 끌어당깁니다. 32로 갈아줍니다."}, [2]={mob="마른나무껍질부족 의술사", note="마른나무껍질 마을 동부의 조밀한 일반 캐스터. 주문 방해는 건물 주변을 치유하고 제거합니다. 더 높은 레벨의 마른나무껍질 인간사냥꾼을 조심하세요."}}, supply={[1]={npc="우르다"}, [2]={npc="여관주인 아데그와"}, [3]={npc="무우타"}, [4]={npc="여관주인 아데그와"}, [5]={npc="그라우드"}}, steps={[1]={hint="돌주먹 오우거 8마리와 돌주먹일족 집행자 10마리를 처치한 다음 아라시 고원의 해머폴로 가서 드럼 펠을 찾아야 합니다."}, [2]={text="해머폴(73.02, 32.70)에 도착하면 우르다의 비행 지점를 알아보세요."}, [3]={npc="드럼 펠", tgt="드럼 펠"}, [4]={npc="고르멀", tgt="고르멀"}, [5]={hint="해머폴에 있는 토건과 대화해야 합니다."}, [6]={npc="토건", tgt="토건"}, [7]={npc="토건", tgt="토건"}, [8]={npc="토건", tgt="토건"}, [9]={npc="드럼 펠", tgt="드럼 펠"}, [10]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터"}, [11]={hint="줄무늬 고원랩터와 외뿔 고원랩터에게서 고원 랩터 눈 10개를 구해 해머폴에 있는 토건에게 가져가야 합니다."}, [12]={hint="해머폴에 있는 토건에게 혈석 아뮬렛 10개를 가져가야 합니다."}, [13]={npc="토건", tgt="토건"}, [14]={npc="토건", tgt="토건"}, [15]={npc="토건", tgt="토건"}, [16]={hint="고르멀에게 랩터 발톱 아뮬렛을 전달해야 합니다."}, [17]={npc="고르멀", tgt="고르멀"}, [18]={npc="고르멀", tgt="고르멀"}, [19]={hint="토건과 대화해야 합니다."}, [20]={npc="토건", tgt="토건"}, [21]={hint="마른나무껍질부족 도끼투척병 10명과 인간사냥꾼 10명, 의술사 8명을 처치하고 해머폴 전초기지에 있는 드럼 펠에게 돌아가야 합니다."}, [22]={hint="아라시 고원 해머폴에 있는 의사 그레고리 빅터에게 외과용 거미줄 12개를 가져가야 합니다."}, [23]={npc="드럼 펠", tgt="드럼 펠"}, [24]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터"}, [25]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터", desc="공급 퀘스트를 잠금 해제하려면 동일한 의사에게 비단결 봉합사를 제출하세요."}, [26]={hint="고셰크 농장 조렐의 실험실에서 포장된 강장제 보관함을 획득한 후, 해머폴에 있는 의사 그레고리 빅터에게 반환해야 합니다."}, [27]={npc="의사 그레고리 빅터", tgt="의사 그레고리 빅터"}, [28]={text="언더시티로 날아가서 훈련하고 가방을 정리하세요. 브릴 남쪽에서 비행선을 타고 오그리마로 가세요. 잠금이 해제되면 높새바람 봉우리로 날아갑니다. 그렇지 않으면 타우라조 야영지로 날아가서 Great 승강기를 타고 내려간 다음 높새바람 봉우리 리프트를 타고 올라갑니다."}}},
    ["05-d13"] = {name="붉은십자군 수도원: 대성당", entrance="티리스팔 숲 85.20, 32.10", pickup="해머폴에서 언더시티로 비행합니다. 레벨 35에서는 도서관와 무기고를 이용해 대성당을 운영하세요. 힐스브래드 레그에서 왕실의 바리마트라스를 확인하여 레벨 33의 붉은십자군 수도원으로를 확인하세요. 35 미만인가요? 알터랙 산맥 반환을 위해 실행을 저장합니다. 스칼렛 키를 가져와 도서관와 무기고 처치를 완료하세요.", pickupS={{"해머폴에서 언더시티로 비행합니다"}, {"레벨 35에서는 도서관와 무기고를 이용해 대성당을 운영하세요"}, {"힐스브래드 레그에서 왕실의 바리마트라스를 확인하여 레벨 33의 붉은십자군 수도원으로를 확인하세요"}, {"35 미만인가요?"}, {"알터랙 산맥 반환을 위해 실행을 저장합니다"}, {"스칼렛 키를 가져와 도서관와 무기고 처치를 완료하세요"}}, tips={{k="動線", text="분수대 안뜰을 건너 계단을 올라가고 → 대성당에서 모그레인을 처치하고 → 화이트메인이 그를 부활시키기를 기다리고 → 둘 다 처치합니다."}, {k="取捨", text="아직도 Loksey나 헤로드가 필요합니까? 마을로 돌아가기 전에 해당 동으로 돌아가세요."}, {k="說明", text="스칼렛 키를 가져오거나 도적와 별 관측 자물쇠 따기로 문을 열도록 하세요.", s={{"스칼렛 키를 가져오거나 도적와 별 관측 자물쇠 따기로 문을 열도록 하세요"}}}}, steps={[1]={text="선행 퀘스트: 붉은십자군 수도원으로"}, [2]={text="붉은십자군 수도원: 대성당 입구"}, [3]={hint="종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 붉은십자군 용사 헤로드와 사냥개조련사 록시를 처치한 후 언더시티에 있는 바리마트라스에게 돌아가 보고해야 합니다.", desc="먼저 방 주변을 정리하세요. 화이트메인이 모그레인을 부활시킵니다. 위치: 분수 마당을 건너 계단을 올라갑니다. 두 대성당 보스를 모두 처치하십시오. 순서: 모그레인 처치 → 화이트메인이 그를 부활 → 둘 다 싸웁니다.", spot="분수 마당을 건너 계단을 올라갑니다. 두 대성당 보스를 모두 처치하십시오."}, [4]={npc="바리마트라스", tgt="바리마트라스", desc="4명의 보스가 모두 카운트된 후 언더시티의 왕실에 반납하세요."}}},
    ["05-d12"] = {name="붉은십자군 수도원: 무기고", entrance="티리스팔 숲 85.20, 32.10", pickup="해머폴에서 언더시티로 날아가서 Armoury를 도서관와 페어링하세요. 레벨 33에서는 왕실에 있는 바리마트라스에서 붉은십자군 수도원으로를 획득하세요. 이미 갖고 있다면 활성화 상태를 유지하고 주홍열쇠를 가져오세요. 티리스팔을 거쳐 수도원까지 북쪽 도로를 따라 가세요.", pickupS={{"해머폴에서 언더시티로 날아가서 Armoury를 도서관와 페어링하세요"}, {"레벨 33에서는 왕실에 있는 바리마트라스에서 붉은십자군 수도원으로를 획득하세요"}, {"이미 갖고 있다면 활성화 상태를 유지하고 주홍열쇠를 가져오세요"}, {"티리스팔을 거쳐 수도원까지 북쪽 도로를 따라 가세요"}}, tips={{k="動線", text="무기고 문을 열고 → 병영과 홀을 따라 헤로드로 이동 → 스칼렛 훈련생이 죽은 후 처치하세요."}, {k="取捨", text="스칼렛 키를 갖고 있는 사람이 있다면 바로 무기고로 가세요."}, {k="說明", text="스칼렛 키를 가져오거나 도적와 별 관측 자물쇠 따기로 문을 열도록 하세요.", s={{"스칼렛 키를 가져오거나 도적와 별 관측 자물쇠 따기로 문을 열도록 하세요"}}}}, steps={[1]={text="선행 퀘스트: 붉은십자군 수도원으로"}, [2]={text="붉은십자군 수도원: 무기고 입구"}, [3]={text="붉은십자군 수도원으로에 대해 헤로드를 종료합니다. 근접 공격은 소용돌이 중에 물러나야 합니다."}, [4]={text="대성당용으로 붉은십자군 수도원으로를 유지하세요. 네 명의 보스를 모두 처치한 후 언더시티에 제출하세요.", desc="무기고 이후 퀘스트를 유지하고 대성당으로 계속 진행하세요."}}},
    ["05-d11"] = {name="붉은십자군 수도원: 도서관", entrance="티리스팔 숲 85.20, 32.10", pickup="도서관를 위해 해머폴에서 언더시티로 비행하세요. 먼저 높새바람 봉우리에서 Dorn의 믿음의 시험 → 인내의 시험 → 용기의 시험 체인을 수행합니다. 해바위 야영지를 완료했다면 남쪽 잿빛 골짜기 터널을 사용하여 Braug로 이동한 다음 언더시티에서 Parqual을 참조하세요. 오크, 타우렌, 트롤은 썬더 블러프에서 타락의 개요를 차지할 수 있습니다. 마법사는 Shimmering Flats 및 담쟁이 마을에서 타베사 및 Tirth의 전제 조건을 수행한 후 다음 동부 왕국 방문에서 책을 얻을 수 있습니다.", pickupS={{"도서관를 위해 해머폴에서 언더시티로 비행하세요"}, {"먼저 높새바람 봉우리에서 Dorn의 믿음의 시험 → 인내의 시험 → 용기의 시험 체인을 수행합니다"}, {"해바위 야영지를 완료했다면 남쪽 잿빛 골짜기 터널을 사용하여 Braug로 이동한 다음 언더시티에서 Parqual을 참조하세요"}, {"오크, 타우렌, 트롤은 썬더 블러프에서 타락의 개요를 차지할 수 있습니다", {race={"Orc", "Tauren", "Troll"}}}, {"마법사는 Shimmering Flats 및 담쟁이 마을에서 타베사 및 Tirth의 전제 조건을 수행한 후 다음 동부 왕국 방문에서 책을 얻을 수 있습니다", {class={"MAGE"}}}}, tips={{k="動線", text="갤러리를 지나 작은 왼쪽 방에서 책 가져오기 → 사냥개조련사 록시 죽이기 → Doan 앞의 마지막 복도와 선반에서 책 모으기 → 신비술사 도안를 죽이고 그의 뒤에 있는 금고에서 주홍 열쇠를 약탈하세요."}, {k="取捨", text="무기고와 대성당을 열려면 스칼렛 키를 획득하세요. 동시에 퀘스트 책을 집으십시오."}, {k="說明", text="Quest 붉은십자군 수도원으로는 세 개의 날개에 걸쳐 있습니다. 전체 클리어 및 턴인에 대해서는 대성당 섹션을 참조하세요.", s={{"Quest 붉은십자군 수도원으로는 세 개의 날개에 걸쳐 있습니다"}, {"전체 클리어 및 턴인에 대해서는 대성당 섹션을 참조하세요"}}}}, steps={[1]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", desc="높새바람 봉우리에서 이 작업을 수행했다면 건너뛰세요."}, [2]={hint="믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오.", tag="선택사항", desc="높새바람 봉우리에서 이 작업을 수행했다면 건너뛰세요."}, [3]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", desc="높새바람 봉우리에서 이 작업을 수행했다면 건너뛰세요."}, [4]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", preText="믿음의 시험"}, [5]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 그렌카의 발톱을 가져가야 합니다.", tag="선택사항"}, [6]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항"}, [7]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", preText="인내의 시험"}, [8]={hint="버섯구름 봉우리에 있는 도른 플레인스토커에게 로크알림의 파편을 가져가야 합니다.", tag="선택사항"}, [9]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항"}, [10]={npc="도른 플레인스토커", tgt="도른 플레인스토커", tag="선택사항", preText="용기의 시험"}, [11]={hint="돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿을 찾아야 합니다.", tag="선택사항"}, [12]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항"}, [13]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", desc="동굴에서 책을 찾은 다음 브라우그에게 돌아가세요.", preText="지혜의 시험"}, [14]={hint="고대의 유산을 찾아 돌발톱 산맥에 있는 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿에게 가져가야 합니다.", tag="선택사항", desc="동굴에서 책을 찾은 다음 브라우그에게 돌아가세요."}, [15]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", desc="동굴에서 책을 찾은 다음 브라우그에게 돌아가세요."}, [16]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", preText="지혜의 시험"}, [17]={hint="브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다.", tag="선택사항"}, [18]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항"}, [19]={npc="브라우그 딤스피릿", tgt="브라우그 딤스피릿", tag="선택사항", preText="지혜의 시험"}, [20]={hint="언더시티에서 파쿠알 핀탈라스를 찾아야 합니다.", tag="선택사항"}, [21]={npc="파쿠알 핀탈라스", tgt="파쿠알 핀탈라스", tag="선택사항"}, [22]={npc="파쿠알 핀탈라스", tgt="파쿠알 핀탈라스", tag="선택사항", preText="지혜의 시험"}, [23]={npc="현자 트루스시커", tgt="현자 트루스시커"}, [24]={npc="바리마트라스", tgt="바리마트라스", desc="레벨 33+. 이번에 너무 낮으면 나중에 집어들고 Loksey를 다시 죽이세요."}, [25]={npc="다이노", tgt="다이노", tag="선택사항", desc="오그리마를 통해. 대체: 울신 굴 25.70,14.19; 아나스타샤 하트웰 85.14,10.03."}, [26]={hint="타베사와 대화하십시오.", tag="선택사항"}, [27]={npc="타베사", tgt="타베사", tag="선택사항"}, [28]={npc="타베사", tgt="타베사", tag="선택사항", preText="습지대로의 여행"}, [29]={hint="소금 평원에 있는 학자 틸스와 대화하십시오.", tag="선택사항"}, [30]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항"}, [31]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", preText="숨겨진 비밀"}, [32]={hint="틸스의 금고를 여는 주문을 알아서 틸스에게 돌아가야 합니다.", tag="선택사항"}, [33]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항"}, [34]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", preText="주문 알아오기"}, [35]={text="붉은십자군 수도원: 도서관 입구"}, [36]={hint="언데드 위협의 기원을 찾아 언더시티에 있는 파쿠알 핀탈라스에게 가져가야 합니다.", tag="선택사항", desc="위치: 갤러리 시작 부분 근처의 작은 왼쪽 방에 있는 테이블을 확인하세요.", spot="갤러리 시작 부분 근처의 작은 왼쪽 방에 있는 테이블을 확인하세요."}, [37]={hint="티리스팔 숲의 붉은십자군 수도원에서 타락의 개요를 찾아 썬더 블러프에 있는 현자 트루스시커에게 가져가야 합니다.", desc="위치: 패스 록시. 마지막 차례를 마치고 도안의 홀 시작 부분에 있는 책장을 확인하세요.", spot="패스 록시. 마지막 차례를 마치고 도안의 홀 시작 부분에 있는 책장을 확인하세요."}, [38]={hint="먼지진흙 습지대에 있는 타베사에게 마력의 의식을 가져가야 합니다.", tag="선택사항", desc="위치: 마지막 홀이 시작되면 왼쪽 선반에 튀어나온 책을 확인해보세요.", spot="마지막 홀이 시작되면 왼쪽 선반에 튀어나온 책을 확인해보세요."}, [39]={text="붉은십자군 수도원으로에 대해 사냥개조련사 록시를 종료합니다."}, [40]={text="신비술사 도안를 처치하고 그 뒤에 있는 금고에서 주홍 열쇠를 약탈하세요."}, [41]={npc="파쿠알 핀탈라스", tgt="파쿠알 핀탈라스", tag="선택사항"}, [42]={npc="현자 트루스시커", tgt="현자 트루스시커"}, [43]={npc="타베사", tgt="타베사", tag="선택사항"}}},
    ["03-17"] = {name="버섯구름 봉우리", nameA="버섯구름 봉우리: {a:484} & {a:439}", shortA="버섯구름 봉우리: {a:484} +", tips={{k="取捨", text="루프를 만들기 전에 Shimmering Flats 퀘스트 6개를 모두 선택하세요. 다음 톱니항 방문 시 배송을 수행하세요. 그런 다음 부두주임 디지위그에서 크레이블의 부품를 가져와 다음 Shimmering Flats 방문 시 경마장에 반납하세요."}, {k="取捨", text="카르가스의 경우 망명자 마르텍, 그늘수렵 마을의 경우 Brother(형제애), Grom'gol 및 무법항 다리의 경우 Nesingwary(헤멧 네싱워리)를 저장하세요."}, {k="提醒", text="곤충 떼의 위협을 제출하지 않은 경우 곤충 떼의 위협를 건너뛰세요. 영상에서는 벌집 깊은 곳에 있는 더 높은 레벨의 몹에 대해 경고합니다. 입구 근처에서 죽이고 떠나십시오. 실리시드 등껍질를 마치면 담쟁이 마을로 가는 길에 크로스로드에 반납하세요.", s={{"곤충 떼의 위협을 제출하지 않은 경우 곤충 떼의 위협를 건너뛰세요"}, {"영상에서는 벌집 깊은 곳에 있는 더 높은 레벨의 몹에 대해 경고합니다"}, {"입구 근처에서 죽이고 떠나십시오"}, {"실리시드 등껍질를 마치면 담쟁이 마을로 가는 길에 크로스로드에 반납하세요"}}}, {k="提醒", text="이 레벨 32-34 레그를 그늘수렵 마을와 결합합니다. 레벨 33 이하인가요? 경마장 남쪽(약 76, 85)에서 거북이, 독수리, 전갈을 갈아낸 다음 잊혀진 땅로 향합니다.", s={{"이 레벨 32-34 레그를 그늘수렵 마을와 결합합니다"}, {"레벨 33 이하인가요?"}, {"경마장 남쪽(약 76, 85)에서 거북이, 독수리, 전갈을 갈아낸 다음 잊혀진 땅로 향합니다"}}}}, danger={[1]="더 높은 레벨의 실리시드가 Shimmering Flats 벌집 뒤편을 가득 메우고 있습니다. 곤충 떼의 위협 이후 입구까지 발걸음을 되돌려보세요."}, grind={[1]={mob="소금바위 수정바실리스크", note="Shimmering Flats 경마장 남쪽에 밀집된 일반 몹. 레벨 32의 열린 소금 평지에서 싱글을 선택하세요."}, [2]={mob="굼벵이 소금껍질거북", note="소금 평지에서 동쪽으로 더 멀리 떨어진 일반 몹의 밀도는 보통이다. 도마뱀과 번갈아 가며 딱딱한 거북이 껍질을 수집하세요."}, [3]={mob="점박이독전갈", note="경마장 남동쪽에 있는 일반 몹의 밀도는 보통입니다. 지상을 돌며 다른 짐승을 조심하세요. 필요한 경우 소금기 있는 전갈 독를 수집하세요."}}, supply={[1]={npc="니세"}, [2]={npc="여관주인 아베크와"}, [3]={npc="스타른"}, [4]={npc="여관주인 아베크와"}, [5]={npc="스타른"}, [6]={npc="몬타르"}, [7]={npc="신게"}, [8]={npc="리즈넥"}, [9]={npc="신게"}}, steps={[1]={text="니세 의 높새바람 봉우리 비행 지점 (45.14, 49.11)를 배운 다음 남동쪽으로 길을 따라 Shimmering Flats로 가세요."}, [2]={npc="절벽파수꾼 롱혼", tgt="절벽파수꾼 롱혼"}, [3]={npc="목타르 크린", tgt="목타르 크린", tag="선택사항"}, [4]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [5]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [6]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [7]={npc="경주로관리인 제린", tgt="경주로관리인 제린"}, [8]={npc="포직", tgt="포직"}, [9]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [10]={hint="소금 평원에 있는 피즐 브라스볼츠에게 소금기 있는 전갈 독 6개를 가져가야 합니다."}, [11]={hint="소금 평원에 있는 위즐 브라스볼츠에게 단단한 거북 등껍질 9개를 가져가야 합니다."}, [12]={hint="소금 평원의 크레이블 콜비어드에게 로켓 자동차 부품 30개를 가져가야 합니다."}, [13]={hint="소금 평원에 있는 경주로관리인 제린을 위해 소금바위 바실리스크 10 마리, 소금바위 수정바실리스크 10 마리 및 소금바위 큰눈바실리스크 6 마리를 처치해야 합니다."}, [14]={hint="소금 평원에 있는 포직을 위해 가벼운 독수리 뼈 10개를 구해야 합니다."}, [15]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [16]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠"}, [17]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드"}, [18]={npc="경주로관리인 제린", tgt="경주로관리인 제린"}, [19]={npc="포직", tgt="포직"}, [20]={npc="피즐 브라스볼츠", tgt="피즐 브라스볼츠"}, [21]={npc="포직", tgt="포직", tag="톱니항를 통과하는 경우, 선택사항"}, [22]={npc="크레이블 콜비어드", tgt="크레이블 콜비어드", tag="톱니항를 통과하는 경우, 선택사항"}, [23]={text="부두주임 디지위그를 획득했다면 톱니항로 우회하세요."}, [24]={hint="톱니항에 있는 가즈로와 대화하십시오.", tag="톱니항를 통과하는 경우, 선택사항"}, [25]={hint="톱니항에 있는 부두주임 디지위그에게 크레이블의 부품주문서를 가져가야 합니다.", tag="톱니항를 통과하는 경우, 선택사항"}, [26]={npc="가즈로", tgt="가즈로", tag="톱니항를 통과하는 경우, 선택사항"}, [27]={npc="부두주임 디지위그", tgt="부두주임 디지위그", tag="톱니항를 통과하는 경우, 선택사항"}, [28]={npc="가즈로", tgt="가즈로", tag="선택사항"}, [29]={npc="금이 간 실리시드 등껍질", npcObj=true, tag="곤충 떼의 위협 중에 떨어지면 수락합니다., 선택사항", desc="곤충 떼의 위협년 동안 금이 간 실리시드 등껍질를 루팅하세요. 퀘스트를 시작하려면 마우스 오른쪽 버튼을 클릭하세요."}, [30]={hint="크로스로드에 있는 코란에게 실리시드의 심장 1개, 실리시드의 갈퀴발톱 5개, 온전한 실리시드의 등껍질 3개를 가져가야 합니다.", tag="곤충 떼의 위협와 함께 수행, 선택사항"}, [31]={hint="탐색꾼 실리시드 5마리, 일꾼 실리시드 5마리, 병정 실리시드 5마리를 처치하고 버섯구름 봉우리에 있는 목타르 크린에게 돌아가야 합니다.", tag="선택사항"}, [32]={npc="목타르 크린", tgt="목타르 크린", tag="선택사항"}, [33]={hint="불모의 땅에 있는 이슬렌 워터시어에게 물의 결정을 가져가야 합니다.", desc="물의 토템를 얻으려면 퀘스트를 완료하세요."}, [34]={npc="이슬렌 워터시어", tgt="이슬렌 워터시어", desc="물의 토템를 얻으려면 퀘스트를 완료하세요."}, [35]={npc="시안 파이어워더", tgt="시안 파이어워더", desc="오그리마 에서 바람의 부름 를 시작하거나 썬더 블러프 에서 바람의 부름 시작 퀘스트를 가져옵니다."}, [36]={hint="버섯구름 봉우리에서 프레이트 클라우드시어를 찾아야 합니다.", desc="오그리마 에서 바람의 부름 를 시작하거나 썬더 블러프 에서 바람의 부름 시작 퀘스트를 가져옵니다."}, [37]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", desc="오그리마 에서 바람의 부름 를 시작하거나 썬더 블러프 에서 바람의 부름 시작 퀘스트를 가져옵니다."}, [38]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="알터랙을 위해 최종 보스의 메모를 저장하세요. 라우 클리프러너도 제공합니다(46.14, 51.71)."}, [39]={hint="가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 관한 정보를 수집해야 합니다.", tag="선택사항", desc="알터랙 턴인에 대한 가시덩굴 우리의 최종 보스의 메모를 보관하세요."}, [40]={text="Shimmering Flats를 마친 후 경로를 되돌아보고 리프트를 타고 높새바람 봉우리까지 가세요. 해바위 야영지로 비행한 다음 Charred Vale을 통해 남서쪽으로 이동하여 잊혀진 땅로 이동합니다."}}},
    ["05-d14"] = {name="가시덩굴 우리", entrance="불모의 땅 (1413), 가시 통로의 던전 입구 근처. 약 42.30, 89.90.", pickup="버섯구름 봉우리로 가는 길에 가시덩굴 우리를 실행하세요. 톱니항 에서 청엽수 줄기 및 고퍼 도구를 선택합니다. 힐스브래드로 가는 길에 언더시티에 있는 Faranell에게서 조분석을 나에게!를 수락하세요. 달리기 전에 썬더 블러프를 통과한다면 Auld에서 운명의 복수를 얻으십시오. 높새바람 봉우리에서 Great 승강기를 불모의 땅으로 다시 가져간 다음 서쪽 가시 길을 따라 포털로 가세요.", pickupS={{"버섯구름 봉우리로 가는 길에 가시덩굴 우리를 실행하세요"}, {"톱니항 에서 청엽수 줄기 및 고퍼 도구를 선택합니다"}, {"힐스브래드로 가는 길에 언더시티에 있는 Faranell에게서 조분석을 나에게!를 수락하세요"}, {"달리기 전에 썬더 블러프를 통과한다면 Auld에서 운명의 복수를 얻으십시오"}, {"높새바람 봉우리에서 Great 승강기를 불모의 땅으로 다시 가져간 다음 서쪽 가시 길을 따라 포털로 가세요"}}, tips={{k="動線", text="가시덤불 길을 따라 청엽수 줄기용 고퍼 사용 → 옆길의 루구그 → 자르그바 → 람터스크 → 동굴의 박쥐 구아노 → 하트와 퀘스트 전리품을 위한 찰가의 오두막 → 윌릭스의 텐트로 돌아와 입구까지 안내합니다."}, {k="取捨", text="열정의 증거와 후속 가시덩굴 구릉를 잠금 해제하려면 전면 홀에서 최종 보스와 박쥐를 처치하세요. 시간이 부족할 경우에는 먼저 길을 따라 고퍼나 에스코트를 하세요."}, {k="說明", text="가시덩굴 우리는 Great 승강기의 서쪽에 있습니다. 가시덩굴 구릉는 동쪽입니다. Forever 클라이언트는 42.30, 89.90에 입구를 표시합니다. 주요 도로에서 서쪽 가시 터널을 따라 던전 포털로 이동하세요.", s={{"가시덩굴 우리는 Great 승강기의 서쪽에 있습니다"}, {"가시덩굴 구릉는 동쪽입니다"}, {"Forever 클라이언트는 42.30, 89.90에 입구를 표시합니다"}, {"주요 도로에서 서쪽 가시 터널을 따라 던전 포털로 이동하세요"}}}}, steps={[1]={npc="메보크 미지릭스", tgt="메보크 미지릭스", desc="입장하기 전에 톱니항 NPC로부터 상자, 커맨드 스틱, 설명서를 받으세요."}, [2]={npc="아울드 스톤스파이어", tgt="아울드 스톤스파이어"}, [3]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="붉은십자군 수도원 퀘스트 열정의 증거을 잠금 해제하려면 제출하세요."}, [4]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항"}, [5]={hint="타우라조 야영지에 있는 루가 레이지토템에게 꿈틀거리는 더듬이 5개를 가져가야 합니다.", tag="선택사항"}, [6]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항"}, [7]={npc="루가 레이지토템", tgt="루가 레이지토템", tag="선택사항", preText="거인의 들판에서의 시험"}, [8]={hint="불모의 땅에 있는 툰그림 파이어게이즈와 대화하십시오.", tag="선택사항"}, [9]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [10]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항", desc="연기가 자욱한 철 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개를 가져오세요. 마지막 매트: RFK.", preText="거인의 들판에서의 시험, 툰그림과의 대화"}, [11]={npc="시안 파이어워더", tgt="시안 파이어워더", tag="던전 선행"}, [12]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="던전 선행"}, [13]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="레벨 30 토템 체인. 대체 수락: 라우 클리프러너(46.14, 51.71)."}, [14]={text="가시덩굴 우리 입구"}, [15]={hint="구멍 난 상자를 집어야 합니다.", desc="위치: 파기는 가시나무 길을 따라 덩이줄기 위로 올라가거나 Willix를 다시 호위하는 동안.", spot="파기는 가시나무 길을 따라 덩이줄기 위로 올라가거나 Willix를 다시 호위하는 동안."}, [16]={hint="툰그림 파이어게이즈에게 연기나는 철제 주괴 15개, 아주라이트 가루 10개, 철 주괴 10개, 연소 약병 1개를 가져가야 합니다.", tag="선택사항", desc="위치: 루구그로 가는 초기 측면 경로를 택하세요. 먼저 추가 내용을 삭제하세요.", spot="루구그로 가는 초기 측면 경로를 택하세요. 먼저 추가 내용을 삭제하세요."}, [17]={npc="수입업자 윌릭스", tgt="수입업자 윌릭스", tag="게임 내 확인이 필요합니다", desc="던전 내 NPC로부터 호위를 시작하세요."}, [18]={hint="수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다.", desc="던전 내 NPC로부터 호위를 시작하세요. 위치: 마지막 보스 옆에 있는 텐트에서 윌릭스를 찾아 입구로 다시 데려가세요. 순서: 호위를 시작하기 전에 17~20단계를 완료하세요.", spot="마지막 보스 옆에 있는 텐트에서 윌릭스를 찾아 입구로 다시 데려가세요."}, [19]={npc="수입업자 윌릭스", tgt="수입업자 윌릭스", tag="게임 내 확인이 필요합니다", desc="던전 내 NPC로부터 호위를 시작하세요.", spot="던전 입구, 호위가 끝나는 곳"}, [20]={hint="언더시티에 있는 수석 연금술사 파라넬에게 가시덩굴 조분석을 가져가야 합니다.", desc="위치: 최종 보스가 나타나기 전에 동굴에서 박쥐를 처치하세요.", spot="최종 보스가 나타나기 전에 동굴에서 박쥐를 처치하세요."}, [21]={hint="썬더 블러프에 있는 아울드 스톤스파이어에게 차를가의 심장을 가져가야 합니다.", desc="위치: 박쥐 동굴을 떠나 플랫폼으로 올라가 마지막 오두막에서 Charlga를 죽이십시오.", spot="박쥐 동굴을 떠나 플랫폼으로 올라가 마지막 오두막에서 Charlga를 죽이십시오."}, [22]={hint="가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 관한 정보를 수집해야 합니다.", tag="선택사항", desc="위치: 18단계를 수행하는 동안 마지막 오두막에서 Charlga를 처치하십시오. 순서: 18단계에서 이것을 약탈하세요.", spot="18단계를 수행하는 동안 마지막 오두막에서 Charlga를 처치하십시오."}, [23]={npc="작은 두루마리", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="서슬깃 차를가에서 작은 두루마리를 루팅하고 사용하세요. 언더시티용으로 저장하세요."}, [24]={npc="메보크 미지릭스", tgt="메보크 미지릭스"}, [25]={npc="아울드 스톤스파이어", tgt="아울드 스톤스파이어"}, [26]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", desc="언더시티 에서 제출한 다음 열정의 증거를 수락합니다."}, [27]={hint="작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다.", tag="선택사항"}, [28]={npc="바리마트라스", tgt="바리마트라스", tag="선택사항"}, [29]={npc="툰그림 파이어게이즈", tgt="툰그림 파이어게이즈", tag="선택사항"}, [30]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="알터랙에서 제출하세요. 로그에 높새바람 봉우리 라고 표시되면 Rau(46.14, 51.71)를 참조하세요."}}},
    ["03-18"] = {name="잊혀진 땅", nameA="잊혀진 땅: {a:2408}", tips={{k="取捨", text="고속도로 강도와 뼈 수집가를 함께 수행하십시오. 비블리의 오두막으로 가는 길에 모닥불를 클릭하세요. 세 가지 퀘스트는 모두 레벨 40이며 레벨 30이 필요합니다. 무법항에 대한 On the Lam 제출을 저장하세요."}, {k="取捨", text="남쪽 도로에서 겔키스 퀘스트 겔키스 동맹 및 보급품 훔치기를 수행하세요. Magram을 선택했거나 평판이 잘못된 경우 그늘수렵 마을 Gelkis 후속 조치를 모두 건너뛰세요."}, {k="取捨", text="그늘수렵 마을 해안 루프에서는 물 퀘스트와 고대서를 함께 수행하세요. 천둥도끼 요새 에서 빛의 홀 및 이룩소스의 손를 먼저 수행합니다. 경험치가 부족한 경우 두 번째 방문 시 제출하세요."}, {k="取捨", text="캐러밴이 없으면 계속 이동하세요. 호위를 기다리지 마십시오. 가시덤불 골짜기의 다음 정류장을 위해 가시덤불 골짜기의 사냥꾼를 저장하세요."}, {k="提醒", text="레벨 34 이하? 가시덤불 골짜기로 떠나기 전에 코도 무덤(약 56, 60-68) 주변의 일반 켄타우로스 또는 서해안의 Slitherblade 나가(35.91, 28.84)를 처치하세요.", s={{"레벨 34 이하?"}, {"가시덤불 골짜기로 떠나기 전에 코도 무덤(약 56, 60-68) 주변의 일반 켄타우로스 또는 서해안의 Slitherblade 나가(35.91, 28.84)를 처치하세요"}}}}, danger={[1]="서해안 나가들은 수중 마크루라 근처에 있습니다. 수중에서 두 무리가 공격하는 것을 방지하려면 캐스터를 해변으로 당기십시오."}, grind={[1]={note="코도 무덤 동쪽의 희박한 일반 몹. 다른 썩은 고기 새를 조심하세요. 묘지 퀘스트 루프에서 작은 경험치를 선택하세요."}, [2]={mob="뱀갈퀴일족 나가", note="서해안의 밀집된 일반 몹. 싱글을 선택하고 근처의 마법사를 살펴보세요. 다른 해안 퀘스트와 짝을 이루세요."}, [3]={mob="뱀갈퀴일족 여마법사", note="서해안 나가 지역 남쪽 끝에 있는 일반 시전자의 밀도는 보통입니다. 마크루라가 추가되는 것을 방지하려면 해안으로 끌어당기세요."}}, supply={[1]={npc="탈론"}, [2]={npc="여관주인 시케와"}, [3]={npc="해윌라니"}, [4]={npc="여관주인 시케와"}, [5]={npc="투크"}}, steps={[1]={npc="펠굴 투커츠", tgt="펠굴 투커츠"}, [2]={npc="구르다 와일드메인", tgt="구르다 와일드메인"}, [3]={npc="구르다 와일드메인", tgt="구르다 와일드메인"}, [4]={npc="나타카 롱혼", tgt="나타카 롱혼"}, [5]={hint="절벽파수꾼 롱혼의 보고서를 잊혀진 땅의 침묵의 초소에 있는 나타카 롱혼에게 가져가야 합니다."}, [6]={npc="나타카 롱혼", tgt="나타카 롱혼"}, [7]={npc="스미드 스크래블스크류", tgt="스미드 스크래블스크류"}, [8]={hint="길들인 코도 5마리와 코도 유인기를 자신의 야영지에 있는 스미드 스크래블스크류에게 가져가야 합니다."}, [9]={npc="스미드 스크래블스크류", tgt="스미드 스크래블스크류"}, [10]={text="겔키스(Gelkis) 마을을 지나 남쪽 도로를 따라 가세요. 탈론의 비행 지점(21.60, 74.13)를 배우고 귀환석를 그늘수렵 마을에 바인딩하세요."}, [11]={npc="룬 와일드메인", tgt="룬 와일드메인"}, [12]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [13]={npc="마이라힐", tgt="마이라힐"}, [14]={npc="드룰제가르 스크락후크", tgt="드룰제가르 스크락후크"}, [15]={npc="아카라이", tgt="아카라이"}, [16]={text="해안 → 천둥도끼 요새 → 동쪽으로 사티로스"}, [17]={npc="랙모어의 