은 지옥사냥개의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.", tag="선택사항", desc="하나의 지점을 선택하십시오. 루비로 마나먹는 지옥사냥개 또는 마법사 사냥개 영혼을 포획하세요. 메나라를 참조하세요."}, [78]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="하나의 지점을 선택하십시오. 루비로 마나먹는 지옥사냥개 또는 마법사 사냥개 영혼을 포획하세요. 메나라를 참조하세요."}, [79]={npc="수행사제 마가즈", tgt="수행사제 마가즈", tag="선택사항", desc="하나의 지점을 선택하십시오. 에메랄드로 하급 지옥불정령의 영혼을 사로잡으세요. 메나라를 참조하세요."}, [80]={hint="지옥불 에메랄드를 가지고 가서 잊혀진 땅의 지옥불정령 중 하나에게 사용해 영혼을 사로 잡아야 합니다. 성공하면 지옥불 에메랄드와 사로잡은 지옥불정령의 영혼을 불모의 땅에 있는 미네라에게 가져가야 합니다.", tag="선택사항", desc="하나의 지점을 선택하십시오. 에메랄드로 하급 지옥불정령의 영혼을 사로잡으세요. 메나라를 참조하세요."}, [81]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="하나의 지점을 선택하십시오. 에메랄드로 하급 지옥불정령의 영혼을 사로잡으세요. 메나라를 참조하세요."}, [82]={hint="톱니항이 내려다보이는 탑 안에 살고 있는 미네라의 조수들과 대화하고 그들이 제시하는 길 중 하나를 따라가야 합니다.", tag="선택사항"}, [83]={npc="타베사", tgt="타베사", tag="선택사항"}, [84]={npc="타베사", tgt="타베사", tag="선택사항"}, [85]={hint="보주의 악마를 물리치고 타베사와 대화하십시오.", tag="선택사항"}, [86]={npc="타베사", tgt="타베사", tag="선택사항"}, [87]={npc="타베사", tgt="타베사", tag="선택사항"}, [88]={hint="정화된 지옥의 보주를 불모의 땅의 미네라에게 가져가야 합니다.", tag="선택사항"}, [89]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항"}, [90]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="지점의 피날레를 수행하십시오. 완성된 다르오라힐의 보주 또는 완성된 노오라힐의 보주가 표시되지 않으면 정화의 보주 가져가기 이후 Menara를 확인하세요."}, [91]={hint="미네라 보이드렌더가 다르오라힐의 보주를 완성시킬 때까지 기다렸다가 그녀에게 말을 걸어야 합니다.", tag="선택사항", desc="지점의 피날레를 수행하십시오. 완성된 다르오라힐의 보주 또는 완성된 노오라힐의 보주가 표시되지 않으면 정화의 보주 가져가기 이후 Menara를 확인하세요."}, [92]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="지점의 피날레를 수행하십시오. 완성된 다르오라힐의 보주 또는 완성된 노오라힐의 보주가 표시되지 않으면 정화의 보주 가져가기 이후 Menara를 확인하세요."}, [93]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="지점의 피날레를 수행하십시오. 완성된 다르오라힐의 보주 또는 완성된 노오라힐의 보주가 표시되지 않으면 정화의 보주 가져가기 이후 Menara를 확인하세요."}, [94]={hint="미네라 보이드렌더가 노오라힐의 보주를 완성하길 기다렸다가 그녀에게 말을 걸어야 합니다.", tag="선택사항", desc="지점의 피날레를 수행하십시오. 완성된 다르오라힐의 보주 또는 완성된 노오라힐의 보주가 표시되지 않으면 정화의 보주 가져가기 이후 Menara를 확인하세요."}, [95]={npc="미네라 보이드렌더", tgt="미네라 보이드렌더", tag="선택사항", desc="지점의 피날레를 수행하십시오. 완성된 다르오라힐의 보주 또는 완성된 노오라힐의 보주가 표시되지 않으면 정화의 보주 가져가기 이후 Menara를 확인하세요."}, [96]={text="그늘수렵 마을에서 오그리마로 비행합니다. 듀로타 비행선 탑(50.80, 13.60)에서 가시덤불 골짜기의 Grom'gol에 탑승하세요."}}},
    ["03-19"] = {name="가시덤불 골짜기", tips={{k="取捨", text="무법항를 처음 방문할 때 On the Lam을 제출하세요. 당신의 생각에 따라 체리 와인을 구입하시겠습니까? 아라시 고원 남동쪽 섬을 방문하면 후속 조치를 취하세요."}, {k="取捨", text="Zul'Kunda에서 Gimix를 찾은 경우에만 열쇠와 호위를 수행하십시오. 키와 도난당한 화물는 같은 영역에 있습니다. 다른 플레이어가 그를 호위하고 있다면 계속해서 퀘스트를 수행하세요. [zhTW quest record](https://wowamobi.com/quests/열쇠는 어디에?)"}, {k="取捨", text="무법항를 처음 방문하면 비행 지점를 잠금 해제하고 퀘스트를 받으세요. 레벨 35 정도에서는 붉은머리부족의 귀, 야영지 조사, 민물 악어 가죽, 노래하는 수정 조각 및 적대적 탈취 만 반납하고, 완료되면 돈 될 만한 물건 및 지믹스의 대탈출 를 반납하세요. 민물 악어 가죽 및 노래하는 수정 조각를 돌려 무쇠턱 악어 가죽 및 투자개발회사 채광을 잠금 해제하세요."}, {k="取捨", text="남부 루프 이후 무법항 반환을 위해 투자개발회사 채광 및 덩치큰 바다악어 가죽를 저장합니다. 을 잠금 해제하려면 방문 시 먼저 무쇠턱 악어 가죽를 반납하세요."}, {k="取捨", text="레벨 42 복귀를 위해 Bloodsail 붉은해적단 → 붉은해적단 → 붉은해적단 → 붉은해적단 → 붉은해적단를 저장하세요. 잃어버린 눈, 코담배를 찾아서, 잔질의 비법 및 겁쟁이 → 맥킨리에게 돌아가기 → 빚 돌려받기와 페어링합니다. 가시덤불 골짜기의 열병 / 가시덤불 골짜기의 열병, 쪽지가 든 병 → 쪽지가 든 병, 선장의 상자, 레벨 45+ 무법항 목록의 경우 위스키 슬림의 잃어버린 술병 및 선물로 받은 OOX. 비디오의 시차를 두고 진행되는 퀘스트를 따르고 이러한 퀘스트 ID를 사용하여 퀘스트를 계획하세요."}, {k="取捨", text="랩터 사냥법 익히기를 로 전진시킨 다음, 속눈썹꼬리 랩터와 그롬골 방어를 함께 처치하세요. 노래하는 수정 조각를 위해 북쪽 수정 가시 바실리스크를 처치하세요. 이번 방문에서는 남쪽 우회로를 건너뛰세요."}, {k="取捨", text="34세에 새롭게 시작하시나요? 세 가지 사냥 체인의 처음 두 라운드와 그롬골 및 피머리 퀘스트를 모두 수행하세요. Shadowmaw Panthers는 퓨마 사냥법 익히기 및 모크타르딘의 마법으로 계산됩니다. 동일한 루프에서 호랑이 사냥법 익히기를 위해 신달를 죽입니다. 네즐뤼크와의 대화를 위한 트로피 3개와 무법항를 위한 부서진 뼈목걸이를 저장하세요. 페이지가 있는 경우 가시덤불 골짜기의 푸른 언덕( - 제 4 장)를 제출하세요."}, {k="提醒", text="가라앉은 도시를 레벨 35에서 그룹으로 실행하세요(권장 35~40). 퀘스트를 먼저 확인해보세요. 그롬골 서쪽 해저로 들어가세요.", s={{"가라앉은 도시를 레벨 35에서 그룹으로 실행하세요(권장 35~40)"}, {"퀘스트를 먼저 확인해보세요"}, {"그롬골 서쪽 해저로 들어가세요"}}}, {k="提醒", text="34~35쯤 되면 가시덤불 북부(29.76, 21.62)에서 붉은머리 트롤을 처치합니다. 36에서 그롬골 남동쪽의 오우거 캠프(35.55, 30.92)로 전환하세요. 필요에 따라 37까지 갈고 비행선에 탑승하기 전에 캠프에서 완료된 퀘스트를 완료하세요.", s={{"34~35쯤 되면 가시덤불 북부(29.76, 21.62)에서 붉은머리 트롤을 처치합니다"}, {"36에서 그롬골 남동쪽의 오우거 캠프(35.55, 30.92)로 전환하세요"}, {"필요에 따라 37까지 갈고 비행선에 탑승하기 전에 캠프에서 완료된 퀘스트를 완료하세요"}}}}, danger={[1]="정예 소금비늘 멀록이 폐허를 지키고 있습니다. 표면에서 급강하를 꺼내 태블릿까지 외벽을 따라갑니다. 돌아오는 수영을 위해 충분한 공기를 남겨 두십시오.", [2]="줄쿤다의 폐허를 통해 Gimix의 호위가 순찰 경로를 통과합니다. 시작하기 전에 캠프 외부를 정리하세요."}, grind={[1]={mob="붉은머리부족 전사", note="북부 블러드스칼프 폐허에 있는 일반 몹의 밀도는 보통입니다. 외벽을 따라 적 한 명씩 끌어당기고 무당을 감시하세요. 34에서 연마하세요. 전사는 소용돌이 무기에 사용할 붉은머리 엄니를 수집할 수 있습니다."}, [2]={mob="채찍꼬리랩터", note="그롬골 북쪽 숲에 밀집된 일반 몹. 길을 따라 싱글을 선택하고 물 속의 엘리트 Saltscale 몹을 피하십시오. 랩터 사냥과 짝을 이루세요."}, [3]={mob="모쉬오그일족 투사", note="그롬골 남동쪽 오우거 캠프 외부에는 보통 몹이 밀집해 있습니다. 마녀 의사와 희귀한 로로취를 피하세요. 레벨 36에서 37까지 연마하세요."}}, supply={[1]={npc="시스타"}, [2]={npc="여관주인 툴벡"}, [3]={npc="크래크"}, [4]={npc="나르가트"}, [5]={npc="우톡"}, [6]={npc="그링거"}, [7]={npc="여관주인 스킨들"}, [8]={npc="주타크"}, [9]={npc="닉스락스 필라머그"}, [10]={npc="하렌 칸메"}}, steps={[1]={text="오그리마 외부에서 그롬골 비행선을 가져가세요. 시스타의 비행 지점(32.54, 29.35)를 알아보세요. 이미 가시덤불 골짜기에 있다면 곧바로 캠프로 향하세요."}, [2]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬"}, [3]={npc="님보야", tgt="님보야", tag="밀집된 몹, 선택사항"}, [4]={npc="킨윌레이", tgt="킨윌레이", tag="밀집된 몹, 선택사항"}, [5]={npc="예언자 모크타르딘", tgt="예언자 모크타르딘"}, [6]={npc="님보야", tgt="님보야"}, [7]={npc="킨윌레이", tgt="킨윌레이"}, [8]={npc="식충 잡초", tgt="젬밀", desc="크랭크 피즐버브는 이 퀘스트(27.12, 77.21)도 제공합니다."}, [9]={hint="그롬골 주둔지에 있는 킨윌레이에게 서판 조각을 가져가야 합니다.", desc="수영를 가라앉은 유적 외벽의 석판에 연결합니다. 정예 멀록 순찰대를 피하세요."}, [10]={npc="킨윌레이", tgt="킨윌레이"}, [11]={npc="킨윌레이", tgt="킨윌레이", desc="이것을 켜면 물(물속의 적)의 적들을 잠금 해제할 수 있습니다."}, [12]={text="잠금이 해제된 경우 그롬골에서 무법항로 비행하세요. 그렇지 않으면 남쪽으로 길을 따라 그링거의 비행 지점(26.87, 77.10)를 알아보세요. 돌아오기 전에 첫 번째 배치를 선택하세요."}, [13]={npc="케복", tgt="케복", tag="밀집된 몹, 선택사항"}, [14]={npc="크라젝", tgt="크라젝"}, [15]={npc="크라젝", tgt="크라젝"}, [16]={npc="크라젝", tgt="크라젝"}, [17]={npc="드리즐릭", tgt="드리즐릭"}, [18]={npc="크랭크 피즐버브", tgt="크랭크 피즐버브"}, [19]={hint="잊혀진 땅 약탈자를 찾아야 합니다."}, [20]={npc="토칼", tgt="토칼"}, [21]={npc="토칼", tgt="토칼"}, [22]={hint="무법항에 있는 토칼에게 체리 그로그주를 가져간 후 이야기를 마저 들어야 합니다.", desc="사서 제출하세요. 마시지 마세요."}, [23]={npc="토칼", tgt="토칼", desc="반납 후 도둑의 명예 따윈 없다를 수락하세요. 아라시 고원 남동쪽 해안을 위해 저장하세요."}, [24]={npc="케복", tgt="케복"}, [25]={hint="무법항에 있는 부두주임 로즈길과 대화하십시오.", tag="선택사항"}, [26]={npc="부두주임 로즈길", tgt="부두주임 로즈길", tag="선택사항"}, [27]={npc="부두주임 로즈길", tgt="부두주임 로즈길", tag="선택사항"}, [28]={hint=