    ["05-d16"] = {name="The Drowned City", entrance="가시덤불 골짜기 21.50, 27.70", pickup="첫 번째 가시덤불 방문에 따라 Grom'gol에서 썩은내 산호초를 가져와 암초 목표를 수행한 다음 구루바시의 옛 전설에 반환합니다. 무법항의 크라젝에서 수상쩍은 소금선견자 및 소금선견자 대장를 가져옵니다. 줄쿤다에서 구루바시의 옛 전설에 대한 탁본을 가져가세요. Grom'gol로 돌아가서 잃어버린 도시를 찾아 및 물속의 적를 선택하고 서해안에서 둘 다 수행한 다음 가라앉은 도시 및 착한 소금비늘은 죽은 소금비늘뿐...을 선택합니다. 썬더 블러프를 잠금 해제한 경우 실행 전에 그곳으로 날아가서 멀고어 도로를 따라 하늘감시자 고원에서 마주콘까지 가세요. 그롬골로 돌아가 서해안에서 수중 차원문으로 수영해 가세요.", pickupS={{"첫 번째 가시덤불 방문에 따라 Grom'gol에서 썩은내 산호초를 가져와 암초 목표를 수행한 다음 구루바시의 옛 전설에 반환합니다"}, {"무법항의 크라젝에서 수상쩍은 소금선견자 및 소금선견자 대장를 가져옵니다"}, {"줄쿤다에서 구루바시의 옛 전설에 대한 탁본을 가져가세요"}, {"Grom'gol로 돌아가서 잃어버린 도시를 찾아 및 물속의 적를 선택하고 서해안에서 둘 다 수행한 다음 가라앉은 도시 및 착한 소금비늘은 죽은 소금비늘뿐...을 선택합니다"}, {"썬더 블러프를 잠금 해제한 경우 실행 전에 그곳으로 날아가서 멀고어 도로를 따라 하늘감시자 고원에서 마주콘까지 가세요"}, {"그롬골로 돌아가 서해안에서 수중 차원문으로 수영해 가세요"}}, tips={{k="動線", text="줄알라이 → 바르타카 → 대장 드레드라이즈 → 불사 골수 → 독사 민로스. 입구 웅덩이 왼쪽, 바르타카 왼쪽, 배 옆 두개골, Min'loth 뒤에 문지르기를 합니다. 해적에게서 유물을 약탈하세요. 태고의 정령 및 Gill은 선택 사항입니다."}, {k="取捨", text="밖으로 나가기 전에 그롬골 전제 조건을 모두 완료하면 함선 섹션보다 더 많은 일을 할 수 있습니다. 방해가 되는 경우 단일 멀고어 턴인을 건너뜁니다."}, {k="說明", text="입구는 그롬골 서쪽 물속 동굴에 있습니다. 수중 호흡 물약을 챙기거나 기술이 있는 파티원에게 부탁하세요.", s={{"입구는 그롬골 서쪽 물속 동굴에 있습니다"}, {"수중 호흡 물약을 챙기거나 기술이 있는 파티원에게 부탁하세요"}}}}, steps={[1]={npc="킨윌레이", tgt="킨윌레이", desc="Grom'gol 및 무법항 다리에서 이 작업을 수행했다면 건너뛰십시오."}, [2]={hint="그롬골 주둔지에 있는 킨윌레이에게 서판 조각을 가져가야 합니다.", desc="Grom'gol 및 무법항 다리에서 이 작업을 수행했다면 건너뛰십시오."}, [3]={npc="킨윌레이", tgt="킨윌레이", desc="Grom'gol 및 무법항 다리에서 이 작업을 수행했다면 건너뛰십시오."}, [4]={npc="킨윌레이", tgt="킨윌레이", preText="썩은내 산호초"}, [5]={hint="가죽과 목탄을 사용해 트롤의 전설 3부 서판의 탁본을 만들어야 합니다."}, [6]={npc="킨윌레이", tgt="킨윌레이"}, [7]={npc="킨윌레이", tgt="킨윌레이", preText="구루바시의 옛 전설"}, [8]={hint="썩은내 산호초를 살펴 동굴 입구를 찾아야 합니다."}, [9]={npc="킨윌레이", tgt="킨윌레이"}, [10]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", desc="썩은내 산호초 이후, 킨윌레이를 방문하면서 지휘관에게 확인하세요.", preText="썩은내 산호초, 구루바시의 옛 전설"}, [11]={hint="소금비늘 척후병에게서 소금비늘 삼지창 10개를 입수해야 합니다.", tag="대상: 소금비늘 척후병", desc="썩은내 산호초 이후, 킨윌레이를 방문하면서 지휘관에게 확인하세요."}, [12]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", desc="썩은내 산호초 이후, 킨윌레이를 방문하면서 지휘관에게 확인하세요."}, [13]={npc="킨윌레이", tgt="킨윌레이", preText="잃어버린 도시를 찾아"}, [14]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬", preText="물속의 적, 잃어버린 도시를 찾아"}, [15]={npc="크라젝", tgt="크라젝"}, [16]={npc="크라젝", tgt="크라젝"}, [17]={npc="마주콘", tgt="마주콘", tag="선택사항", desc="마주콘는 멀고어의 하늘감시자 고원에 있습니다. 운송 수단이 잠금 해제되어 있으면 가십시오."}, [18]={text="The Drowned City 입구"}, [19]={hint="가죽과 목탄을 사용해 가라앉은 도시에서 발견된 서판의 탁본을 만들어야 합니다.", desc="위치: 풀 왼쪽, 바르타카 왼쪽, 대장 드레드라이즈 두개골, 마지막 보스 뒤. 순서: 길을 따라 4개의 랜드마크를 문지르세요.", spot="풀 왼쪽, 바르타카 왼쪽, 대장 드레드라이즈 두개골, 마지막 보스 뒤."}, [20]={hint="가라앉은 도시에서 바르타카를 처치해야 합니다.", desc="보스 옆에 있는 사제를 먼저 처치하세요. 수중에서 호흡을 조심하세요. 위치: 줄알라이를 지나면 침수된 기록 보관소에서 두 명의 여사제 옆에 있는 보스를 찾으세요.", spot="줄알라이를 지나면 침수된 기록 보관소에서 두 명의 여사제 옆에 있는 보스를 찾으세요."}, [21]={hint="가라앉은 도시의 소금선견자 해적에게서 부두가 깃든 유물 10개를 수집해야 합니다.", desc="여전히 물품이 필요한 경우 배 주변의 해적을 계속 제거하세요. 위치: 배 옆에서 Saltseer 해적을 처치하고 유물을 약탈하세요. 순서: 21단계로 이 영역을 지웁니다.", spot="배 옆에서 Saltseer 해적을 처치하고 유물을 약탈하세요."}, [22]={hint="가라앉은 도시에서 소금선견자 검시관 3명과 대장 드레드라이즈를 처치해야 합니다.", desc="위치: 선박 구역의 선장 근처 통로를 따라 검시관을 제거하세요. 순서: 선장을 죽인 후 빛나는 진주를 클릭하세요.", spot="선박 구역의 선장 근처 통로를 따라 검시관을 제거하세요."}, [23]={hint="가라앉은 도시에서 고대 구루바시 우상을 회수해야 합니다.", tag="선택사항", desc="위치: 선장과 진주 방벽을 통과한 다음 불사신의 골수를 처치하십시오.", spot="선장과 진주 방벽을 통과한 다음 불사신의 골수를 처치하십시오."}, [24]={npc="킨윌레이", tgt="킨윌레이"}, [25]={npc="사령관 아그로고쉬", tgt="사령관 아그로고쉬"}, [26]={npc="크라젝", tgt="크라젝"}, [27]={npc="크라젝", tgt="크라젝"}, [28]={npc="마주콘", tgt="마주콘", tag="선택사항"}, [29]={npc="킨윌레이", tgt="킨윌레이", tag="선택사항", desc="이미 오그리마로 비행 중이라면 반납하세요. 실행이 끝날 때까지 기다릴 수 있습니다.", preText="가라앉은 도시"}, [30]={hint="서판 탁본을 듀로타 센진 마을에 있는 장로 가드린에게 가져가야 합니다.", tag="선택사항", desc="이미 오그리마로 비행 중이라면 반납하세요. 실행이 끝날 때까지 기다릴 수 있습니다."}, [31]={npc="장로 가드린", tgt="장로 가드린", tag="선택사항", desc="이미 오그리마로 비행 중이라면 반납하세요. 실행이 끝날 때까지 기다릴 수 있습니다."}}},
    ["05-d15"] = {name="놈리건", entrance="가시덤불 골짜기 27.60, 77.48", pickup="무법항 이전에 명예의 골짜기에서 소빅 및 노그를 방문하세요. 톱니항에서 보트를 타거나 Grom'gol에서 무법항까지 비행기를 타세요. 선임기술자 스쿠티 → 놈리거어어어언!를 스쿠티로 마무리하고 고블린 응답장치를 유지하여 입장하세요.", pickupS={{"무법항 이전에 명예의 골짜기에서 소빅 및 노그를 방문하세요"}, {"톱니항에서 보트를 타거나 Grom'gol에서 무법항까지 비행기를 타세요"}, {"선임기술자 스쿠티 → 놈리거어어어언!를 스쿠티로 마무리하고 고블린 응답장치를 유지하여 입장하세요"}}, tips={{k="動線", text="왼쪽으로 내려가서 Clean Zone으로 이동 → 오른쪽 구역에서 케르노비 호위 → 기계화 문지기 6000 → 고철 압축기 9-60 → Thermaplugg를 사용하고 금고에서 그의 코드를 사용하세요. 꼬질꼬질한 반지를 약탈한 경우 Clean Zone에서 Sparklematic을 사용하세요."}, {k="取捨", text="장비나 퀘스트 경험치가 그만한 가치가 있으면 실행하세요. 퀘스트를 무법항 퀘스트와 결합하여 여행 비용을 절약하세요."}, {k="說明", text="던 모로에 있는 시설로 텔레포터를 사용하고 지하 복도를 따라 던전 포털로 이동하세요. 아이언포지를 건너뛰세요. 텔레포터가 잠겨 있으면 스쿠티의 체인을 먼저 완료하세요.", s={{"던 모로에 있는 시설로 텔레포터를 사용하고 지하 복도를 따라 던전 포털로 이동하세요"}, {"아이언포지를 건너뛰세요"}, {"텔레포터가 잠겨 있으면 스쿠티의 체인을 먼저 완료하세요"}}}}, steps={[1]={npc="노그", tgt="노그"}, [2]={npc="소빅", tgt="소빅", preText="기술 전쟁"}, [3]={hint="무법항에 있는 스쿠티와 대화하십시오."}, [4]={npc="스쿠티", tgt="스쿠티"}, [5]={npc="스쿠티", tgt="스쿠티", preText="선임기술자 스쿠티"}, [6]={hint="스쿠티가 고블린 응답장치를 조절하는 동안 기다려야 합니다."}, [7]={npc="스쿠티", tgt="스쿠티"}, [8]={text="놈리건 입구"}, [9]={hint="놈리건에서 장치 설계도와 텔마플러그의 금고 암호를 찾아서 오그리마에 있는 노그에게 가져다주어야 합니다.", desc="전투 중에 누군가가 대피소 옆에 있는 버튼을 눌러 폭탄을 제어하게 하세요. 위치: 작업장 터널을 따라 둥근 방으로 가세요. 마지막 보스를 죽이고 금고를 엽니다.", spot="작업장 터널을 따라 둥근 방으로 가세요. 마지막 보스를 죽이고 금고를 엽니다."}, [10]={npc="케르노비", tgt="케르노비", tag="게임 내 확인이 필요합니다", desc="청정지역 근처에서 케르노비를 찾아보세요. 먼저 호위 경로를 클리어하세요."}, [11]={hint="태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.", desc="위치: Clean Zone 구역에서 케르노비를 수락하세요. 그를 정문까지 안내하세요. 순서: 최종 보스에게 더 깊이 들어가기 전에 9~10단계를 수행하세요.", spot="Clean Zone 구역에서 케르노비를 수락하세요. 그를 정문까지 안내하세요."}, [12]={npc="꼬질꼬질한 반지", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="은색 3개를 가져와 기계의 대사를 따라가세요."}, [13]={hint="꼬질꼬질한 반지에서 찌꺼기를 제거할 방법을 찾아야 합니다.", tag="선택사항", desc="은색 3개를 가져와 기계의 대사를 따라가세요. 위치: 좌회전하여 Clean Zone으로 내려갑니다. 벽 옆에서 Sparklematic을 찾으세요. 순서: 먼저 검은무쇠단 첩보원에서 반지를 약탈하세요.", spot="좌회전하여 Clean Zone으로 내려갑니다. 벽 옆에서 Sparklematic을 찾으세요."}, [14]={npc="삐까뻔쩍세척기 5200", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="은색 3개를 가져와 기계의 대사를 따라가세요.", spot="입구 왼쪽 경사 아래, 세척 구역 벽의 청소기"}, [15]={npc="삐까뻔쩍세척기 5200", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", preText="꼬질꼬질한 반지"}, [16]={npc="스쿠티", tgt="스쿠티"}, [17]={npc="노그", tgt="노그"}, [18]={hint="반지를 그냥 가지거나, 반지 안쪽 부분에 새겨진 인장 자국의 주인을 찾아야 합니다.", tag="선택사항"}, [19]={npc="노그", tgt="노그", tag="선택사항"}}},
    ["03-20"] = {name="먼지진흙 슾지대", nameA="먼지진흙 슾지대: {a:496}", tips={{k="取捨", text="마을에 들어가기 전에 불타버린 같은 여관에서 검은 방패, 수상한 발굽 자국, 부관 파발 리테를 수락하세요."}, {k="取捨", text="마을을 떠나기 전에 독특한 양념 3개를 가져오세요. 달의 강철 브로드소드가 있으면 켜십시오. 구매하거나 제작하면 우회가 추가됩니다. 합격하면 톱니항에서 말썽꾼의 탈출를 반납하거나, 저장하거나 건너뛰세요."}, {k="提醒", text="담쟁이 마을와 그늘수렵 마을는 함께 레벨 37~38을 커버합니다. 잊혀진 땅 퀘스트를 이미 제출한 경우 38까지 북부 먼지진흙 습지대에서 일반 거미와 랩터를 처치하세요.", s={{"담쟁이 마을와 그늘수렵 마을는 함께 레벨 37~38을 커버합니다"}, {"잊혀진 땅 퀘스트를 이미 제출한 경우 38까지 북부 먼지진흙 습지대에서 일반 거미와 랩터를 처치하세요"}}}}, danger={[1]="북부 습지에는 독거미와 랩터 순찰대가 겹칩니다. 가장자리에서 한 번에 한 명의 적을 끌어내고 수풀에서 순찰대가 만나는 지점을 피하십시오."}, grind={[1]={mob="시든덩굴 수렁괴물", note="다른 위더바인 몹과 함께 북쪽 늪지에 밀집된 일반 몹이 있습니다. 마른 땅에서 한 번에 한 명의 적을 끌어당겨 다음 정거장의 레벨에 도달하세요."}, [2]={mob="검은송곳니 독거미", note="북부 늪지 동부에는 보통의 몹 밀도가 있다. 독 피해와 랩터 순찰을 조심하세요. 위더바인 몹이 사육되고 있다면 여기로 이동하세요."}, [3]={mob="긴송곳니 붉은늪지랩터", note="북쪽 늪의 수목한계선을 따라 밀집된 일반 몹. 해안을 따라 한 번에 한 명의 적을 끌어당기고 악어와 다른 랩터를 조심하세요. 38시에 출발하세요."}}, supply={[1]={npc="샤르디"}, [2]={npc="크라크"}, [3]={npc="오그마르"}, [4]={npc="자나라"}, [5]={npc="발라이 로크웨인"}}, steps={[1]={npc="코란", tgt="코란", tag="선택사항"}, [2]={text="타우라조 야영지에서 동쪽으로 먼지진흙 습지대로 향합니다. 길가에 있는 불타버린 여관에 먼저 들러보세요."}, [3]={npc="검은 방패", npcObj=true}, [4]={npc="발굽 자국", npcObj=true}, [5]={npc="테라모어 경비병 휘장", npcObj=true}, [6]={nodeA="{a:496}", desc="잠금 해제 비행 지점 및 샤르디."}, [7]={text="다음 구간에서 돌아올 수 있도록 그늘수렵 마을 난로를 유지하세요."}, [8]={hint="담쟁이 마을에 있는 크로그에게 타락의 철제 방패를 가져가야 합니다."}, [9]={hint="담쟁이 마을에 있는 크로그에게 그늘 쉼터 여관의 수상한 흔적에 대해 보고해야 합니다."}, [10]={hint="담쟁이 마을에 있는 크로그에게 리테의 배지를 가져가야 합니다."}, [11]={npc="크로그", tgt="크로그"}, [12]={npc="크로그", tgt="크로그"}, [13]={npc="크로그", tgt="크로그"}, [14]={npc="크로그", tgt="크로그"}, [15]={hint="담쟁이 마을에 있는 도골에게 타락의 철제 방패를 보여 주십시오."}, [16]={npc="도골", tgt="도골"}, [17]={npc="도골", tgt="도골"}, [18]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [19]={npc="머드크러쉬 더트피트", tgt="머드크러쉬 더트피트"}, [20]={npc="오그론", tgt="오그론"}, [21]={hint="오그론과 함께 가서 리테를 심문한 다음 담쟁이 마을에 있는 크로그에게 돌아가야 합니다."}, [22]={npc="크로그", tgt="크로그"}, [23]={hint="테라모어 첩보원 9명을 처치한 다음 담쟁이 마을에 있는 나지르 블러드파이크에게 돌