", desc="토템 번들 10개를 유지하세요. 외부 봉인의 마법진에서 결합하십시오."}, [61]={npc="타베사", tgt="타베사", tag="선택사항", desc="토템 번들 10개를 유지하세요. 외부 봉인의 마법진에서 결합하십시오."}, [62]={npc="타베사", tgt="타베사", tag="선택사항"}, [63]={hint="소금 평원에 있는 학자 틸스와 대화하십시오.", tag="선택사항"}, [64]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항"}, [65]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", desc="치킨과 /beckon를 타겟으로 합니다. 인간으로 변한 후 말을 걸어보세요."}, [66]={hint="틸스의 금고를 여는 주문을 알아서 틸스에게 돌아가야 합니다.", tag="선택사항", desc="치킨과 /beckon를 타겟으로 합니다. 인간으로 변한 후 말을 걸어보세요."}, [67]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", desc="치킨과 /beckon를 타겟으로 합니다. 인간으로 변한 후 말을 걸어보세요."}, [68]={npc="학자 틸스", tgt="학자 틸스", tag="선택사항", desc="도서관를 위해 그룹을 구성하고 선반에서 책을 찾으세요."}, [69]={hint="먼지진흙 습지대에 있는 타베사에게 마력의 의식을 가져가야 합니다.", tag="선택사항", desc="도서관를 위해 그룹을 구성하고 선반에서 책을 찾으세요. 붉은십자군 수도원에 들어가면 도서관 구역으로 가세요."}, [70]={npc="타베사", tgt="타베사", tag="선택사항", desc="도서관를 위해 그룹을 구성하고 선반에서 책을 찾으세요."}, [71]={npc="타베사", tgt="타베사", tag="선택사항", desc="다시 보고하기 전에 지팡이 재료 체인을 모두 완료하세요.", star={"맹위의 얼음마법봉 / 황천의 마법봉 / 맹위의 화염마법봉"}}, [72]={hint="의식이 끝나면 타베사와 대화하십시오.", tag="선택사항", desc="다시 보고하기 전에 지팡이 재료 체인을 모두 완료하세요."}, [73]={npc="타베사", tgt="타베사", tag="선택사항", desc="다시 보고하기 전에 지팡이 재료 체인을 모두 완료하세요.", star={"맹위의 얼음마법봉 / 황천의 마법봉 / 맹위의 화염마법봉"}}, [74]={text="담쟁이 마을로 돌아가서 그늘수렵 마을로 날아갑니다. 경로를 이용할 수 없는 경우 크로스로드에서 항공편을 변경하세요. 만노로크 소굴에서 돌아올 때를 위해 난로를 아껴두세요."}}},
    ["03-21"] = {name="잊혀진 땅", nameA="잊혀진 땅: {a:2408}", tips={{k="取捨", text="영상에는 이번 왕복 여행이 포함되어 있습니다. 레벨 37에서 경험치가 부족하다면 남동부 켄타우로스 퀘스트와 인근 불타는 중 군단 포털을 수행하세요. 이룩소스의 손를 반납하여 악마의 차원문을 잠금 해제하세요. 상자를 사용하여 유령의 플라스마의 유령을 끌어낸 다음 한 번에 하나씩 처치하세요."}, {k="取捨", text="지금 온게쿠를 수락하고 스토나드 레그에서 수행하세요. 마을에서 이를 반납하여 칸 젠를 잠금 해제하세요. 나중에 저장해 둘 수 있습니다."}, {k="提醒", text="레벨 38 이하인가요? 만노로크 소굴 가장자리(50.40, 70.40 주변)에서 일반 악마를 처치하세요. 처치 속도가 느린 경우 코도 무덤 남동쪽의 켄타우로스로 전환하세요.", s={{"레벨 38 이하인가요?"}, {"만노로크 소굴 가장자리(50.40, 70.40 주변)에서 일반 악마를 처치하세요"}, {"처치 속도가 느린 경우 코도 무덤 남동쪽의 켄타우로스로 전환하세요"}}}}, danger={[1]="정예 영주들이 만노로크 소굴 남쪽을 배회합니다. 경험치나 재료는 동쪽에 있는 마법사 헌터에게 붙어주세요."}, grind={[1]={mob="하급 지옥불정령", note="만노로크 소굴 북쪽에 밀집된 일반 몹. 근처의 악마를 조심하세요. 워록은 마법의 황금 혈로브용 하급 지옥정령석를 수집할 수 있습니다."}, [2]={note="만노로크 소굴의 동일한 외부 가장자리에 있는 일반 캐스터의 적당한 밀도. 지형을 사용하여 무리에서 멀리 끌어내십시오. 하급 지옥불정령과 교대로 사용하세요."}, [3]={mob="마법사 사냥개", note="만노로크 소굴 동쪽의 일반 몹 밀도는 보통입니다. 가장자리 주변의 싱글을 선택하고 남쪽의 엘리트 군주를 피하세요. 외부 루프가 혼잡한 경우 이 지점을 사용하십시오."}}, supply={[1]={npc="탈론"}, [2]={npc="여관주인 시케와"}, [3]={npc="해윌라니"}, [4]={npc="여관주인 시케와"}, [5]={npc="투크"}}, steps={[1]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [2]={text="그늘수렵 마을에서 먼저 침묵의 초소로 이동합니다. 남쪽 도로를 따라 만노로크 소굴로 가세요."}, [3]={npc="호르니즈 브림버즐", tgt="호르니즈 브림버즐"}, [4]={npc="현자 우텍", tgt="현자 우텍", tag="전제 조건이 있는 Gelkis 체인, 선택사항"}, [5]={hint="만노로크 소굴에서 악마의 차원문 6개를 없애고 타이가 와이즈메인에게 돌아가야 합니다.", desc="홀에 있는 포털에서 타이가의 이룩소스의 손를 사용하여 6마리의 악마를 추방하세요."}, [6]={hint="잊혀진 땅의 호르니즈 브림버즐에게 유령의 플라스마 8개와 유령 유인기 상자를 가져가야 합니다.", desc="상자를 뼈의 골짜기에 내려놓으세요. 뒤로 물러서서 유령들을 하나씩 끌어당겨 보세요."}, [7]={npc="호르니즈 브림버즐", tgt="호르니즈 브림버즐"}, [8]={npc="타이가 와이즈메인", tgt="타이가 와이즈메인"}, [9]={npc="다이노", tgt="다이노", tag="선택사항", desc="오그리마를 통해. 대체: 울신 굴 25.70,14.19; 아나스타샤 하트웰 85.14,10.03."}, [10]={hint="타베사와 대화하십시오.", tag="선택사항"}, [11]={npc="타베사", tgt="타베사", tag="선택사항"}, [12]={npc="타베사", tgt="타베사", tag="선택사항"}, [13]={hint="먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가야 합니다.", tag="선택사항"}, [14]={npc="타베사", tgt="타베사", tag="선택사항"}, [15]={npc="타베사", tgt="타베사", tag="선택사항", desc="체력과 마나를 충전한 다음 타베사에게 엑소시즘을 시작하도록 요청하세요."}, [16]={hint="보주의 악마를 물리치고 타베사와 대화하십시오.", tag="선택사항", desc="체력과 마나를 충전한 다음 타베사에게 엑소시즘을 시작하도록 요청하세요."}, [17]={npc="타베사", tgt="타베사", tag="선택사항", desc="체력과 마나를 충전한 다음 타베사에게 엑소시즘을 시작하도록 요청하세요."}, [18]={npc="타베사", tgt="타베사", tag="선택사항", desc="귀하의 그룹이 흑요석 파수꾼로 이어지는 입구를 사용하고 있는지 확인하십시오."}, [19]={hint="흑요석 마력원천을 구해서 먼지진흙 습지대에 있는 타베사에게 가져가야 합니다.", tag="선택사항", desc="귀하의 그룹이 흑요석 파수꾼로 이어지는 입구를 사용하고 있는지 확인하십시오. 울다만 뒷문으로 들어가 흑요석 파수꾼을 찾으세요."}, [20]={npc="타베사", tgt="타베사", tag="선택사항", desc="귀하의 그룹이 흑요석 파수꾼로 이어지는 입구를 사용하고 있는지 확인하십시오."}, [21]={npc="타베사", tgt="타베사", tag="선택사항", desc="수락하기 전에 마나를 충전하세요. 수락하면 타이머가 시작됩니다."}, [22]={hint="주어진 시간 안에 마력의 폭풍 12마리를 물리쳐야 합니다.", tag="선택사항", desc="수락하기 전에 마나를 충전하세요. 수락하면 타이머가 시작됩니다."}, [23]={npc="타베사", tgt="타베사", tag="선택사항", desc="수락하기 전에 마나를 충전하세요. 수락하면 타이머가 시작됩니다."}, [24]={npc="타베사", tgt="타베사", tag="선택사항"}, [25]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [26]={npc="타베사", tgt="타베사", tag="선택사항"}, [27]={text="Shadowprey에 묶여 있으면 귀환석를 사용하여 Shadowprey로 돌아가세요. 그렇지 않으면 비행 조련사에게 다시 달려가십시오. 훈련하려면 오그리마로 날아가세요."}}},
    ["03-22"] = {name="알터랙 산맥", tips={{k="取捨", text="타렌 밀농장에서 포로 구출 및 비밀결사대원 현상수배를 확인하세요. 한 번의 여행으로 던홀드 요새의 두 가지 전제 조건을 모두 수행하세요. Alterac에서 침투를 켜서 를 잠금 해제한 다음 비밀결사대 캠프에서 골디르와 Vardus를 찾으세요."}, {k="提醒", text="이 다리와 해머폴를 사용하여 레벨 40에 도달하세요. 도착하면 경험치를 확인하세요. 키가 작다면 해머폴로 향하기 전에 일반 비밀결사대 몹(58.44, 70.00)을 처치하세요.", s={{"이 다리와 해머폴를 사용하여 레벨 40에 도달하세요"}, {"도착하면 경험치를 확인하세요"}, {"키가 작다면 해머폴로 향하기 전에 일반 비밀결사대 몹(58.44, 70.00)을 처치하세요"}}}}, danger={[1]="엘리트 오우거는 알터랙 폐허 내부에 있습니다. 당신의 그룹이 도착할 때까지 바깥쪽 길을 따라 일반 Brutes와 싸우십시오."}, grind={[1]={mob="비밀결사대 염탐꾼", note="비밀결사대 캠프 외부에 밀집된 일반 몹. 숨어 있는 몹과 마법사를 조심하세요. 해머폴 이전에 약간의 경험치에 대한 싱글을 선택하세요."}, [2]={note="알터랙 폐허 외부의 산길을 따라 밀집된 일반 몹. 엘리트를 피하기 위해 밖에 머물면서 경로에서 혼자 계속 연습하십시오."}}, supply={[1]={npc="자라이즈"}, [2]={npc="여관주인 셰이"}, [3]={npc="여관주인 셰이"}, [4]={npc="케이렌 수트할로우"}, [5]={npc="고든 웬드헴"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="오그리마 밖에서 티리스팔 비행선에 탑승하세요. 브릴의 남쪽 타워에서 언더시티로 향하고 타렌 밀농장로 날아간 다음 귀환석를 바인딩하세요."}, [2]={npc="멜리사라", tgt="멜리사라", tag="단체 추천, 선택사항"}, [3]={npc="크루스크", tgt="크루스크"}, [4]={npc="현상수배!", npcObj=true, desc="수배 포스터에서도 이 퀘스트를 제공합니다(62.57, 20.66)."}, [5]={hint="타렌 밀농장에 있는 크루스크가 던홀드 요새에서 드럴과 토그타르를 구출해 달라고 부탁했습니다.", desc="던홀드 경비병에게서 열쇠 두 개를 모두 약탈한 다음 포로 두 명을 구출하세요."}, [6]={hint="비밀결사대 도적 10명과 비밀결사대 경비병 10명을 처치해야 합니다. 그런 다음 타렌 밀농장에 있는 고위집행관 다살리아에게 돌아가 보상금을 받으십시오."}, [7]={npc="크루스크", tgt="크루스크"}, [8]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [9]={npc="크루스크", tgt="크루스크"}, [10]={npc="현상수배!", npcObj=true, desc="수배 포스터에서도 이 퀘스트를 제공합니다(62.57, 20.66)."}, [11]={hint="타렌 밀농장에 있는 크루스크를 위해 골디르가 어디에 있는지 정보를 찾아야 합니다."}, [12]={hint="타렌 밀농장에 있는 멜리사라를 위해 산사태일족 싸움꾼 14마리를 처치해야 합니다.", tag="단체 추천, 선택사항", desc="알터랙 폐허에 진입하기 전에 정예 Crushridge Maulers와 함께 그룹을 구성하세요."}, [13]={npc="크루스크", tgt="크루스크"}, [14]={npc="멜리사라", tgt="멜리사라", tag="단체 추천, 선택사항"}, [15]={npc="멜리사라", tgt="멜리사라", tag="선택사항"}, [16]={npc="크루스크", tgt="크루스크"}, [17]={hint="골디르를 구출하여 타렌 밀농장에 있는 크루스크에게 돌아가야 합니다."}, [18]={hint="바르두스 남작을 처치하고 그 증거로 그의 머리카락을 타렌 밀농장에 있는 고위집행관 다살리아에게 가져가야 합니다.", desc="골디르 근처에서 Vardus를 확인한 다음 더 북쪽에 있는 비밀결사대 캠프를 검색하세요."}, [19]={npc="골디르", tgt="골디르"}, [20]={npc="골디르", tgt="골디르"}, [21]={hint="타렌 밀농장에 있는 크루스크에게 골디르가 수집한 정보를 전해야 합니다."}, [22]={npc="크루스크", tgt="크루스크"}, [23]={npc="고위집행관 다살리아", tgt="고위집행관 다살리아"}, [24]={hint="타르그, 무크라케, 글롬무스를 처치하고 그 증거로 그들의 머리카락을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다.", tag="선택사항"}, [25]={npc="멜리사라", tgt="멜리사라", tag="선택사항"}, [26]={npc="멜리사라", tgt="멜리사라", tag="단체 추천, 선택사항"}, [27]={hint="무그톨을 처치하고 그 증거로 그의 머리카락과 의지의 왕관을 타렌 밀농장에 있는 멜리사라에게 가져가야 합니다.", tag="단체 추천, 선택사항"}, [28]={npc="멜리사라", tgt="멜리사라", tag="단체 추천, 선택사항"}, [29]={npc="멜리사라", tgt="멜리사라", tag="단체 추천, 선택사항"}, [30]={hint="언더시티에 있는 샬린드라에게 의지의 왕관을 가져가야 합니다.", tag="단체 추천, 선택사항"}, [31]={npc="샬린드라", tgt="샬린드라", tag="단체 추천, 선택사항"}, [32]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="24개 필요; 퀘스트 레벨 36. 이번 알터랙 여행에서 꼭 해보세요."}, [33]={hint="바턴을 소매치기하여 바턴의 정찰 보고서를 훔친 후, 라벤홀트 장원의 미로코스 사일런트폼에게 가져가야 합니다.", tag="선택사항, 대상: 바턴", desc="24개 필요; 퀘스트 레벨 36. 이번 알터랙 여행에서 꼭 해보세요."}, [34]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="24개 필요; 퀘스트 레벨 36. 이번 알터랙 여행에서 꼭 해보세요."}, [35]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="사물함에서 유니폼을 약탈하세요. 후속 조치를 위해 스트롬가드에서 변장한 상태를 유지하세요."}, [36]={hint="북부습곡 장원에서 비밀결사대 제복을 훔쳐 스트롬가드 요새에 잠입해야 합니다.", tag="선택사항", desc="사물함에서 유니폼을 약탈하세요. 후속 조치를 위해 스트롬가드에서 변장한 상태를 유지하세요."}, [37]={npc="비밀결사대 사물함", npcObj=true, tag="선택사항", desc="사물함에서 유니폼을 약탈하세요. 후속 조치를 위해 스트롬가드에서 변장한 상태를 유지하세요."}, [38]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="RFK 메모를 휴대하세요. 로그에 높새바람 봉우리 가 표시되면 Rau(46.14, 51.71)로 설정하세요."}, [39]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="정기의 도움 이후에는 Bath'rah를 참조하세요. 높새바람 봉우리에 반납하신 경우, Rau에서 수령하세요."}, [40]={hint="버섯구름 봉우리에 있는 프레이트 클라우드시어와 대화해야 합니다.", tag="선택사항", desc="정기의 도움 이후에 수락하세요."}, [41]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="정기의 도움 이후에 수락하세요."}, [42]={npc="프레이트 클라우드시어", tgt="프레이트 클라우드시어", tag="선택사항", desc="바스라에서 제공하는 경우 수락합니다. 25/27 정류장에서 불/땅을 얻으세요. 공기와 물로 돌아갑니다."}, [43]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항, 게임 내 확인이 필요합니다", desc="Bath'rah가 제공하는 경우 이 사이드 퀘스트를 수행하십시오. 레벨링이 완료될 때까지 기다릴 수 있습니다."}, [44]={hint="버섯구름 봉우리의 높새바람 봉우리에 있는 라우 클리프러너에게 가야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="Bath'rah가 제공하는 경우 이 사이드 퀘스트를 수행하십시오. 레벨링이 완료될 때까지 기다릴 수 있습니다."}, [45]={npc="라우 클리프러너", tgt="라우 클리프러너", tag="선택사항, 게임 내 확인이 필요합니다", desc="Bath'rah가 제공하는 경우 이 사이드 퀘스트를 수행하십시오. 레벨링이 완료될 때까지 기다릴 수 있습니다."}, [46]={text="비밀결사대 캠프를 마친 후 소라딘의 성벽를 거쳐 동쪽으로 이동하여 아라시 고원로 돌아갑니다."}}},
    ["03-23"] = {name="아라시 고원", nameA="아라시 고원: {a:321}", tips={{k="取捨", text="재방문 시 나중에 볼더피스트, 랩터, 비밀결사대 퀘스트를 함께 수행하세요. 같은 이름의 이전 퀘스트를 놓친 경우 후속 작업을 건너뛰세요. 루프에서 마법진의 돌의 돌을 클릭하고 그룹을 위해 포즈루크(쐐기돌 깨기)를 저장합니다."}, {k="取捨", text="팔디르의 만에서 회수품, 수중 보물, 선장 퀘스트를 선택하세요. 가라앉은 보물를 완료하여 가라앉은 보물를 잠금 해제하고 고글을 얻으세요. 같은 여행에서 심해의 인양 작업와 비통한 마음를 수중에서 수행하세요. 무법항를 위해 가라앉은 보물를 저장하고 나중에 팔디르의 만 방문 시 가라앉은 보물를 제출하세요."}, {k="取捨", text="영상에서는 스트롬가드를 선택 사항으로 취급합니다. 해머폴 근처의 크리스탈과 대물렌즈를 먼저 수행하세요. 이동 시간을 절약하려면 Stromgarde 퀘스트 아라소르의 인장 - 트롤칼라를 건너뛰세요."}, {k="提醒", text="잠금 해제 스토나드를 통과하면 비행 지점가 됩니다. 스토나드 다리에 대한 슬픔의 늪 퀘스트를 저장하세요.", s={{"잠금 해제 스토나드를 통과하면 비행 지점가 됩니다"}, {"스토나드 다리에 대한 슬픔의 늪 퀘스트를 저장하세요"}}}, {k="提醒", text="레벨 40 이하? 해머폴 동쪽 마른수염 골짜기에서 일반 코볼트를 처치하세요(약 84, 31). 회색으로 변하면 마을 밖의 일반 마른나무껍질 트롤로 전환합니다(약 68, 69).", s={{"레벨 40 이하?"}, {"해머폴 동쪽 마른수염 골짜기에서 일반 코볼트를 처치하세요(약 84, 31)"}, {"회색으로 변하면 마을 밖의 일반 마른나무껍질 트롤로 전환합니다(약 68, 69)"}}}}, danger={[1]="스트롬가드 경비병이 관문에 집결합니다. 인장 체인을 넣기 전에 별도로 당기고 건물 내부에서 두 팩을 공격하지 마십시오.", [2]="수중 몹이 팔디르의 만 난파선을 지키고 있습니다. 보물 사냥용 고글을 착용하고 입장하기 전에 숨을 지켜보세요."}, grind={[1]={mob="마른수염일족 흙점쟁이", note="해머폴 동쪽 마른수염 골짜기 깊은 곳의 일반 몹 밀도는 보통입니다. 좁은 동굴을 단계별로 클리어하세요. 희귀한 흙점쟁이 플린트대거를 살펴보세요."}, [2]={mob="마른수염일족 채굴꾼", note="Drywhisker 터널에는 탐사자와 뒤섞인 빽빽한 일반 몹입니다. 크리스탈 퀘스트와 짝을 이루세요. 나가는 길에 부활을 조심하세요."}, [3]={mob="떠도는 물의 정령", note="해머폴 북서쪽의 조밀한 일반 물 정령. 코볼트보다 레벨이 약간 높으며 40까지 좋습니다. 전사는 소용돌이 무기의 부적을 수집할 수 있습니다."}}, supply={[1]={npc="우르다"}, [2]={npc="여관주인 아데그와"}, [3]={npc="무우타"}, [4]={npc="여관주인 아데그와"}, [5]={npc="그라우드"}}, steps={[1]={npc="미즈라엘의 결정", npcObj=true}, [2]={npc="토건", tgt="토건"}, [3]={npc="드럼 펠", tgt="드럼 펠"}, [4]={npc="토건", tgt="토건", tag="선택사항"}, [5]={hint="아라시 고원의 해머폴로 가서 젠구와 대화해야 합니다."}, [6]={npc="젠구", tgt="젠구"}, [7]={npc="젠구", tgt="젠구", tag="선택사항"}, [8]={hint="미즈라엘의 결정 파편을 12개 모아서 마른수염 골짜기에 있는 오색 결정에 가져가야 합니다."}, [9]={npc="오색 결정", npcObj=true}, [10]={npc="오색 결정", npcObj=true}, [11]={hint="식인 고원랩터에게서 랩터 심장 12개를 얻어 토건에게 가져가야 합니다."}, [12]={hint="돌주먹일족 투사 10마리와 돌주먹일족 사제 4마리를 처치한 다음 해머폴 전초 기지에 있는 드럼 펠에게 돌아가야 합니다."}, [13]={hint="마레즈 코울의 더럽혀진 혈석 수정구를 빼앗아 해머폴에 있는 토건에게 가져가야 합니다.", tag="선택사항"}, [14]={npc="토건", tgt="토건"}, [15]={npc="드럼 펠", tgt="드럼 펠"}, [16]={npc="토건", tgt="토건", tag="선택사항"}, [17]={npc="토건", tgt="토건"}, [18]={hint="고르멀에게 토건의 수정구를 전달해야 합니다."}, [19]={npc="고르멀", tgt="고르멀"}, [20]={npc="고르멀", tgt="고르멀"}, [21]={hint="토건과 대화해야 합니다."}, [22]={npc="토건", tgt="토건"}, [23]={npc="드럼 펠", tgt="드럼 펠", tag="선택사항"}, [24]={npc="코린 펠", tgt="코린 펠", tag="선택사항"}, [25]={hint="돌주먹일족 주술사 15마리와 돌주먹일족 우두머리 10마리를 처치한 다음 해머폴 전초 기지에 있는 드럼 펠에게 돌아가야 합니다.", tag="선택사항"}, [26]={hint="오르칼라를 처치하고 그 증거로 그의 머리카락을 해머폴 전초 기지에 있는 코린 펠에게 가져가야 합니다.", tag="선택사항"}, [27]={npc="드럼 펠", tgt="드럼 펠", tag="선택사항"}, [28]={npc="코린 펠", tgt="코린 펠", tag="선택사항"}, [29]={hint="해머폴에 있는 젠구에게 스트롬의 인장을 가져가야 합니다.", tag="선택사항"}, [30]={npc="젠구", tgt="젠구", tag="선택사항"}, [31]={npc="젠구", tgt="젠구", tag="선택사항"}, [32]={hint="스트롬가드의 수호병들에게서 인장 조각 11개를 빼앗아 해머폴에 있는 토건에게 가져가야 합니다.", tag="선택사항"}, [33]={npc="토건", tgt="토건", tag="선택사항"}, [34]={npc="토건", tgt="토건", tag="선택사항"}, [35]={hint="해머폴에 있는 젠구에게 소라딘의 인장을 가져가야 합니다.", tag="선택사항"}, [36]={npc="젠구", tgt="젠구", tag="선택사항"}, [37]={hint="서부 봉인석, 동부 봉인석, 외부 봉인석에서 각각 불타는 열쇠, 용마루장식 열쇠, 천둥 열쇠를 구해야 합니다."}, [38]={npc="내부 봉인석", npcObj=true}, [39]={npc="내부 봉인석", npcObj=true, tag="단체 추천, 선택사항"}, [40]={hint="포즈루크를 찾아 처치해야 합니다. 아라시 고원에 있는 쐐기돌에 질서의 마법봉을 가져가야 합니다.", tag="단체 추천, 선택사항"}, [41]={npc="쐐기돌", npcObj=true, tag="단체 추천, 선택사항"}, [42]={npc="쐐기돌", npcObj=true, tag="단체 추천, 선택사항"}, [43]={hint="해머폴에 있는 자루크와 대화해야 합니다.", tag="단체 추천, 선택사항"}, [44]={npc="자루크", tgt="자루크", tag="단체 추천, 선택사항"}, [45]={npc="자루크", tgt="자루크", tag="선택사항", desc="해머폴에서 미즈라엘의 친구들를 반납한 다음 자루크에서 수락하세요. 황야의 땅용으로 저장하세요."}, [46]={text="팔디르의 만"}, [47]={npc="망꾼 롤로", tgt="망꾼 롤로"}, [48]={hint="팔디르의 만에 있는 선장 오브린과 대화해야 합니다."}, [49]={npc="셰익스 오브린", tgt="셰익스 오브린"}, [50]={npc="학자 피즐솔프", tgt="학자 피즐솔프"}, [51]={hint="학자 피즐솔프가 동굴에 들어갔다 나올 수 있도록 호위해야 합니다.", desc="교수 주변을 정리하세요. 그를 동굴로 안내한 다음 무법항로 돌아갑니다."}, [52]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [53]={npc="일등항해사 닐즐릭스", tgt="일등항해사 닐즐릭스"}, [54]={npc="선장 스틸구트", tgt="선장 스틸구트"}, [55]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [56]={hint="일등항해사 닐즐릭스가 메이든즈 폴리호와 실버파인 스피릿호에서 해도와 항해일지를 찾아 달라고 부탁했습니다."}, [57]={hint="팔디르의 만에 있는 선장 스틸구트가 비수가시일족 침략자 10마리와 비수가시일족 여마법사 3마리를 처치해 달라고 부탁했습니다."}, [58]={hint="팔디르의 만에 있는 발명가 드랙슬게이지가 엘프의 보석 10개를 주워 오고 이 일을 끝낸 후 보물찾기 고글을 돌려 달라고 부탁했습니다.", desc="고글에는 가라앉은 보물를 사용하세요. 수중 보석으로 착용하세요. 심해의 인양 작업 및 비통한 마음와 페어링됩니다."}, [59]={npc="일등항해사 닐즐릭스", tgt="일등항해사 닐즐릭스"}, [60]={npc="선장 스틸구트", tgt="선장 스틸구트"}, [61]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [62]={npc="발명가 드랙슬게이지", tgt="발명가 드랙슬게이지"}, [63]={hint="선장 오브린에게 엘프의 보석을 가져가야 합니다."}, [64]={npc="셰익스 오브린", tgt="셰익스 오브린"}, [65]={npc="셰익스 오브린", tgt="셰익스 오브린"}, [66]={npc="토건", tgt="토건"}, [67]={npc="바스라의 가마솥", npcObj=true, tag="선택사항", desc="필요한 경우 AH에서 참을 구매하세요. 동일한 가마솥을 사용하여 수락하고 반납하세요."}, [68]={hint="획득처: 마른수염 코볼트, 마른수염일족 흙점쟁이, 마른수염일족 채굴꾼", tag="선택사항", desc="필요한 경우 AH에서 참을 구매하세요. 동일한 가마솥을 사용하여 수락하고 반납하세요."}, [69]={npc="바스라의 가마솥", npcObj=true, tag="선택사항", desc="필요한 경우 AH에서 참을 구매하세요. 동일한 가마솥을 사용하여 수락하고 반납하세요."}, [70]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항"}, [71]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="40레벨 엘리트 퀘스트입니다. 트리거하기 전에 그룹화하십시오."}, [72]={hint="바람의감시자 바스라에게 소용돌이의 눈을 가져가야 합니다.", tag="선택사항", desc="40레벨 엘리트 퀘스트입니다. 트리거하기 전에 그룹화하십시오."}, [73]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="40레벨 엘리트 퀘스트입니다. 트리거하기 전에 그룹화하십시오."}, [74]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", star={"소용돌이 도끼 / 소용돌이 검 / 소용돌이 전투망치"}}, [75]={hint="퀘스트 목표를 완료하세요.", tag="선택사항"}, [76]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", star={"소용돌이 도끼 / 소용돌이 검 / 소용돌이 전투망치"}}, [77]={npc="비밀결사대 사물함", npcObj=true, tag="선택사항", desc="들어가기 전에 유니폼을 입으세요. 변장을 유지하려면 전투를 피하세요."}, [78]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.", tag="선택사항", desc="들어가기 전에 유니폼을 입으세요. 변장을 유지하려면 전투를 피하세요."}, [79]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항", desc="들어가기 전에 유니폼을 입으세요. 변장을 유지하려면 전투를 피하세요."}, [80]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항"}, [81]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", tag="선택사항", desc="스트롬가드 요새로 집 위층에서 아나스타샤의 은닉물을 찾으세요."}, [82]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항"}, [83]={npc="아나스타시아 밀러", tgt="아나스타시아 밀러", tag="선택사항", desc="경비병 두 명이 화물을 지키고 있습니다."}, [84]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", tag="선택사항", desc="경비병 두 명이 화물을 지키고 있습니다."}, [85]={npc="미로코스 사일런트폼", tgt="미로코스 사일런트폼", tag="선택사항", desc="경비병 두 명이 화물을 지키고 있습니다."}, [86]={text="해머폴로 돌아갑니다. 로그마 및 스토나드가 잠금 해제된 경우 로그마로 날아갑니다. 처음 방문하는 경우 대신 스토나드로 비행하세요. 스토나드가 잠겨 있으면 그롬골로 날아가 그늘숲를 통해 북쪽으로 달려가 다크샤이어의 경비병을 피해갑니다. 죽음의 고개를 거쳐 슬픔의 늪로 동쪽으로 이동합니다. 그롬골이 잠겨 있으면 브릴 남쪽 탑에서 비행선을 가져가세요.", tag="아직 비행 경로를 열지 않았습니다. 처음에는 걸어서 이동하세요."}}},
    ["05-d17"] = {name="가시덩굴 구릉", entrance="불모의 땅 (1413), 가시터널 깊은 곳에 있는 포탈, 49.10, 93.40 에 대해서.", pickup="해머폴에서 언더시티로 비행합니다. Shimmering Flats 구간에서 가시덩굴 우리를 실행하고 사악한 동맹를 약탈하세요. Alterac- 해머폴 구간에서 언더시티에서 바리마트라스로 전환한 다음 Andrew에게서 암네나르 처치를 가져옵니다. 티리스팔에서 비행선을 타고 오그리마로 간 다음 썬더 블러프로 날아가서 멀고어 북서쪽에 있는 수타라 평원추적자를 보고 혹한의 눈을 찾으세요. 타우라조 야영지로 날아가서 입구 바깥쪽의 미리암 문싱어로 남쪽으로 가세요. 화약심지 항구에서 스팀휘들 항구까지 보트를 타고 북쪽으로 버섯구름 봉우리로 향할 수도 있습니다.", pickupS={{"해머폴에서 언더시티로 비행합니다"}, {"Shimmering Flats 구간에서 가시덩굴 우리를 실행하고 사악한 동맹를 약탈하세요"}, {"Alterac- 해머폴 구간에서 언더시티에서 바리마트라스로 전환한 다음 Andrew에게서 암네나르 처치를 가져옵니다"}, {"티리스팔에서 비행선을 타고 오그리마로 간 다음 썬더 블러프로 날아가서 멀고어 북서쪽에 있는 수타라 평원추적자를 보고 혹한의 눈을 찾으세요"}, {"타우라조 야영지로 날아가서 입구 바깥쪽의 미리암 문싱어로 남쪽으로 가세요"}, {"화약심지 항구에서 스팀휘들 항구까지 보트를 타고 북쪽으로 버섯구름 봉우리로 향할 수도 있습니다"}}, tips={{k="動線", text="불꽃눈 모드레쉬 근처에 있는 벨리스트라즈의 감방으로 이동 → 맹세석을 제출하고 그를 우상으로 안내하고, 마주치면 썩어가는 역병아귀와 함께 → 나선형 경사로를 타고 Amnennar로 가서 근처에 있는 Coldbringer's Eye를 찾으세요."}, {k="取捨", text="레벨 40 이상의 그룹으로 전체 던전을 진행하세요. 혹한의 눈와 암네나르 처치의 최종 보스를 모두 처치하세요. 34에서 안구 퀘스트를 선택하고 통과하면 밖에서 악의 무리를 수행하세요."}, {k="說明", text="5인 던전. 열쇠가 필요하지 않습니다. Great 승강기 북쪽의 동쪽 도로를 이용하세요. 가시덩굴 우리는 서쪽에 있습니다. 강물터에서 화약심지 항구에서 스팀휘들 항구까지 보트를 탄 후 북쪽으로 향합니다.", s={{"5인 던전"}, {"열쇠가 필요하지 않습니다"}, {"Great 승강기 북쪽의 동쪽 도로를 이용하세요"}, {"가시덩굴 우리는 서쪽에 있습니다"}, {"강물터에서 화약심지 항구에서 스팀휘들 항구까지 보트를 탄 후 북쪽으로 향합니다"}}}, {k="提醒", text="5인 던전. 열쇠가 필요하지 않습니다. Great 승강기 북쪽의 동쪽 도로를 이용하세요. 가시덩굴 우리는 서쪽에 있습니다. 강물터에서 화약심지 항구에서 스팀휘들 항구까지 보트를 탄 후 북쪽으로 향합니다.", s={{"5인 던전"}, {"열쇠가 필요하지 않습니다"}, {"Great 승강기 북쪽의 동쪽 도로를 이용하세요"}, {"가시덩굴 우리는 서쪽에 있습니다"}, {"강물터에서 화약심지 항구에서 스팀휘들 항구까지 보트를 탄 후 북쪽으로 향합니다"}}}}, steps={[1]={npc="작은 두루마리", npcObj=true, tag="게임 내 확인이 필요합니다", desc="이미 가시덩굴 우리의 Charlga에게서 작은 두루마리를 약탈했다면 건너뛰세요."}, [2]={hint="작은 두루마리를 언더시티에 있는 바리마트라스에게 가져가야 합니다."}, [3]={npc="바리마트라스", tgt="바리마트라스"}, [4]={npc="바리마트라스", tgt="바리마트라스", desc="사악한 동맹 이후 여기에서 수락하세요. 대상은 가시덩굴 구릉 외부의 가시덤불에 있습니다.", preText="사악한 동맹"}, [5]={npc="앤드류 브로넬", tgt="앤드류 브로넬", desc="언더시티의 마법 지구 레벨 37에서 수락하세요."}, [6]={npc="수타라 평원추적자", tgt="수타라 평원추적자", desc="포에버에서 새로 추가된 퀘스트입니다."}, [7]={npc="미리암 문싱어", tgt="미리암 문싱어", desc="불모의 땅 남쪽에 있는 미리암(49.01, 94.94)에게서 수락하세요. 들어가기 전에 외부를 정리하세요."}, [8]={hint="사절 말킨을 처치한 다음 언더시티에 있는 바리마트라스에게 그의 머리카락을 증거로 가져가야 합니다."}, [9]={hint="가시덩굴일족 전투호위병과 가시덩굴일족 가시마술사, 그리고 죽음의 머리교 신도를 각각 8마리씩 죽인 후 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어에게 돌아가야 합니다."}, [10]={npc="미리암 문싱어", tgt="미리암 문싱어"}, [11]={text="가시덩굴 구릉 입구"}, [12]={npc="벨리스트라즈", tgt="벨리스트라즈", tag="게임 내 확인이 필요합니다", desc="셀에서 벨리스트라즈를 찾으세요. 에스코트가 시작되기 전에 모두가 맹세를 마쳐야 합니다."}, [13]={hint="그가 당신에게 서약의 돌을 줄 것입니다. 벨리스트라즈의 계획을 돕는 것에 동의하면 다시 그와 대화하여 그에게 서약의 돌을 돌려주십시오.", desc="위치: 불꽃눈 모드레쉬 근처의 셀에서 벨리스트라즈를 찾습니다. 순서: 호위를 시작하기 전에 모두가 맹세의 돌을 제출하도록 하세요.", spot="불꽃눈 모드레쉬 근처의 셀에서 벨리스트라즈를 찾습니다."}, [14]={npc="벨리스트라즈", tgt="벨리스트라즈", tag="게임 내 확인이 필요합니다", spot="불꽃눈 모드레쉬 근처 감옥, 벨니스트라즈"}, [15]={npc="벨리스트라즈", tgt="벨리스트라즈", tag="게임 내 확인이 필요합니다", desc="시작하기 전에 전체 그룹을 기다린 다음 NPC에게 가까이 다가가세요.", preText="가시덩굴 구릉의 스컬지"}, [16]={hint="가시덩굴 구릉에 있는 가시멧돼지의 우상까지 벨리스트라즈를 호위해야 합니다.", desc="위치: 벨리스트라즈를 감방에서 아이돌까지 호위하고 그를 보호하세요.", spot="벨리스트라즈를 감방에서 아이돌까지 호위하고 그를 보호하세요."}, [17]={npc="벨리스트라즈의 화로", npcObj=true, tag="게임 내 확인이 필요합니다", spot="우상 옆 화로, 벨니스트라즈가 의식을 치르는 곳"}, [18]={hint="앤드류 브로넬이 혹한의 암네나르를 처치하고 혹한의 해골을 가져다 달라고 부탁했습니다.", desc="위치: 감방을 떠나 나선형 경사로를 타고 Amnennar까지 올라갑니다.", spot="감방을 떠나 나선형 경사로를 타고 Amnennar까지 올라갑니다."}, [19]={hint="가시덩굴 구릉에서 혹한의 눈을 회수해야 합니다.", desc="위치: Amnennar의 둥지에서 Coldbringer의 눈을 찾으십시오. 순서: 17단계와 동일한 영역입니다.", spot="Amnennar의 둥지에서 Coldbringer의 눈을 찾으십시오."}, [20]={npc="수타라 평원추적자", tgt="수타라 평원추적자"}, [21]={npc="앤드류 브로넬", tgt="앤드류 브로넬"}, [22]={npc="바리마트라스", tgt="바리마트라스"}}},
    ["03-24"] = {tips={{k="取捨", text="첫 번째 방문 시 로그마 주변의 농장, 놀, 강둑, 짐승을 처치하세요. 그룹에 대한 초그자크(황혼은 이제 끝이다!) 및 후속 조치를 저장합니다. 지금 볼데로크 멧돼지 및 채석장 퀘스트를 선택하세요. 볼데로크 및 화약심지 항구 반환을 위해 레벨 42+ 황혼 및 해안 퀘스트를 저장하세요."}, {k="取捨", text="로그마의 비행 지점을 개방하세요. 보급품은 Toka에게서 구할 수 있습니다. 카르가스 및 스토나드까지 이동 시간이 줄어듭니다."}, {k="提醒", text="퀘스트 완료 후 레벨 41 미만인가요? 나조크 농장 남쪽의 일반 멧돼지(70.62, 33.08) 또는 로그마 남쪽의 짐승(약 61, 50)을 처치하세요. 화약심지 항구 반환을 위해 이후 볼데로크 황혼 퀘스트를 저장하세요.", s={{"퀘스트 완료 후 레벨 41 미만인가요?"}, {"나조크 농장 남쪽의 일반 멧돼지(70.62, 33.08) 또는 로그마 남쪽의 짐승(약 61, 50)을 처치하세요"}, {"화약심지 항구 반환을 위해 이후 볼데로크 황혼 퀘스트를 저장하세요"}}}}, danger={[1]="Farholde 정찰병과 사제들이 로그마 남쪽을 배회하고 있습니다. 사제를 데려오지 않으려면 고독한 정찰병을 뽑으세요.", [2]="햇살숲의 황혼 의식 동굴은 좁습니다. 의식을 방해하기 전에 입구를 정리하세요. 뒤에서 다시 나타나는 섀도우맨서를 조심하세요."}, grind={[1]={mob="저지대 평원 대머리수리", note="로그마 남쪽에 밀집된 일반 몹. 길을 따라 싱글을 선택하고, 레벨 41~42의 엘리트 짐승을 피하고, 화살깃에 쓸 깃털을 위한 깃털을 수집하세요."}, [2]={mob="파홀드 정찰병", note="로그마 남쪽의 Farholde 정찰 지역에 밀집된 일반 몹. 그거 그렇게 하는 거 아닌데를 위해 강을 따라 정리하고 사제와 정찰병을 모으는 것을 피하세요."}, [3]={mob="파홀드 사제", note="남쪽 제방 서쪽 끝에 있는 일반 캐스터의 밀도는 보통입니다. 주문 방해는 치유를 제공하고 스카우트가 당하지 않도록 합니다. 여기서 그거 그렇게 하는 거 아닌데의 서쪽 다리를 그라인딩하세요."}}, supply={[1]={npc="그라크나"}, [2]={npc="여관주인 토카"}, [3]={npc="구르도크"}, [4]={npc="날루크"}, [5]={npc="마카"}, [6]={npc="브레이크"}, [7]={npc="툴타조르"}}, steps={[1]={nodeA="{a:75}", desc="늪에서 육로로 오는 경우 잠금 해제, 브레이크가 포함된 비행 지점. 그렇지 않으면 건너뜁니다."}, [2]={text="로그마를 잠금 해제한 경우 스토나드에서 비행하세요. 첫 번째 방문에서는 슬픔의 늪에서 강물터를 입력하고 테랄의 감시터(약 60, 64)를 지나 남쪽을 따라 길을 따라 간 다음 북쪽으로 로그마로 향합니다(비디오 26:56-27:13). 해머폴에서 비행했다면 바로 비행 마스터에게 가세요.", tag="아직 비행 경로를 열지 않았습니다. 처음에는 걸어서 이동하세요."}, [3]={node="로그마", desc="잠금 해제 비행 지점 및 그라크나."}, [4]={text="귀환석를 여관주인 토카(57.58, 45.47)와 바인딩하세요."}, [5]={hint="강물터 로그마 전초기지에 있는 크롬로쉬에게 보고해야 합니다."}, [6]={hint="강물터의 로그마에서 탄자니를 찾아야 합니다."}, [7]={npc="크롬로쉬", tgt="크롬로쉬"}, [8]={npc="탄자니", tgt="탄자니"}, [9]={npc="크롬로쉬", tgt="크롬로쉬"}, [10]={npc="크롬로쉬", tgt="크롬로쉬"}, [11]={npc="구르도크", tgt="크레자 다크쏜"}, [12]={npc="탄자니", tgt="탄자니"}, [13]={text="남부 농장과 남서부 놀"}, [14]={hint="풀잎개울에서 풀잎개울 농장 일꾼 12명을 처치하고 크롬로쉬에게 성공 소식을 전해야 합니다.", tag="대상: 풀잎개울 농장 일꾼"}, [15]={hint="풀잎개울 얼라이언스 농장에서 먹이 자루 6개를 훔쳐 크롬로쉬에게 가야 합니다."}, [16]={npc="크롬로쉬", tgt="크롬로쉬"}, [17]={npc="크롬로쉬", tgt="크롬로쉬"}, [18]={npc="크롬로쉬", tgt="크롬로쉬"}, [19]={hint="훔친 먹이를 로그마에 있는 그로그에게 전달해야 합니다."}, [20]={npc="그로그", tgt="그로그"}, [21]={npc="그로그", tgt="그로그"}, [22]={hint="훈련장에서 로그마 훈련생 8명에게 음식을 줘야 합니다.", tag="대상: 로그마 훈련생"}, [23]={npc="그로그", tgt="그로그"}, [24]={npc="크롬로쉬", tgt="크롬로쉬"}, [25]={hint="강 남쪽에서 파홀드 사제 8명과 파홀드 정찰병 12명을 처치해야 합니다.", tag="대상: 파홀드 사제 / 파홀드 정찰병"}, [26]={npc="크롬로쉬", tgt="크롬로쉬"}, [27]={npc="트란굴", tgt="트란굴"}, [28]={npc="트란굴", tgt="트란굴"}, [29]={text="강변 목재 캠프 및 햇살숲"}, [30]={hint="터너의 벌목지에 있는 벌목꾼에게서 로그마의 크레자 다크쏜에게 줄 목공의 도끼 10개를 회수해야 합니다.", tag="대상: 터너의 제재소 벌목꾼"}, [31]={hint="터너의 벌목지에 있는 인부 장작더미에서 목재 묶음을 획득한 후, 급조한 찌르기 창 20개에 사용해야 합니다."}, [32]={npc="구르도크", tgt="크레자 다크쏜"}, [33]={npc="구르도크", tgt="크레자 다크쏜", desc="빌린 칼날 이후 여기에서 수락하세요. 화약심지 항구에 Friz의 검을 저장하세요."}, [34]={npc="탄자니", tgt="탄자니"}, [35]={npc="탄자니", tgt="탄자니"}, [36]={hint="민물악어 10마리를 꿰뚫은 후 로그마에 있는 탄자니에게 가야 합니다.", tag="대상: 민물악어"}, [37]={npc="탄자니", tgt="탄자니"}, [38]={hint="로그마의 트란굴을 위해 황혼의 약탈병 8명과 황혼의 수련사 8명을 처치해야 합니다.", tag="대상: 황혼의 약탈병/황혼의 망치단 흑마술사/황혼의 수련사"}, [39]={hint="햇살숲에 있는 황혼의 망치단 흑마술사에게서 황혼의 서신 3개를 회수해 로그마에 있는 트란굴에게 반납해야 합니다.", tag="대상: 황혼의 망치단 흑마술사"}, [40]={npc="트란굴", tgt="트란굴"}, [41]={npc="트란굴", tgt="트란굴"}, [42]={npc="트란굴", tgt="트란굴"}, [43]={hint="햇살숲의 황혼의 망치단 광부를 설득해 비밀을 실토하게 해야 합니다."}, [44]={npc="몽둥이발", tgt="몽둥이발"}, [45]={npc="몽둥이발", tgt="몽둥이발"}, [46]={hint="몽둥이발을 위해 햇살숲 지하 동굴에서 실종된 오우거를 찾아야 합니다."}, [47]={npc="강화된 투사", tgt="황혼의 투사"}, [48]={npc="강화된 투사", tgt="황혼의 투사"}, [49]={npc="몽둥이발", tgt="몽둥이발"}, [50]={hint="강화된 투사 5명과 황혼의 의식술사 10명을 처치한 후 햇살숲에 있는 몽둥이발에게 가야 합니다.", tag="대상: 강화된 투사/황혼의 의식술사"}, [51]={hint="햇살숲 지하 동굴에 설치된 황혼의 의식진 5개를 파괴해야 합니다."}, [52]={npc="몽둥이발", tgt="몽둥이발"}, [53]={npc="몽둥이발", tgt="몽둥이발"}, [54]={npc="몽둥이발", tgt="몽둥이발", tag="단체 추천, 선택사항"}, [55]={hint="햇살숲 동굴에서 초그자크를 처치하고 머리카락을 수집해 몽둥이발에게 전달해야 합니다.", tag="단체 추천, 선택사항, 대상: 초그자크", desc="Chogg'Zac은 클리어우드 