    ["05-d19"] = {name="Krol'dok Stronghold", nameA="{a:17780}", entrance="강물터 48.60, 26.30", pickup="로그마에서 트란굴의 햇살숲 및 몽둥이발 퀘스트를 수행한 다음 볼데로크 전제 조건을 수행합니다. 로그마에서 서쪽으로 황혼 캠프로 가서 다그로쉬와 Crag'rog를 찾으세요. 눈과 책 퀘스트를 잠금 해제하려면 로그마에 편지를 제출하세요. 로그마로 날아가거나 카르가스에서 걸어간 다음 햇살숲 북쪽 높이에 있는 포털을 찾으세요. 금형 후속 작업을 위해 두꺼운 가죽 4개와 철괴 12개를 가져오세요.", pickupS={{"로그마에서 트란굴의 햇살숲 및 몽둥이발 퀘스트를 수행한 다음 볼데로크 전제 조건을 수행합니다"}, {"로그마에서 서쪽으로 황혼 캠프로 가서 다그로쉬와 Crag'rog를 찾으세요"}, {"눈과 책 퀘스트를 잠금 해제하려면 로그마에 편지를 제출하세요"}, {"로그마로 날아가거나 카르가스에서 걸어간 다음 햇살숲 북쪽 높이에 있는 포털을 찾으세요"}, {"금형 후속 작업을 위해 두꺼운 가죽 4개와 철괴 12개를 가져오세요"}}, tips={{k="動線", text="광산: 노예파괴자 그록스 → 황혼의 사령관 자르모크 → Ashka 대장간의 금형 → 황혼의 고서의 경우 나르구르크 → 다리의 Bossman Toof → 머그의 눈의 Overlord Mugg. 길을 따라 이교도의 귀를 약탈하세요."}, {k="取捨", text="한 번에 세 가지를 모두 수행할 수 있도록 그룹화하기 전에 로그마, 볼데로크 및 화약심지 항구 전제 조건을 완료하세요. 몰드재료를 가져와서 몰드가 떨어지면 돌려주세요."}, {k="說明", text="입구는 햇살숲 북쪽에 있으며, 요새 문 옆에 또 다른 차원문이 있습니다.", s={{"입구는 햇살숲 북쪽에 있으며, 요새 문 옆에 또 다른 차원문이 있습니다"}}}}, steps={[1]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [2]={hint="풀잎개울에서 풀잎개울 농장 일꾼 12명을 처치하고 크롬로쉬에게 성공 소식을 전해야 합니다.", tag="던전 선행"}, [3]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [4]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [5]={hint="풀잎개울 얼라이언스 농장에서 먹이 자루 6개를 훔쳐 크롬로쉬에게 가야 합니다.", tag="던전 선행"}, [6]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [7]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [8]={hint="강 남쪽에서 파홀드 사제 8명과 파홀드 정찰병 12명을 처치해야 합니다.", tag="던전 선행"}, [9]={npc="크롬로쉬", tgt="크롬로쉬", tag="던전 선행"}, [10]={npc="트란굴", tgt="트란굴"}, [11]={npc="트란굴", tgt="트란굴"}, [12]={hint="로그마의 트란굴을 위해 황혼의 약탈병 8명과 황혼의 수련사 8명을 처치해야 합니다.", tag="대상: 황혼의 약탈병/황혼의 망치단 흑마술사/황혼의 수련사"}, [13]={hint="햇살숲에 있는 황혼의 망치단 흑마술사에게서 황혼의 서신 3개를 회수해 로그마에 있는 트란굴에게 반납해야 합니다.", tag="대상: 황혼의 망치단 흑마술사"}, [14]={npc="트란굴", tgt="트란굴"}, [15]={npc="트란굴", tgt="트란굴"}, [16]={npc="트란굴", tgt="트란굴", preText="다가오는 황혼, 황혼의 서신"}, [17]={hint="햇살숲의 황혼의 망치단 광부를 설득해 비밀을 실토하게 해야 합니다."}, [18]={npc="몽둥이발", tgt="몽둥이발"}, [19]={npc="몽둥이발", tgt="몽둥이발", preText="답을 캐내다"}, [20]={hint="몽둥이발을 위해 햇살숲 지하 동굴에서 실종된 오우거를 찾아야 합니다."}, [21]={npc=