t="오우거 광부 5명을 영입해야 합니다.", tag="선택사항", desc="3개의 마이너 핀이 검증되었습니다. 다른 위치는 알 수 없습니다."}, [58]={npc="오우거 광부", tgt="크라그로그", tag="선택사항"}, [59]={npc="다그로쉬", tgt="다그로쉬"}, [60]={npc="다그로쉬", tgt="다그로쉬"}, [61]={npc="다그로쉬", tgt="다그로쉬", desc="Carving a Path and Break their Chains 후에도 여전히 사용할 수 없다면 Klarg의 리드를 따르세요.", preText="길을 열어라, 사슬을 부숴라"}, [62]={hint="황혼의 장막에서 대군주 킬가르를 처치하고 머리카락을 다그로쉬에게 전달해야 합니다.", tag="대상: 대군주 킬가르"}, [63]={npc="다그로쉬", tgt="다그로쉬"}, [64]={npc="다그로쉬", tgt="다그로쉬", desc="대군주 킬가르의 머리를 돌려서 다그로쉬에서 잠금을 해제하세요.", preText="적의 숨통을 끊어라"}, [65]={npc="다그로쉬", tgt="다그로쉬", preText="적의 숨통을 끊어라"}, [66]={hint="서신을 로그마에 있는 크롬로쉬에게 전달해야 합니다."}, [67]={npc="크롬로쉬", tgt="크롬로쉬"}, [68]={npc="크롬로쉬", tgt="크롬로쉬", preText="때가 왔다, 형제여..."}, [69]={npc="트란굴", tgt="트란굴", preText="때가 왔다, 형제여..."}, [70]={text="Krol'dok Stronghold 입구"}, [71]={hint="크롤도크 보루 내 황혼의 망치단에게서 이교도 귀 15개를 수집해야 합니다.", desc="먼저 자르목크 근처의 이교도들을 제거한 다음 개수를 확인하세요. 던전 맵: 자르목(39.10, 69.40)은 귀의 소스 중 하나입니다. 위치: 광산 이후 자르모크(Zarmok) 주변을 정리하세요. 요새 통로에서 더 많은 귀를 획득하세요.", spot="광산 이후 자르모크(Zarmok) 주변을 정리하세요. 요새 통로에서 더 많은 귀를 획득하세요."}, [72]={npc="크롤도크 거푸집", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", desc="Tunk에서 금형을 약탈하고 마우스 오른쪽 버튼을 클릭하여 퀘스트를 시작하세요. War 조련사 아쉬카의 대장간에서 Tunk를 찾으세요. 전리품을 찾아 금형을 마우스 오른쪽 버튼으로 클릭하세요."}, [73]={hint="크롤도크 보루에서 황혼의 고서를 회수해야 합니다.", desc="던전 맵: 나르구르크 (34.70, 50.30). 위치: Ashka를 지나 황혼 캐스터 영역에서 나르구르크를 찾으세요.", spot="Ashka를 지나 황혼 캐스터 영역에서 나르구르크를 찾으세요."}, [74]={hint="크롤도크 보루에 침투한 뒤, 우두머리가 죽었다는 증거를 확보해 크롬로쉬에게 가야 합니다.", desc="던전 맵: 머그(71.00, 14.30). 위치: Bossman Toof의 다리를 건너세요. 마지막 방에서 머그 대군주를 처치하십시오.", spot="Bossman Toof의 다리를 건너세요. 마지막 방에서 머그 대군주를 처치하십시오."}, [75]={npc="크롬로쉬", tgt="크롬로쉬"}, [76]={npc="트란굴", tgt="트란굴"}, [77]={hint="로그마에서 거푸집에 관해 아는 사람을 찾아야 합니다.", tag="선택사항"}, [78]={npc="구르도크", tgt="크레자 다크쏜", tag="선택사항"}, [79]={npc="구르도크", tgt="크레자 다크쏜", tag="선택사항", desc="경매장에서 재료를 미리 구매하세요.", preText="크롤도크 거푸집"}, [80]={hint="두꺼운 가죽 4개와 철 주괴 12개를 크레자 다크쏜에게 가져가야 합니다.", tag="선택사항", desc="경매장에서 재료를 미리 구매하세요."}, [81]={npc="구르도크", tgt="크레자 다크쏜", tag="선택사항", desc="경매장에서 재료를 미리 구매하세요."}, [82]={npc="다그로쉬", tgt="다그로쉬", desc="로그마 에서 서쪽으로 다시 다그로쉬 로 향합니다."}}},
    ["04-29"] = {name="타나리스", nameA="타나리스: {a:977} & {a:976}", shortA="타나리스: {a:977} +", tips={{k="取捨", text="첫 번째 스팀휘들 항구 방문에서 해적 모자, 처치, 현상금 및 상자를 함께 수행하세요. TUG는 먼저 페랄라스를 수행하고 해적을 위해 돌아옵니다. 화약심지 항구에서 보트를 타고 지금 해안을 정리하여 영상의 정지 명령을 유지하세요."}, {k="取捨", text="모자케 야영지 의 경우 계곡천둥매의 영혼, 모래망치 주둔지 의 경우 모래망치의 빚, 슬픔의 늪 로 가는 길에 무법항 제출의 경우 맥킨리에게 배달 를 저장하세요."}, {k="提醒", text="다음 정류장에 경험치가 필요합니까? Wastewander 캠프(59.40, 24.71) 또는 해적단 소굴 입구(70.90, 42.48)에서 일반 몹을 처치하세요. 줄파락 그룹이 있는 경우 왕쇠똥구리 껍질, 자동 탐사막대 및 트롤 경화제를 가져온 다음 가젯잔 및 Dunemaul 다리를 켭니다.", s={{"다음 정류장에 경험치가 필요합니까?"}, {"Wastewander 캠프(59.40, 24.71) 또는 해적단 소굴 입구(70.90, 42.48)에서 일반 몹을 처치하세요"}, {"줄파락 그룹이 있는 경우 왕쇠똥구리 껍질, 자동 탐사막대 및 트롤 경화제를 가져온 다음 가젯잔 및 Dunemaul 다리를 켭니다"}}}}, danger={[1]="칼리프는 순찰을 하고 경비원이 있을 수도 있습니다. 근처의 황야유랑단 도적들을 처치하고 그가 열린 땅에 도달하면 끌어당기세요."}, grind={[1]={mob="남쪽바다해적단 무법자", note="해적단 소굴 입구에 밀집된 일반 몹. 다른 플레이어가 해적 퀘스트를 수행하고 있을 수도 있습니다. 가장자리를 따라 해변을 향해 청소하고 방울을 수집하세요."}, [2]={mob="남쪽바다해적단 칼잡이", note="부두 밖의 일반 몹. 해적 입구가 붐비는 경우 여기로 전환하세요. 도크 가드를 피하기 위해 가장자리에서 당기십시오."}}, supply={[1]={npc="벌크렉 레이지피스트"}, [2]={npc="여관주인 피즈그림블"}, [3]={npc="링클 굿스틸"}, [4]={npc="여관주인 피즈그림블"}, [5]={npc="브리즈릭 벅샷"}, [6]={npc="긱킥스"}}, steps={[1]={text="강물터(80.60, 54.60)의 화약심지 항구에서 보트에 탑승하고 타나리스(68.60, 23.00)의 스팀휘들 항구에서 하차하세요. 가젯잔가 잠금 해제된 경우 오그리마에서 비행하세요. 처음 방문하는 경우 높새바람 봉우리에서 Shimmering Flats를 지나 남쪽 경사로를 따라 가젯잔까지 달릴 수도 있습니다."}, [2]={text="항구에서 수락한 후 마을에서 재보급하세요."}, [3]={npc="거만한 의류상", tgt="거만한 의류상"}, [4]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [5]={npc="현상수배: 칼리프 스콜피드스팅", npcObj=true}, [6]={npc="현상수배: 칼리프 스콜피드스팅", npcObj=true}, [7]={npc="스톨리", tgt="스톨리"}, [8]={npc="예킨야", tgt="예킨야", desc="페랄라스에서 하세요. 타나리스 방문 중에 스팀휘들 항구에 반납하세요."}, [9]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", tag="선택사항", desc="모래망치 주둔지에서 하세요. 스팀휘들 항구에서 반납하세요."}, [10]={text="서쪽으로 길을 따라 가젯잔로 가세요. 벌크렉 레이지피스트(51.60, 25.44)에게서 호드 연합 비행 지점를 배우고 귀환석를 여관주인 피즈그림블(52.51, 27.91)와 바인딩하세요. 나중에 모자케 야영지에서 다시 바인딩하세요."}, [11]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [12]={npc="양수기기사 루글룬켓", tgt="양수기기사 루글룬켓"}, [13]={npc="트란렉", tgt="트란렉", tag="선택사항", desc="줄파락를 실행하는 경우에만 수락합니다."}, [14]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐", tag="선택사항", desc="줄파락의 계단 이벤트 중에 이것을 약탈하세요.", star={"석공 조합 반지", {"ROGUE", "HUNTER", "DRUID"}}}, [15]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머", tag="선택사항", desc="줄파락를 실행하는 경우에만 수락합니다."}, [16]={text="Wastewander 캠프 및 해적단 소굴"}, [17]={hint="가젯잔의 동쪽에서 10명의 사막유랑단 약탈자와 좀도둑을 처치한 후, 선임기술자 빌지위즐에게 돌아와 보고하십시오."}, [18]={hint="가젯잔에 있는 양수기기사 루글룬켓에게 사막유랑단 물주머니 5개를 가져가야 합니다."}, [19]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [20]={npc="양수기기사 루글룬켓", tgt="양수기기사 루글룬켓"}, [21]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [22]={hint="가젯잔에 있는 선임기술자 빌지위즐을 위해 사막유랑단 도적 8명, 사막유랑단 암살자 6명, 그리고 사막유랑단 어둠마법사 10명을 처치해야 합니다.", desc="가젯잔 남동쪽의 웨이스트유랑자 캠프로 들어갑니다."}, [23]={hint="칼리프 스콜피드스팅을 처치하고 그 증거로 그의 머리카락을 칼리프 스콜피드스팅의 머리카락을 가져다주어야 합니다.", desc="그는 호위를 받을 수도 있습니다. 당기기 전에 그가 캠프 가장자리에 도달할 때까지 기다리십시오."}, [24]={hint="타나리스의 스팀휘들 항구에 있는 보안과장 빌지위즐이 남쪽바다해적단 무법자, 약탈자, 부두일꾼, 칼잡이를 각각 10명씩 처치해 달라고 부탁했습니다."}, [25]={hint="타나리스의 스팀휘들 항구에 있는 거만한 의류상의 부탁으로 남쪽바다 해적 모자 20개를 모아서 가져가야 합니다.", desc="남쪽바다해적단 처리반 퀘스트 중에는 처치한 적을 모두 루팅하세요."}, [26]={hint="앙드레를 처치하고 그 증거로 그의 머리카락을 스팀휘들 항구에 있는 보안과장 빌지위즐에게 가져가야 합니다."}, [27]={hint="스팀휘들 항구에 있는 스톨리에게 뱃짐을 찾아다 주어야 합니다."}, [28]={npc="선적 일정표", npcObj=true, tag="선택사항", desc="해적의 사물함을 약탈한 다음 내부 일정을 마우스 오른쪽 버튼으로 클릭하여 퀘스트를 시작하세요."}, [29]={hint="스팀휘들 항구의 관계자에게 선적 일정표에 대해 보고하십시오.", tag="선택사항"}, [30]={text="해안 북쪽을 따라 스팀휘들 항구로 가서 해적과 화물 퀘스트를 함께 시작하세요."}, [31]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [32]={npc="거만한 의류상", tgt="거만한 의류상"}, [33]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐"}, [34]={npc="스톨리", tgt="스톨리"}, [35]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", tag="선택사항"}, [36]={npc="스톨리", tgt="스톨리", desc="스토나드 / 샛바람 해안 다리를 위해 저장하세요. 무법항에서 반납하세요."}, [37]={text="두 번째 Wastewander 배치와 원하는 퀘스트를 받으려면 가젯잔로 돌아가세요. 거기에 묶여 있으면 난로."}, [38]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [39]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}}},
    ["04-30"] = {name="페랄라스", nameA="페랄라스: {a:1099}", tips={{k="取捨", text="전투 계획서를 통해 Woodpaw gnoll 체인을 따라가면 모자케 야영지 남동쪽에서 겹치는 두 개의 Zukk'ash 퀘스트를 잠금 해제할 수 있습니다."}, {k="取捨", text="OOX-22/FE 조난 탐지기가 떨어지면 보관하십시오. 모자케 야영지 귀환을 위해 호위병, 해안 거인, 물의 정령을 구하세요."}, {k="提醒", text="레벨 47 이하인가요? 거친흉터 골짜기(55.29, 53.76) 또는 모자케 야영지(75.13, 34.86) 북쪽의 Gordunni 오우거에서 예티를 처치한 다음 캠프로 돌아가 반납하세요.", s={{"레벨 47 이하인가요?"}, {"거친흉터 골짜기(55.29, 53.76) 또는 모자케 야영지(75.13, 34.86) 북쪽의 Gordunni 오우거에서 예티를 처치한 다음 캠프로 돌아가 반납하세요"}}}}, danger={[1]="모자케 야영지 북쪽의 Gordunni 캠프에는 캐스터와 짐승이 모두 있습니다. 코발트를 채굴하기 전에 출구를 비우고 캠프 뒤쪽에 머물지 마세요."}, grind={[1]={mob="원시설인", note="거친흉터 골짜기의 바깥쪽 경사면에 있는 일반 설인 클러스터입니다. 탐구자가 동굴 입구에 있으면 예티가 숨을 수 있도록 경사면을 순환하세요."}, [2]={mob="덩치큰 원시설인", note="약간 높은 레벨의 노멀 설인은 거친흉터 골짜기 남서쪽입니다. 외부에서 근접 몹을 끌어당기고 붐비는 동굴 입구를 피하세요."}}, supply={[1]={npc="쉬인"}, [2]={npc="여관주인 그룰"}, [3]={npc="카윈드 트루에임"}, [4]={npc="여관주인 그룰"}, [5]={npc="카윈드 트루에임"}, [6]={npc="탈후스"}}, steps={[1]={text="잠금이 해제된 경우 가젯잔에서 모자케 야영지로 비행합니다. 첫 번째 방문에서는 북쪽의 Shimmering Flats로 향하고 버섯구름 봉우리를 통해 페랄라스로 서쪽 도로를 이용하세요.", tag="아직 비행 경로를 열지 않았습니다. 처음에는 걸어서 이동하세요."}, [2]={nodeA="{a:1099}", desc="잠금 해제 비행 지점 및 쉬인."}, [3]={text="귀환석를 여관주인 그룰(74.80, 45.18)와 바인딩하세요."}, [4]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [5]={npc="올윈 기즈믹", tgt="올윈 기즈믹"}, [6]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [7]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [8]={npc="의술사 우제리", tgt="의술사 우제리"}, [9]={npc="로크 올한", tgt="로크 올한"}, [10]={text="캠프 주변과 북쪽의 첫 번째 Gordunni 퀘스트"}, [11]={hint="모자케 야영지에 있는 아도겐 스위프트스트라이더에게 덩굴발일족 갈기 10개를 가져가야 합니다."}, [12]={hint="모자케 야영지에 있는 로크 올한이 골두니 오우거 10명, 골두니일족 오우거 마법사 10명, 골두니일족 투사 5명을 처치해달라고 부탁했습니다."}, [13]={hint="모자케 야영지에 있는 올윈 기즈믹이 골두니 코발트 12개를 가져다 달라고 부탁했습니다.", desc="Gordunni 캠프의 파란색 마운드 옆에 있는 퀘스트 삽을 사용하세요."}, [14]={npc="골두니 두루마리", npcObj=true, desc="북쪽 끝 지상에 있는 골두니 두루마리를 클릭하세요."}, [15]={hint="모자케 야영지에 있는 로크 올한에게 골두니 두루마리를 가져가야 합니다."}, [16]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [17]={npc="로크 올한", tgt="로크 올한"}, [18]={npc="올윈 기즈믹", tgt="올윈 기즈믹"}, [19]={npc="로크 올한", tgt="로크 올한"}, [20]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [21]={npc="로크 올한", tgt="로크 올한"}, [22]={npc="로크 올한", tgt="로크 올한"}, [23]={hint="1시간 안에 덩굴발일족 우두머리 5마리를 처치하고 아도겐 스위프트스트라이더에게 되돌아와야 합니다.", desc="1시간 타이머. 남쪽에 있는 덩굴발 언덕에서 5명을 처치하고 즉시 돌아옵니다."}, [24]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [25]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [26]={hint="모자케 야영지 남쪽에 있는 놀 야영지에서 덩굴발일족 전투계획서를 찾아야 합니다."}, [27]={npc="덩굴발일족 작전도", npcObj=true}, [28]={npc="덩굴발일족 작전도", npcObj=true}, [29]={hint="모자케 야영지에 있는 아도겐 스위프트스트라이더에게 덩굴발일족 전투계획서를 가지고 가야 합니다."}, [30]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [31]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [32]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [33]={text="중앙에 페어리 드래곤이 있고 서쪽으로 거친흉터 골짜기가 있습니다."}, [34]={hint="모자케 야영지에 있는 크루엑 스컬스플리터에게 오색 화살요정용 날개 10개를 가져가야 합니다."}, [35]={hint="페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다.", desc="가젯잔 / 모래망치 주둔지 구간을 지나 스팀휘들 항구에서 반납하세요."}, [36]={hint="모자케 야영지에 있는 장도르 스위프트스트라이더에게 두꺼운 설인 가죽 10개를 가져가야 합니다.", desc="두꺼운 설인 가죽를 위해 동굴 내부와 주변에서 Rage Scar Yetis를 처치하세요."}, [37]={text="거친흉터 골짜기 이후에는 모자케 야영지에 난로를 놓고 함께 반납합니다."}, [38]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [39]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [40]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [41]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [42]={hint="모자케 야영지에 있는 크루엑 스컬스플리터에게 그림토템일족 뿔 20개를 가져가야 합니다.", desc="모자케 야영지 북서쪽에 있는 그림토템 캠프에서 뿔피리를 얻은 후 돌아오세요."}, [43]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [44]={npc="크루엑 스컬스플리터", tgt="크루엑 스컬스플리터"}, [45]={text="슬픔의 늪로 가는 도중에 페랄라스 후속 조치를 위해 오그리마에 들릅니다."}, [46]={text="일반적으로 타우라조 야영지 또는 기타 잠금 해제된 정류장을 통해 모자케 야영지에서 오그리마까지 비행합니다. 동부 슬픔의 늪 루프 이후를 위해 모자케 야영지 난로를 유지하세요."}, [47]={hint="오그리마에 있는 네루 파이어블레이드에게 구겨진 가면을 가져가야 합니다."}, [48]={hint="오그리마에 있는 벨그롬 록마울에게 그림토템일족 뿔 상자를 가져가야 합니다."}, [49]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드"}, [50]={npc="벨그롬 록마울", tgt="벨그롬 록마울"}, [51]={npc="네루 파이어블레이드", tgt="네루 파이어블레이드", desc="무쇠설인 소굴 다리를 위해 저장하세요. 모자케 야영지에서 반납하세요."}}},
    ["04-31"] = {name="슬픔의 늪", nameA="슬픔의 늪: {a:75}", tips={{k="取捨", text="북부 드레노어 난민 및 호위는 이미 완료되었습니다. 이번에는 해안을 따라가세요. 보급품 보충와 보급품 보충를 반납하여 멀록 체인을 잠금 해제하세요. 나가는 길에 게다리를 모아서 돌아오는 길에 반납하세요."}, {k="提醒", text="가라앉은 사원를 실행 중입니까? 스토나드 에서 추방된 아탈라이 트롤 로 시작하세요. Hinterlands에서 회전하므로 레반터스크 마을 및 진타알로 다리를 위해 저장하세요. 레벨 47 이하, 샛바람 해안(91.00, 70.80) 근처에서 일반 거대 게를 처치하세요. 레벨 49에 가까워지면 다음 정거장에서 더 높은 레벨의 Rage Scar Yetis를 연마하세요.", s={{"가라앉은 사원를 실행 중입니까?"}, {"스토나드 에서 추방된 아탈라이 트롤 로 시작하세요"}, {"Hinterlands에서 회전하므로 레반터스크 마을 및 진타알로 다리를 위해 저장하세요"}, {"레벨 47 이하, 샛바람 해안(91.00, 70.80) 근처에서 일반 거대 게를 처치하세요"}, {"레벨 49에 가까워지면 다음 정거장에서 더 높은 레벨의 Rage Scar Yetis를 연마하세요"}}}}, danger={[1]="멀록은 샛바람 해안에 서로 가까이 서 있으며, 잉크 분무기와 오라클은 뒤에서 추가할 수 있습니다. 해안에서 한 번에 한 명의 적을 끌어당기고 물속으로 쫓아가지 마십시오."}, grind={[1]={mob="괴물게", note="슬픔의 늪 동부 해안을 따라 밀집된 일반 게. 당신이 가면서 피부를 벗기십시오. 도착 시 또는 해안 퀘스트와 함께 작은 경험치 충전에 가장 적합합니다."}, [2]={mob="덩치큰 무쇠설인", note="49에 가까우면 페랄라스까지 기다리세요. 무쇠설인 소굴의 일반 설인이 더 나은 수준입니다. 외부 경사면에서 한 번에 한 명의 적을 끌어당기고 분주한 동굴 입구를 피하세요."}}, supply={[1]={npc="브레이크"}, [2]={npc="여관주인 카라쿨"}, [3]={npc="가라쉬"}, [4]={npc="툴타쉬"}, [5]={npc="툴타조르"}}, steps={[1]={text="오그리마에서 톱니항까지 비행기를 타고 무법항까지 보트를 타세요. 모자케 야영지 난로를 유지하세요."}, [2]={text="도중에 무법항 퀘스트 진행"}, [3]={hint="무법항에 있는 \"바다늑대\" 맥킨리에게 칼림도어산 럼주가 든 스톨리의 병을 가져가야 합니다."}, [4]={npc="바다늑대 맥킨리", tgt="바다늑대 맥킨리"}, [5]={npc="크라젝", tgt="크라젝", tag="선택사항", desc="꿈가루를 모두 확보한 후에만 스토나드에 반납하세요."}, [6]={npc="위스키 슬림", tgt="위스키 슬림", desc="Hinterlands 해안에서 그로그를 줍습니다. 무법항를 다시 방문할 때 제출하세요."}, [7]={text="스토나드 남동쪽 해안"}, [8]={text="무법항에서 스토나드로 비행합니다. 잠겨 있으면 가시덤불 골짜기 를 통해 북쪽으로 달린 다음 동쪽 그늘숲 를 따라 죽음의 고개 를 통과합니다. 브레이크(46.07, 54.83)에서 비행 지점를 알아보세요."}, [9]={npc="다르", tgt="다르"}, [10]={npc="다르", tgt="다르"}, [11]={hint="슬픔의 늪에 있는 톡카르에게 신선한 톱니악어 고기 8개를 가져가야 합니다.", desc="눈물의 연못 남서쪽에서 Saltjaw Crocolisks를 처치하십시오. 자세한 내용은 해안을 확인하세요."}, [12]={hint="슬픔의 늪에 있는 다르에게 괴물게 집게발 10개를 가져가야 합니다.", desc="북부 해안을 따라 게를 죽여보세요. 남쪽으로 향하기 전에 다리 10개를 모으세요."}, [13]={npc="톡카르", tgt="톡카르"}, [14]={npc="톡카르", tgt="톡카르"}, [15]={hint="슬픔의 늪에 있는 톡카르에게 무쇠턱 톱니악어 발톱 6개를 가져가야 합니다."}, [16]={npc="톡카르", tgt="톡카르"}, [17]={npc="톡카르", tgt="톡카르"}, [18]={hint="슬픔의 늪에 있는 카타르와 대화해야 합니다."}, [19]={npc="카타르", tgt="카타르"}, [20]={npc="카타르", tgt="카타르", desc="남동쪽 해변에 있는 멀록 3종을 각각 10마리씩 처치하세요. 카타르로 돌아갑니다."}, [21]={hint="늪지멀록 10마리, 늪지멀록 먹물쟁이 10마리, 늪지멀록 청소부 10마리를 처치한 다음 슬픔의 늪에 있는 카타르에게 돌아가십시오.", desc="남동쪽 해변에 있는 멀록 3종을 각각 10마리씩 처치하세요. 카타르로 돌아갑니다."}, [22]={npc="카타르", tgt="카타르", desc="남동쪽 해변에 있는 멀록 3종을 각각 10마리씩 처치하세요. 카타르로 돌아갑니다."}, [23]={npc="카타르", tgt="카타르"}, [24]={hint="슬픔의 늪에 있는 톡카르와 대화해야 합니다."}, [25]={npc="톡카르", tgt="톡카르"}, [26]={npc="카타르", tgt="카타르", desc="1427 이후에는 카타르 를 참조하세요. 더 북쪽에서 오라클을 찾으세요. 세 가지 킬 횟수를 모두 확인하세요."}, [27]={hint="늪지멀록 먹물쟁이 10마리, 늪지멀록 청소부 10마리, 늪지멀록 점쟁이 10마리를 처치한 다음 슬픔의 늪에 있는 카타르에게 돌아가야 합니다.", desc="1427 이후에는 카타르 를 참조하세요. 더 북쪽에서 오라클을 찾으세요. 세 가지 킬 횟수를 모두 확인하세요."}, [28]={npc="카타르", tgt="카타르", desc="1427 이후에는 카타르 를 참조하세요. 더 북쪽에서 오라클을 찾으세요. 세 가지 킬 횟수를 모두 확인하세요."}, [29]={text="서쪽의 경로를 스토나드로 되돌리고 게 다리를 다르로 돌립니다."}, [30]={npc="다르", tgt="다르"}, [31]={text="반납 후 귀환석를 사용하여 모자케 야영지로 돌아갑니다. 그렇지 않으면 무법항로 날아가서 톱니항 보트를 타고 모자케 야영지로 날아가세요."}}},
    ["04-32"] = {name="페랄라스: 혈투의 전장", nameA="페랄라스: {a:1099} & 혈투의 전장", shortA="페랄라스: {a:1099} +", tips={{k="取捨", text="Rage Scar Yetis와 거친흉터 골짜기 Yetis는 별도의 목표입니다. 모자케 야영지에 품질 표시를 반납한 다음 품질 향상를 수행합니다. 아이템이 떨어지는 경우에만 완전한 설인 가죽를 반납하세요."}, {k="取捨", text="교차점을 저장하기 위해 멀록 체인 후 난로로 돌아갑니다. Hinterlands 구간에서 단지 실험를 위한 부엉이 정수를 수집하세요. 모자케 야영지에 대해 히포그리프 뮤세크 - 영혼의 무기를 저장합니다."}, {k="提醒", text="영상은 레벨 49 근처에서 페랄라스로 돌아갑니다. 경험치가 부족하면 55.73, 33.05에서 54.39, 33.10까지의 외부 루프에서 Rage Scar Yetis를 처치하세요. 한 번에 한 명의 적을 끌어 당깁니다.", s={{"영상은 레벨 49 근처에서 페랄라스로 돌아갑니다"}, {"경험치가 부족하면 55.73, 33.05에서 54.39, 33.10까지의 외부 루프에서 Rage Scar Yetis를 처치하세요"}, {"한 번에 한 명의 적을 끌어 당깁니다"}}}}, danger={[1]="예티 동굴 입구는 좁습니다. 덩치큰 무쇠설인 예티는 몹의 입으로 끌어당길 수 있습니다. 들어가기 전에 외부를 정리하세요."}, grind={[1]={mob="분노한 무쇠설인", note="무쇠설인 소굴의 바깥쪽 경사면에 있는 일반 예티입니다. 동굴이 붐비면 설인이 숨어 있는지 경사면을 반복하세요."}, [2]={mob="덩치큰 무쇠설인", note="같은 캠프에 있는 더 높은 레벨의 일반 예티입니다. 49에 도달할 때까지 섞으세요. 좁은 동굴에서 이중 당김을 피하기 위해 먼저 입구부터 클리어하세요."}}, supply={[1]={npc="쉬인"}, [2]={npc="여관주인 그룰"}, [3]={npc="카윈드 트루에임"}, [4]={npc="여관주인 그룰"}, [5]={npc="카윈드 트루에임"}, [6]={npc="탈후스"}}, steps={[1]={hint="페랄라스에 있는 의술사 우제리에게 네루의 약초 주머니를 가져가야 합니다."}, [2]={npc="의술사 우제리", tgt="의술사 우제리"}, [3]={npc="의술사 우제리", tgt="의술사 우제리", desc="동부 내륙지 올빼미야수 시체에 용기를 사용하세요. 모자케 야영지에서 반납하세요."}, [4]={npc="의술사 우제리", tgt="의술사 우제리", tag="선택사항", desc="진행하면서 천연 재료를 저장하세요. 수집을 마치고 모자케 야영지에 반납하세요."}, [5]={npc="의술사 우제리", tgt="의술사 우제리", desc="타나리스의 무너진 기둥에 있는 Marvon에게 돌아가세요."}, [6]={npc="탈로 쏜후프", tgt="탈로 쏜후프", desc="악령의 숲의 곰과 마울러를 위해 아껴두세요. 다음 방문 시에는 모자케 야영지에 제출하세요."}, [7]={hint="페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 주크애쉬 등껍질 20개를 가져가야 합니다."}, [8]={hint="고통의 구덩이에서 채찍쐐기를 물리치고 페랄라스의 모자케 야영지에 있는 아도겐 스위프트스트라이더에게 분비선을 가져가야 합니다."}, [9]={hint="모자케 야영지에 있는 로크 올한이 골두니일족 주술사 10명, 골두니일족 흑마법사 10명, 그리고 골두니일족 싸움꾼 5명을 처치해 달라고 부탁했습니다."}, [10]={hint="모자케 야영지에 있는 로크 올한이 골두니 수정구를 찾아 와 달라고 부탁했습니다."}, [11]={text="페랄라스의 오우거 및 주크애쉬 출몰를 보려면 모자케 야영지로 돌아가는 길을 따르세요. 다음 루프를 위해 북부 설인을 저장하세요."}, [12]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [13]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더"}, [14]={npc="로크 올한", tgt="로크 올한"}, [15]={npc="로크 올한", tgt="로크 올한"}, [16]={npc="아도겐 스위프트스트라이더", tgt="아도겐 스위프트스트라이더", desc="타나리스 구간에서 오그리마를 통과하면 다른 퀘스트를 완료하세요."}, [17]={npc="로크 올한", tgt="로크 올한", desc="타나리스 다리의 오그리마 턴인을 위해 저장하세요."}, [18]={text="분노의 흉터 예티스와 돌아오는 여행"}, [19]={hint="페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 무쇠설인 가죽 10개를 가져가야 합니다.", desc="서쪽으로 길을 따라 무쇠설인 소굴(55.73, 33.05)로 가세요. 10개의 가죽을 수집하세요."}, [20]={npc="완전한 설인 가죽", npcObj=true, tag="선택사항", desc="분노한 무쇠설인가 온전한 설인 가죽를 삭제하는 경우에만 수락합니다."}, [21]={hint="페랄라스의 모자케 야영지에 있는 장도르 스위프트스트라이더에게 완전한 설인 가죽을 가져가야 합니다.", tag="선택사항"}, [22]={text="예티가 완료되면 귀환석를 사용하여 모자케 야영지로 돌아가거나 주요 도로로 돌아가세요. 방향을 바꾸고 가젯잔로 날아가세요."}, [23]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더"}, [24]={npc="장도르 스위프트스트라이더", tgt="장도르 스위프트스트라이더", tag="선택사항"}}},
    ["05-d20"] = {name="마라우돈", entrance="잊혀진 땅 29.10, 62.50", pickup="레벨 39에서는 그늘수렵 마을 이전에 오그리마의 우텔나이에서 음영석 조각를 가져옵니다. 모자케 야영지에서 그늘수렵 마을로 이동하여 와루그 및 셀렌드라를 확인한 다음 윌로우 및 켄타우로스 추방자를 방문하세요. Forever 물병 체인의 경우 셴드랄라스 남동쪽에 있는 크리스탈 타워 및 마지스터 리드인을 수행한 다음 잊혀진 정원에서 숲이 전하는 말 → 부패와 회한를 선택하세요. 셴드랄라스 퀘스트는 레벨 35부터 가능합니다. 주황색 포털 이전에 카빈드라에서 수락하세요.", pickupS={{"레벨 39에서는 그늘수렵 마을 이전에 오그리마의 우텔나이에서 음영석 조각를 가져옵니다"}, {"모자케 야영지에서 그늘수렵 마을로 이동하여 와루그 및 셀렌드라를 확인한 다음 윌로우 및 켄타우로스 추방자를 방문하세요"}, {"Forever 물병 체인의 경우 셴드랄라스 남동쪽에 있는 크리스탈 타워 및 마지스터 리드인을 수행한 다음 잊혀진 정원에서 숲이 전하는 말 → 부패와 회한를 선택하세요"}, {"셴드랄라스 퀘스트는 레벨 35부터 가능합니다"}, {"주황색 포털 이전에 카빈드라에서 수락하세요"}}, tips={{k="動線", text="주황색: 녹시온 및 칼날채찍. 보라색: 군주 바일텅. 조각상, 칸 보석 및 기타 퀘스트 전리품을 수집하고 → 교차점에서 Celebras를 수행한 다음 그의 홀 의식을 따르세요 → 대지노래 폭포 → 공주 → 필요한 경우 썩은아귀의 수영장."}, {k="取捨", text="첫 번째 실행에서 홀을 얻으려면 주황색과 보라색 날개를 모두 수행하십시오. 공주와 악어만 원한다면 파티원의 홀을 사용해 안쪽 날개로 들어가세요. 외부의 섀도우 몹이 필요하거나 다른 건물의 목표가 필요한 경우 바로가기를 건너뛰세요."}, {k="說明", text="외부 동굴은 29.10, 62.50에 있습니다. 주황색 또는 보라색 터널을 따라 포털로 이동하세요. 두 경로 모두 독폭포에서 만납니다.", s={{"외부 동굴은 29.10, 62.50에 있습니다"}, {"주황색 또는 보라색 터널을 따라 포털로 이동하세요"}, {"두 경로 모두 독폭포에서 만납니다"}}}}, steps={[1]={npc="우텔나이", tgt="우텔나이"}, [2]={npc="바르크 배틀스카", tgt="바르크 배틀스카"}, [3]={npc="셀렌드라", tgt="셀렌드라"}, [4]={npc="윌로우", tgt="윌로우"}, [5]={npc="켄타우로스 추방자", tgt="켄타우로스 추방자", desc="켄타우로스 추방자는 잊혀진 땅 남부를 순찰합니다."}, [6]={npc="셴드랄라 수정탑", npcObj=true, tag="선택사항"}, [7]={hint="셴드랄라스를 탐사하며 전에 발견한 것과 같은 수정탑을 더 찾아야 합니다.", tag="선택사항"}, [8]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항"}, [9]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항", preText="이상한 수정탑"}, [10]={hint="마그람과 겔키스 마을에서 경비병이 지키는 수정탑의 조각과 파편을 회수한 후, 모덴트 이븐셰이드에게 가져가야 합니다.", tag="선택사항", desc="핀은 마그람 마을과 겔키스 켄타우로스 마을의 두 항목을 순서대로 표시합니다."}, [11]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항"}, [12]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항", desc="필요한 마나량은 퀘스트 목록에서 확인하세요.", preText="수정탑의 파편"}, [13]={hint="셴드랄라스 사원 안에서 마나 여과기를 입수하여 고대 마나 결정을 수집해야 합니다. 마나를 충분히 모으면 수정탑에 힘을 불어넣은 뒤, 모덴트 이븐셰이드에게 가야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="필요한 마나량은 퀘스트 목록에서 확인하세요. 위쪽 신전 가장 높은 층에서 체를 얻으세요. 마나는 총 8개, 탑마다 4개씩 모읍니다. 서쪽 탑과 동쪽 탑은 은신 상태에서도 상호작용할 수 있습니다."}, [14]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항", desc="필요한 마나량은 퀘스트 목록에서 확인하세요."}, [15]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항, 게임 내 확인이 필요합니다", preText="수정탑 동력 공급"}, [16]={hint="셴드랄라스에 있는 모덴트 이븐셰이드와 대화해 복구한 수정에 관한 정보를 얻어야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [17]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항, 게임 내 확인이 필요합니다"}, [18]={npc="모든트 이븐셰이드", tgt="모든트 이븐셰이드", tag="선택사항, 게임 내 확인이 필요합니다", preText="간략한 역사 수업"}, [19]={hint="셴드랄라스의 사원에서 마법학자 키란디스를 찾아야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [20]={npc="마법학자 키란디스", tgt="마법학자 키란디스", tag="선택사항, 게임 내 확인이 필요합니다"}, [21]={npc="미세라", tgt="미세라", tag="던전 선행"}, [22]={npc="미세라", tgt="미세라", tag="던전 선행"}, [23]={npc="미세라", tgt="미세라", tag="선택사항, 게임 내 확인이 필요합니다", preText="마법학자와의 만남"}, [24]={hint="잊혀진 땅 셴드랄라스에 있는 버려진 정원에서 우드와이어드를 찾아야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [25]={npc="우드와이어드", tgt="우드와이어드", tag="선택사항, 게임 내 확인이 필요합니다"}, [26]={npc="우드와이어드", tgt="우드와이어드", tag="선택사항, 게임 내 확인이 필요합니다", desc="먼저 숲이 전하는 말를 켜세요. 이것을 내부 마라우돈로 가져옵니다.", preText="숲이 전하는 말"}, [27]={npc="카빈드라", tgt="카빈드라", desc="카빈드라는 주황색 포탈 밖에 있습니다. 각 팀의 보스에게서 아이템 하나씩을 전리품으로 획득하세요."}, [28]={hint="마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다."}, [29]={text="마라우돈 입구"}, [30]={text="주황색 면: 썩은포자 동굴(45-53). 동굴 깊은 곳에 있는 주황색 수정과 웅덩이를 찾아보세요. 포털에 들어가기 전에 약병을 채우세요."}, [31]={hint="마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.", desc="위치: 주황색 포털 바깥쪽 수영장에서 약병을 채우세요. 내부에서 덩굴을 찾으세요.", spot="주황색 포털 바깥쪽 수영장에서 약병을 채우세요. 내부에서 덩굴을 찾으세요."}, [32]={text="보라색 면: 사악한 동굴(45-53). 삼방향 분기점에서 보라색 수정 통로를 이용하세요. 군주 바일텅에서 다이아몬드를 약탈하세요."}, [33]={hint="트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.", desc="정확한 수량은 퀘스트 목록을 기준으로 하세요. 위치: 이동하면서 포털과 전리품 조각상 밖에서 켄타우로스를 처치하세요.", spot="이동하면서 포털과 전리품 조각상 밖에서 켄타우로스를 처치하세요."}, [34]={hint="추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.", desc="세 명의 칸이 갈림길과 외부 터널을 순찰합니다. 하나는 각 포털 내부에 있습니다. 위치: 분기점과 외부 동굴에서 세 명의 칸을 찾은 다음 각 포털 내부에서 한 명씩 찾습니다.", spot="분기점과 외부 동굴에서 세 명의 칸을 찾은 다음 각 포털 내부에서 한 명씩 찾습니다."}, [35]={hint="<name>레브라스의 홀 조각인 <name>레브리안 마법봉과 <name>레브리안 다이아몬드를 찾아야 합니다.", desc="위치: 주황색은 막대를, 보라색은 다이아몬드를 얻으세요. 그들이 만나는 곳에서 셀레브라스를 처치하십시오. 순서: 주황색과 보라색 경로를 모두 이용하세요. 재료가 모두 준비되면 제출하세요.", spot="주황색은 막대를, 보라색은 다이아몬드를 얻으세요. 그들이 만나는 곳에서 셀레브라스를 처치하십시오."}, [36]={npc="회복된 셀레브라스", tgt="회복된 셀레브라스", tag="게임 내 확인이 필요합니다", desc="보스를 처치한 후 회복된 셀레브라스와 대화하세요. 처치한 뒤 같은 방에 있는 구원받은 자에게 제출하세요.", spot="저주받은 셀레브라스 방 안, 구원받은 셀레브라스"}, [37]={npc="회복된 셀레브라스", tgt="회복된 셀레브라스", tag="게임 내 확인이 필요합니다", desc="구원받은 자는 우두머리 방에 있습니다. 의식 중에 그를 따라가세요.", preText="마라우돈의 전설"}, [38]={hint="회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.", desc="구원받은 자는 우두머리 방에 있습니다. 의식 중에 그를 따라가세요. 위치: 보스룸에서 회복된 셀레브라스의 의식을 따라가세요.", spot="보스룸에서 회복된 셀레브라스의 의식을 따라가세요."}, [39]={npc="회복된 셀레브라스", tgt="회복된 셀레브라스", tag="게임 내 확인이 필요합니다", desc="구원받은 자는 우두머리 방에 있습니다. 의식 중에 그를 따라가세요.", spot="저주받은 셀레브라스 방 안, 구원받은 셀레브라스"}, [40]={text="내부 경로: 대지노래 폭포(48-57). 주황색/보라색 교차로에서 내려오거나 홀을 가진 플레이어가 지름길을 열도록 하세요."}, [41]={hint="마라우돈으로 이동해 대지의 노래 물병을 회수한 후, 잊혀진 땅 버려진 정원에 있는 우드와이어드에게 제출해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다", desc="썩은아귀가 웅덩이를 순찰합니다. 작은 분수는 같은 웅덩이의 수면에 있습니다. 위치: 공주 아래의 썩은아귀 풀에 들어가세요. 표면에서 스프링을 찾으세요. 순서: 다이빙하기 전에 39단계를 수행하십시오.", spot="공주 아래의 썩은아귀 풀에 들어가세요. 표면에서 스프링을 찾으세요."}, [42]={hint="공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.", desc="위치: 대지노래 폭포를 따라 재타르의 동굴로 들어가 공주의 플랫폼에 도달하세요.", spot="대지노래 폭포를 따라 재타르의 동굴로 들어가 공주의 플랫폼에 도달하세요."}, [43]={npc="재타르의 영혼", tgt="재타르의 영혼", tag="게임 내 확인이 필요합니다", desc="재타르의 영혼는 공주가 죽은 후에 나타납니다. 지금 수락하여 밖에서 반납하세요."}, [44]={npc="셀렌드라", tgt="셀렌드라"}, [45]={npc="바르크 배틀스카", tgt="바르크 배틀스카"}, [46]={npc="윌로우", tgt="윌로우"}, [47]={npc="켄타우로스 추방자", tgt="켄타우로스 추방자"}, [48]={npc="우텔나이", tgt="우텔나이"}, [49]={hint="마라우돈으로 이동해 대지의 노래 물병을 회수한 후, 잊혀진 땅 버려진 정원에 있는 우드와이어드에게 제출해야 합니다.", tag="선택사항, 게임 내 확인이 필요합니다"}, [50]={npc="우드와이어드", tgt="우드와이어드", tag="선택사항, 게임 내 확인이 필요합니다"}, [51]={hint="달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다.", desc="달의 숲를 통과할 때를 대비해 절약하세요."}, [52]={npc="수호자 레물로스", tgt="수호자 레물로스", desc="달의 숲용으로 저장하세요."}}},
    ["04-33"] = {name="타나리스: 모래폭풍 야영지", nameA="타나리스: {a:976} & 모래폭풍 야영지", shortA="타나리스: {a:976} +", tips={{k="取捨", text="북쪽 수영장에 들어가 82개를 잠금 해제하세요. 82개를 돌려 10개를 잠금 해제한 다음 Dunemaul, 덤불나무 골짜기 및 남부 하이브 목표를 한 루프에서 수행하세요."}, {k="取捨", text="그룹이 있고 4개의 던전 퀘스트를 모두 함께 수행하는 경우 줄파락를 실행하세요. 그렇지 않으면 건너뛰고 고대의 알을 건너뛰세요."}, {k="取捨", text="32와 주크애쉬 보고서를 먼저 제출하세요. Quest 실리시드의 행진에는 레벨 50이 필요합니다. 자격이 되면 어둠의 틈를 확인하고 가젯잔 및 무너진 기둥 구간에 대한 전체 후속 조치를 저장하세요."}, {k="提醒", text="레벨 50 이하? 모래망치 주둔지 (40.75, 50.67)에서 천으로 묶인 일반 오우거를 갈아주세요. 이글거리는 협곡를 땡땡이치고 싶다면 경험치 간격을 조금 남겨두세요.", s={{"레벨 50 이하?"}, {"모래망치 주둔지 (40.75, 50.67)에서 천으로 묶인 일반 오우거를 갈아주세요"}, {"이글거리는 협곡를 땡땡이치고 싶다면 경험치 간격을 조금 남겨두세요"}}}}, danger={[1]="Centipaar 벌통 입구는 제압하기 쉽습니다. 벌집 밖의 열린 땅에서 싸우고 폭도들을 쫓아 좁은 터널로 들어가지 마세요."}, grind={[1]={mob="모래망치일족 투사", note="모래망치 주둔지 외부의 밀집된 일반 근접 몹. 천을 모아 오우거 퀘스트를 수행하세요. 캠프가 붐비면 가장자리를 따라 계속 이동하세요."}, [2]={mob="우두머리 센티파르", note="서쪽 실리시드 벌집 외부에 밀집된 더 높은 수준의 일반 몹. 입구 근처로 한 번에 한 명의 적을 끌어당깁니다. 좁은 터널에서는 무리를 피하세요."}}, supply={[1]={npc="벌크렉 레이지피스트"}, [2]={npc="여관주인 피즈그림블"}, [3]={npc="링클 굿스틸"}, [4]={npc="여관주인 피즈그림블"}, [5]={npc="브리즈릭 벅샷"}}, steps={[1]={text="모자케 야영지에서 가젯잔로 날아가서 지금은 귀환석를 거기에 바인딩하세요."}, [2]={text="가젯잔에서 수락한 후 서쪽으로 이동하여 물 샘플과 Noxious Lair를 찾으세요."}, [3]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [4]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [5]={npc="앤디 린", tgt="앤디 린"}, [6]={npc="트란렉", tgt="트란렉"}, [7]={npc="쿠인", tgt="쿠인", tag="선택사항", desc="통과하면 사막 스크랩을 약탈하세요."}, [8]={hint="슬픈모래 감시탑의 물 웅덩이 부근에서 추출 전의 탐사장치를 사용하십시오. 다 채웠으면 가젯잔에 있는 선임측량사 피즐도저에게 추출한 탐사장치를 가져가야 합니다.", desc="슬픈모래 감시탑 풀에서 추출 전의 탐사장치를 사용합니다. 샘플을 가지고 돌아오세요."}, [9]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [10]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [11]={hint="맹독의 둥지에서 센티파르 곤충 기관 5개를 구해 가젯잔에 있는 연금술사 페슬저그에게 가져가야 합니다."}, [12]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [13]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [14]={text="남쪽으로 Sandfury 및 덤불나무 골짜기까지 이동한 후 산기슭을 따라 벌집으로 이동하세요."}, [15]={hint="가젯잔에 있는 앤디 린이 모래망치일족 투사, 모래망치일족 집행자를 각각 10명씩 처치하고 파괴자 고르마로크를 처단하여 모래망치 주둔지를 없애 달라고 부탁했습니다."}, [16]={hint="타나리스 스팀휘들 항구의 보안과장 빌지위즐을 위해 모래망치 오우거 주둔지 근처에서 잃어버린 유난히 반짝이는 팔찌를 회수해야 합니다.", tag="선택사항", desc="스팀휘들 항구 및 가젯잔 다리에서 집어든 경우에만 이 작업을 수행하십시오."}, [17]={hint="가득 찬 이슬샘을 모아 가젯잔에 있는 마린 노겐포저에게 가져가야 합니다.", desc="덤불나무 골짜기에서 이슬 수집가를 처치하십시오. 가득 찬 이슬샘 1개를 획득하세요."}, [18]={hint="가젯잔에 있는 트란렉이 옹이진 덤불나무괴물 8마리와 억센뿌리 덤불나무괴물 8마리를 처치해달라고 부탁했습니다."}, [19]={hint="후임측량사 슈섕크가 어떻게 되었는지 알아보고 가젯잔에 있는 선임측량사 피즐도저에게 데려오거나 그의 측량 장비라도 찾아서 가져가야 합니다.", desc="남쪽 균열의 지하로 가서 슈섕크의 측량 장비를 찾으세요."}, [20]={hint="사막 잔해 7개를 회수한 후, 가젯잔에 있는 쿠인에게 가야 합니다.", tag="선택사항", desc="핀은 확인된 산란을 표시합니다. 얼라이언스 연합 퀘스트는 스크랩을 드롭할 수 있습니다. 가젯잔 외부를 확인하세요."}, [21]={text="퀘스트를 완료하려면 가젯잔로 돌아가세요. 준비가 되었으면 난로에 있는 동안 맛의 달인 및 곤충 기관 분석를 선택하세요."}, [22]={npc="앤디 린", tgt="앤디 린"}, [23]={npc="트란렉", tgt="트란렉"}, [24]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [25]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [26]={npc="쿠인", tgt="쿠인", tag="선택사항"}, [27]={npc="마린 노겐포저", tgt="마린 노겐포저"}, [28]={hint="마린 노겐포저가 가젯잔에 있는 스프링클과 대화할 것을 부탁했습니다."}, [29]={npc="스프링클", tgt="스프링클"}, [30]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [31]={hint="가젯잔에 가서 연금술사 페슬저그를 만나 곤충 기관의 분석이 끝났는지 알아보아야 합니다."}, [32]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [33]={npc="연금술사 페슬저그", tgt="연금술사 페슬저그"}, [34]={hint="가젯잔에 있는 선임측량사 피즐도저에게 곤충 분석 보고서를 가져가야 합니다. 연금술사 페슬저그가 요청한 대로 피즐도저로부터 보고서의 사본을 꼭 받아야 합니다."}, [35]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저"}, [36]={npc="스프링클", tgt="스프링클", desc="동부 내륙지의 돌개바람 호수에서 제비수염버섯를 수집하세요. 가젯잔에서 반납하세요."}, [37]={npc="선임측량사 피즐도저", tgt="선임측량사 피즐도저", desc="오그리마의 어둠의 틈에서 반납하세요. 주크애쉬 보고서로 전제조건을 수행하십시오."}, [38]={text="옵션 스팀휘들 항구 및 줄파락"}, [39]={npc="예킨야", tgt="예킨야", desc="모자케 야영지 다리에서 3개의 계곡천둥매의 영혼가 필요합니다."}, [40]={npc="보안과장 빌지위즐", tgt="보안과장 빌지위즐", tag="선택사항"}, [41]={npc="예킨야", tgt="예킨야", tag="선택사항", desc="먼저 계곡천둥매의 영혼를 켜세요. 줄파락 그룹이 생기면 이것을 선택하세요."}, [42]={hint="타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다.", tag="선택사항"}, [43]={hint="가젯잔에 있는 트란렉에게 온전한 왕쇠똥구리 껍질 5개를 가져가야 합니다.", tag="선택사항", desc="줄파락 묘지의 풍뎅이를 제거하세요."}, [44]={hint="가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다.", tag="선택사항", desc="계단 이벤트를 완료하세요. 하사관 블라이에서 막대를 가져옵니다."}, [45]={hint="가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다.", tag="선택사항"}, [46]={npc="예킨야", tgt="예킨야", tag="선택사항"}, [47]={npc="예킨야", tgt="예킨야", tag="선택사항", desc="모쉬아루의 예언 이후, 동부 내륙지에서 고대의 알를 얻으세요. 스팀휘들 항구에서 반납하세요."}, [48]={npc="트란렉", tgt="트란렉", tag="선택사항"}, [49]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐", tag="선택사항", star={"석공 조합 반지", {"ROGUE", "HUNTER", "DRUID"}}}, [50]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머", tag="선택사항"}, [51]={text="가젯잔에서 오그리마로 비행합니다. 드래그에서 질지빈 드럼로어를 확인한 다음 Darkbriar Lodge에서 골두니 수정구를 반납하세요."}, [52]={hint="오그리마에 있는 질지빈 드럼로어에게 보고서를 가져가야 합니다."}, [53]={hint="오그리마 골목길에 사는 질지빈 드럼로어에게 모자케 야영지 주크애쉬 보고서를 전달해야 합니다."}, [54]={hint="오그리마의 검은장미 오두막에 있는 우텔나이에게 골두니 수정구를 가져가야 합니다."}, [55]={npc="질지빈 드럼로어", tgt="질지빈 드럼로어"}, [56]={npc="질지빈 드럼로어", tgt="질지빈 드럼로어"}, [57]={npc="우텔나이", tgt="우텔나이"}}},
    ["05-d21"] = {name="줄파락", entrance="타나리스 38.70, 20.00", pickup="가젯잔에서 세 가지 지역 퀘스트를 수행한 다음 스팀휘들 항구의 예킨야에서 계곡천둥매의 영혼를 수행합니다. 페랄라스에서 영혼을 수집하세요. 스팀휘들 항구로 돌아가 계곡천둥매의 영혼를 반납하고 모쉬아루의 예언를 수락한 후 가젯잔에서 그룹을 만나세요. Shimmering Flats를 통과할 때 가즈릴라를 획득하세요. 마법사는 슬픔의 늪 이전에 타베사의 Dustwallow 퀘스트를 수행할 수 있습니다.", pickupS={{"가젯잔에서 세 가지 지역 퀘스트를 수행한 다음 스팀휘들 항구의 예킨야에서 계곡천둥매의 영혼를 수행합니다"}, {"페랄라스에서 영혼을 수집하세요"}, {"스팀휘들 항구로 돌아가 계곡천둥매의 영혼를 반납하고 모쉬아루의 예언를 수락한 후 가젯잔에서 그룹을 만나세요"}, {"Shimmering Flats를 통과할 때 가즈릴라를 획득하세요"}, {"마법사는 슬픔의 늪 이전에 타베사의 Dustwallow 퀘스트를 수행할 수 있습니다"}}, tips={{k="動線", text="안투술의 측면 경로 → 첫 번째 Mosh'aru 태블릿을 위한 Theka → Zum'rah의 묘지 → 자동 탐사막대를 위한 피라미드 계단 이벤트 → 두 번째 태블릿을 위한 Velratha → 수영장의 옵션 가즈릴라 → Chief Ukorz. 풍뎅이 껍질과 트롤 경화제를 전체적으로 획득하세요."}, {k="取捨", text="세 가지 가젯잔 퀘스트와 Mosh'aru의 서판을 우선적으로 처리하세요. 망치가 있다면 가즈릴라와 싸워보세요. Dustwallow 방문을 위해 타베사를 저장하세요."}, {k="說明", text="스팀휘들 항구 및 가젯잔 구간에서 한 번 실행합니다. 예킨야의 풀 체인을 수행하는 경우 가젯잔 및 Dunemaul이 방문할 때까지 기다리십시오. 모쉬아루의 서판은 학카르 체인의 전제 조건이기도 합니다.", s={{"스팀휘들 항구 및 가젯잔 구간에서 한 번 실행합니다"}, {"예킨야의 풀 체인을 수행하는 경우 가젯잔 및 Dunemaul이 방문할 때까지 기다리십시오"}, {"모쉬아루의 서판은 학카르 체인의 전제 조건이기도 합니다"}}}}, steps={[1]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [2]={npc="트란렉", tgt="트란렉"}, [3]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머"}, [4]={npc="예킨야", tgt="예킨야", desc="스팀휘들 항구에서 수락한 다음 페랄라스를 수행합니다. 이것을 반납한 후 모쉬아루의 예언를 가져가세요."}, [5]={hint="페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다."}, [6]={npc="예킨야", tgt="예킨야"}, [7]={npc="예킨야", tgt="예킨야", preText="계곡천둥매의 영혼"}, [8]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠", tag="선택사항", desc="줄파락의 나무망치를 가져오세요. Zul의 제단에서 신성한 나무망치를 얻고 진타알로에서 사용하세요."}, [9]={npc="타베사", tgt="타베사", tag="선택사항", desc="타베사에서 직접 수락하세요. 레벨 40 언더시티 시작 퀘스트(타베사의 임무)는 선택사항입니다."}, [10]={text="줄파락 입구"}, [11]={hint="가젯잔에 있는 트란렉에게 온전한 왕쇠똥구리 껍질 5개를 가져가야 합니다.", desc="위치: 순교자 데카의 방 주변에 있는 풍뎅이를 처치하세요. 순서: 여기서 15단계의 첫 번째 알약을 복용하세요.", spot="순교자 데카의 방 주변에 있는 풍뎅이를 처치하세요."}, [12]={hint="가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다.", desc="실행하기 전에 전리품에 동의하십시오. 하나의 클리어가 충분히 드롭되지 않을 수 있습니다. 위치: 입구에서 주요 경로를 따라 성난모래 트롤을 처치하세요.", spot="입구에서 주요 경로를 따라 성난모래 트롤을 처치하세요."}, [13]={hint="먼지진흙 습지대에 있는 타베사에게 심연의 티아라를 가져가야 합니다.", tag="선택사항", desc="위치: 피라미드를 지나 수영장 옆에서 벨라타를 찾으세요. 순서: 여기서 15단계를 위한 두 번째 알약을 복용하세요.", spot="피라미드를 지나 수영장 옆에서 벨라타를 찾으세요."}, [14]={hint="소금 평원에 있는 위즐 브라스볼츠에게 가즈릴라의 전기 비늘을 가져가야 합니다.", tag="선택사항", desc="위치: 벨라타의 웅덩이 옆에서 징을 울리면 가즈릴라를 소환할 수 있습니다. 순서: 징을 울리기 전에 유체술사 벨라타를 처치하세요.", spot="벨라타의 웅덩이 옆에서 징을 울리면 가즈릴라를 소환할 수 있습니다."}, [15]={hint="가젯잔에 있는 선임기술자 빌지위즐에게 자동 탐사막대를 가져가야 합니다.", desc="계단 이벤트를 위해 우리를 엽니다. 적대적으로 변하기 전에 아래의 파도를 제거하세요. 위치: 피라미드 꼭대기에 있는 우리를 엽니다. 계단을 내려가 파도를 막아보세요. 순서: 파도를 방어하고 하사관 블라이에 도전하세요.", spot="피라미드 꼭대기에 있는 우리를 엽니다. 계단을 내려가 파도를 막아보세요."}, [16]={hint="타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다.", desc="위치: 풍뎅이 방에 있는 Theka와 수영장 옆에 있는 Velratha를 약탈하세요. 순서: 딱정벌레 방에서는 10단계를 수행하고 수영장에서는 12~13단계를 수행합니다.", spot="풍뎅이 방에 있는 Theka와 수영장 옆에 있는 Velratha를 약탈하세요."}, [17]={npc="트란렉", tgt="트란렉"}, [18]={npc="트렌튼 라이트해머", tgt="트렌튼 라이트해머"}, [19]={npc="선임기술자 빌지위즐", tgt="선임기술자 빌지위즐"}, [20]={npc="예킨야", tgt="예킨야"}, [21]={npc="예킨야", tgt="예킨야", desc="지금 수락하세요. 아탈 신전' 학카르 앞에 있는 진타알로에서 알을 루팅하세요.", preText="모쉬아루의 예언"}, [22]={npc="위즐 브라스볼츠", tgt="위즐 브라스볼츠", tag="선택사항"}, [23]={npc="타베사", tgt="타베사", tag="선택사항"}}},
    ["04-34"] = {name="이글거리는 협곡", nameA="이글거리는 협곡: {a:1446}", tips={{k="交通", text="잠금 해제 토륨 조합 거점의 호드 연합 비행 지점. 내륙지로 계속 이동하기 전에 언더시티 또는 해머폴로 비행하세요."}, {k="取捨", text="한 번의 루프에서 4개의 처치 목표를 클리어하세요. 도난품: 가열로 바람구멍 및 감시병의 망원경 드랍이 부족한 경우 다른 드랍을 먼저 제출하세요. 그룹이 있다면 같은 동굴에서 현상수배: 감독관 말토류스와 불꽃 융해촉진제?를 하세요."}, {k="取捨", text="퀘스트를 완료하면 토륨 조합 거점를 떠나 레벨 50에 도달할 수 있습니다. 이후의 횃불 퀘스트와 남동부 나무 간이화장실는 모두 역추적이 필요합니다. 경험치가 필요한 경우에만 수행하십시오."}, {k="提醒", text="약간의 경험치가 필요하십니까? 가마솥 동쪽의 중전차 골렘(44.76, 38.72)이나 북쪽 경사면(41.21, 23.33)의 일반 검은무쇠 감독관을 처치하세요.", s={{"약간의 경험치가 필요하십니까?"}, {"가마솥 동쪽의 중전차 골렘(44.76, 38.72)이나 북쪽 경사면(41.21, 23.33)의 일반 검은무쇠 감독관을 처치하세요"}}}}, danger={[1]="감독관 말토류스는 슬래그 구덩이 옆 검은무쇠 광산 깊은 곳에 있습니다. 그룹과 함께 터널을 청소하세요. 솔로인 경우 현상금을 건너뜁니다."}, grind={[1]={mob="육중한 전투골렘", note="가마솥 동쪽 가장자리에 있는 일반 골렘입니다. 테두리를 따라 높은 곳에 머물며 퀘스트를 위해 킬 수를 세어보세요. 다른 플레이어가 있으면 바닥을 피하세요."}, [2]={mob="검은무쇠단 감독관", note="토륨 조합 거점 남쪽의 일반 검은무쇠 몹. 비행 지점로 돌아가기 전에 킬과 퀘스트 드롭을 선택하세요. 캠프 내부에 추가 사항이 있는지 확인하세요."}}, supply={[1]={npc="그리샤"}, [2]={npc="수석대장장이 버니네이트"}, [3]={npc="수석대장장이 버니네이트"}, [4]={npc="수석대장장이 버니네이트"}}, steps={[1]={text="오그리마에서 톱니항로 비행합니다. 무법항로 보트를 타기 전에 부두에서 운고로 리드인을 찾으세요. 카르가스로 날아가세요."}, [2]={npc="리브 리즐픽스", tgt="리브 리즐픽스", desc="49가 필요합니다. 운고로의 불기둥 마루에서 수행하세요. 톱니항에서 반납하세요."}, [3]={text="카르가스에서 남서쪽 도로를 타고 이글거리는 협곡로 들어간 후 북쪽 도로를 따라 토륨 조합 거점로 가세요."}, [4]={nodeA="{a:1446}", desc="잠금 해제 호드 연합 비행 지점 및 그리샤."}, [5]={text="토륨 조합 거점에서 수락한 다음 가마솥과 슬래그 구덩이를 순환합니다."}, [6]={npc="구인광고/분실물센터/지명수배", npcObj=true}, [7]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [8]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [9]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [10]={npc="구인광고/분실물센터/지명수배", npcObj=true, tag="선택사항", desc="몹을 제거하면서 두 방울을 모두 약탈하세요."}, [11]={npc="구인광고/분실물센터/지명수배", npcObj=true, tag="선택사항", desc="마르토리우스는 엘리트입니다. 그룹으로만 수락하세요."}, [12]={npc="수석대장장이 버니네이트", tgt="수석대장장이 버니네이트", tag="선택사항", desc="Martorius 그룹 실행에서 이것을 선택하십시오."}, [13]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [14]={hint="벨라로크 윈드블레이드가 하는 이야기를 들으십시오."}, [15]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [16]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [17]={hint="이글거리는 협곡의 고원과 용암 웅덩이에 서식하는 불타는 용암거미 20마리를 찾아 처치해야 합니다."}, [18]={hint="검은무쇠 감독관 15명과 검은무쇠 노예상인 15명을 처치하고 임무를 완수한 후, 이글거리는 협곡에 있는 작업반장 스크랜지에게 돌아가야 합니다."}, [19]={hint="이글거리는 협곡의 용광로 주변을 돌아다니는 육중한 전투골렘 20마리를 처치하고 임무를 완수하면 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다."}, [20]={hint="화염의 심장 4개와 골렘 기름 4개를 모아 벨라로크 윈드블레이드에게 가져가야 합니다.", desc="가마솥 주변의 골렘과 불의 정령을 처치하세요."}, [21]={hint="이글거리는 협곡에 있는 작업반장 스크랜지에게 가열로 바람구멍과 감시병의 망원경을 찾아 가져가야 합니다.", tag="선택사항"}, [22]={hint="용광로에 있는 잿가루 채석장 안의 용암 지대를 점령하고 있는 인센도사우루스 20마리를 처치한 후, 이글거리는 협곡에 있는 한셀 헤비핸드에게 돌아가야 합니다.", desc="검은무쇠 몹과 함께 잿가루 구덩이에 있는 인센도사우루스를 처치하세요."}, [23]={hint="용광로의 잿가루 채석장 어딘가에 감독관 말토류스가 훔친 비밀조제법: 불꽃 융해촉진제가 있을 것입니다. 이 조제법을 찾아서 이글거리는 협곡에 있는 수석대장장이 버니네이트에게 가져가야 합니다.", tag="선택사항", desc="슬래그 구덩이 깊은 곳에 있는 마르토리우스 근처에서 계획을 찾아보세요. 안전할 때 약탈하세요."}, [24]={hint="이글거리는 협곡의 용광로에 있는 잿가루 채석장 깊은 곳에서 검은무쇠 드워프 변절자인 감독관 말토류스를 찾아 처치하고, 이글거리는 협곡에 있는 감시대장 롤로 롱스트라이커에게 그의 머리카락을 증거로 가져가 보상을 받아야 합니다.", tag="선택사항"}, [25]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드"}, [26]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항", desc="경험치가 필요하고 Cauldron을 다시 방문할 의향이 있으면 수락하세요."}, [27]={hint="벨라로크 윈드블레이드에게 토륨 도금 단검 8개를 가져가야 합니다.", tag="선택사항", desc="잿가루 구덩이에 있는 검은무쇠 감독관과 노예상인에게서 획득할 수 있습니다."}, [28]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [29]={text="토륨 조합 거점로 돌아가서 모든 가마솥 퀘스트를 함께 완료하세요."}, [30]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [31]={npc="작업반장 스크랜지", tgt="작업반장 스크랜지"}, [32]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [33]={npc="한셀 헤비핸드", tgt="한셀 헤비핸드"}, [34]={npc="작업반장 스크랜지", tgt="작업반장 스크랜지", tag="선택사항"}, [35]={npc="수석대장장이 버니네이트", tgt="수석대장장이 버니네이트", tag="선택사항"}, [36]={npc="감시대장 롤로 롱스트라이커", tgt="감시대장 롤로 롱스트라이커", tag="선택사항"}, [37]={text="여전히 필요한 경우 추가 경험치 또는 토치"}, [38]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항", desc="횃불 자루 만들기을 완료하세요. 라그나로스의 상징를 위해 서쪽 동굴에서 황혼 몹을 처치하세요."}, [39]={hint="벨라로크 윈드블레이드에게 라그나로스의 상징 1개를 찾아 가져가야 합니다.", tag="선택사항", desc="횃불 자루 만들기을 완료하세요. 라그나로스의 상징를 위해 서쪽 동굴에서 황혼 몹을 처치하세요."}, [40]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항", desc="횃불 자루 만들기을 완료하세요. 라그나로스의 상징를 위해 서쪽 동굴에서 황혼 몹을 처치하세요."}, [41]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [42]={hint="벨라로크 윈드블레이드가 응보의 횃불을 완성할 동안 기다려야 합니다.", tag="선택사항"}, [43]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [44]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [45]={hint="응보의 횃불을 집어 드십시오.", tag="선택사항"}, [46]={npc="응보의 횃불", npcObj=true, tag="선택사항"}, [47]={npc="칼라란 윈드블레이드", tgt="칼라란 윈드블레이드", tag="선택사항"}, [48]={hint="수습기사 몰트레이크와 대화해야 합니다.", tag="선택사항"}, [49]={npc="수습기사 몰트레이크", tgt="수습기사 몰트레이크", tag="선택사항"}, [50]={npc="수습기사 몰트레이크", tgt="수습기사 몰트레이크", tag="선택사항", desc="네 개의 탑에 불을 붙이기 전에 경비병을 끌어내세요."}, [51]={hint="북쪽, 남쪽, 동쪽과 서쪽 감시탑 내부에서 응보의 횃불을 사용해 불을 지르십시오.", tag="선택사항", desc="네 개의 탑에 불을 붙이기 전에 경비병을 끌어내세요."}, [52]={npc="수습기사 몰트레이크", tgt="수습기사 몰트레이크", tag="선택사항", desc="네 개의 탑에 불을 붙이기 전에 경비병을 끌어내세요."}, [53]={npc="검은용군단의 보물", npcObj=true, tag="선택사항"}, [54]={hint="궤짝을 여십시오.", tag="선택사항"}, [55]={npc="검은용군단의 보물", npcObj=true, tag="선택사항"}, [56]={npc="나무 간이화장실", npcObj=true, tag="선택사항", desc="경험치에서 남동쪽으로 향하거나 짧은 경우 나무 간이화장실로 우회하세요. 비단 옷감 15개를 가져오세요."}, [57]={hint="검은무쇠 지질학자 8명을 처치하고 이글거리는 협곡의 화장실에 갇힌 사람에게 비단 옷감 15개를 가져가야 합니다.", tag="선택사항", desc="경험치에서 남동쪽으로 향하거나 짧은 경우 나무 간이화장실로 우회하세요. 비단 옷감 15개를 가져오세요."}, [58]={npc="나무 간이화장실", npcObj=true, tag="선택사항", desc="경험치에서 남동쪽으로 향하거나 짧은 경우 나무 간이화장실로 우회하세요. 비단 옷감 15개를 가져오세요."}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="먼지진흙 습지대 75.30, 14.10", pickup="레벨 48 이하인가요? 잠금 해제 담쟁이 마을 슬픔의 늪로 가는 길. 이글거리는 협곡 이전에 지혜의 골짜기(34.28, 39.35)에 있는 스랄의 방에 있는 아이트리그에서 실종된 코르크론를 가져옵니다. 담쟁이 마을로 날아가 나지르 블러드파이크를 확인하세요. 북동쪽 해안에서 수영까지 알카즈 섬. 섬 옆에 있는 하사에게 정예 중의 정예와 적절한 장소, 잘못된 시간를 반납한 다음 탑 아래로 들어가기 전에 오크를 구하라를 가져가세요. 오그리마용 Thrall Needs to Know를 저장합니다.", pickupS={{"레벨 48 이하인가요?"}, {"잠금 해제 담쟁이 마을 슬픔의 늪로 가는 길"}, {"이글거리는 협곡 이전에 지혜의 골짜기(34.28, 39.35)에 있는 스랄의 방에 있는 아이트리그에서 실종된 코르크론를 가져옵니다"}, {"담쟁이 마을로 날아가 나지르 블러드파이크를 확인하세요"}, {"북동쪽 해안에서 수영까지 알카즈 섬"}, {"섬 옆에 있는 하사에게 정예 중의 정예와 적절한 장소, 잘못된 시간를 반납한 다음 탑 아래로 들어가기 전에 오크를 구하라를 가져가세요"}, {"오그리마용 Thrall Needs to Know를 저장합니다"}}, tips={{k="動線", text="위쪽 셀에서 지휘관 Folkar 찾기 → 키를 위해 감독관 렉스 죽이기 → 심문관 및 해일여제 카자스 지우기, 두건 약탈 → 청소부 카테리나 및 불길포효에 대한 아래쪽 셀 열기 → 숨겨진 방에서 메모를 읽고 위층 Folkar로 돌아갑니다."}, {k="取捨", text="실종된 코르크론에서 Thrall Needs to Know까지 Kor'kron 구조 체인의 우선순위를 지정하세요. 한 번 실행한 후 두건이 부족하면 제출을 저장하세요."}, {k="說明", text="테라모어를 피하세요. 담쟁이 마을에서 북동쪽 해안으로 가서 헤엄쳐 건너세요. 상사는 섬 옆에 있고, 던전 포탈은 탑 아래 복도에 있습니다.", s={{"테라모어를 피하세요"}, {"담쟁이 마을에서 북동쪽 해안으로 가서 헤엄쳐 건너세요"}, {"상사는 섬 옆에 있고, 던전 포탈은 탑 아래 복도에 있습니다"}}}}, steps={[1]={npc="아이트리그", tgt="아이트리그", desc="48에서 지혜의 골짜기의 스랄 홀에서 아이트리그를 찾으세요."}, [2]={hint="담쟁이 마을에서 나지르 블러드파이크와 대화해야 합니다."}, [3]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크"}, [4]={npc="나지르 블러드파이크", tgt="나지르 블러드파이크", preText="실종된 코르크론"}, [5]={hint="실종된 코르크론 정예병을 찾아야 합니다."}, [6]={npc="하사관 울카", tgt="하사관 울카"}, [7]={npc="하사관 울카", tgt="하사관 울카", preText="정예 중의 정예"}, [8]={hint="하사관 울카와 대화하여 알카즈 섬의 상황을 자세히 알아봐야 합니다."}, [9]={npc="하사관 울카", tgt="하사관 울카"}, [10]={npc="하사관 울카", tgt="하사관 울카", preText="적절한 장소, 잘못된 시간"}, [11]={npc="하사관 울카", tgt="하사관 울카", tag="선택사항", desc="오그리마에서 섬까지 실종된 코르크론 - 적절한 장소, 잘못된 시간를 수행한 후 상사의 퀘스트를 확인하세요."}, [12]={npc="하사관 울카", tgt="하사관 울카", tag="선택사항", desc="상사는 게임에서 이것을 제공합니다. 잠금 해제는 확인되지 않았습니다. 먼저 실종된 코르크론 - 적절한 장소, 잘못된 시간를 수행하세요."}, [13]={text="Alcaz Prison 입구"}, [14]={hint="알카즈 감옥에 진입해 사령관 폴카르를 찾아야 합니다.", desc="위치: 위쪽 홀을 타고 감방에서 지휘관 Folkar를 찾으세요.", spot="위쪽 홀을 타고 감방에서 지휘관 Folkar를 찾으세요."}, [15]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", spot="위층 복도의 감옥, Commander Folkar"}, [16]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", preText="오크를 구하라"}, [17]={hint="알카즈 감옥에 진입해 스트라샤즈 병사 15명과 스트라샤즈 요술사 8명을 처치하고 해일여제 카자스의 머리카락을 하사관 울카에게 가져가야 합니다.", tag="선택사항", desc="위치: 위쪽 셀로 해일여제 카자스를 찾으세요. 홀을 따라 나가를 정리하세요.", spot="위쪽 셀로 해일여제 카자스를 찾으세요. 홀을 따라 나가를 정리하세요."}, [18]={hint="알카즈 감옥에 진입해 인간 경비병에게서 핏빛 붉은 복면 8개를 입수해야 합니다.", tag="선택사항", desc="또 다른 실행이 필요할 수도 있습니다. 던전을 떠나기 전에 카운트를 확인하세요. 위치: 모든 방울을 얻을 때까지 위쪽 감옥 홀을 따라 인간 경비원을 죽이십시오.", spot="모든 방울을 얻을 때까지 위쪽 감옥 홀을 따라 인간 경비원을 죽이십시오."}, [19]={hint="Look for King Varian Wrynn in Alcaz Prison.", desc="위치: 아래쪽 문을 열고 마지막 보스를 처치하세요. 숨겨진 방에서 메모를 찾으세요. 순서: 먼저 소장에게서 열쇠를 받으세요.", spot="아래쪽 문을 열고 마지막 보스를 처치하세요. 숨겨진 방에서 메모를 찾으세요."}, [20]={npc="퀘스트 물체", npcObj=true, tag="게임 내 확인이 필요합니다", spot="블레이즈로어 뒤 비밀 방 바닥의 쪽지"}, [21]={npc="퀘스트 물체", npcObj=true, tag="게임 내 확인이 필요합니다", preText="The Honor of the Kor'kron"}, [22]={hint="Report back to Commander Folkar.", desc="위치: 마지막 보스의 숨겨진 방에서 위쪽 감방에 있는 사령관에게로 돌아갑니다. 순서: 먼저 18단계의 메모를 읽어보세요.", spot="마지막 보스의 숨겨진 방에서 위쪽 감방에 있는 사령관에게로 돌아갑니다."}, [23]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", spot="위층 복도의 감옥, Commander Folkar"}, [24]={npc="Commander Folkar", tag="게임 내 확인이 필요합니다", preText="Bad News for Folkar"}, [25]={npc="하사관 울카", tgt="하사관 울카", tag="선택사항"}, [26]={hint="Bring word of Varian Wrynn's fate to Thrall in Orgrimmar."}, [27]={npc="스랄", tgt="스랄"}, [28]={npc="아이트리그", tgt="아이트리그", tag="선택사항"}}},
    ["04-35"] = {name="동부 내륙지", nameA="동부 내륙지: {a:3317} & {a:354}", shortA="동부 내륙지: {a:3317} +", tips={{k="取捨", text="거북이 퀘스트와 같은 해변에서 위스키 슬림의 잃어버린 술병를 하세요. 포악한 올빼미야수 사냥와 단지 실험의 올빼미야수를 함께 처치하세요."}, {k="取捨", text="퀘스트 구인광고: 레반터스크 마을의 경비대장에는 80명의 엘리트 처치가 필요합니다. 그룹이 없으면 건너뛰세요. 진타알로가 솔로하기 너무 어렵다면 해안과 내륙 퀘스트를 먼저 수행하세요."}, {k="取捨", text="무법항에서 위스키 슬림의 잃어버린 술병를, 모자케 야영지에서 단지 실험를 제출하세요. 가젯잔 및 무너진 기둥 다리에 대해 스프링클의 비밀 재료 및 고대의 알를 저장합니다."}, {k="提醒", text="레벨 52 이하인가요? 동부 내륙지에서 거북이나 올빼미야수를 사냥하거나 그룹으로 진타알로를 클리어하세요.", s={{"레벨 52 이하인가요?"}, {"동부 내륙지에서 거북이나 올빼미야수를 사냥하거나 그룹으로 진타알로를 클리어하세요"}}}}, danger={[1]="엘리트 Vilebranch 트롤과 힐러는 상위 진타알로를 포장합니다. 그룹별로 한 티어씩 클리어하세요. 혼자라면 해안에 붙어라.", [2]="감메리타는 해안을 순찰하는 엘리트 거북이입니다. 일반 거북이를 갈아주는 동안 그녀를 지켜보고 혼자라면 그녀에게 공간을 제공하십시오."}, grind={[1]={mob="무쇠턱바다거북", note="레반터스크 마을 북쪽 해변의 일반 거북이. 해안을 따라가며 껍질을 벗기고 거북이 고기를 찾는 사람들과 해변을 공유하세요. 진타알로 엘리트를 건너뛰세요."}}, supply={[1]={npc="고르카스"}, [2]={npc="라드"}, [3]={npc="대장장이 슬래그트리"}, [4]={npc="라드"}, [5]={npc="레나즈"}, [6]={npc="비술사 야요진"}}, steps={[1]={text="이글거리는 협곡에서 레반터스크 마을로 비행합니다. 잠겨 있으면 타렌 밀농장로 날아가서 던홀드 요새 북쪽 패스를 사용하세요. 동쪽으로 Hinterlands 도로를 따라 간 다음 해안을 따라 남쪽으로 가세요.", tag="아직 비행 경로를 열지 않았습니다. 처음에는 걸어서 이동하세요."}, [2]={nodeA="{a:3317}", desc="잠금 해제 비행 지점 및 고르카스."}, [3]={text="이 다리에서는 귀환석를 레반터스크 마을에 바인딩할 수 있습니다."}, [4]={text="레반터스크 마을에서 수락 → 해안"}, [5]={npc="낚시꾼 카툼", tgt="낚시꾼 카툼"}, [6]={npc="낚시꾼 카툼", tgt="낚시꾼 카툼"}, [7]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [8]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [9]={npc="라드", tgt="라드"}, [10]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [11]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크"}, [12]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크"}, [13]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르", tag="선택사항", desc="희귀한 칼부리 그리폰을 발견한 경우에만 수행하세요."}, [14]={npc="대장장이 슬래그트리", tgt="대장장이 슬래그트리", tag="선택사항", desc="북동쪽에 있는 사원으로 우회하세요."}, [15]={npc="전장으로!", npcObj=true, tag="선택사항", desc="진타알로의 상부 테라스에서 엘리트 그룹을 구성하세요."}, [16]={npc="전장으로!", npcObj=true, tag="선택사항", desc="진타알로에서 엘리트 80명을 처치하려는 경우에만 선택하세요.", star={"수호대장의 룬", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [17]={hint="무쇠턱바다거북 15마리를 처치하고 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다."}, [18]={hint="감메리타를 처치하고 카툼의 최고급 미끼를 되찾아 동부 내륙지의 레반터스크 마을에 있는 낚시꾼 카툼에게 돌아가야 합니다.", desc="무쇠턱바다거북 처치 및 위스키 슬림의 잃어버린 술병을 사용하십시오. 목표물을 발견하면 죽이십시오."}, [19]={hint="무법항에 있는 위스키 슬림이 잃어버린 퍼플리버보스 포트 와인을 찾아 달라고 부탁했습니다.", desc="스토나드 / 샛바람 해안 정류장에서 수락하세요. 병을 찾으려면 해변 북쪽으로 가세요."}, [20]={hint="동부 내륙지의 레반터스크 마을에 있는 라드에게 라드의 점심을 가져가야 합니<name>."}, [21]={hint="수수께끼를 풀어야 합니다.", tag="선택사항", desc="코르텔로의 수수께끼가 켜져 있고 코르텔로의 수수께끼가 활성화되어 있어야 합니다. 다리 아래 스크롤에서 코르텔로의 수수께끼를 켜세요."}, [22]={npc="코르텔로의 보물", npcObj=true, tag="선택사항", desc="퀘스트 목록에 코르텔로의 수수께끼가 없으면 건너뛰세요."}, [23]={text="내륙 야생야수 및 은빛갈기 → 진타알로 제단"}, [24]={hint="긴발톱 은빛갈기늑대 15마리와 긴울음 은빛갈기늑대 15마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다."}, [25]={hint="포악한 올빼미야수 20마리를 처치한 후 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 돌아가야 합니다."}, [26]={hint="동부 내륙지로 가서 올빼미야수를 찾아 10마리를 처치하고 뮤세크 단지를 사용해 죽은 올빼미야수를 갈무리해서 담아와야 합니다.", desc="모자케 야영지 / 무쇠설인 소굴 다리를 선택하세요. 나중에 페랄라스를 제출하세요."}, [27]={hint="우두머리 뾰족부리그리핀 한 마리를 처치하고 그 우두머리 그리핀의 깃털을 동부 내륙지의 레반터스크 마을에 있는 사냥꾼 마코르에게 가져가야 합니다.", tag="선택사항", desc="보이면 죽여라."}, [28]={hint="동부 내륙지의 레반터스크 마을에 있는 대장장이 슬래그트리에게 슬래그트리의 잃어버린 연장을 찾아 되찾아줘야 합니다.", tag="선택사항"}, [29]={hint="가젯잔에 있는 스프링클이 제비수염버섯을 하나 구해 가지고 올 것을 부탁했습니다.", desc="첫 번째 가젯잔/Dunemaul 방문 시 수락하세요. 가젯잔에서 반납하세요."}, [30]={hint="진타알로에서 얼룩진 피가 담긴 용기 10개를 찾아 동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크에게 돌아가야 합니<name>.", desc="장로 쏜터스크의 퀘스트와 함께 수행하세요. 계단에서 순찰을 조심하세요."}, [31]={hint="레반터스크 마을의 사냥꾼 마코르에게 쌍둥이 동생인 말코르의 해골을 찾아서 가져가야 합니<name>.", desc="두 아이템을 모두 약탈하세요. 그들은 서로 다른 장소에 있습니다."}, [32]={hint="동부 내륙지에 있는 레반터스크 마을의 주술사 쏜터스크가 그녀의 남편인 장로 쏜터스크를 진타알로에서 구해 달라고 부탁했습니<name>."}, [33]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [34]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [35]={hint="수호자 히타야를 죽이고 족쇄 열쇠를 찾아서 진타알로에 갇혀 있는 장로 쏜터스크에게 돌아가야 합니다."}, [36]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [37]={npc="장로 쏜터스크", tgt="장로 쏜터스크"}, [38]={hint="고대의 알을 타나리스에 있는 예킨야에게 가져다주어야 합니다.", tag="선택사항", desc="Dunemaul 정류장에서 수락되면 수행하십시오. 스팀휘들 항구에서 반납하세요."}, [39]={hint="타락한 여사제 헥스와 썩은가지부족 아만자시 경비병 20명을 해치운 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크와 대화해야 합니<name>.", tag="선택사항"}, [40]={hint="썩은가지부족 광전사 20명, 썩은가지부족 어둠사냥꾼 20명, 썩은가지부족 혈투사 20명, 썩은가지부족 영혼사냥꾼 20명을 처치한 후, 동부 내륙지의 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가야 합니<name>.", tag="선택사항"}, [41]={text="귀환석를 사용하여 레반터스크 마을로 돌아가서 모든 퀘스트를 완료하세요."}, [42]={hint="장로 쏜터스크가 레반터스크 마을에 있는 주술사 쏜터스크에게 돌아가서 자신이 진타알로에서 풀려났다는 사실을 전해 달라고 부탁했습니다."}, [43]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크"}, [44]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [45]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크"}, [46]={npc="낚시꾼 카툼", tgt="낚시꾼 카툼"}, [47]={npc="낚시꾼 카툼", tgt="낚시꾼 카툼"}, [48]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [49]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르"}, [50]={npc="라드", tgt="라드"}, [51]={npc="사냥꾼 마코르", tgt="사냥꾼 마코르", tag="선택사항"}, [52]={npc="대장장이 슬래그트리", tgt="대장장이 슬래그트리", tag="선택사항"}, [53]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크", tag="선택사항"}, [54]={npc="주술사 쏜터스크", tgt="주술사 쏜터스크", tag="선택사항", star={"수호대장의 룬", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [55]={npc="크리스토프 워커", tgt="크리스토프 워커", tag="선택사항", desc="동부 내륙지 이전 언더시티의 크리스토프 워커에서 수락하세요. 저주받은 땅를 제출하세요."}, [56]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="AH에서 4가지 재료를 구매하세요. 타렌 밀농장에서 북쪽으로 원소에 대한 깨달음을 타고 Bath'rah까지 가세요."}, [57]={hint="바람의감시자 바스라에게 바람, 불, 대지, 물의 원소를 가져가야 합니다.", tag="선택사항", desc="AH에서 4가지 재료를 구매하세요. 타렌 밀농장에서 북쪽으로 원소에 대한 깨달음을 타고 Bath'rah까지 가세요."}, [58]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="AH에서 4가지 재료를 구매하세요. 타렌 밀농장에서 북쪽으로 원소에 대한 깨달음을 타고 Bath'rah까지 가세요."}, [59]={npc="바람의감시자 바스라", tgt="바람의감시자 바스라", tag="선택사항", desc="원소에 대한 깨달음 또는 원소에 대한 깨달음을 수행합니다. 서부 역병지대에서 재료를 수집합니다."}, [60]={npc="마일즈 덱스터", tgt="마일즈 덱스터", tag="선택사항", desc="첫 번째 동부 내륙 여행에서 언더시티의 도적 지구를 수락하세요."}, [61]={hint="라벤홀트 장원에 있는 조라크 라벤홀트 경과 대화해야 합니다.", tag="선택사항", desc="첫 번째 동부 내륙 여행에서 언더시티의 도적 지구를 수락하세요."}, [62]={npc="조라크 라벤홀트 경", tgt="조라크 라벤홀트 경", tag="선택사항", desc="첫 번째 동부 내륙 여행에서 언더시티의 도적 지구를 수락하세요."}, [63]={npc="조라크 라벤홀트 경", tgt="조라크 라벤홀트 경", tag="선택사항", desc="라벤홀트 장원에서 수락하세요. 아즈샤라용으로 저장하세요."}}},
    ["04-36"] = {name="저주받은 땅", tips={{k="取捨", text="수집 퀘스트 5개를 모두 함께 수행하세요. 턱살 5개, 멧돼지 폐 6개, 집게발 6개, 바실리스크 뇌 11개, 독수리 모래주머니 14개를 가져오세요. 턴인할 때마다 재료가 소모됩니다."}, {k="取捨", text="더 빠른 드롭이 있는 퀘스트를 먼저 제출하세요. 독수리나 바실리스크가 경쟁하는 경우 미완성 바실리스크의 내장 또는 독수리의 면역력를 저장하고 무법항로 이동하세요."}, {k="提醒", text="경험치가 필요하십니까? 북쪽 경사면에서 짐승을 갈아라(46~53, 15~27). 더 높은 레벨의 몹은 더 남쪽에 있습니다.", s={{"경험치가 필요하십니까?"}, {"북쪽 경사면에서 짐승을 갈아라(46~53, 15~27)"}, {"더 높은 레벨의 몹은 더 남쪽에 있습니다"}}}}, danger={[1]="혈법사 캠프 남쪽의 몹은 북쪽 경사면에 있는 몹보다 레벨이 더 높습니다. 북부 컬렉션 퀘스트를 위해 외부 경사면을 고수하세요."}, grind={[1]={mob="스콜포크 독침전갈", note="혈법사 캠프 동쪽의 일반 전갈입니다. 집게발을 모아 껍질을 벗기세요. 혼잡할 때는 도로에서 벗어나 엘리트 순찰대를 조심하세요."}}, supply={[1]={npc="브레이크"}, [2]={npc="여관주인 카라쿨"}, [3]={npc="가라쉬"}, [4]={npc="툴타쉬"}, [5]={npc="툴타조르"}}, steps={[1]={text="레반터스크 마을에서 스토나드까지 비행한 후 남쪽으로 도로를 따라 저주받은 땅로 들어갑니다. 북쪽에 있는 두 명의 혈법사(50.55, 14.20 및 50.64, 14.30)를 방문하세요."}, [2]={npc="혈법사 드라지알", tgt="혈법사 드라지알"}, [3]={npc="혈법사 드라지알", tgt="혈법사 드라지알"}, [4]={npc="혈법사 드라지알", tgt="혈법사 드라지알"}, [5]={npc="혈법사 린노어", tgt="혈법사 린노어"}, [6]={npc="혈법사 린노어", tgt="혈법사 린노어"}, [7]={hint="혈법사 드라지알에게 칼송곳니하이에나 턱 3개, 손상된 멧돼지 허파 2개, 스콜포크 집게발 1개를 가져가야 합니다."}, [8]={hint="혈법사 드라지알에게 손상된 멧돼지 허파 3개, 스콜포크 집게발 2개, 바실리스크 뇌 1개를 가져다주어야 합니다."}, [9]={hint="혈법사 드라지알에게 스콜포크 집게발 3개, 독수리 모래주머니 2개, 손상된 멧돼지 허파 1개를 가져가야 합니다."}, [10]={hint="혈법사 린노어에게 바실리스크 뇌 10개와 독수리 모래주머니 2개를 가져가야 합니다."}, [11]={hint="혈법사 린노어에게 독수리 모래주머니 10개와 칼송곳니하이에나 턱 2개를 가져가야 합니다."}, [12]={npc="혈법사 드라지알", tgt="혈법사 드라지알"}, [13]={npc="혈법사 드라지알", tgt="혈법사 드라지알"}, [14]={npc="혈법사 드라지알", tgt="혈법사 드라지알"}, [15]={npc="혈법사 린노어", tgt="혈법사 린노어"}, [16]={npc="혈법사 린노어", tgt="혈법사 린노어"}, [17]={npc="수집가 굼이샤", tgt="수집가 굼이샤", tag="선택사항", desc="아이템이 드롭되지 않으면 건너뛰세요."}, [18]={hint="저주받은 땅을 돌아다니다가 완전무결한 드레니시스트 구슬을 발견하면 수집가 굼이샤에게 가져가야 합니다.", tag="선택사항", desc="아이템이 드롭되지 않으면 건너뛰세요."}, [19]={npc="수집가 굼이샤", tgt="수집가 굼이샤", tag="선택사항", desc="아이템이 드롭되지 않으면 건너뛰세요."}, [20]={npc="수집가 굼이샤", tgt="수집가 굼이샤", tag="선택사항", desc="아이템이 드롭되지 않으면 건너뛰세요."}, [21]={hint="굼이샤에게 불완전한 드레니시스트 조각을 가져다주고 각 파편에 대해 보상을 받으십시오.", tag="선택사항", desc="아이템이 드롭되지 않으면 건너뛰세요."}, [22]={npc="수집가 굼이샤", tgt="수집가 굼이샤", tag="선택사항", desc="아이템이 드롭되지 않으면 건너뛰세요."}, [23]={hint="저주받은 땅의 입구에 있는 호드 영웅의 넋과 대화해야 합니다.", tag="선택사항"}, [24]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항"}, [25]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항", desc="Blood 마법사의 멧돼지 폐 퀘스트와 짝을 이루세요. 북쪽에 있는 두 목표물을 모두 처치하세요."}, [26]={hint="저주받은 땅에 있는 지옥멧돼지 7마리를 처치하고 호드 영웅의 넋에게 돌아가야 합니다.", tag="선택사항", desc="Blood 마법사의 멧돼지 폐 퀘스트와 짝을 이루세요. 북쪽에 있는 두 목표물을 모두 처치하세요."}, [27]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항", desc="Blood 마법사의 멧돼지 폐 퀘스트와 짝을 이루세요. 북쪽에 있는 두 목표물을 모두 처치하세요."}, [28]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항", desc="캠프 가장자리에서 몹을 한 번에 하나씩 끌어당깁니다."}, [29]={hint="저주받은 땅에서 어둠의혈맹 숙련사제, 이교도, 암살단원을 각 20명씩 해치우고 호드 영웅의 넋에게 돌아가야 합니다.", tag="선택사항", desc="캠프 가장자리에서 몹을 한 번에 하나씩 끌어당깁니다."}, [30]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항", desc="캠프 가장자리에서 몹을 한 번에 하나씩 끌어당깁니다."}, [31]={npc="호드 영웅의 넋", tgt="호드 영웅의 넋", tag="선택사항", desc="지금 그룹으로 진행하거나 동부 왕국 여행을 위해 희망의 빛 예배당로 절약하세요.", star={"다이아몬드 물통", {"WARRIOR"}}}, [32]={text="스토나드로 가는 경로를 되돌아가서 무법항로 비행하세요."}}},
    ["04-37"] = {name="가시덤불 골짜기 (재방문)", nameA="가시덤불 골짜기: {a:35} (재방문)", tips={{k="取捨", text="50레벨 퀘스트 위스키 슬림의 잃어버린 술병를 먼저 제출하세요. 낮은 레벨의 가시덤불 퀘스트는 이전 방문으로 나누어졌습니다. 완료되면 로그에 있는 스틸을 모두 제출하세요."}, {k="取捨", text="Hinterlands 그로그 또는 완료된 퀘스트가 없나요? 그냥 보트를 타세요. 선장의 상자 및 가시덤불 골짜기의 열병 는 마을 밖에서 왕복 여행이 필요합니다. 추가 경험치 또는 그룹을 위해 저장하세요."}, {k="提醒", text="무법항는 중립 포트입니다. 여객선을 타고 톱니항로 이동하여 올바른 페리에 탑승했는지 확인하세요.", s={{"무법항는 중립 포트입니다"}, {"여객선을 타고 톱니항로 이동하여 올바른 페리에 탑승했는지 확인하세요"}}}}, grind={[1]={mob="블러드 엘프 수색꾼", note="무법항에서 퀘스트를 완료하고 배를 타세요. 53레벨 미만이면 아즈샤라에서 일반 블러드 엘프를 처치하세요. 퀘스트 중인 플레이어가 있다면 야영지 외곽에서 적을 유인하세요."}}, supply={[1]={npc="그링거"}, [2]={npc="여관주인 스킨들"}, [3]={npc="주타크"}, [4]={npc="닉스락스 필라머그"}, [5]={npc="하렌 칸메"}}, steps={[1]={npc="위스키 슬림", tgt="위스키 슬림", desc="스토나드 / 샛바람 해안 정류장에서 수락하세요. 동부 내륙지에서 그로그를 수집하세요."}, [2]={npc="선장 허클베리 스모츠", tgt="선장 허클베리 스모츠", tag="선택사항", desc="선택적인 레벨 47 퀘스트. 경험치가 필요하지만 아직 수행하지 않은 경우 수락하세요."}, [3]={npc="핀 피즈라켓", tgt="핀 피즈라켓", tag="선택사항", desc="먼저 그룹화하세요. 여러 파도의 고릴라가 공격합니다."}, [4]={hint="무법항에 있는 허클베리 스모츠에게 스모츠의 상자를 가져가야 합니다.", tag="선택사항"}, [5]={npc="의술사 운바그와", tgt="의술사 운바그와", tag="선택사항", desc="이벤트를 트리거하기 위해 엄니를 반납하기 전에 가시덤불 골짜기의 열병를 수락하세요."}, [6]={hint="획득처: 안개계곡고릴라, 천둥고릴라, 광포한 은빛털고릴라", tag="선택사항", desc="이벤트를 트리거하기 위해 엄니를 반납하기 전에 가시덤불 골짜기의 열병를 수락하세요."}, [7]={npc="의술사 운바그와", tgt="의술사 운바그와", tag="선택사항", desc="이벤트를 트리거하기 위해 엄니를 반납하기 전에 가시덤불 골짜기의 열병를 수락하세요."}, [8]={hint="의술사 운바그와를 찾아 흉포한 모크를 불러내도록 해야 합니다. 핀 피즈라켓에게 모크의 심장을 가져가야 합니다.", tag="선택사항", desc="가시덤불 골짜기의 열병의 엄니 반납 이벤트 중에 생성됩니다."}, [9]={npc="선장 허클베리 스모츠", tgt="선장 허클베리 스모츠", tag="선택사항"}, [10]={npc="핀 피즈라켓", tgt="핀 피즈라켓", tag="선택사항"}, [11]={text="보트를 타고 톱니항로 가서 오그리마로 날아갑니다. 아즈샤라의 발로르모크로 향하기 전에 Belgrom에서 배신를 선택할 수 있습니다."}}},
    ["04-38"] = {name="아즈샤라: 아르코록 사원", nameA="아즈샤라: {a:1237} & 아르코록 사원", shortA="아즈샤라: {a:1237} +", tips={{k="取捨", text="하나의 루프에서 탈라시안 주둔지, 세 개의 표시 및 Rimtori를 수행하십시오. 엘다라스 폐허에서 4개의 정제와 나가 룬을 모두 수집하세요."}, {k="取捨", text="영상에서는 두 개의 그룹 퀘스트를 건너뜁니다. Forever는 Ley of the Land와 Deadliest Catch를 엘리트 후보로 나열합니다. 이번 방문에서는 두 가지를 모두 건너뛰세요."}, {k="取捨", text="희망의 빛 예배당 전송 중에 언더시티(54.81, 76.33)에서 안드론 건트에게 전달를 안드론 건트로 전환합니다. 아즈샤라로 돌아가는 후속 조치를 건너뛰세요."}, {k="提醒", text="레벨 53 이하인가요? 퀘스트 드롭을 찾는 동안 엘다라스 폐허에서 나가를 연마하거나 탈라시안 주둔지에서 블러드 엘프를 연마하세요.", s={{"레벨 53 이하인가요?"}, {"퀘스트 드롭을 찾는 동안 엘다라스 폐허에서 나가를 연마하거나 탈라시안 주둔지에서 블러드 엘프를 연마하세요"}}}}, danger={[1]="나가 캐스터는 내부 엘다라스 폐허를 포장합니다. 정제를 모으는 동안 외벽을 껴안으세요. 주문 방해 캐스터를 꺼내서 방 밖으로 꺼냅니다."}, grind={[1]={mob="블러드 엘프 수색꾼", note="탈라시안 주둔지의 일반 블러드 엘프는 경험치 및 퀘스트 드랍에 적합한 레벨입니다. 캐스터가 내부에 연결되지 않도록 가장자리를 따라 당깁니다."}, [2]={mob="원한의꼬리일족 미르미돈", note="엘다라스 폐허의 일반 나가. 나가 퀘스트와 짝을 이루세요. 외벽을 따라 한 번에 한 명의 적을 끌어당기고 내부에 밀집된 캐스터 무리를 피하세요."}}, supply={[1]={npc="크로움"}, [2]={npc="그룰 다크블레이드"}, [3]={npc="쿠를"}, [4]={npc="여관주인 그리쉬카"}, [5]={npc="카자"}, [6]={npc="호르투스"}}, steps={[1]={npc="벨그롬 록마울", tgt="벨그롬 록마울", desc="오그리마의 명예의 골짜기를 수락합니다. 업데이트된 배신 체인을 시작합니다."}, [2]={npc="제스리몬", tgt="제스리몬", tag="선택사항", desc="선택사항. 지금 획득한 다음 운고로에서 라바사우루스를 처치하세요."}, [3]={text="아즈샤라 비행 지점를 잠금 해제한 경우 오그리마에서 발로르모크로 비행하세요. 첫 번째 방문에서는 토막나무 주둔지 에서 동쪽으로 달리고 로아투 에 정차한 다음 발로르모크 로 계속 이동하세요.", tag="아직 비행 경로를 열지 않았습니다. 처음에는 걸어서 이동하세요."}, [4]={text="서쪽의 로아투 → 발로르모크에서 수락"}, [5]={npc="로아투", tgt="로아투"}, [6]={npc="로아투", tgt="로아투"}, [7]={hint="명가의 유령 6명과 명가의 망령 6명을 처치한 후 아즈샤라에 있는 로아투에게 돌아가십시오."}, [8]={hint="할<name>르 사티로스 6명, 할<name>르 요술사 2명, 할<name>르 악마추종자 2명을 처치한 후 잿빛 골짜기 경계에 있는 로아투에게 돌아가십시오."}, [9]={npc="로아투", tgt="로아투"}, [10]={npc="로아투", tgt="로아투"}, [11]={nodeA="{a:1237}", desc="잠금 해제 비행 지점 및 크로움."}, [12]={hint="아즈샤라에 있는 아그토르 블러드피스트에게 아그토르에게 보내는 봉인된 편지를 전해야 합니다."}, [13]={npc="아그토르 블러드피스트", tgt="아그토르 블러드피스트"}, [14]={npc="아그토르 블러드피스트", tgt="아그토르 블러드피스트"}, [15]={npc="제디가", tgt="제디가"}, [16]={text="탈라시안 주둔지 → 사원 및 엘다라스 폐허 → 발로르모크"}, [17]={npc="킴야엘", tgt="킴야엘"}, [18]={hint="탈라시안 주둔지에서 킴야엘의 나침반, 망원경, 박제한 닭, 그리고 땅콩까개를 찾은 후, 아즈샤라에 있는 킴야엘에게 돌려주어야 합니다."}, [19]={npc="킴야엘", tgt="킴야엘"}, [20]={npc="킴야엘", tgt="킴야엘"}, [21]={hint="블러드 엘프 수색꾼 10명과 블러드 엘프 감정관 10명을 처치한 후, 학자 림토리의 야영지를 찾아내십시오. 야영지를 찾으면 그녀를 싸움으로 유인하는데 사용할 수 있을 만한 것을 찾아보십시오. 림토리가 중요하게 여기는 것이라야 합니다.", desc="정확한 수량은 퀘스트 목록을 기준으로 하세요."}, [22]={npc="나이트 엘프 소환의 고서", npcObj=true, tag="게임 내 확인이 필요합니다"}, [23]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="게임 내 확인이 필요합니다", desc="포에버의 배신 체인입니다. 먼저 를 완료한 후 각 인장을 하나씩 수집하세요."}, [24]={hint="획득처: Lieutenant Suncrest, 대학자 호크헬름, Ranger Lydrea", tag="대상: 선크레스트 중위 / 대학자 호크헬름 / 순찰자 리드레아 / 스카이본 Test, 게임 내 확인이 필요합니다", desc="포에버의 배신 체인입니다. 먼저 를 완료한 후 각 인장을 하나씩 수집하세요."}, [25]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="게임 내 확인이 필요합니다", desc="포에버의 배신 체인입니다. 먼저 를 완료한 후 각 인장을 하나씩 수집하세요."}, [26]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="게임 내 확인이 필요합니다"}, [27]={hint="획득처: 학자 림토리", tag="게임 내 확인이 필요합니다"}, [28]={hint="엘다라스 폐허에서 나가들이 가지고 있는 어떤 룬을 찾아 아즈샤라에 있는 킴야엘에게 가져가야 합니다."}, [29]={hint="베스아마라 서판, 진야엘 서판, 마크리 서판, 샤엘하이 서판을 찾아 아즈샤라에 있는 제디가에게 돌아가야 합니다."}, [30]={npc="킴야엘", tgt="킴야엘"}, [31]={npc="제디가", tgt="제디가"}, [32]={npc="아그토르 블러드피스트", tgt="아그토르 블러드피스트", tag="게임 내 확인이 필요합니다"}, [33]={npc="아그토르 블러드피스트", tgt="아그토르 블러드피스트", tag="게임 내 확인이 필요합니다"}, [34]={npc="제디가", tgt="제디가", tag="선택사항", desc="다음 정류장 전에 썬더 블러프를 통과하면 진입하세요."}, [35]={npc="제디가", tgt="제디가", tag="선택사항", desc="오그리마에 대한 이번 방문을 켜십시오."}, [36]={npc="제디가", tgt="제디가", tag="선택사항", desc="다음에 언더시티를 통과할 때까지 반납을 저장합니다."}, [37]={text="헤드 및 태블릿 퀘스트를 완료하려면 발로르모크에서 오그리마로 비행하세요. 썬더 블러프 태블릿 턴인은 또 다른 비행을 펼칩니다."}, [38]={hint="Bring the Head of Magus Rimtori to Belgrom Rockmaul in Orgrimmar.", tag="게임 내 확인이 필요합니다"}, [39]={npc="벨그롬 록마울", tgt="벨그롬 록마울", tag="게임 내 확인이 필요합니다"}, [40]={hint="오그리마에 있는 제스리몬에게 진야엘 서판을 가져가야 합니다.", tag="선택사항"}, [41]={npc="제스리몬", tgt="제스리몬", tag="선택사항"}, [42]={npc="질지빈 드럼로