    ["05-d29"] = {name="혈투의 전장: 서쪽", entrance="페랄라스 (1444), 60.30, 30.20. 안뜰 서쪽에 있는 포털.", pickup="모자케 야영지에서 현자 코로루스크를 방문하고 레벨 54에서 엘프의 전설를 선택하세요. 캠프로 날아가서 서쪽의 주요 도로를 따라가세요. 누군가 초승달 열쇠를 가지고 있는지 확인하거나 동쪽 날개를 먼저 실행하십시오.", pickupS={{"모자케 야영지에서 현자 코로루스크를 방문하고 레벨 54에서 엘프의 전설를 선택하세요"}, {"캠프로 날아가서 서쪽의 주요 도로를 따라가세요"}, {"누군가 초승달 열쇠를 가지고 있는지 확인하거나 동쪽 날개를 먼저 실행하십시오"}}, tips={{k="動線", text="서쪽 문 → 정원 철탑 제거 → 굽이나무 텐드리스 → 위층 고대를 보고 남은 철탑 제거, Kalendris 및 Illyanna 선택 사항 → 감옥의 이몰타르 → 도서관의 왕자 토르텔드린. 고대로 돌아온 다음 도서관로 돌아가서 상자와 유적을 찾으세요."}, {k="取捨", text="한 번에 엘프의 전설, 내면의 광기 및 셴드랄라의 보물 를 수행하세요. 장비 실행을 위해 마법 재료와 더 긴 다중 던전 체인을 저장하세요."}, {k="說明", text="5인 던전. 동쪽 윙에 있는 푸실린에서 초승달 열쇠를 얻으세요. 이몰타르 앞에 있는 파일론 5개를 모두 제거하세요. 도서관 수업 도서에 대한 북쪽 날개 노트를 참조하세요.", s={{"5인 던전"}, {"동쪽 윙에 있는 푸실린에서 초승달 열쇠를 얻으세요"}, {"이몰타르 앞에 있는 파일론 5개를 모두 제거하세요"}, {"도서관 수업 도서에 대한 북쪽 날개 노트를 참조하세요"}}}, {k="提醒", text="5인 던전. 동쪽 윙에 있는 푸실린에서 초승달 열쇠를 얻으세요. 이몰타르 앞에 있는 파일론 5개를 모두 제거하세요. 도서관 수업 도서에 대한 북쪽 날개 노트를 참조하세요.", s={{"5인 던전"}, {"동쪽 윙에 있는 푸실린에서 초승달 열쇠를 얻으세요"}, {"이몰타르 앞에 있는 파일론 5개를 모두 제거하세요"}, {"도서관 수업 도서에 대한 북쪽 날개 노트를 참조하세요"}}}}, steps={[1]={npc="현자 코로루스크", tgt="현자 코로루스크", desc="모자케 야영지에서 수락하세요. 서쪽 또는 북쪽 지름길을 통해 도서관에 도달하세요."}, [2]={text="혈투의 전장: 서쪽 입구"}, [3]={npc="셴드랄라 고대인", tgt="셴드랄라 고대인", tag="게임 내 확인이 필요합니다", desc="먼저 혈투의 전장 West의 상위 레벨에 있는 셴드랄라 고대인와 대화하세요."}, [4]={hint="이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다.", desc="먼저 5개의 파일런을 모두 제거하세요. 위치: 5개의 철탑을 제거한 다음 잠긴 문을 통해 이몰타르와 Prince로 이동하세요. 순서: 5개의 철탑 → 이몰타르 → 도서관의 왕자.", spot="5개의 철탑을 제거한 다음 잠긴 문을 통해 이몰타르와 Prince로 이동하세요."}, [5]={npc="셴드랄라 고대인", tgt="셴드랄라 고대인", tag="게임 내 확인이 필요합니다", spot="도서관의 쉔드랄라 고대인"}, [6]={npc="셴드랄라 고대인", tgt="셴드랄라 고대인", tag="게임 내 확인이 필요합니다", desc="고대인에게 제출한 후 후속 조치를 수락하세요. 내면의 광기과 동일한 실행으로 수행하십시오.", preText="내면의 광기"}, [7]={hint="도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!", desc="위치: 이몰타르의 케이지에서 도서관로 이동합니다. 계단 아래에 상자가 있는지 확인하세요.", spot="이몰타르의 케이지에서 도서관로 이동합니다. 계단 아래에 상자가 있는지 확인하세요."}, [8]={npc="셴드랄라의 보물", npcObj=true, tag="게임 내 확인이 필요합니다", spot="도서관 계단 아래 쉔드랄라 보물 상자"}, [9]={hint="혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.", desc="위치: 케이지에서 도서관까지 홀을 따라가세요. 선반 옆에서 유해를 찾아보세요.", spot="케이지에서 도서관까지 홀을 따라가세요. 선반 옆에서 유해를 찾아보세요."}, [10]={npc="현자 코로루스크", tgt="현자 코로루스크"}}},
    ["05-d28"] = {name="혈투의 전장: 동쪽", entrance="페랄라스 (1444), 64.80, 30.20. 경기장 동쪽 벽을 따라 움푹 들어간 곳에 있는 포털입니다.", pickup="레벨 54에서 발로르모크 다리의 오그리마를 통과할 때 징집관 고를라취에서 를 가져옵니다. Talo로 돌아와서 모자케 야영지에서 레스텐드리스의 그물를 가져가세요. 모자케 야영지로 비행하여 라리스 정자에서 아즈토르딘를 방문하세요. 정화의 성물함의 경우 달의 숲에서 획득하고 마파람 마을에서 성물함을 수집한 다음 나이트헤이븐에서 반납하여 악령덩굴 조각을 잠금 해제하세요. 필요한 경우 나중에 실행할 수 있도록 해당 체인을 저장하세요.", pickupS={{"레벨 54에서 발로르모크 다리의 오그리마를 통과할 때 징집관 고를라취에서 를 가져옵니다"}, {"Talo로 돌아와서 모자케 야영지에서 레스텐드리스의 그물를 가져가세요"}, {"모자케 야영지로 비행하여 라리스 정자에서 아즈토르딘를 방문하세요"}, {"정화의 성물함의 경우 달의 숲에서 획득하고 마파람 마을에서 성물함을 수집한 다음 나이트헤이븐에서 반납하여 악령덩굴 조각을 잠금 해제하세요"}, {"필요한 경우 나중에 실행할 수 있도록 해당 체인을 저장하세요"}}, tips={{k="動線", text="입구에서 푸실린를 쫓아가서 마지막에 싸운다 → 옆길에서 레스텐드리스, 히드로스폰 → 사티로스 제단에서 제브림 쏜후프 → 칼날바람 알진. 서쪽 또는 북쪽에서 도서관에 들어가세요."}, {k="取捨", text="혈투의 전장 East에서 초승달 열쇠를 구입하세요. Talo와 푸실린의 퀘스트는 가장 빠르게 페어링됩니다. 악령덩굴 조각가 여전히 잠겨 있는 경우 성물함을 위해 두 구역을 건너지 마세요."}, {k="說明", text="5인 던전. 동쪽 출입구를 이용하세요. 보스런에서 푸실린를 건너뛰지 마세요. 서쪽과 북쪽 날개의 열쇠를 보관하세요.", s={{"5인 던전"}, {"동쪽 출입구를 이용하세요"}, {"보스런에서 푸실린를 건너뛰지 마세요"}, {"서쪽과 북쪽 날개의 열쇠를 보관하세요"}}}, {k="提醒", text="5인 던전. 동쪽 출입구를 이용하세요. 보스런에서 푸실린를 건너뛰지 마세요. 서쪽과 북쪽 날개의 열쇠를 보관하세요.", s={{"5인 던전"}, {"동쪽 출입구를 이용하세요"}, {"보스런에서 푸실린를 건너뛰지 마세요"}, {"서쪽과 북쪽 날개의 열쇠를 보관하세요"}}}}, steps={[1]={npc="징집관 고를라취", tgt="징집관 고를라취", desc="Thalo에서 직접 레스텐드리스의 그물를 가져가서 도시 시작 퀘스트를 건너뛰세요."}, [2]={hint="페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오."}, [3]={npc="탈로 쏜후프", tgt="탈로 쏜후프"}, [4]={npc="탈로 쏜후프", tgt="탈로 쏜후프", desc="호드 연합 퀘스트. 모자케 야영지 리드인은 선택 사항입니다."}, [5]={npc="아즈토르딘", tgt="아즈토르딘", desc="모자케 야영지 북쪽에서 라리스 정자를 찾습니다."}, [6]={npc="라빈 사투르나", tgt="라빈 사투르나", desc="52번, 56번, 59번 정류장에서 이미 주요 경로에 있습니다. 제출한 경우 건너뜁니다."}, [7]={hint="실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다."}, [8]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [9]={npc="라빈 사투르나", tgt="라빈 사투르나", desc="정화의 성물함를 가져오세요. 가 완료되지 않은 경우 다음 실행을 위해 저장하세요.", preText="정화의 성물함"}, [10]={text="혈투의 전장: 동쪽 입구"}, [11]={hint="혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다.", desc="푸실린을 쫓아가며 각 지점마다 말을 걸어 마지막까지 따라가세요. 위치: 동쪽 입구에 있는 푸실린에게 말을 걸어 끝까지 쫓아가세요. 순서: 전투를 시작하려면 각 정류장에서 그들과 대화하세요.", spot="동쪽 입구에 있는 푸실린에게 말을 걸어 끝까지 쫓아가세요."}, [12]={hint="페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.", desc="위치: 정원에서 레스텐드리스 플랫폼까지 위쪽 통로를 이용하세요.", spot="정원에서 레스텐드리스 플랫폼까지 위쪽 통로를 이용하세요."}, [13]={hint="혈투의 전장에서 악령덩굴 조각을 채취하십시오. 칼날바람 알진을 물리쳐야만 얻을 수 있을 것입니다. 정화의 성물함에 단단히 봉인한 후, 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다.", desc="악령덩굴 조각은 알진 근처에 있습니다. 위치: Alzzin으로 향하는 마지막 터널을 따라가세요. 그를 죽인 다음 파편을 약탈하고 봉인하세요.", spot="Alzzin으로 향하는 마지막 터널을 따라가세요. 그를 죽인 다음 파편을 약탈하고 봉인하세요."}, [14]={npc="현자 리드로스", tgt="현자 리드로스", tag="게임 내 확인이 필요합니다", desc="60시에 서쪽 또는 북쪽 방향으로 도서관를 타고 Lydros에서 수락한 다음 동쪽으로 이동합니다."}, [15]={hint="혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.", desc="위치: 혈투의 전장 East의 낮은 수로를 이용하세요. 수영장 옆에서 히드로스폰를 처치하세요.", spot="혈투의 전장 East의 낮은 수로를 이용하세요. 수영장 옆에서 히드로스폰를 처치하세요."}, [16]={npc="아즈토르딘", tgt="아즈토르딘"}, [17]={npc="탈로 쏜후프", tgt="탈로 쏜후프"}, [18]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [19]={npc="현자 리드로스", tgt="현자 리드로스", tag="게임 내 확인이 필요합니다", desc="도서관로 돌아가서 제출하면 음료 창조의 최고 등급을 배울 수 있습니다."}}},
    ["04-55"] = {name="운고로 분화구", tips={{k="交通", text="1단계와 11단계에서 가젯잔를 통과하고 도중에 기계설인를 사용하세요. 마지막 단계에서 북서쪽 경사면을 실리더스 로 가져갑니다."}, {k="取捨", text="얼음불꽃 온천에서 새로운 온천를, 눈망루 마을에서 깜짝 기계설인 대작전를 제출하세요. 강철나무 숲용 링쿠의 기억를 저장합니다."}, {k="取捨", text="계란을 집어 아직 제출할 수 있는 경우에만 고성능 자동부화기를 선택하세요. 그렇지 않으면 뒤로 돌아가지 마세요."}, {k="提醒", text="이 다리는 여전히 레벨 57~59용입니다. 경험치가 뒤처지면 불기둥 마루의 일반 정령이나 북쪽의 고릴라를 처치하세요. 아파트에서 데빌사우루스를 조심하세요.", s={{"이 다리는 여전히 레벨 57~59용입니다"}, {"경험치가 뒤처지면 불기둥 마루의 일반 정령이나 북쪽의 고릴라를 처치하세요"}, {"아파트에서 데빌사우루스를 조심하세요"}}}}, danger={[1]="레벨 54~56의 정예 데빌사우루스가 불기둥 마루 남쪽의 아파트를 순찰합니다. 링고 스타를 호위하기 전에 경로를 정찰하고 경사면에 충실하세요."}, grind={[1]={mob="살아있는 불길", note="불기둥 마루의 상위 레벨 일반 원소입니다. 화산 퀘스트와 짝을 이루세요. 경사면을 따라 차를 세우고 평원의 데빌사우루스 순찰을 피하세요."}, [2]={mob="우두머리 송진괴물", note="마샬의 야영지 근처의 일반 타르 몹. 경험치의 마지막 비트에 대해 몇 바퀴를 돌립니다. 수영장 가장자리에서 한 번에 한 명의 적을 끌어당깁니다."}}, supply={[1]={npc="그리페"}, [2]={npc="기버트"}, [3]={npc="네르갈"}, [4]={npc="네르갈"}, [5]={npc="여관주인 피즈그림블"}}, steps={[1]={text="먼저 가젯잔에서 묘지 퀘스트를 완료하세요. 기계설인 퀘스트를 진행 중인 경우 남쪽 도로로 이동하기 전에 마을에서 사용하세요."}, [2]={npc="자동부화기", npcObj=true, tag="선택사항", desc="페랄라스에서 공작날개 고원의 계란을 사용하세요. 이미 완료했다면 건너뛰세요."}, [3]={hint="사용/수집: 히포그리프 알", tag="선택사항"}, [4]={npc="자동부화기", npcObj=true, tag="선택사항"}, [5]={hint="가젯잔 밖에 있는 무덤으로 가서 앞날의 비약을 사용하십시오. 도노바의 지시에 따라 개리얀을 찾아야 합니다.", desc="마시기 그것은 당신을 죽입니다. 죽은 상태에서 대화를 나눈 후 묘지에서 부활하세요."}, [6]={npc="개리얀", tgt="개리얀"}, [7]={npc="개리얀", tgt="개리얀"}, [8]={hint="부활한 후, 개리얀이 말한 묘비를 찾아야 합니다."}, [9]={npc="눈에 띄는 묘비", npcObj=true}, [10]={npc="눈에 띄는 묘비", npcObj=true}, [11]={text="가젯잔(51.06, 26.87)의 스프링클에서 기계설인를 사용한 다음 운고로로 가는 남쪽 도로를 이용하세요."}, [12]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [13]={hint="운고로 분화구에 있는 동쪽 수정탑의 위치를 알아내야 합니다."}, [14]={hint="토르와의 주머니에 든 물건들로 라르코르위를 불러내 물리친 후 라르코르위의 머리를 운고로 분화구 입구에 있는 토르와 패스파인더에게 가져가야 합니다.", desc="토르와의 주머니를 열어보세요. 고기를 내려놓고 페로몬을 사용해 라르코르위를 유인합니다."}, [15]={hint="운고로 분화구 입구에 있는 토르와 패스파인더에게 운고로 고릴라 모피 2개, 운고로 우레고릴라 모피 2개, 운고로 천둥고릴라 모피 2개를 가져가야 합니<name>.", tag="대상: 운고로 고릴라 / 운고로 고릴라 / 운고로 우레고릴라 / 운고로 천둥고릴라"}, [16]={hint="운고로 분화구에 있는 북쪽 수정탑의 위치를 알아내야 합니다."}, [17]={hint="운고로 분화구에 있는 링쿠에게 링쿠의 명검을 가져가야 합니다."}, [18]={npc="링쿠", tgt="링쿠"}, [19]={npc="링쿠", tgt="링쿠"}, [20]={hint="마샬의 야영지에 있는 동굴에서 J.D. 콜리를 찾아야 합니다."}, [21]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [22]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [23]={npc="스프래글 프록", tgt="스프래글 프록"}, [24]={hint="우미의 기계설인을 가지고 가서 아래 친구들에게 겁을 주어야 합니다.", desc="처음 두 대상 이후에 퀵실의 예티를 사용하세요. 서리속삭임 골짜기에서 반납하세요."}, [25]={hint="운고로 분화구에 있는 서쪽 수정탑의 위치를 알아내야 합니다."}, [26]={npc="크래클", tgt="크래클"}, [27]={hint="운고로 분화구에 있는 크래클이 불기둥 마루에서 가장 뜨거운 자리를 찾도록 요청했습니다.", desc="반응이 계산될 때까지 기다리십시오. 용암에서 벗어나세요."}, [28]={hint="불기둥 마루에서 링고 스타를 찾아야 합니다."}, [29]={npc="링고 스타", tgt="링고 스타"}, [30]={npc="링고 스타", tgt="링고 스타", desc="호위하기 전에 동굴 입구를 정리하세요. 스프래글의 수통로 링고 스타를 깨워보세요."}, [31]={hint="마샬의 야영지에 있는 스프래글 프록에게 링고 스타를 데려다 주어야 합니다."}, [32]={npc="스프래글 프록", tgt="스프래글 프록"}, [33]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [34]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [35]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [36]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [37]={hint="잠시 기다린 후, J.D. 콜리와 대화해야 합니다."}, [38]={npc="J.D. 콜리", tgt="J.D. 콜리"}, [39]={npc="크래클", tgt="크래클"}, [40]={npc="크래클", tgt="크래클"}, [41]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [42]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [43]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [44]={hint="운고로 분화구 입구에 있는 토르와 패스파인더에게 우차의 모피를 가져가야 합니다.", desc="동굴 입구에 있는 고릴라를 처치하세요. 우차는 일반 몹입니다."}, [45]={npc="토르와 패스파인더", tgt="토르와 패스파인더"}, [46]={npc="토르와 패스파인더", tgt="토르와 패스파인더", tag="선택사항", desc="남동쪽 입구를 통해 Torwa로 진입하세요. 가죽 갑옷이나 지팡이를 선택하세요.", star={"불곰 모피 조끼", {"DRUID"}}}, [47]={text="운고로의 북서쪽 경사로를 사용하여 실리더스로 들어갑니다. 세나리온 요새로 가는 길을 따라가세요."}}},
    ["05-d31"] = {name="구체자의 정원", entrance="운고로 분화구 (동부 내륙지로), 48.10, 6.10. 티탄 구조를 표시합니다. 정확한 포털 코드를 알 수 없습니다.", pickup="달의 숲로 가는 길에 썬더 블러프를 지나 북서쪽 멀고어에 있는 마예나 어스시커에 들러보세요. 마샬의 야영지로 돌아가 북쪽의 돌계단을 타고 타이탄 구조물로 가세요. 나머지 두 퀘스트의 수락 NPC는 확인되지 않았습니다.", pickupS={{"달의 숲로 가는 길에 썬더 블러프를 지나 북서쪽 멀고어에 있는 마예나 어스시커에 들러보세요"}, {"마샬의 야영지로 돌아가 북쪽의 돌계단을 타고 타이탄 구조물로 가세요"}, {"나머지 두 퀘스트의 수락 NPC는 확인되지 않았습니다"}}, tips={{k="動線", text="입구 → 타이탄 유적지를 통해 4가지 크리스탈 색상 수집 → 무색 크리스탈로 수영장 목표 처리 타이탄 드래곤 쏜살, 비트릭스 및 나나야의 전체 주문은 아직 확인되지 않았습니다."}, {k="取捨", text="먼저 Crystalline Elements를 선택하세요. 캠프에 다른 퀘스트가 없다면 일행과 함께 입장하세요."}, {k="說明", text="Forever의 새로운 5인 던전. 마샬의 야영지 북쪽으로 오르막길로 가세요. 티탄 관문에서 운고로의 힘 수정을 사용하세요. 외부 입구 랜드마크는 48.10, 6.10 주변입니다. 정확한 포털 스팟은 확인되지 않았습니다.", s={{"Forever의 새로운 5인 던전"}, {"마샬의 야영지 북쪽으로 오르막길로 가세요"}, {"티탄 관문에서 운고로의 힘 수정을 사용하세요"}, {"외부 입구 랜드마크는 48.10, 6.10 주변입니다"}, {"정확한 포털 스팟은 확인되지 않았습니다"}}}, {k="提醒", text="Forever의 새로운 5인 던전. 마샬의 야영지 북쪽으로 오르막길로 가세요. 티탄 관문에서 운고로의 힘 수정을 사용하세요. 외부 입구 랜드마크는 48.10, 6.10 주변입니다. 정확한 포털 스팟은 확인되지 않았습니다.", s={{"Forever의 새로운 5인 던전"}, {"마샬의 야영지 북쪽으로 오르막길로 가세요"}, {"티탄 관문에서 운고로의 힘 수정을 사용하세요"}, {"외부 입구 랜드마크는 48.10, 6.10 주변입니다"}, {"정확한 포털 스팟은 확인되지 않았습니다"}}}}, steps={[1]={npc="마예나 어스시커", tgt="마예나 어스시커", desc="썬더 블러프에서 서쪽 절벽을 선택하세요. NPC는 플레이어 기록에서 나옵니다."}, [2]={npc="연금술사 퓰리", tgt="연금술사 퓰리", tag="게임 내 확인이 필요합니다"}, [3]={npc="수석 연금술사 파라넬", tgt="수석 연금술사 파라넬", tag="게임 내 확인이 필요합니다"}, [4]={text="구체자의 정원 입구"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", tag="게임 내 확인이 필요합니다", desc="위치: 타이탄 폐허를 따라가며 정령에게서 네 가지 크리스탈 색상을 모두 약탈하세요.", spot="타이탄 폐허를 따라가며 정령에게서 네 가지 크리스탈 색상을 모두 약탈하세요."}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", tag="게임 내 확인이 필요합니다", desc="위치: 안에서 스며드는 슬라임을 찾으세요. 정확한 수영장 위치는 확인되지 않았습니다.", spot="안에서 스며드는 슬라임을 찾으세요. 정확한 수영장 위치는 확인되지 않았습니다."}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="위치: 무색 수정 주변의 바닥에서 고갈된 조각을 찾아보세요.", spot="무색 수정 주변의 바닥에서 고갈된 조각을 찾아보세요."}, [8]={npc="마예나 어스시커"}, [9]={npc="연금술사 퓰리", tgt="연금술사 퓰리", tag="게임 내 확인이 필요합니다"}, [10]={tag="게임 내 확인이 필요합니다"}}},
    ["04-56"] = {name="실리더스", tips={{k="交通", text="1단계에서 잠금 해제 세나리온 요새 비행 지점를 수행합니다. 마지막 단계에서 제플린을 동부 왕국로 다시 가져갑니다."}, {k="取捨", text="달의 숲 턴인을 위해 정화의 성물함 및 기록관 움버를 저장합니다."}, {k="取捨", text="레벨링하는 경우 노글의 잃어버린 가방 및 현상수배: 사막의 난폭자 죽음의 갈고리를 건너뛰세요. 퀘스트 노글의 잃어버린 가방는 당신을 먼 남쪽으로 돌려보내고, 현상수배: 사막의 난폭자 죽음의 갈고리는 엘리트 처치가 필요합니다."}, {k="取捨", text="영상의 그늘날개 퀘스트(혐오스런 그늘날개)는 동부 역병지대 에 있습니다. 실리더스에서도 엘리트 그룹 퀘스트를 건너뜁니다."}, {k="提醒", text="레벨 59 이하라도 Bulwark로 향하세요. 먼저 갈기려면 세나리온 요새 북동쪽(약 55, 29) 또는 황혼 남서쪽(약 38, 44) 이교도를 죽이십시오.", s={{"레벨 59 이하라도 Bulwark로 향하세요"}, {"먼저 갈기려면 세나리온 요새 북동쪽(약 55, 29) 또는 황혼 남서쪽(약 38, 44) 이교도를 죽이십시오"}}}}, danger={[1]="마파람 마을 타워 꼭대기에 도달하면 실리시드 떼가 발동합니다. 탈출구를 확보하려면 먼저 탑과 계단을 정리하세요."}, grind={[1]={mob="황혼의 복수자", note="캠프 외부의 일반 황혼 이교도는 좋은 경험치이며 황혼 장비를 떨어뜨립니다. 이교도 퀘스트와 짝을 이루세요. 다른 사람이 농기구를 사용하고 있으면 가장자리에서 치우세요."}, [2]={mob="작살미늘벌레", note="세나리온 요새 북동쪽 공터에 있는 일반 몹은 레벨이 약간 낮지만 밀도가 높습니다. 황혼 캠프가 바쁜 경우 재료 수집 경로에 있는 농장."}}, supply={[1]={npc="룬크 윈드테이머"}, [2]={npc="캘랜드라스"}, [3]={npc="바르구스"}, [4]={npc="캘랜드라스"}, [5]={npc="캘랜드라스"}, [6]={npc="쿠르 혼스트라이커"}}, steps={[1]={nodeA="{a:3425}", desc="잠금 해제, 호드 연합 비행 지점, 룬크 윈드테이머, 세나리온 요새."}, [2]={text="귀환석를 용사의 안식처 이후에 사용하려면 여관(51.89, 39.16)에서 바인딩하세요."}, [3]={hint="실리더스의 세나리온 요새에 있는 바람소환사 프라우드혼과 대화해야 합니다."}, [4]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [5]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [6]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [7]={npc="지질학자 락스베인", tgt="지질학자 락스베인"}, [8]={npc="보르 와일드메인", tgt="보르 와일드메인"}, [9]={hint="실리더스에서 돌꼬리전갈 독침 8개와 모래그물 바위거미 송곳니 8개를 모은 후, 세나리온 요새에 있는 비틱스 픽클스프라그에게 돌아가야 합니다."}, [10]={hint="실리더스의 세나리온 요새에 있는 바람소환사 프라우드혼이 작살미늘벌레 15마리를 처치해 달라고 부탁했습니다."}, [11]={hint="실리더스의 묘지인 용사의 안식처 근처에 있는 라요 스타스트라이크를 찾아가 라빈의 편지를 보여주어야 합니다."}, [12]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [13]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [14]={hint="실리더스의 세나리온 요새에 있는 지질학자 락스베인이 황혼의 서판 조각 8개를 모아 달라고 부탁했습니다."}, [15]={hint="세나리온 요새에 있는 보르 와일드메인에게 암호화된 황혼의 문서 10개를 가져가야 합니다."}, [16]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [17]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [18]={npc="지질학자 락스베인", tgt="지질학자 락스베인"}, [19]={npc="보르 와일드메인", tgt="보르 와일드메인"}, [20]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [21]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [22]={npc="지질학자 락스베인", tgt="지질학자 락스베인"}, [23]={hint="실리더스의 세나리온 요새에 있는 바람소환사 프라우드혼이 망치미늘벌레 20마리를 처치해 달라고 부탁했습니다."}, [24]={hint="실리더스에서 돌꼬리집게전갈 독침 3개, 돌꼬리채찍전갈 독침 3개, 긴다리 바위거미 송곳니 3개를 모은 후, 세나리온 요새에 있는 비틱스 픽클스프라그에게 돌아가야 합니다."}, [25]={hint="실리더스에 있는 은둔자 오르텔에게 복원한 서판을 가져다줘야 합니다."}, [26]={npc="은둔자 오르텔", tgt="은둔자 오르텔"}, [27]={hint="실리더스로 가서 마파람 마을 부근 유적지에 있을 정화의 성물함을 찾아내야 합니다. 찾게 되면 달의 숲의 나이트헤이븐에 있는 라빈 사투르나에게 돌아가야 합니다."}, [28]={hint="마파람 마을에서 고통받는 드루이드 8명과 고통받는 파수꾼 8명의 영혼을 해방한 후, 실리더스, 용사의 안식처 묘지에 있는 라요 스타스트라이크에게 돌아가야 합니다.", desc="언데드가 죽으면 실리시드를 생성할 수 있습니다. 다음 당기기 전에 죽여라."}, [29]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [30]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [31]={hint="마파람 마을에 있는 탑 위로 올라가 실리시드 소굴을 들쑤셔 놓을 방법을 찾아야 합니다. 그러는 가운데 뭔가 알아낸 것이 있으면 실리더스의 용사의 안식처 묘지에 있는 라요 스타스트라이크에게 보고해야 합니다.", desc="아이템을 열기 전에 타워 계단을 클리어하세요. 시선을 조심하세요."}, [32]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [33]={npc="라요 스타스트라이크", tgt="라요 스타스트라이크"}, [34]={text="세나리온 요새로 돌아갑니다. 여기에 묶이면 난로가 됩니다."}, [35]={npc="비틱스 픽클스프라그", tgt="비틱스 픽클스프라그"}, [36]={npc="바람소환사 프라우드혼", tgt="바람소환사 프라우드혼"}, [37]={text="세나리온 요새에서 오그리마로 비행한 다음 듀로타에서 티리스팔 비행선을 탑승하세요."}}},
    ["04-57"] = {name="서부 역병지대", tips={{k="交通", text="1단계에서 Bulwark에 진입합니다. 마지막 단계에서 언더시티 외부에서 비행선을 타고 이동합니다."}, {k="取捨", text="동일한 루프에서 펠스톤 농장와 Andorhal을 수행합니다. 돌아오는 길에 흰개미 퀘스트를 완료하세요."}, {k="取捨", text="크로미의 남은 퀘스트는 동부 역병지대로 다시 돌아갑니다. 왕복 여행을 위해 보관하십시오."}, {k="提醒", text="레벨 59 이하인가요? 악령의 숲로 향하기 전에 안돌할 동부(약 46, 64) 외곽이나 역병 농장에서 일반 언데드를 처치하세요.", s={{"레벨 59 이하인가요?"}, {"악령의 숲로 향하기 전에 안돌할 동부(약 46, 64) 외곽이나 역병 농장에서 일반 언데드를 처치하세요"}}}}, danger={[1]="안돌할 마을회관는 레벨 61 엘리트인 소환사 아라즈 근처에 있습니다. 다로우샤이어 연대기를 찾을 때 외벽을 따라가세요."}, grind={[1]={mob="불타죽은 구울", note="안돌할의 동쪽 가장자리에 있는 일반 언데드입니다. 농장으로 돌아가기 전에 여기서 갈아주세요. 건물에 있는 엘리트와 무리를 피하세요."}, [2]={mob="오싹한 환영", note="가론의 흉가의 더 높은 레벨의 일반 망령. 아직 동쪽에 있다면 이 지점을 이용하세요. 실내에서 몹이 연결되지 않도록 가장자리를 고리로 만드세요."}}, supply={[1]={npc="은빛병참장교 하사나"}, [2]={npc="마이클 가레트"}, [3]={npc="여관주인 노먼"}, [4]={npc="여관주인 노먼"}, [5]={npc="엘리노르 러스크"}, [6]={npc="토마스 모던"}, [7]={npc="에제키엘 그레이브"}}, steps={[1]={text="Tirisfal 비행선 탑에서 Bulwark까지 이동한 다음 펠스톤 농장, Andorhal 및 북마루 벌목지를 통과합니다."}, [2]={hint="서부 역병지대의 보루에 있는 어둠의여사제 반디스에게 가득 찬 가론의 흉가 혼합물을 가져가야 합니다."}, [3]={npc="어둠의여사제 반디스", tgt="어둠의여사제 반디스"}, [4]={npc="미키 레빈", tgt="미키 레빈"}, [5]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", star={"용기의 쇼트소드", {"PALADIN", "MAGE", "WARLOCK"}}}, [6]={hint="퀘스트 목표를 완료하세요."}, [7]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", star={"용기의 쇼트소드", {"PALADIN", "MAGE", "WARLOCK"}}}, [8]={npc="미키 레빈", tgt="미키 레빈"}, [9]={hint="서부 역병지대에 있는 재니스 펠스톤에게 행운의 부적 조각을 되돌려줘야 합니다."}, [10]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [11]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [12]={hint="서부 역병지대에 있는 펠스톤 농장에서 행운의 부적 목줄을 찾아 붙이십시오.", desc="구울이 농장을 순찰합니다. 먼저 남쪽을 확인해 보세요."}, [13]={npc="재니스 펠스톤", tgt="재니스 펠스톤"}, [14]={hint="안돌할 폐허 남쪽에서 말레네와 대화해야 합니다."}, [15]={npc="말레네 레드패스", tgt="말레네 레드패스"}, [16]={npc="말레네 레드패스", tgt="말레네 레드패스"}, [17]={hint="조셉의 결혼반지를 크로미에게 가져가야 합니다.", desc="엘리트 리치가 안돌할 중심부에 있습니다. 여관으로 가는 길에 외곽에 머물러 보세요."}, [18]={npc="크로미", tgt="크로미"}, [19]={npc="크로미", tgt="크로미"}, [20]={npc="크로미", tgt="크로미"}, [21]={hint="안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다.", desc="덮개를 확인하세요. 가짜 책은 적을 생성할 수 있습니다. 중앙의 엘리트를 피하세요."}, [22]={hint="안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오."}, [23]={npc="크로미", tgt="크로미"}, [24]={npc="크로미", tgt="크로미"}, [25]={npc="크로미", tgt="크로미"}, [26]={hint="안돌할 도시의 폐허에서 안돌할 시계 5개를 찾아 서부 역병지대의 안돌할 여관에 있는 크로미에게 가져가야 합니다."}, [27]={npc="크로미", tgt="크로미"}, [28]={hint="서부 역병지대의 북마루 벌목지 중앙에 적당한 장소를 찾아 역병지대 흰개미 통을 놓아야 합니다."}, [29]={npc="흰개미 통", npcObj=true}, [30]={npc="흰개미 통", npcObj=true}, [31]={hint="북마루 벌목지에 역병지대 흰개미를 놓아준 다음 역병지대 흰개미 통을 가지고 트리스팔 숲 보루에 있는 미키 레빈에게 돌아가야 합니다.", desc="통을 열면 적이 몰려옵니다. 통을 열자마자 자리를 피하세요."}, [32]={npc="미키 레빈", tgt="미키 레빈"}, [33]={npc="애도의 기사", tag="선택사항, 게임 내 확인이 필요합니다", desc="티리스팔 남서쪽에 있는 애도의 기사를 확인하세요. 애도의 검(Sword of Mourning)은 보상 선택입니다.", star={"Sword of Mourning", {"PALADIN"}}}, [34]={text="언더시티 비행선 탑으로 돌아갑니다. 오그리마 비행선을 타고 악령의 숲로 계속 가세요."}}},
    ["05-d32"] = {name="스칼로맨스", entrance="서부 역병지대 (바다의 위협), 68.90, 72.80 소개. 카엘 다로우 지하 입구.", pickup="Bulwark에서 Alexi에게서 바로브 가의 유산를 가져와 열쇠 고리를 시작하십시오. 희망의 빛 예배당에서 역병 걸린 작은 새끼용를 수락하세요. Bulwark에서 카엘 다로우까지 남쪽 도로를 따라 가다가 들어가기 전에 Eva를 만나세요. 나만의 열쇠를 만들려면 보루에서 뼈조각를 반납하고, 금형 퀘스트를 수행한 후, 보루로 돌아가기 전에 가젯잔와 불기둥 마루를 방문하세요.", pickupS={{"Bulwark에서 Alexi에게서 바로브 가의 유산를 가져와 열쇠 고리를 시작하십시오"}, {"희망의 빛 예배당에서 역병 걸린 작은 새끼용를 수락하세요"}, {"Bulwark에서 카엘 다로우까지 남쪽 도로를 따라 가다가 들어가기 전에 Eva를 만나세요"}, {"나만의 열쇠를 만들려면 보루에서 뼈조각를 반납하고, 금형 퀘스트를 수행한 후, 보루로 돌아가기 전에 가젯잔와 불기둥 마루를 방문하세요"}}, tips={{k="動線", text="입구 다리 → 첫 번째 홀의 증서 → 소환실을 지나 또 다른 것 → 들창어금니 및 부화용 납골당 → 라스 프로스트위스퍼의 방에 있는 증서 → 아래층의 크라스티노프 및 최종 증서 → 암흑스승 간들링."}, {k="取捨", text="네 가지 행동, 역병 새끼, 교수를 한 번에 수행하세요. 누군가 문을 열 수 있다면 다른 모든 사람은 핵심 자료 체인을 건너뛸 수 있습니다."}, {k="說明", text="5인 던전. 열쇠홀더로 외부 문을 열도록 하세요. 교수 소름끼치는 크라스티노브의 가방, 사자 키르토노스 이후의 퀘스트는 반복 실행이 필요합니다. 다시 실행할 수 있는 그룹을 위해 저장하세요.", s={{"5인 던전"}, {"열쇠홀더로 외부 문을 열도록 하세요"}, {"교수 소름끼치는 크라스티노브의 가방, 사자 키르토노스 이후의 퀘스트는 반복 실행이 필요합니다"}, {"다시 실행할 수 있는 그룹을 위해 저장하세요"}}}, {k="提醒", text="5인 던전. 열쇠홀더로 외부 문을 열도록 하세요. 교수 소름끼치는 크라스티노브의 가방, 사자 키르토노스 이후의 퀘스트는 반복 실행이 필요합니다. 다시 실행할 수 있는 그룹을 위해 저장하세요.", s={{"5인 던전"}, {"열쇠홀더로 외부 문을 열도록 하세요"}, {"교수 소름끼치는 크라스티노브의 가방, 사자 키르토노스 이후의 퀘스트는 반복 실행이 필요합니다"}, {"다시 실행할 수 있는 그룹을 위해 저장하세요"}}}}, steps={[1]={npc="알렉시 바로브", tgt="알렉시 바로브", desc="레벨 52에 도달하면 Bulwark에서 일찍 수락하세요."}, [2]={npc="베티나 비글징크", tgt="베티나 비글징크", desc="희망의 빛 예배당에서 Bettina를 찾으세요."}, [3]={npc="에바 사크호프", tgt="에바 사크호프", desc="카엘 다로우 문 밖에서 에바를 찾으세요."}, [4]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", desc="자신의 스칼로맨스 키가 필요한 경우에만 수행하십시오. Bulwark에서 완료했다면 건너뛰세요."}, [5]={hint="펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오."}, [6]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴"}, [7]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", desc="이미 서부 역병지대의 Bulwark 주요 경로에 있습니다.", preText="붉은십자군의 주의 끌기"}, [8]={hint="신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다."}, [9]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴"}, [10]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", desc="Bulwark에서 일찍 반납할 수 있습니다.", preText="감시탑 공격 준비"}, [11]={hint="서부 역병지대의 보루에 있는 연금술사 디더스와 대화하십시오."}, [12]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [13]={npc="연금술사 디더스", tgt="연금술사 디더스", desc="Bulwark에서 완료했다면 이 세 가지를 건너뛰세요. 자신만의 열쇠를 만들려면 틀을 이용하세요.", preText="스칼로맨스"}, [14]={hint="서부 역병지대의 보루에 있는 연금술사 디더스에게 뼈조각 15개를 가져가야 합니다."}, [15]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [16]={npc="연금술사 디더스", tgt="연금술사 디더스", desc="가젯잔를 떠나 마샬의 야영지로 가기 전에 토륨 주괴 2개를 가져오세요.", preText="뼈조각"}, [17]={hint="가젯잔에 있는 크린클 굿스틸에게 15골드와 함께 마력 깃든 뼈조각을 가져가야 합니다."}, [18]={npc="크린클 굿스틸", tgt="크린클 굿스틸"}, [19]={npc="크린클 굿스틸", tgt="크린클 굿스틸", desc="마샬의 야영지 다리에서 불기둥 마루 퀘스트를 수행하세요.", preText="거푸집과 뼈조각"}, [20]={hint="운고로 분화구에 있는 불기둥 마루 꼭대기로 해골 열쇠 거푸집과 토륨 주괴 2개를 가져가야 합니다. 용암의 강에서 해골 열쇠 거푸집으로 불완전한 해골 열쇠를 만들어야 합니다."}, [21]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [22]={npc="연금술사 디더스", tgt="연금술사 디더스", desc="그룹이 있다면 Bulwark에서 Andorhal 구간 동안 수행하세요.", preText="불기둥 용광로"}, [23]={hint="소환사 아라즈를 처치하고 아라즈의 스카라베를 서부 역병지대에 보루에 있는 연금술사 디더스에게 돌아가야 합니다."}, [24]={npc="연금술사 디더스", tgt="연금술사 디더스"}, [25]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴", preText="아라즈의 스카라베"}, [26]={hint="퀘스트 목표를 완료하세요."}, [27]={npc="고위집행관 델링턴", tgt="고위집행관 델링턴"}, [28]={text="스칼로맨스 입구"}, [29]={hint="스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다.", desc="위치: 첫 번째 홀을 검색하고 소환실을 지나 라스와 바로브의 방을 검색하세요. 순서: 사우스쇼어 → 타렌 밀농장 → 브릴 → 카엘 다로우.", spot="첫 번째 홀을 검색하고 소환실을 지나 라스와 바로브의 방을 검색하세요."}, [30]={hint="역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다.", desc="위치: 소환실을 통과하고 들창어금니의 납골당에 있는 새끼를 처치하세요.", spot="소환실을 통과하고 들창어금니의 납골당에 있는 새끼를 처치하세요."}, [31]={hint="스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다.", desc="에바와 루시앙의 유해는 교수의 방에 있습니다. 위치: 마지막 6개의 방에서 크라스티노프를 찾으세요. 태우기 두 세트의 유해가 그의 방에 있습니다. 순서: 유해는 같은 방에 있습니다.", spot="마지막 6개의 방에서 크라스티노프를 찾으세요. 태우기 두 세트의 유해가 그의 방에 있습니다."}, [32]={npc="에바 사크호프", tgt="에바 사크호프", desc="다음에는 Eva에게서 The Bag of Horrors를 가져가세요. 처음 실행할 때는 그냥 제출하세요."}, [33]={npc="알렉시 바로브", tgt="알렉시 바로브"}, [34]={npc="베티나 비글징크", tgt="베티나 비글징크"}}},
    ["04-58"] = {name="악령의 숲", tips={{k="交通", text="1단계에서 잿빛 골짜기에서 북쪽으로 가세요. 마지막 단계에서 나무구렁 요새 를 거쳐 달의 숲 로 이동합니다."}, {k="取捨", text="Quest 마지막 일격에서는 3개의 목표를 달성하려면 어둠의 요새 깊숙한 곳으로 또 다른 여행이 필요합니다. 혼자 달리는 것이 시간을 투자할 가치가 없다면 건너뛰세요."}, {k="取捨", text="맹독 정령를 여명의 설원의 얼음불꽃 온천에 가져와 반납하세요."}, {k="提醒", text="레벨 60 이하? 강철나무 숲(약 49, 25)에서 맹독 정령 및 Irontree 트렌트를 처치하거나 여명의 설원에서 따라잡으세요.", s={{"레벨 60 이하?"}, {"강철나무 숲(약 49, 25)에서 맹독 정령 및 Irontree 트렌트를 처치하거나 여명의 설원에서 따라잡으세요"}}}}, danger={[1]="어둠의 요새의 화로는 좁은 터널을 통해 흩어져 있습니다. 화로를 사용하기 전에 각 섹션을 정리하세요. 밖으로 나가기 위해 발걸음을 되돌려 보세요."}, grind={[1]={mob="맹독 정령", note="강철나무 숲 풀의 일반 원소입니다. 이동하면서 맹독 정령 물방울을 수집하세요. 작은 경험치 간격에 적합합니다. 풀이 사용 중이면 여명의 설원로 이동하세요."}, [2]={mob="굽이나무 갈퀴늪괴물", note="북쪽 도로의 일반 트렌트. 수영장이 붐비는 경우 여기로 전환하고 나무구렁 요새로 가는 길을 따라 계속 가세요. 캠프 내부의 캐스터를 조심하세요."}}, supply={[1]={npc="여관주인 카일리스크"}, [2]={npc="여관주인 카일리스크"}, [3]={npc="브라카르"}, [4]={npc="알트소바 레이지토템"}, [5]={npc="베일"}, [6]={npc="베일"}}, steps={[1]={text="오그리마에서 토막나무 주둔지로 비행합니다. 북쪽의 주요 도로를 따라 악령의 숲로 진입한 후 에메랄드 성소에서 정차하고 인근 도로를 따라 가세요."}, [2]={npc="메이베스 리버브리즈", tgt="메이베스 리버브리즈"}, [3]={hint="정화된 달샘 물을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다."}, [4]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [5]={hint="악령의 숲 남부에 있는 에리단 블루윈드를 찾아가야 합니다."}, [6]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [7]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [8]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [9]={hint="정화된 달샘 물을 써서 악령의 숲에 있는 어둠의 요새를 감싸고 있는 화로 4개를 파괴한 후 에메랄드 성소에 있는 그레타 모스후프에게 돌아가야 합니다.", desc="먼저 통로를 클리어하세요. 동굴 내부에서는 지도 핀이 겹칠 수 있습니다."}, [10]={hint="악령의 숲에 있는 에리단 블루윈드에게 은백색 발톱 11개와 강철나무 심장 1개를 가져가야 합니다.", desc="늑대와 곰에게서 은빛 발톱을 획득하세요. 강철나무 나무정령을 처치해 심장을 얻으세요."}, [11]={npc="그레타 모스후프", tgt="그레타 모스후프"}, [12]={npc="에리단 블루윈드", tgt="에리단 블루윈드"}, [13]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="선택사항", desc="파트너와 함께 어둠의 요새로 깊이 돌아가거나 한 번에 하나씩 몹을 끌어낼 수 있는 경우."}, [14]={hint="무라와 살리라, 그리고 어둠의 군주 펠단을 처치하십시오. 그리고 그 증거로 펠단의 머리카락을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다.", tag="선택사항", desc="경비원은 영주와 가깝습니다. 근처 순찰대를 먼저 클리어하세요."}, [15]={npc="그레타 모스후프", tgt="그레타 모스후프", tag="선택사항"}, [16]={npc="트룰 페일베인", tgt="트룰 페일베인"}, [17]={hint="여명의 설원에 있는 도노바 스노우덴에게 맹독 정령 수액 3개를 갖다주어야 합니다."}, [18]={npc="임프시", tgt="임프시", tag="선택사항", desc="영혼 수확기는 보상 선택 중 하나입니다.", star={"영혼 수확기", {"WARLOCK"}}}, [19]={hint="악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다.", tag="선택사항", desc="45번, 52번, 57번 정류장에서 다리에 있는 모든 것을 모았다면 임프시로 돌아가세요."}, [20]={npc="임프시", tgt="임프시", tag="선택사항"}, [21]={npc="임프시", tgt="임프시", tag="선택사항", desc="엘리트를 위해 그룹을 구성하세요. 불지옥를 잠금 해제하려면 Niby로 전환하세요."}, [22]={hint="악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다.", tag="선택사항", desc="엘리트를 위해 그룹을 구성하세요. 불지옥를 잠금 해제하려면 Niby로 전환하세요."}, [23]={npc="전지전능한 나이비", tgt="전지전능한 나이비", tag="선택사항", desc="엘리트를 위해 그룹을 구성하세요. 불지옥를 잠금 해제하려면 Niby로 전환하세요."}, [24]={text="북쪽으로 나무구렁 요새로 이동한 후 달의 숲 출구로 나가세요."}}},
    ["04-59"] = {name="달의 숲", tips={{k="交通", text="1단계에서 나이트헤이븐로 이동합니다. 마지막 단계에서 퀘스트에 따라 얼음불꽃 온천 또는 눈망루 마을로 이동합니다."}, {k="取捨", text="한 번의 마을 방문에서 나이트헤이븐 NPC 핸드오프를 모두 수행합니다."}, {k="取捨", text="혈투의 전장 East 실행을 위해 악령덩굴 조각를 저장합니다."}, {k="提醒", text="이 다리는 여전히 레벨 59~60용입니다. 완료되면 바로 서리속삭임 골짜기로 이동하세요.", s={{"이 다리는 여전히 레벨 59~60용입니다"}, {"완료되면 바로 서리속삭임 골짜기로 이동하세요"}}}}, danger={[1]="달의 숲에서 여명의 설원로 이동하기 전에 Timbermaw 평판을 확인하세요. 여전히 적대적이라면 터널에 진입하기 전에 악령의 숲 쪽에서 평판을 높이십시오."}, grind={[1]={mob="광포한 톱니이빨곰", note="달의 숲 퀘스트를 완료한 후 요새를 통과하여 서리속삭임 골짜기 북쪽 입구 근처에 있는 일반 곰을 처치하세요. 그들은 60에 가깝습니다. 아래의 엘리트를 피하십시오."}}, supply={[1]={npc="멜리리"}, [2]={npc="다르곤"}, [3]={npc="대올린 서머리프"}, [4]={npc="파우스트론"}}, steps={[1]={text="나무구렁 요새를 떠나 주요 도로를 따라 나이트헤이븐로 가세요. 실리더스의 두 항목을 모두 제출하세요."}, [2]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [3]={hint="달의 숲의 나이트헤이븐 마을에 있는 세나리온 의회의 기록관, 움버에게 딱딱한 실리시드 조각을 가져가야 합니다."}, [4]={npc="움버", tgt="움버"}, [5]={npc="움버", tgt="움버"}, [6]={hint="달의 숲의 나이트헤이븐에 있는 라빈 사투르나와 대화해야 합니다."}, [7]={npc="라빈 사투르나", tgt="라빈 사투르나"}, [8]={npc="움버", tgt="움버"}, [9]={hint="퀘스트 목표를 완료하세요."}, [10]={npc="움버", tgt="움버"}, [11]={text="새로운 온천 또는 맹독 정령를 사용하여 나무구렁 요새를 통해 여명의 설원 온천으로 돌아갑니다. 둘 다 없고 Donova를 건너뛰는 경우 파우스트론(32.09, 66.61)에서 눈망루 마을로 날아갑니다."}}},
    ["04-60"] = {name="여명의 설원", tips={{k="交通", text="먼저 얼음불꽃 온천에 멈춰주세요. 눈망루 마을 설인 퀘스트를 완료한 후 남쪽으로 가서 협곡 북쪽 입구 밖에서 갈아주세요."}, {k="取捨", text="눈사태일족 정찰꾼의 외로운 배달원을 찾으세요. 탐험 퀘스트 이상한 근원가 영상의 핵심 지점으로 가는 중입니다."}, {k="取捨", text="Quest 대부족장 눈사태에는 엘리트 타겟이 있습니다. 혼자라면 대신 일반 곰을 죽이십시오."}, {k="提醒", text="60레벨 미만이면 영상대로 서리속삭임 골짜기 북쪽에서 곰을 잡으세요. 일반 광기의 조각니 곰은 57.63, 70.83 / 66.68, 70.57 부근에 있습니다. 골짜기 바닥의 정예는 피하세요.", s={{"60레벨 미만이면 영상대로 서리속삭임 골짜기 북쪽에서 곰을 잡으세요"}, {"일반 광기의 조각니 곰은 57.63, 70.83 / 66.68, 70.57 부근에 있습니다"}, {"골짜기 바닥의 정예는 피하세요"}}}}, danger={[1]="레벨 59~60 엘리트 Frostmaul 거인이 서리속삭임 골짜기를 배회합니다. 북쪽 입구의 경사면을 따라 곰을 한 마리씩 끌어당기고 협곡 안으로 끌고 들어가지 마세요.", [2]="레벨 57~60 엘리트 헤데린 슬레이어가 검은속삭임 협곡를 배회합니다. 트리거 이상한 근원 북쪽 입구에서 후 도로로 돌아갑니다."}, grind={[1]={mob="광포한 톱니이빨곰", note="일반 근접전은 서리속삭임 골짜기 북쪽 입구 서쪽에서 진행됩니다. 한 번에 한 명의 적을 끌어당겨 껍질을 벗기세요. 클리어 후 동쪽으로 회전합니다. 아래의 엘리트를 피하십시오."}, [2]={mob="광포한 톱니이빨곰", note="보통은 협곡의 북쪽 입 동쪽에 있습니다. 서쪽이 바쁘거나 다시 생성되지 않으면 여기로 전환하세요. 엘리트들로부터 멀리 떨어진 길로 오르막길을 차세요."}}, supply={[1]={npc="유그렉"}, [2]={npc="여관주인 비지"}, [3]={npc="닉스락"}, [4]={npc="여관주인 비지"}, [5]={npc="윅스락"}}, steps={[1]={text="나무구렁 요새에서 온천의 도노바를 만나보세요. 마샬의 야영지 및 강철나무 숲 퀘스트를 제출한 다음 눈망루 마을와 남쪽 계곡으로 향하세요. 눈망루 마을로 바로 날아가서 온천 퀘스트를 건너뛰고 있다면 우미부터 시작하세요."}, [2]={hint="여명의 설원으로 가서 도노바 스노우덴과 대화하십시오."}, [3]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [4]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [5]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [6]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [7]={hint="눈사태일족 정찰꾼들을 찾아 눈사태일족 마을로 물건을 전달하는 것을 막아야 합니다.", desc="나무구렁 입구나 마른나무 가마솥 근처에서 외로운 짐꾼을 찾으세요."}, [8]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [9]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="선택사항", desc="레벨 59 정예병과 근처의 펄볼그들을 모아보세요."}, [10]={hint="여명의 설원에 있는 도노바 스노우덴이 대부족장 눈사태를 처치해 달라고 부탁했습니다.", tag="선택사항", desc="먼저 외부 몹을 제거하세요. 편지가 떨어져서 체인이 필요한 경우 후속 조치를 취하세요."}, [11]={npc="휘갈겨 쓴 일지", npcObj=true, tag="선택사항", desc="대족장 눈사태가 저널을 삭제하면 저널을 마우스 오른쪽 버튼으로 클릭하세요."}, [12]={hint="여명의 설원에 있는 도노바 스노우덴에게 휘갈겨 쓴 일지를 가져다주어야 합니다.", tag="선택사항"}, [13]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="선택사항"}, [14]={npc="도노바 스노우덴", tgt="도노바 스노우덴", tag="선택사항"}, [15]={npc="우미 럼플스니커", tgt="우미 럼플스니커"}, [16]={hint="도노바 스노우덴의 지시를 따라 탐색을 한 후 되돌아오십시오.", desc="계곡 입구에서 멈춰주세요. 내부의 엘리트를 피하세요."}, [17]={npc="도노바 스노우덴", tgt="도노바 스노우덴"}, [18]={text="레벨 60 이하? 협곡 북쪽 입구 밖에서 일반 광기 파편이빨 곰을 처치하세요."}}},
    ["05-d34"] = {name="검은바위 첨탑 상층", entrance="이글거리는 협곡 (1427), 34.80, 85.30. 검은바위 산에 대한 접근 방식을 표시합니다.", pickup="레벨 55에서 눈망루 마을에서 오그리마로 날아간 다음 비행선을 타고 동부 왕국로 이동하세요. Lower 검은바위 첨탑 퀘스트 장군의 명령를 수행한 다음 카르가스의 장군 고어투스에서 아이트리그의 지혜를 가져옵니다. 톱니항 이후 지혜의 골짜기에서 아이트리그 및 스랄를 확인하고 호드를 위하여!를 유지하세요. 레벨 57에서 언더시티 Apothecarium에서 비비안 라그레이브와 다크스톤 서판를 가져온 다음 카르가스로 날아가서 Vivian으로 전환하고 다크스톤 서판을 가져가세요. 승천의 인장 → 승천의 인장를 완성하고 봉인을 가져오세요. 이미 가지고 있는 사람이 있다면 바로 Upper 검은바위 첨탑로 가세요.", pickupS={{"레벨 55에서 눈망루 마을에서 오그리마로 날아간 다음 비행선을 타고 동부 왕국로 이동하세요"}, {"Lower 검은바위 첨탑 퀘스트 장군의 명령를 수행한 다음 카르가스의 장군 고어투스에서 아이트리그의 지혜를 가져옵니다"}, {"톱니항 이후 지혜의 골짜기에서 아이트리그 및 스랄를 확인하고 호드를 위하여!를 유지하세요"}, {"레벨 57에서 언더시티 Apothecarium에서 비비안 라그레이브와 다크스톤 서판를 가져온 다음 카르가스로 날아가서 Vivian으로 전환하고 다크스톤 서판을 가져가세요"}, {"승천의 인장 → 승천의 인장를 완성하고 봉인을 가져오세요"}, {"이미 가지고 있는 사람이 있다면 바로 Upper 검은바위 첨탑로 가세요"}}, tips={{k="動線", text="7개의 룬을 클리어하고 → 불의수호자 엠버시어 → 번식지의 태블릿 → 블랙핸드 홀 → 경기장의 분쇄 및 기스 → 대장간, 괴수 옵션 → 사령관 드라키사스가 왕좌에 있고 그의 브랜드가 뒤에 있습니다."}, {k="取捨", text="카르가스 및 오그리마 퀘스트를 먼저 선택하세요. 공격대 조율이 필요한 경우에만 블랙핸드의 명령서를 수행하세요."}, {k="說明", text="Lower 검은바위 첨탑와 공용 출입구를 이용하세요. 잠긴 위쪽 문을 찾으려면 왼쪽으로 올라가십시오. 승천의 인장를 가지고 있는 사람을 데려오세요. 발사 가이드는 게이트 순서를 보여줍니다. 점프로 인해 경로가 막히면 바깥쪽 위쪽 통로를 이용하세요.", s={{"Lower 검은바위 첨탑와 공용 출입구를 이용하세요"}, {"잠긴 위쪽 문을 찾으려면 왼쪽으로 올라가십시오"}, {"승천의 인장를 가지고 있는 사람을 데려오세요"}, {"발사 가이드는 게이트 순서를 보여줍니다"}, {"점프로 인해 경로가 막히면 바깥쪽 위쪽 통로를 이용하세요"}}}}, steps={[1]={npc="장군 고어투스", tgt="장군 고어투스", desc="퀘스트 창이 열리지 않으면 NPC와 대화하여 가방에 있는 주문서를 사용하세요."}, [2]={hint="대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다.", desc="문서가 이동할 수 있습니다. 처음 세 개의 방에 도달하면 각각을 확인하세요. 문서는 어느 우두머리 방에서든 나올 수 있으니 방마다 확인하세요."}, [3]={npc="장군 고어투스", tgt="장군 고어투스"}, [4]={npc="장군 고어투스", tgt="장군 고어투스", preText="장군의 명령"}, [5]={hint="오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다."}, [6]={npc="스랄", tgt="스랄"}, [7]={npc="스랄", tgt="스랄", preText="아이트리그의 지혜"}, [8]={npc="연금술사 진게", tgt="연금술사 진게", tag="선택사항", desc="언더시티의 Apthecarium에서 57시에 수락하세요. 다크스톤 서판이 있는 경우 이 리드를 건너뛰세요."}, [9]={hint="어둠마법사 비비안 라그레이브와 대화해야 합니다.", tag="선택사항"}, [10]={npc="어둠마법사 비비안 라그레이브", tgt="어둠마법사 비비안 라그레이브", tag="선택사항"}, [11]={npc="어둠마법사 비비안 라그레이브", tgt="어둠마법사 비비안 라그레이브", desc="제공되는 경우 Vivian에서 수락하세요. 그렇지 않으면 언더시티 에서 비비안 라그레이브와 다크스톤 서판 로 시작하세요."}, [12]={npc="블랙핸드의 명령서", npcObj=true, tag="선택사항", desc="BWL에 액세스하려면 검은바위 첨탑 외부에서 병참장교의 편지를 약탈하고 사용하세요."}, [13]={text="검은바위 첨탑 상층 입구"}, [14]={hint="검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.", desc="위치: 번식지를 블랙핸드 홀(Blackhand Hall)로 전달하세요. 경기장 북쪽 게이트로 들어가 분쇄를 발동하세요. 순서: 경기장 앞에 있는 부화장에서 태블릿을 가져가세요.", spot="번식지를 블랙핸드 홀(Blackhand Hall)로 전달하세요. 경기장 북쪽 게이트로 들어가 분쇄를 발동하세요."}, [15]={hint="카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다.", desc="길을 따라가며 알을 피하세요. 뒤틀린 드레나이 알은 새끼용을 생성합니다. 위치: 불의수호자 엠버시어 이후, 번식지로 들어갑니다. 벽으로 바닥을 확인하세요. 순서: 13단계의 경기장 앞에서 이 작업을 수행합니다.", spot="불의수호자 엠버시어 이후, 번식지로 들어갑니다. 벽으로 바닥을 확인하세요."}, [16]={hint="아주 멍청한 오크로군요. 지배의 보주를 사용하려면 드라키사스의 낙인을 찾아 드라키사스의 징표를 받아야 할 거 같습니다.", tag="선택사항", desc="낙인은 드라키사스 뒤에 있습니다. 위치: 경기장의 남쪽 문을 떠나 대장간을 통과하세요. 브랜드는 사장 뒤에 있다. 순서: Drakkisath를 죽인 다음 그 뒤에 있는 낙인을 클릭하세요.", spot="경기장의 남쪽 문을 떠나 대장간을 통과하세요. 브랜드는 사장 뒤에 있다."}, [17]={npc="드라키사스의 낙인", npcObj=true, tag="선택사항, 게임 내 확인이 필요합니다", spot="드라키사스 왕좌 뒤의 낙인"}, [18]={npc="스랄", tgt="스랄"}, [19]={npc="어둠마법사 비비안 라그레이브", tgt="어둠마법사 비비안 라그레이브"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="여명의 설원 66.60, 84.40", pickup="발로르모크의 제디가에서 Beneath Nordrassil를 가져오고 오그틴크에서 찢는 발톱, 꿰뚫는 엄니를 가져옵니다. 레벨 55에 에칼을 위해 아즈샤라로 돌아갑니다. 톱니항를 통해 칼림도어로 돌아갈 때 썬더 블러프에서 장로의 봉우리로 날아간 다음 제디가의 편지를 반납하고 뿌리를 찾아서을 받습니다. 멀고어에서 멀른 어스퓨리를 방문합니다. 발로르모크로 비행하여 아즈샤라 터널을 통해 들어갑니다. 다음 썬더 블러프 및 멀고어 방문을 위해 뿌리를 찾아서 및 검은아귀 마법를 저장하세요.", pickupS={{"발로르모크의 제디가에서 Beneath Nordrassil를 가져오고 오그틴크에서 찢는 발톱, 꿰뚫는 엄니를 가져옵니다"}, {"레벨 55에 에칼을 위해 아즈샤라로 돌아갑니다"}, {"톱니항를 통해 칼림도어로 돌아갈 때 썬더 블러프에서 장로의 봉우리로 날아간 다음 제디가의 편지를 반납하고 뿌리를 찾아서을 받습니다"}, {"멀고어에서 멀른 어스퓨리를 방문합니다"}, {"발로르모크로 비행하여 아즈샤라 터널을 통해 들어갑니다"}, {"다음 썬더 블러프 및 멀고어 방문을 위해 뿌리를 찾아서 및 검은아귀 마법를 저장하세요"}}, tips={{k="動線", text="입구 터널에서 검은아귀 주머니를 약탈하고 → 지하에서 Nordrassil Rootcaps를 모으고 → 마른아귀 및 꺾이지 않는 해골주둥이의 가지 → 의식 토템을 위한 장로 주술사 핏빛갈기를 사용합니다. 정확한 포크와 보스 순서는 확인되지 않았습니다."}, {k="取捨", text="통과하면서 오그틴크 및 엘다라스 폐허 준비를 하세요. 한 번의 썬더 블러프 방문으로 호드 연합 루트캡 체인을 완성하세요."}, {k="說明", text="포탈 핀은 여명의 설원 지도에 나타납니다. 아즈샤라(38.70, 33.40)의 펄볼그 터널에 들어가서 이를 따라 포탈로 이동하세요. 여명의 설원 표면에서 찾지 마십시오.", s={{"포탈 핀은 여명의 설원 지도에 나타납니다"}, {"아즈샤라(38.70, 33.40)의 펄볼그 터널에 들어가서 이를 따라 포탈로 이동하세요"}, {"여명의 설원 표면에서 찾지 마십시오"}}}}, steps={[1]={npc="제디가", tgt="제디가", tag="게임 내 확인이 필요합니다"}, [2]={hint="Speak to Nara Wildmane at Elder Rise in Thunder Bluff.", tag="게임 내 확인이 필요합니다"}, [3]={npc="나라 와일드메인", tgt="나라 와일드메인", tag="게임 내 확인이 필요합니다"}, [4]={npc="나라 와일드메인", tgt="나라 와일드메인", tag="게임 내 확인이 필요합니다", preText="Beneath Nordrassil"}, [5]={npc="오그틴크", tgt="오그틴크"}, [6]={npc="알라나 스톰워커", tgt="Muln Earthfury", desc="썬더 블러프 경로에 멀고어 맵 핀을 사용하세요."}, [7]={npc="에칼", tgt="에칼"}, [8]={text="Blackmaw Hold 입구"}, [9]={hint="검은아귀 요새에서 놀드랏실 뿌리 버섯 10개를 채집해 썬더 블러프에 있는 나라 와일드메인에게 전달해야 합니다.", tag="게임 내 확인이 필요합니다", desc="위치: 지하 뿌리로 가는 통로를 따라가서 그곳에서 뿌리뚜껑을 모으세요.", spot="지하 뿌리로 가는 통로를 따라가서 그곳에서 뿌리뚜껑을 모으세요."}, [10]={hint="위대한 곰의 발톱과 굽히지 않는 자의 엄니를 아즈샤라에 있는 오그틴크에게 가져가야 합니<name>.", tag="대상: 거인 베어 마른아귀 / 꺾이지 않는 해골주둥이, 게임 내 확인이 필요합니다", desc="위치: 터널에서 마른아귀 및 꺾이지 않는 해골주둥이를 찾으세요. 포크가 확인되지 않았습니다.", spot="터널에서 마른아귀 및 꺾이지 않는 해골주둥이를 찾으세요. 포크가 확인되지 않았습니다."}, [11]={hint="검은아귀 요새에서 검은아귀 의식 토템을 회수해야 합니다.", tag="게임 내 확인이 필요합니다", desc="위치: 보스 루트를 따라 장로 주술사 핏빛갈기로 가서 그의 의식 토템을 약탈하세요.", spot="보스 루트를 따라 장로 주술사 핏빛갈기로 가서 그의 의식 토템을 약탈하세요."}, [12]={hint="획득처: Blackmaw Berserker, Blackmaw Thrall, Blackmaw Headhunter", desc="위치: 거실과 전리품 주머니에 있는 타락한 검은아귀 펄볼그를 제거하세요.", spot="거실과 전리품 주머니에 있는 타락한 검은아귀 펄볼그를 제거하세요."}, [13]={npc="오그틴크", tgt="오그틴크"}, [14]={npc="에칼", tgt="에칼"}, [15]={npc="나라 와일드메인"}, [16]={npc="알라나 스톰워커", tgt="Muln Earthfury"}}},
  },
  quests = {
    [2] = {n="뾰족발톱의 발톱", d="뾰족발톱의 발톱을 잿빛 골짜기의 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다."},
    [10] = {n="슈섕크 탈출", d="후임측량사 슈섕크가 어떻게 되었는지 알아보고 가젯잔에 있는 선임측량사 피즐도저에게 데려오거나 그의 측량 장비라도 찾아서 가져가야 합니다.", objs={"슈섕크의 측량 장비"}},
    [23] = {n="우르산고우스의 앞발", d="우르산고우스의 앞발을 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다."},
    [24] = {n="샤둠브라의 머리", d="샤둠브라의 머리를 잿빛 골짜기 토막나무 주둔지에 있는 세나니 썬더하트에게 가져가야 합니다."},
    [25] = {n="돌발톱 산맥의 정체 해결", d="돌발톱 토굴길에서 동쪽으로, 그리고 토막나무 주둔지에서 남서쪽으로 있는 미스트랄 호수에서 타락한 물의 정령 12마리를 처치해야 합니다.\n미스트랄 호수에 있는 전망대로 가서 얼라이언스 전초기지를 살펴봐야 합니다.\n그런 다음 잿빛 골짜기 토막나무 주둔지에 있는 마스토크 윌리히스에게 돌아가십시오.", tgo={{"타락한 물의 정령"}}},
