    [28] = {n="엘룬아라 호수의 시험", d="엘룬아라 호수에서 제단 구슬을 찾은 후, 달의 숲 북서부에 있는 레물로스의 제단으로 가져가야 합니다. 그곳에 이르면 제단 구슬을 사용하십시오.\n그런 다음 제단에 있는 타자리와 대화해야 시험이 끝나게 됩니다.", objs={"레물로스의 제단"}},
