    [2339] = {n="보석과 마력원천 찾기", d="울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다.\n일지의 내용을 보니 루비는 어둠괴철로단의 방어진에 숨겨져 있습니다.\n토파즈는 얼라이언스 드워프 근처에 있는 트로그 구역 중 하나에 있는 항아리에 숨겨져 있습니다.\n사파이어는 트로그의 우두머리인 그림로크가 가지고 있습니다.\n마력원천은 울다만에서 가장 강한 피조물을 처치하면 얻을 수 있습니다.", tgo={{}, {"그림로크"}, {}, {"아카에다스"}}, objs={"어둠괴철로단 금고", "특이한 항아리"}},
