    [2379] = {n="잔도잔", d="어둠의 틈에 있는 잔도잔과 대화하십시오."},
    [2381] = {n="약탈자 약탈하기", d="톱니항에 있는 비운의 레닉스에게 남쪽바다해적단 보물을 가져가야 합니다. 레닉스의 기계장치에서 E.C.A.C.와 도둑 도구를 얻는 것도 잊지 마십시오. 임무를 완수하려면 이 두 가지가 모두 필요합니다.\n유별나게 공격적인 앵무새에게 맞서게 되면 E.C.A.C.를 사용하십시오!", tgo={{"앵무새"}}},
