    [2521] = {n="굼이샤의 지시", d="저주받은 땅을 돌아다니다가 완전무결한 드레니시스트 구슬을 발견하면 수집가 굼이샤에게 가져가야 합니다.\n이 보석은 아제로스를 통틀어 가장 희귀한 수정 중 하나로써 이곳 생물들이 지니고 있을 가능성도 있습니다.\n완전무결한 드레니시스트 구슬을 수집해 갈 때마다 각각에 대해 보상을 받게 됩니다.", tgo={{"우레망치일족 오우거", "우레망치일족 오우거 마법사", "우레망치일족 투사"}}},
